// Structure for LTE UE contexts
typedef struct {
    char imsi[15];   // Valid UE identifier (IMSI)
    int num_rb;      // Number of active radio bearers
    int *rb_ids;     // Array of radio bearer identifiers
    float *qos_parms;// Array of QoS parameters for each radio bearer
} lte_ue_context_t;

// Function to create and populate a list of LTE UE contexts
void create_lte_ue_context_list(char **imsis, int num_ues, lte_ue_context_t ***ctx_list) {
    // Allocate memory for the list of UE contexts
    *ctx_list = (lte_ue_context_t**)malloc(sizeof(lte_ue_context_t*) * num_ues);
    if (*ctx_list == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize each UE context structure
    for (int i = 0; i < num_ues; i++) {
        (*ctx_list)[i] = (lte_ue_context_t*)malloc(sizeof(lte_ue_context_t));
        if ((*ctx_list)[i] == NULL) {
            printf("Memory allocation failed!\n");
            return;
        }
        strcpy((*ctx_list)[i]->imsi, imsis[i]);
        (*ctx_list)[i]->num_rb = 0;
        (*ctx_list)[i]->rb_ids = NULL;
        (*ctx_list)[i]->qos_parms = NULL;
    }

    // Add active radio bearers to each UE context structure
    for (int i = 0; i < num_ues; i++) {
        int num_active_rb = 0;
        char **rb_ids = (char**)malloc(sizeof(char*) * num_active_rb);
        if (rb_ids == NULL) {
            printf("Memory allocation failed!\n");
            return;
        }
        float **qos_parms = (float**)malloc(sizeof(float*) * num_active_rb);
        if (qos_parms == NULL) {
            printf("Memory allocation failed!\n");
            return;
        }
        for (int j = 0; j < num_active_rb; j++) {
            rb_ids[j] = (char*)malloc(sizeof(char) * 15);
            if (rb_ids[j] == NULL) {
                printf("Memory allocation failed!\n");
                return;
            }
            qos_parms[j] = (float*)malloc(sizeof(float) * 4);
            if (qos_parms[j] == NULL) {
                printf("Memory allocation failed!\n");
                return;
            }
        }
        (*ctx_list)[i]->num_rb = num_active_rb;
        (*ctx_list)[i]->rb_ids = rb_ids;
        (*ctx_list)[i]->qos_parms = qos_parms;
    }
}

// Function to add a new UE context to the list
void add_ue_context(char *imsi, lte_ue_context_t **ctx_list, int num_ues) {
    // Check if the IMSI already exists in the list
    for (int i = 0; i < num_ues; i++) {
        if (strcmp((*ctx_list)[i]->imsi, imsi) == 0) {
            printf("UE with IMSI %s already exists!\n", imsi);
            return;
        }
    }

    // Create a new UE context structure and add it to the list
    (*ctx_list)[num_ues] = (lte_ue_context_t*)malloc(sizeof(lte_ue_context_t));
    if ((*ctx_list)[num_ues] == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
    strcpy((*ctx_list)[num_ues]->imsi, imsi);
    (*ctx_list)[num_ues]->num_rb = 0;
    (*ctx_list)[num_ues]->rb_ids = NULL;
    (*ctx_list)[num_ues]->qos_parms = NULL;
}

// Function to delete an UE context from the list
void delete_ue_context(char *imsi, lte_ue_context_t **ctx_list, int num_ues) {
    // Find the index of the UE context with the specified IMSI
    int idx = -1;
    for (int i = 0; i < num_ues; i++) {
        if (strcmp((*ctx_list)[i]->imsi, imsi) == 0) {
            idx = i;
            break;
        }
    }
    if (idx == -1) {
        printf("UE with IMSI %s does not exist!\n", imsi);
        return;
    }

    // Delete the UE context structure and free its memory
    lte_ue_context_t *ctx = (*ctx_list)[idx];
    if (ctx->rb_ids != NULL) {
        for (int i = 0; i < ctx->num_rb; i++) {
            free(ctx->rb_ids[i]);
            free(ctx->qos_parms[i]);
        }
        free(ctx->rb_ids);
        free(ctx->qos_parms);
    }
    free(ctx);

    // Shift the remaining UE contexts to fill the gap
    for (int i = idx; i < num_ues - 1; i++) {
        (*ctx_list)[i] = (*ctx_list)[i + 1];
    }
}
```
