void allocate_records(size_t num_records, size_t offset_size, size_t key_size,
                      long **offsets, int **keys, record_t ***records) {
    // Allocate memory for the arrays of long offsets and int keys
    *offsets = (long *)malloc(num_records * sizeof(long));
