    *records = (record_t **)malloc(num_records * record_size);

    // Set the value of each record's int field to a random value within a given range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = (record_t *)malloc(record_size);
        (*records)[i]->value = rand() % 100;
    }

    // Implement error checking for each memory allocation step and ensure that all allocated memory is properly freed when no longer needed
    if (!(*offsets) || !(*keys) || !(*records)) {
