    // Optimize the function to handle large datasets efficiently without causing excessive resource consumption or performance degradation
    if (num_records > 1000) {
        printf("Optimizing allocation of records for large dataset\n");
        size_t record_size = sizeof(record_t);
        *records = (record_t **)realloc(*records, num_records * record_size);
    }

    pthread_mutex_unlock(&mutex);
}
