#include <string.h>
#include <limits.h>

#define MAX_INPUT 1000

int largest(int *arr, int size) {
    int max = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void read_input(int *arr, int *size) {
    char input[MAX_INPUT];
    fgets(input, MAX_INPUT, stdin);
    int count = 0;
    for (int i = 0; i < strlen(input); i++) {
        if (isdigit(input[i])) {
            arr[count++] = atoi(&input[i]);
        } else if (!isspace(input[i]) && !isnewline(input[i])) {
            break;
        }
    }
    *size = count;
}

int main() {
    int arr[MAX_INPUT];
    int size;
    read_input(arr, &size);
    if (size > 0) {
        int max = largest(arr, size);
        printf("The largest integer in the array is: %d\n", max);
    } else {
        printf("No integers were entered.\n");
    }
    return 0;
}
