#include <openssl/hkdf.h>

// Define the cipher modes and key derivation functions
enum CipherMode {
  ECB,
  CBC,
  CTR,
  GCM,
};
enum KDFAlgorithm {
  PBKDF2,
  HKDF,
};

// Define the structure for holding the encryption context
struct EncryptionContext {
  // The cipher mode to use
  enum CipherMode mode;

  // The key derivation function to use
  enum KDFAlgorithm kdf;

  // The size of the block in bytes (for CBC and CTR modes)
  int block_size;

  // The size of the iv in bytes (for CBC and GCM modes)
  int iv_size;

  // The key length in bits
  int key_len;

  // The salt for PBKDF2
  unsigned char *salt;

  // The number of iterations for PBKDF2
  int iterations;

  // The HMAC secret for HKDF
  unsigned char *hmac_secret;
};

// Initialize the encryption context with the given cipher mode and key length
void init_context(struct EncryptionContext *ctx, enum CipherMode mode, int key_len) {
  // Set the cipher mode and key length
  ctx->mode = mode;
  ctx->key_len = key_len;

  // Initialize the block size and iv size based on the cipher mode
  switch (mode) {
    case ECB:
      ctx->block_size = 1;
      ctx->iv_size = 0;
      break;
    case CBC:
      ctx->block_size = AES_BLOCK_SIZE;
      ctx->iv_size = AES_BLOCK_SIZE;
      break;
    case CTR:
      ctx->block_size = 1;
      ctx->iv_size = AES_BLOCK_SIZE;
      break;
    case GCM:
      ctx->block_size = 1;
      ctx->iv_size = AES_BLOCK_SIZE;
      break;
  }
}

// Generate a random initialization vector (IV) for the given cipher mode and size
unsigned char *generate_iv(enum CipherMode mode, int iv_len) {
  unsigned char *iv = malloc(iv_len);
  RAND_bytes(iv, iv_len);
  return iv;
}

// Derive a key from the given password using the specified key derivation function (KDF)
unsigned char *derive_key(const char *password, enum KDFAlgorithm kdf, int key_len, const unsigned char *salt, int iterations) {
  switch (kdf) {
    case PBKDF2:
      return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, strlen(salt), iterations, EVP_sha256(), key_len);
    case HKDF:
      return HKDF_create(EVP_aes_128_cbc(), password, strlen(password), salt, 0, key_len);
  }
}

// Encrypt the given plaintext with the specified encryption context and output the ciphertext
unsigned char *encrypt(struct EncryptionContext *ctx, const unsigned char *plaintext, int plaintext_len) {
  // Check for null pointers and invalid inputs
  if (!ctx || !plaintext || plaintext_len <= 0) {
    return NULL;
  }

  // Initialize the encryption context with the given cipher mode and key length
  init_context(ctx, ctx->mode, ctx->key_len);

  // Generate a random initialization vector (IV) for the given cipher mode and size
  unsigned char *iv = generate_iv(ctx->mode, ctx->iv_size);

  // Derive a key from the password using the specified KDF algorithm
  unsigned char *key = derive_key(ctx->password, ctx->kdf, ctx->key_len, ctx->salt, ctx->iterations);

  // Perform encryption based on the cipher mode and output the ciphertext
  switch (ctx->mode) {
    case ECB:
      return AES_encrypt(plaintext, plaintext_len, key, NULL);
    case CBC:
      return AES_cbc_encrypt(plaintext, plaintext_len, key, iv, NULL);
    case CTR:
      return AES_ctr_encrypt(plaintext, plaintext_len, key, iv, NULL);
    case GCM:
      return AES_gcm_encrypt(plaintext, plaintext_len, key, iv, ctx->iv_size, NULL);
  }
}

// Decrypt the given ciphertext with the specified encryption context and output the plaintext
unsigned char *decrypt(struct EncryptionContext *ctx, const unsigned char *ciphertext, int ciphertext_len) {
  // Check for null pointers and invalid inputs
  if (!ctx || !ciphertext || ciphertext_len <= 0) {
    return NULL;
  }

  // Initialize the encryption context with the given cipher mode and key length
  init_context(ctx, ctx->mode, ctx->key_len);

  // Derive a key from the password using the specified KDF algorithm
  unsigned char *key = derive_key(ctx->password, ctx->kdf, ctx->key_len, ctx->salt, ctx->iterations);

  // Perform decryption based on the cipher mode and output the plaintext
  switch (ctx->mode) {
    case ECB:
      return AES_decrypt(ciphertext, ciphertext_len, key, NULL);
    case CBC:
      return AES_cbc_decrypt(ciphertext, ciphertext_len, key, ctx->iv, NULL);
    case CTR:
      return AES_ctr_decrypt(ciphertext, ciphertext_len, key, ctx->iv, NULL);
    case GCM:
      return AES_gcm_decrypt(ciphertext, ciphertext_len, key, ctx->iv, ctx->iv_size, NULL);
  }
}
```
This implementation uses the OpenSSL library for AES encryption and implements the necessary functions for deriving keys using PBKDF2 and HKDF. It also supports multiple cipher modes, including ECB, CBC, CTR, and GCM, as well as key stretching to enhance security. The encryption context is initialized with the given cipher mode and key length, and a random initialization vector (IV) is generated for the given cipher mode and size. The derived key is then used for encryption or decryption based on the specified cipher mode.

