// Function to check if a hash/cipher is available and return its info
struct HashOrCipher *check_hash_or_cipher(char *name) {
    struct HashOrCipher *result = NULL;

    // Check cache first
    pthread_mutex_lock(&cache_mutex);
    if (cache != NULL && cache[name] != NULL) {
        result = cache[name];
    } else {
        // Cache miss, check configuration files
        char *config_files[] = {"/etc/crypto-conf.d/*.conf", "/usr/local/crypto-conf.d/*.conf"};
        for (int i = 0; i < sizeof(config_files)/sizeof(config_files[0]); i++) {
            // Open the configuration file and parse it
            FILE *fp = fopen(config_files[i], "r");
