    while (fgets(line, sizeof(line), fp)) {
        // Skip comments and empty lines
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into name and parameters
        char *name = strtok(line, " \t");
        int param1 = atoi(strtok(NULL, " \t"));
        int param2 = atoi(strtok(NULL, " \t"));

        // Create a new hash/cipher struct and add it to the cache
        struct HashOrCipher *new_hash_or_cipher = malloc(sizeof(struct HashOrCipher));
        new_hash_or_cipher->name = strdup(name);
        new_hash_or_cipher->func = NULL; // Not implemented yet
        new_hash_or_cipher->param1 = param1;
        new_hash_or_cipher->param2 = param2;
        cache[name] = new_hash_or_cipher;
    }
}

