            // Asynchronous I/O with thread safety for shared resources
            boost::asio::post(io_context, [&]() {
                ++total_requests;

                // Send GET request to server
                if (sandesh_client.sendRequest("GET", large_data)) {
                    ++proxy_sessions;
                } else {
