  private:
    static std::mt19937 mt_;
    static uint64_t seed_;
    static std::uniform_int_distribution<uint64_t> dist_;
    static std::mutex seedMutex_;
    static std::vector<uint64_t> seeds_;
  public:
    RandomNumberGenerator() {
      // Initialize the random number generator with a default seed if not set
      if (seed_ == 0) {
        seed_ = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count();
      }
      mt_.seed(seed_);
    }

    ~RandomNumberGenerator() {
      // Trivial destructor
    }

    static uint64_t generate(const std::string& dist = "uniform") {
      if (dist == "uniform") {
        return dist_(mt_, 0, std::numeric_limits<uint64_t>::max());
      } else if (dist == "normal") {
        return std::generate_canonical<float, 10>(mt_);
      } else {
        // Unsupported distribution type
        throw std::invalid_argument("Unsupported distribution type");
      }
    }

    static void setSeed(uint64_t seed) {
      if (seedMutex_.try_lock()) {
        seed_ = seed;
        mt_.seed(seed_);
        seedMutex_.unlock();
      } else {
        // Conflict in seed management
        throw std::runtime_error("Seed conflict");
      }
    }

    static void addSeeds(const std::vector<uint64_t>& seeds) {
      if (seedMutex_.try_lock()) {
        for (auto seed : seeds) {
          seeds_.push_back(seed);
        }
        mt_.seed(seeds_.at(0));
        seedMutex_.unlock();
      } else {
        // Conflict in seed management
        throw std::runtime_error("Seed conflict");
      }
    }
  };
}
