using System.Data.SqlClient;

public static IDataReader ExecuteDynamicQuery(List<object> values, SqlConnection connection, string sqlCommand)
{
    // Create a new parameterized SQL command
    var cmd = new SqlCommand();
    cmd.Connection = connection;
    cmd.CommandText = sqlCommand;

    // Add parameters to the command for each value in the input list
    foreach (var value in values)
    {
        // If the value is null, add a null parameter to the command
        if (value == null)
        {
            cmd.Parameters.Add(new SqlParameter());
        }
        // Otherwise, add a non-null parameter to the command with the appropriate type
        else
        {
            var param = new SqlParameter();
            switch (value)
            {
                case string str:
                    param.Value = str;
                    param.SqlDbType = SqlDbType.NVarChar;
                    break;
                case int integer:
                    param.Value = integer;
                    param.SqlDbType = SqlDbType.Int;
                    break;
                // Add more cases as needed for other types of values
            }
            cmd.Parameters.Add(param);
        }
    }

    // Execute the command and return an IDataReader for the result set
    var reader = cmd.ExecuteReader();
    return reader;
}
```
