        {
            // Check if configuration file exists and load it
            if (File.Exists(CONFIG_FILE))
            {
                string jsonData = File.ReadAllText(CONFIG_FILE);
                dynamic config = JsonConvert.DeserializeObject<dynamic>(jsonData);

                // Set game world size from configuration
                GameWorldSize = config.gameWorldSize ?? DEFAULT_SIZE;

                // Initialize player positions and health points from configuration
                for (int i = 0; i < config.players.Length; i++)
                {
                    Player player = new Player();
                    player.Position = config.players[i].position ?? Vector3.Zero;
                    player.HealthPoints = config.players[i].health ?? DEFAULT_HEALTH;
                    Players.Add(player);
                }
            }
            else
            {
                // Set default game world size and initialize players with default health points
                GameWorldSize = DEFAULT_SIZE;
                for (int i = 0; i < 4; i++)
                {
                    Player player = new Player();
                    player.Position = Vector3.Zero;
                    player.HealthPoints = DEFAULT_HEALTH;
                    Players.Add(player);
                }
            }
        }

        // Check for modified configuration files at regular intervals and reload them if necessary
        public static void CheckForModifications()
        {
            DateTime lastCheck = DateTime.Now;
            while (true)
            {
                // Sleep for a short interval to prevent excessive CPU usage
                Thread.Sleep(100);

                // Check if any configuration files have been modified since the last check
                bool hasModifiedFiles = false;
                foreach (string file in Directory.GetFiles("./"))
                {
                    if (file == CONFIG_FILE) continue;
                    if (File.GetLastWriteTimeUtc(file) > lastCheck)
                    {
                        hasModifiedFiles = true;
                        break;
                    }
                }

                // Reload configuration files if necessary
                if (hasModifiedFiles)
                {
                    LoadConfiguration();
                    lastCheck = DateTime.Now;
                }
            }
