import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public static String getMD5Hash(String input) {
    if (input == null || input.isEmpty()) {
        return "";
    }

    try {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hash = digest.digest(input.getBytes());
        String md5Hash = new BigInteger(1, hash).toString(16);

        // Log input string and its hash value for auditing purposes
        Logger logger = Logger.getLogger("MD5Hash");
        logger.log(Level.INFO, "Input: {0}", input);
        logger.log(Level.INFO, "Hash: {0}", md5Hash);

        return md5Hash;
    } catch (NoSuchAlgorithmException e) {
        // Handle exception gracefully
        Logger.getLogger("MD5Hash").log(Level.SEVERE, "Error computing MD5 hash", e);
        return "";
    }
}
```
