    // Handle account creation
    if ($id === null && $sub_action === null) {
        // Create new user account
        $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
        $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_DEFAULT)]);

        // Return success message
        return json_encode(['message' => 'success']);
    }

    // Handle account update
    if ($id !== null && $sub_action === null) {
        // Check if the user exists in the database
        $stmt = $db->prepare('SELECT COUNT(*) FROM users WHERE id=:id');
        $stmt->execute([':id' => $id]);
        if (!$stmt->fetchColumn()) {
            return json_encode(['message' => 'error', 'errors' => ['User does not exist']]);
        }

        // Update user account
        $stmt = $db->prepare('UPDATE users SET name=:name, email=:email WHERE id=:id');
        $stmt->execute([':name' => $name, ':email' => $email, ':id' => $id]);

        // Return success message
        return json_encode(['message' => 'success']);
    }

    // Handle account deletion
    if ($sub_action === 'delete') {
        // Check if there are any associated records (e.g., posts or comments) before proceeding with the deletion
        $stmt = $db->prepare('SELECT COUNT(*) FROM users WHERE id=:id');
        $stmt->execute([':id' => $id]);
        if ($stmt->fetchColumn() > 0) {
            return json_encode(['message' => 'error', 'errors' => ['Cannot delete user account with associated records']]);
        }

        // Delete user account
        $stmt = $db->prepare('DELETE FROM users WHERE id=:id');
        $stmt->execute([':id' => $id]);

        // Return success message
        return json_encode(['message' => 'success']);
    }
}

function validateRequest($request) {
    // Check if the request has required keys
    if (!isset($_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password'])) {
        return false;
    }

    // Check if the email is valid and not already in use
    $email = strtolower($_REQUEST['email']);
    if (!filter_var($email, FILTER_VALIDATE_EMAIL) || !empty(getUserByEmail($email))) {
        return false;
    }

    // Check if the password meets requirements (e.g., length, complexity)
    $password = $_REQUEST['password'];
    if (!password_verify($password, password_hash($password, PASSWORD_DEFAULT))) {
        return false;
    }

    // Return true if all validations pass
    return true;
}

function getUserByEmail($email) {
    // Connect to database
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    } catch (PDOException $e) {
        return json_encode(['message' => 'error', 'errors' => ['Database connection failed']]);
    }

    // Query database for user with the provided email
    $stmt = $db->prepare('SELECT COUNT(*) FROM users WHERE email=:email');
    $stmt->execute([':email' => $email]);
    if ($stmt->fetchColumn() > 0) {
        return true;
    } else {
        return false;
    }
}

?>
```
