  if (tests.length === 0) {
    console.log(`No tests found in ${label}`);
    return;
  }

  // Run each test function in a separate environment to prevent state interference between tests
  tests.forEach((test) => {
    let env = Object.create(global);
    env.blueslip = blueslip;

    try {
      f(env, test);
    } catch (error) {
      console.log(`Error running ${test.name}: ${error}`);
    } finally {
      // Reset the mocking library after each test
      env.blueslip.reset();
    }
  });
}
