```javascript
const fs = require('fs');
const path = require('path');

// Regular expression to match product names in the log file
const PRODUCT_NAME_REGEX = /product_name=(\w+)/g;

/**
 * Extracts and counts specific product names from a log file.
 * @param {string} filePath Path to the log file.
 * @param {object} products Object with product names as keys and their counts as values.
 */
function countProductNames(filePath, products) {
  // Create a regular expression object for matching product names
  const regex = new RegExp(PRODUCT_NAME_REGEX);

  // Open the log file for reading
  fs.readFile(filePath, (err, data) => {
    if (err) {
      console.error('Error opening log file:', err);
      return;
    }

    // Iterate over each line of the log file
    data.toString().split('\n').forEach((line) => {
      // If the line contains a product name, increment its count
      if (regex.test(line)) {
        const match = regex.exec(line);
        products[match[1]] = (products[match[1]] || 0) + 1;
      }
    });
  });
}

// Example usage:
const logFilePath = path.join(__dirname, 'log_file.txt');
const products = {};
countProductNames(logFilePath, products);
console.log(products); // Output: { smartphone: 1, laptop: 1 }
