function renderScripts(scripts) {
  const renderedScripts = [];
  for (const script of scripts) {
    if (!script || !script.key || !script.code) continue; // Skip invalid scripts
    let code = script.code;
    if (script.type === 'external') {
      // Handle external script URLs
      const url = new URL(script.code);
      if (url.protocol !== 'https:' && url.host !== 'cdn.example.com') continue; // Skip non-HTTPS or non-whitelisted scripts
