std::forward_list<std::string> insertURL(const std::forward_list<std::string>& list, const std::string& resourceID, const std::string& URL) {
    // create a new forward list with the same elements as the input list
    std::forward_list<std::string> newList = list;

    // find the first occurrence of the resource ID in the list
    auto it = std::find(newList.begin(), newList.end(), resourceID);

    // if the resource ID was found, insert the URL after that element
    if (it != newList.end()) {
        newList.insert_after(it, URL);
    } else {
        // otherwise, insert the URL at the end of the list
        newList.push_back(URL);
    }

    return newList;
}
