function concatenateBuffers(buffers, chunkSize) {
  // Calculate the total length of all buffers
  let totalLength = 0;
  for (const buffer of buffers) {
    totalLength += buffer.length;
  }

  // Create a new buffer with enough capacity to hold all chunks
  const concatenatedBuffer = Buffer.allocUnsafe(totalLength);

  // Iterate over each chunk and copy it into the concatenated buffer
  let offset = 0;
  for (const buffer of buffers) {
    concatenatedBuffer.set(buffer, offset);
    offset += buffer.length;
  }

  return concatenatedBuffer;
}
