['```rust
use std::time::Duration;
use reqwest::blocking::Client;
use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::redirect::Policy;
use reqwest::Method;
use reqwest::StatusCode;
use reqwest::Error;

fn create_http_client(url: &str, disable_certificate_validation: bool) -> Client {
    let mut headers = HeaderMap::new();
    headers.insert(HeaderValue::from_static("Content-Type"), "application/json");
    headers.insert(HeaderValue::from_static("User-Agent"), "My HTTP client");

    let mut config = reqwest::Config::default();
    config.set_redirect(Policy::custom(|attempt| {
        if attempt < 3 {
            Some(Duration::from_secs(1 << (attempt - 1)))
        } else {
            None
        }
    });
    config.set_timeout(Duration::from_secs(60));

    let client = Client::builder()
        .disable_redirect(true)
        .disable_certificate_validation(disable_certificate_validation)
        .headers(headers)
        .build()?;

    Ok(client)
}

fn send_request(url: &str, disable_certificate_validation: bool) -> Result<StatusCode, Error> {
    let client = create_http_client(url, disable_certificate_validation)?;
    let request = reqwest::blocking::Request::new(Method::GET, url);
    let response = client.execute(request).await?;
    Ok(response.status())
}
```
