["Here is an example of a PHP function that generates a random string of a specified length using a given character set and then hashes a given password using a specified hash function. The function also includes a JavaScript function within the same file that reads a configuration file from a specified directory and returns its contents as an object:
```php
<?php

/**
 * Generates a random string of a specified length using a given character set.
 *
 * @param int $length The length of the random string to generate.
 * @param string $characters The character set to use for generating the random string.
 * @return string The generated random string.
 */
function generateRandomString(int $length, string $characters): string
{
    // Generate a random number between 0 and the length of the character set - 1
    $randomNumber = mt_rand(0, strlen($characters) - 1);

    // Use the random number to select a character from the character set
    return substr($characters, $randomNumber, 1);
}

/**
 * Hashes a given password using a specified hash function.
 *
 * @param string $password The password to hash.
 * @param int $hashType The type of hash function to use (e.g., PASSWORD_BCRYPT, PASSWORD_ARGON2I).
 * @return string The hashed password.
 */
function hashPassword(string $password, int $hashType): string
{
    // Generate a random salt using generateRandomString()
    $salt = generateRandomString(16, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');

    // Use the hash function to hash the password with the salt
    return hash($hashType, $password . $salt);
}

/**
 * Reads a configuration file from a specified directory and returns its contents as an object.
 *
 * @param string $directory The directory where the configuration file is located.
 * @param string $filename The name of the configuration file (without the extension).
 * @return stdClass|false An object representing the configuration file's contents, or false on error.
 */
function readConfigurationFile(string $directory, string $filename): stdClass|false
{
    // Check if the directory exists and is readable
    if (!is_dir($directory) || !is_readable($directory)) {
        return false;
    }

    // Get the full path to the configuration file
    $filePath = realpath($directory . '/' . $filename . '.json');

    // Check if the file exists and is readable
    if (!file_exists($filePath) || !is_readable($filePath)) {
        return false;
    }

    // Read the contents of the configuration file
    $contents = file_get_contents($filePath);

    // Check if the contents are valid JSON
    if (!$contents || !json_decode($contents)) {
        return false;
    }

    // Return the object representing the configuration file's contents
    return json_decode($contents, true);
}
```
