function collectData(stream) {
  let array = [];
  let config = getConfig();

  stream.on('data', (chunk) => {
    array.push(chunk);
  });

  stream.on('end', () => {
    console.log(`Collected ${array.length} chunks`);
    saveToFile(array, config);
  });
}

