    if (fp == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    // Allocate memory for the configuration structure and its sections
    section_t* config = malloc(sizeof(section_t));
    if (config == NULL) {
        printf("Error allocating memory: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    // Read the file and process any external dependencies
    int num_sections = 0;
    while (fscanf(fp, "%s", config[num_sections].name) == 1) {
        if (config[num_sections].name[0] == '[') {
            // Process the section name
            config[num_sections].name = strdup(config[num_sections].name + 1);
            num_sections++;
        } else {
            // Read the value for the current section
            fscanf(fp, "%d", &config[num_sections-1].value);
        }
    }

    // Close the file and return the number of sections
    fclose(fp);
    return num_sections;
}
