    // Copy the original filename to the modified filename
    strcpy(modifiedFilename, filename);

    // Find the last occurrence of a period in the filename
    int periodIndex = -1;
    for (int i = len - 1; i >= 0; i--) {
        if (filename[i] == '.') {
            periodIndex = i;
            break;
        }
    }

    // If there is no extension, append ".txt" to the filename
    if (periodIndex == -1) {
        strcat(modifiedFilename, fileType);
    } else {
        // Modify the last extension of the filename
        sprintf(modifiedFilename + periodIndex + 1, "%0*d%s", numDigits, len, fileType);
    }

    // Ensure that the modified filename does not exceed a maximum length of 255 characters
    if (strlen(modifiedFilename) > 255) {
        modifiedFilename[255] = '\0';
    }

    return modifiedFilename;
}']

