        strcmp(token, "rsa") == 0) {
      algorithm_list[num_algorithms++] = token;
    }
    token = strtok(NULL, " ");
  }

  // Dynamically load and initialize additional libraries for unsupported algorithms
  if (strstr(algorithms, "rsa") != NULL) {
    SHA1_load();
