    } else if (strcmp(algorithm, "md5") == 0) {
      MD5_integrate();
    } else if (strcmp(algorithm, "sha") == 0) {
      SHA_integrate();
    } else if (strcmp(algorithm, "rsa") == 0) {
      RSA_integrate();
    } else {
      printf("Error: unsupported algorithm %s\n", algorithm);
      result = -1;
      break;
    }
  }

  // Clean up loaded libraries and resources
