AES_CTX *initCipher(const char *password) {
    AES_CTX *ctx = NULL;

    // Determine the key length based on the password length
    size_t keyLen = 256;
    if (strlen(password) < 16) {
        keyLen = 128;
    } else if (strlen(password) < 32) {
        keyLen = 192;
    }

    // Determine the IV length based on the system constraints
