        return NULL;
    }

    // Create a new file with the generated IV as its name
    char filename[256];
    snprintf(filename, sizeof(filename), "%d", (int)iv);
    cache->cacheFile = fopen(filename, "wb");
    if (cache->cacheFile == NULL) {
        perror("Failed to create theme cache file");
        return NULL;
    }

    // Set the encryption key for the theme cache
    unsigned char salt[16];
    SHA256((unsigned char *)"theme_cache", 10, salt);
    PKCS5_PBKDF2_HMAC_SHA1("theme_cache", strlen("theme_cache"), salt, 1000, 256, cache->key);

    // Free memory for the initialization vector
    free(iv);

    return cache;
}

// Function to clean up and disable the theme cache
void deinitThemeCache(struct ThemeCache *cache) {
    if (cache != NULL) {
        fclose(cache->cacheFile);
        free(cache->key);
        free(cache);
    }
}

// Function to recycle a theme bitmap and set it to null
void recycleThemeBitmap(struct ThemeCache *cache, unsigned char *bitmap) {
    if (cache == NULL || bitmap == NULL) {
        return;
    }

    // Write the bitmap data to the theme cache file
    fwrite(bitmap, 1, 4096, cache->cacheFile);

    // Set the bitmap to null
    memset(bitmap, 0, 4096);
}

