    if (ctx == NULL) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return;
    }
    unsigned char decrypted[4096];
    AES_cbc_decrypt(pngData, read, &ctx->aes, decrypted);

    // Set the PNG data as the theme bitmap
    setThemeBitmap(decrypted);

    // Clean up and disable the cipher context
    deinitCipher(ctx);
}
