        // Build the full path to the file
        sprintf(file, "%s/%s", dir, ep->d_name);

        // Try to remove the file up to three times before giving up
        int i = 0;
        while (i < 3) {
            if (!unlink(file)) {
                break;
            } else {
                ++i;
