public static class TripleDesDecryption
{
    public static string Decrypt(string base64EncodedMessage, string key, string iv)
    {
        // Validate input parameters
        if (base64EncodedMessage == null || key == null || iv == null)
        {
            throw new ArgumentException("Invalid input parameters", nameof(base64EncodedMessage));
        }

        if (key.Length != 24 || iv.Length != 8)
        {
            throw new ArgumentException($"Key and IV must be exactly 24 characters long and 8 characters long respectively.", nameof(key), nameof(iv));
        }

        // Base64 decode the message
        byte[] decodedMessage;
        try
        {
            decodedMessage = Convert.FromBase64String(base64EncodedMessage);
        }
        catch (FormatException ex)
        {
            Console.WriteLine($"Invalid base64 encoded string: {ex.Message}");
            return null;
        }

        // Triple DES decrypt the message
        byte[] plainText = null;
        try
        {
            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Encoding.ASCII.GetBytes(key);
                tripleDes.IV = Encoding.ASCII.GetBytes(iv);

                using (MemoryStream ms = new MemoryStream(decodedMessage))
                {
                    plainText = tripleDes.CreateDecryptor().TransformFinalBlock(ms.ToArray(), 0, decodedMessage.Length);
                }
            }
        }
        catch (CryptographicException ex)
        {
            Console.WriteLine($"Error while decrypting message: {ex.Message}");
            return null;
        }

        // Return the plain text
        return Encoding.UTF8.GetString(plainText);
    }
}
```
