import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.logging.Level;
import java.util.logging.Logger;

public class SerializationHelper {
  private static final Logger LOGGER = Logger.getLogger(SerializationHelper.class.getName());

  public static <T> T deserialize(byte[] serializedObject) throws IOException, ClassNotFoundException {
    try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(serializedObject))) {
      return (T) ois.readObject();
    } catch (ClassNotFoundException | IOException e) {
      LOGGER.log(Level.ERROR, "Failed to deserialize object", e);
      throw new RuntimeException("Failed to deserialize object");
    }
  }
}
