            int request_interval = config.request_interval;

            // create Sandesh client for remote monitoring service
            auto sandesh_client = boost::make_shared<SandeshClient>(io_ctx, server_endpoint);

            // loop until connection is established
            while (true) {
                try {
                    // establish connection with remote monitoring service
                    boost::asio::ip::tcp::socket socket(io_ctx);
                    boost::asio::connect(socket, socket.lowest_layer().resolve({server_endpoint}));

                    // create proxy session for Sandesh client
                    auto proxy_session = boost::make_shared<SandeshProxySession>(sandesh_client, socket);

                    // loop until all vertices and edges are added to the graph database
                    while (true) {
                        // add vertices and edges from configuration file or user input
