                    // send request and receive response from remote monitoring service
                    boost::asio::async_write(socket, request, yield);
                    boost::asio::streambuf response;
                    boost::asio::async_read(socket, response, yield);

                    // extract metadata IP address from response
                    std::string metadata_ip = extractMetadataIpFromResponse(response.data());

                    // find VM UUID from metadata IP address
                    bool found_vm_uuid = FindVmUuidFromMetadataIp(metadata_ip);

                    // log metrics for successful connection and requests
                    if (found_vm_uuid) {
                        std::cout << "Successful connection to remote monitoring service" << std::endl;
                        std::cout << "Requests: " + std::to_string(request.size()) << std::endl;
                        std::cout << "Active proxy sessions: " + std::to_string(proxy_session->activeSessions()) << std::endl;
                    } else {
