                        std::cout << "Requests: " + std::to_string(request.size()) << std::endl;
                        std::cout << "Active proxy sessions: " + std::to_string(proxy_session->activeSessions()) << std::endl;
                    }

                    // break loop if connection is successful or all retries are exhausted
                    if (found_vm_uuid || retries == MAX_RETRIES) {
                        break;
                    }

                    // retry failed connections after specified interval
                    std::this_thread::sleep_for(std::chrono::milliseconds(request_interval));
                } catch (const boost::system::system_error& e) {
                    std::cout << "Error connecting to remote monitoring service: " << e.what() << std::endl;

                    // break loop if all retries are exhausted
                    if (retries == MAX_RETRIES) {
