}

fn transfer_file(data: Vec<u8>) -> Result<(), Box<dyn std::error::Error>> {
    // Transfer the file here
    Ok(())
}

fn check_status(data: Vec<u8>) -> Result<(), Box<dyn std::error::Error>> {
