const MAX_CONCURRENT_CREATIONS: usize = 1000;

struct DirectoryCreator {
    env: Arc<Mutex<HashMap<String, PathBuf>>>,
}

impl DirectoryCreator {
    fn new() -> Self {
        DirectoryCreator {
            env: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn create_directory(&self, name: &str) -> Result<(), Error> {
        let mut env = self.env.lock().unwrap();
        if let Some(path) = env.get(name) {
            Ok(())
        } else {
            let path = PathBuf::from(&format!("{}.{}", name, env::current_pid()));
            fs::create_dir(&path).map_err(|e| Error::new("failed to create directory", e))?;
            env.insert(name.to_owned(), path);
            Ok(())
        }
    }

    fn cleanup(&self, name: &str) {
        let mut env = self.env.lock().unwrap();
        if let Some(path) = env.get(name) {
            fs::remove_dir(path).unwrap();
            env.remove(name);
        }
    }
}

struct Error {
    message: String,
    cause: Option<Error>,
}

impl From<std::io::Error> for Error {
    fn from(error: std::io::Error) -> Self {
        Self {
            message: format!("{}", error),
            cause: Some(Self {
                message: "failed to create directory".to_owned(),
                cause: None,
            }),
        }
    }
}

fn main() {
    let creator = DirectoryCreator::new();
    let name = "my-directory";
    match creator.create_directory(name) {
        Ok(_) => println!("created directory {}", name),
        Err(error) => eprintln!("failed to create directory: {}", error),
    }
}
