import json
import datetime
from typing import Any, Dict, List, Union

class JsonParser:
    def __init__(self):
        self._registry = {}

    def validate_json(self, json_string: str) -> bool:
        try:
            json.loads(json_string)
            return True
        except json.JSONDecodeError as e:
            print("Invalid JSON string:", e)
            return False

    def parse_json(self, json_string: str) -> Dict[str, Any]:
        if not self.validate_json(json_string):
            raise ValueError("JSON string is invalid")
        return json.loads(json_string)

    def create_instance_from_id(self, id: str) -> Union[Dict[str, Any], None]:
        if id in self._registry:
            return self._registry[id]()
        else:
            return None

    def add_factory_function(self, id: str, factory_func):
        if id in self._registry:
            raise ValueError("ID is already registered")
        self._registry[id] = factory_func

    def create_instance(self, json_string: str) -> Union[Dict[str, Any], None]:
        try:
            parsed_json = self.parse_json(json_string)
            if "type" in parsed_json and parsed_json["type"] in self._registry:
                return self._registry[parsed_json["type"]](parsed_json)
            else:
                raise ValueError("Invalid type")
        except KeyError as e:
            print("JSON string is missing required key:", e)
        except json.JSONDecodeError as e:
            print("Invalid JSON string:", e)
        return None

    def serialize(self, obj):
        if not isinstance(obj, dict):
            raise ValueError("Object must be a dictionary")
        serialized_json = json.dumps(obj, default=lambda o: getattr(o, "to_dict", lambda: vars(o))())
        return serialized_json

    def deserialize(self, json_string):
        if not isinstance(json_string, str):
            raise ValueError("JSON string must be a string")
        try:
            parsed_json = self.parse_json(json_string)
            if "type" in parsed_json and parsed_json["type"] in self._registry:
                return self._registry[parsed_json["type"]](parsed_json)
            else:
                raise ValueError("Invalid type")
        except KeyError as e:
            print("JSON string is missing required key:", e)
        except json.JSONDecodeError as e:
            print("Invalid JSON string:", e)

class JsonObject:
    def __init__(self):
        self._id = None

    @property
    def id(self):
        return self._id

    @id.setter
    def id(self, value):
        if not isinstance(value, str):
            raise ValueError("ID must be a string")
        self._id = value

class User(JsonObject):
    def __init__(self, json_data=None):
        super().__init__()
        self.name = None
        self.email = None
        if json_data is not None:
            self.from_dict(json_data)

    def from_dict(self, data):
        self.id = data["id"]
        self.name = data["name"]
        self.email = data["email"]

    def to_dict(self):
        return {
            "id": self.id,
            "name": self.name,
            "email": self.email,
        }

class Event(JsonObject):
    def __init__(self, json_data=None):
        super().__init__()
        self.title = None
        self.description = None
        self.date = None
        if json_data is not None:
            self.from_dict(json_data)

    def from_dict(self, data):
        self.id = data["id"]
        self.title = data["title"]
        self.description = data["description"]
        try:
            self.date = datetime.datetime.strptime(data["date"], "%Y-%m-%d")
        except (ValueError, KeyError):
            pass

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "date": self.date.strftime("%Y-%m-%d") if self.date is not None else "",
        }

if __name__ == "__main__":
    json_parser = JsonParser()
    json_parser.add_factory_function("user", User)
    json_parser.add_factory_function("event", Event)

    user = {
        "id": "1234567890",
        "name": "John Doe",
        "email": "johndoe@example.com",
    }
    event = {
        "id": "abcdefghijklmnopqrstuvwxyz",
        "title": "Example Event",
        "description": "This is an example event.",
        "date": "2023-01-01"
    }

    json_string = json.dumps(user)
    parsed_json = json_parser.parse_json(json_string)
    print(parsed_json)

    json_string = json.dumps(event)
    parsed_json = json_parser.parse_json(json_string)
    print(parsed_json)

    serialized_json = json_parser.serialize(user)
    print(serialized_json)

    deserialized_json = json_parser.deserialize(serialized_json)
    print(deserialized_json)']

