['```c++
#include <random>
#include <list>

// Define a namespace for the LTE UE context manager
namespace LteUeContextManager {
  // Define a class for managing UE contexts
  class UeContext {
    private:
      std::mt19937 mt_; // Mersenne Twister random number generator
      std::list<std::pair<int, int>> activeBearers_; // List of active radio bearers with QoS parameters and IDs

    public:
      UeContext(); // Constructor for the class
      ~UeContext(); // Destructor for the class

      void addActiveBearer(int qos, int rbid); // Function to add an active radio bearer with QoS parameters and ID
      void removeActiveBearer(int rbid); // Function to remove an active radio bearer with a given ID

      std::list<std::pair<int, int>> getActiveBearers(); // Function to retrieve the list of active radio bearers
  };

  UeContext::UeContext() : mt_(std::mt19937(std::random_device{}())) { }

  UeContext::~UeContext() { }

  void UeContext::addActiveBearer(int qos, int rbid) {
    activeBearers_.push_back(std::make_pair(qos, rbid));
  }

  void UeContext::removeActiveBearer(int rbid) {
    for (auto it = activeBearers_.begin(); it != activeBearers_.end(); ++it) {
      if ((*it).second == rbid) {
        activeBearers_.erase(it);
        break;
      }
    }
  }

  std::list<std::pair<int, int>> UeContext::getActiveBearers() {
    return activeBearers_;
  }
}
```
