/**
 * Create an EVP_CIPHER structure representing the chosen cipher based on the provided configuration settings.
 * The function returns a pointer to the created EVP_CIPHER structure, or NULL if an error occurred.
 */
EVP_CIPHER* create_cipher(const char* algorithm, const char* mode, int key_length) {
    // Create a new EVP_CIPHER structure based on the provided configuration settings
    EVP_CIPHER* cipher = NULL;

    // Set the encryption mode
    if (strcmp(mode, "cbc") == 0) {
        cipher = EVP_aes_128_cbc();
    } else if (strcmp(mode, "gcm") == 0) {
        cipher = EVP_aes_128_gcm();
    } else if (strcmp(mode, "chacha20") == 0) {
        cipher = EVP_chacha20();
    } else {
        // Unknown encryption mode
        return NULL;
    }

    // Set the key length
    if (key_length != AES_KEYLEN_128 && key_length != AES_KEYLEN_256) {
        // Invalid key length
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    // Set the encryption key
    if (EVP_CipherInit_ex(cipher, algorithm, NULL, NULL, 0) != 1) {
        // Failed to initialize the cipher
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    return cipher;
}
