import java.util.concurrent.ConcurrentHashMap;

public class FileHasher {
    private static final Map<String, String> hashes = new ConcurrentHashMap<>();

    public static Map<String, String> getFileHashes(List<String> filePaths) {
        // Create a new hash map for the file paths and hashes
        Map<String, String> hashMap = new HashMap<>();

        // Iterate over each file path and compute its SHA-256 hash
        for (String filePath : filePaths) {
            try {
                // Use a try-catch block to handle any exceptions thrown by Files.readAllBytes()
                byte[] fileData = Files.readAllBytes(Paths.get(filePath));
                String hash = computeSHA256Hash(fileData);
                hashMap.put(filePath, hash);
            } catch (IOException | NoSuchAlgorithmException e) {
                // If an exception is thrown, print the error message to the console and continue
                System.err.println("Error computing SHA-256 hash for " + filePath + ": " + e.getMessage());
                continue;
            }
        }

        return hashMap;
    }

    private static String computeSHA256Hash(byte[] data) throws NoSuchAlgorithmException {
        // Use a try-catch block to handle any exceptions thrown by MessageDigest.getInstance()
        try {
            MessageDigest digester = MessageDigest.getInstance("SHA-256");
            return digester.digest(data);
        } catch (NoSuchAlgorithmException e) {
            throw new NoSuchAlgorithmException("Error computing SHA-256 hash", e);
        }
    }
}
