        fprintf(stderr, "Error: The record is null or invalid\n");
        exit(1);
    }

    // Return the offset of the existing record
    return (*record)->offset;
}

// Define a function to check if two records are equal
bool are_records_equal(Record** record1, Record** record2) {
    // Check if the records are null or invalid
    if (*record1 == NULL || *record1->magic_number != MAGIC_NUMBER || *record2 == NULL || *record2->magic_number != MAGIC_NUMBER) {
        fprintf(stderr, "Error: The records are null or invalid\n");
        exit(1);
    }

    // Return true if the values and offsets of the two records are equal, false otherwise
    return (*record1)->value == (*record2)->value && (*record1)->offset == (*record2)->offset;
}

// Define a function to check if a record is valid
bool is_record_valid(Record** record) {
    // Check if the record is null or invalid
    if (*record == NULL || *record->magic_number != MAGIC_NUMBER) {
        fprintf(stderr, "Error: The record is null or invalid\n");
        exit(1);
    }

    // Return true if the record is valid, false otherwise
    return (*record)->value == (*record)->value && (*record)->offset == (*record)->offset;
}
