    }

    // Initialize the error flag and memory tracking variables
    int err = 0;
    size_t successful_allocations = 0;
    size_t failed_allocations = 0;

    // Allocate memory for the offset values array
    offset_values = malloc(num_records * sizeof(long));
    if (offset_values == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset values\n");
        err = -1;
    } else {
        successful_allocations++;
    }

    // Allocate memory for the key values array
    key_values = malloc(num_records * sizeof(int));
    if (key_values == NULL) {
        fprintf(stderr, "Failed to allocate memory for key values\n");
        err = -1;
