        successful_allocations++;
    }

    // Allocate memory for the records array
    records = malloc(num_records * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        err = -1;
    } else {
        successful_allocations++;
    }

    // Initialize the offset values and key values arrays
    for (size_t i = 0; i < num_records; i++) {
        offset_values[i] = rand() % max_heap_size;
        key_values[i] = rand();
    }

