    for (size_t i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for record %lu\n", i);
            err = -1;
            break;
        } else {
            successful_allocations++;
        }
        records[i]->key = rand() % max_heap_size;
    }

    // Check if any of the allocations failed and handle them appropriately
    if (err) {
        fprintf(stderr, "Failed to allocate memory for one or more arrays\n");
        free(offset_values);
        free(key_values);
        for (size_t i = 0; i < num_records; i++) {
            if (records[i] != NULL) {
                free(records[i]);
            }
        }
        return -1;
    }

    // Periodically check for available system resources and adjust the number of records allocated accordingly
    size_t num_records_to_allocate = num_records;
    while (num_records_to_allocate > 0) {
        // Check if there is enough memory available to allocate another record
        if (available_heap_space() >= sizeof(Record)) {
            records[num_records - num_records_to_allocate] = malloc(sizeof(Record));
            if (records[num_records - num_records_to_allocate] == NULL) {
                fprintf(stderr, "Failed to allocate memory for record %lu\n", num_records - num_records_to_allocate);
                err = -1;
                break;
            } else {
                successful_allocations++;
            }
            records[num_records - num_records_to_allocate]->key = rand() % max_heap_size;
            num_records_to_allocate--;
        } else {
            // Adjust the number of records to allocate based on available system resources
            num_records_to_allocate = num_records / 2;
        }
    }

    // Handle any failed allocations and return the appropriate error code
    if (num_records_to_allocate > 0) {
        fprintf(stderr, "Failed to allocate memory for %lu records\n", num_records - num_records_to_allocate);
        free(offset_values);
        free(key_values);
        for (size_t i = 0; i < num_records; i++) {
            if (records[i] != NULL) {
                free(records[i]);
            }
        }
        return -1;
    }

    // Return the arrays and records allocated by the function
    return 0;
}

// Define a function to check for available system resources (e.g., available heap space)
size_t available_heap_space() {
    struct mallinfo mem_info = mallinfo();
    size_t free_memory = mem_info.fordblks;
    return free_memory - (mem_info.uordblks + mem_info.arena);
}
