  unsigned char key[32];
} EncryptionContext;

// Function to initialize a new encryption context
int initEncryption(EncryptionContext *ctx, const unsigned char *key, int key_len) {
  if (!ctx || !key || key_len != 16 && key_len != 32) {
    return -1;
  }

  // Initialize the EVP context with the appropriate cipher and key length
  ctx->ctx = EVP_CIPHER_CTX_new();
  if (!ctx->ctx) {
    return -1;
  }
  switch (key_len) {
    case 16:
      EVP_EncryptInit(ctx->ctx, EVP_AES_128_ECB(), key, NULL);
      break;
    case 32:
      EVP_EncryptInit(ctx->ctx, EVP_AES_256_ECB(), key, NULL);
      break;
  }

  // Set the IV generation strategy based on the chosen cipher mode
  switch (EVP_CIPHER_CTX_get_cipher(ctx->ctx)) {
    case EVP_aes_128_ecb():
      ctx->iv = EVP_CIPHER_CTX_get_iv(ctx->ctx);
      break;
    case EVP_aes_256_ecb():
      ctx->iv = EVP_CIPHER_CTX_get_iv(ctx->ctx);
      break;
  }

  return 0;
}

// Function to encrypt data using the selected cipher and key
int encryptData(EncryptionContext *ctx, const unsigned char *data, int data_len) {
  if (!ctx || !data || data_len <= 0) {
    return -1;
  }

  // Set the input and output lengths
  EVP_CIPHER_CTX_set_padding(ctx->ctx, 0);
  int in_len = data_len;
  int out_len = in_len + AES_BLOCK_SIZE - (in_len % AES_BLOCK_SIZE);

  // Encrypt the data using the EVP context
  unsigned char *out_buf = malloc(out_len);
  if (!out_buf) {
    return -1;
  }
  int len = EVP_EncryptUpdate(ctx->ctx, out_buf, &out_len, data, in_len);
  if (len <= 0) {
    free(out_buf);
    return -1;
  }
  out_buf[out_len] = '\0';

  // Return the encrypted data as a string
  return out_buf;
}

// Function to decrypt data using the selected cipher and key
int decryptData(EncryptionContext *ctx, const unsigned char *data, int data_len) {
  if (!ctx || !data || data_len <= 0) {
    return -1;
  }

  // Set the input and output lengths
  EVP_CIPHER_CTX_set_padding(ctx->ctx, 0);
  int in_len = data_len;
  int out_len = in_len + AES_BLOCK_SIZE - (in_len % AES_BLOCK_SIZE);

  // Decrypt the data using the EVP context
  unsigned char *out_buf = malloc(out_len);
  if (!out_buf) {
    return -1;
  }
  int len = EVP_DecryptUpdate(ctx->ctx, out_buf, &out_len, data, in_len);
  if (len <= 0) {
    free(out_buf);
    return -1;
  }
  out_buf[out_len] = '\0';

  // Return the decrypted data as a string
  return out_buf;
}

// Function to generate an initialization vector (IV) for the selected cipher and mode
unsigned char *genIV(const unsigned char *cipher, int mode) {
  if (!cipher || mode <= 0) {
    return NULL;
  }

  // Generate a random IV using OpenSSL's RAND_bytes function
  unsigned char *iv = malloc(AES_BLOCK_SIZE);
  if (!iv) {
    return NULL;
  }
  RAND_bytes(iv, AES_BLOCK_SIZE);

  // Return the generated IV
  return iv;
}

// Function to handle errors during encryption and decryption operations
int handleError(EncryptionContext *ctx) {
  if (!ctx) {
    return -1;
  }

  // Handle error by printing an appropriate message and freeing the context
  printf("Error occurred during encryption/decryption operation\n");
  EVP_CIPHER_CTX_free(ctx->ctx);
  return -1;
}
