// Define a struct for holding the cipher context and its associated semaphore
struct CipherContext {
    EVP_CIPHER_CTX *ctx;
    sem_t *sem;
};

// Define an array of semaphores for each supported cipher mode
#define NUM_CIPHERS 4
static sem_t *cipher_sem[NUM_CIPHERS];

// Define a function to initialize the cipher context and its associated semaphore
int init_cipher_context(EVP_CIPHER_CTX **ctx, const char *cipher_mode) {
    // Initialize the EVP_CIPHER_CTX structure for the specified cipher mode
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Set the cipher mode and key length for the specified cipher mode
    switch (cipher_mode[0]) {
        case 'E':
            EVP_CIPHER_CTX_set_key_length(*ctx, 16);
            break;
        case 'D':
            EVP_CIPHER_CTX_set_key_length(*ctx, 24);
            break;
        default:
            // Unsupported cipher mode
            return 0;
    }
    EVP_CIPHER_CTX_ctrl(*ctx, EVP_CTRL_SET_MODE, cipher_mode[1] - '0', NULL);

    // Initialize the semaphore for this cipher context
    if (cipher_sem[cipher_mode[1] - '0'] == NULL) {
        cipher_sem[cipher_mode[1] - '0'] = sem_open("cipher", O_CREAT, 0644, 1);
        if (cipher_sem[cipher_mode[1] - '0'] == SEM_FAILED) {
            perror("sem_open");
            return 0;
        }
    }

    // Return a pointer to the EVP_CIPHER structure
    return 1;
}

// Define a function to perform encryption or decryption using the specified cipher mode and key
int encrypt_decrypt(const char *cipher_mode, const unsigned char *key, const size_t key_len, const unsigned char *data, const size_t data_len) {
    // Initialize the cipher context for the specified cipher mode and key
    EVP_CIPHER_CTX *ctx;
    if (!init_cipher_context(&ctx, cipher_mode)) {
        return 0;
    }

    // Set the encryption or decryption key and data for the cipher context
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, key_len) == 0 || EVP_Cipher(ctx, NULL, data, data_len) == 0) {
        ERR_print_errors_fp(stderr);
        return 0;
