    // Perform the encryption or decryption using the cipher context
    if (EVP_EncryptFinal_ex(ctx, NULL, NULL) == 0) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Release the semaphore for this cipher context
    if (sem_wait(cipher_sem[cipher_mode[1] - '0']) == -1) {
        perror("sem_wait");
        return 0;
    }

    // Clean up the cipher context and its associated semaphore
    EVP_CIPHER_CTX_free(ctx);
    sem_unlink("cipher");

    // Return 1 to indicate success
    return 1;
}

