    return (seed = (seed * 1664525 + 1013904223));
}

// Define structure to hold record data
typedef struct {
    int value;
} record_t;

// Define function to dynamically allocate memory for arrays and structures based on runtime parameters
void init_arrays(long* offset_arr, int* key_arr, record_t** record_arr, size_t num_offsets, size_t num_keys) {
    // Initialize successful and failed allocation counters
    size_t alloc_success = 0;
    size_t alloc_failure = 0;

    // Allocate memory for offset array
    if (offset_arr == NULL) {
        offset_arr = malloc(num_offsets * sizeof(long));
        if (offset_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }

    // Allocate memory for key array
    if (key_arr == NULL) {
        key_arr = malloc(num_keys * sizeof(int));
        if (key_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }

    // Allocate memory for record array
    if (record_arr == NULL) {
        record_arr = malloc(num_offsets * sizeof(record_t*));
        if (record_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }

    // Initialize each record structure with a random value
    for (size_t i = 0; i < num_offsets; i++) {
        record_arr[i] = malloc(sizeof(record_t));
        if (record_arr[i] == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
            record_arr[i]->value = my_rand();
        }
    }

    // Print allocation statistics and return
    printf("Allocation Statistics:\n");
    printf("\tSuccessful Allocations: %zu\n", alloc_success);
    printf("\tFailed Allocations: %zu\n", alloc_failure);
}

// Define function to periodically check system resources and dynamically allocate memory if necessary
void check_resources(long* offset_arr, int* key_arr, record_t** record_arr, size_t num_offsets, size_t num_keys) {
    // Check available heap space every 100th iteration
