    if (counter++ % 100 == 0) {
        // Print heap usage statistics
        printf("Heap Usage Statistics:\n");
        printf("\tCurrent Heap Size: %zu\n", malloc_size(NULL));
        printf("\tMaximum Heap Size: %zu\n", malloc_max_size());
    }

    // Dynamically allocate memory for arrays and structures if necessary
    size_t alloc_success = 0;
    size_t alloc_failure = 0;
    if (offset_arr == NULL) {
        offset_arr = realloc(offset_arr, num_offsets * sizeof(long));
        if (offset_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }
    if (key_arr == NULL) {
        key_arr = realloc(key_arr, num_keys * sizeof(int));
        if (key_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }
    if (record_arr == NULL) {
        record_arr = realloc(record_arr, num_offsets * sizeof(record_t*));
        if (record_arr == NULL) {
            alloc_failure++;
        } else {
            alloc_success++;
        }
    }

    // Initialize each record structure with a random value
    for (size_t i = 0; i < num_offsets; i++) {
