#include <json-c/json.h>

typedef struct {
    int intValue;
    float floatValue;
    char *strValue;
} DataItem;

const char *wordList[] = {"apple", "banana", "cherry", "date", "elderberry"};

DataItem *initialize_data(size_t count) {
    DataItem *items = malloc(count * sizeof(DataItem));
    if (!items) {
        return NULL;
    }

    // Retrieve word list from external data source
    CURL *curl = curl_easy_init();
    if (!curl) {
        free(items);
        return NULL;
    }

    curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/word-list");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeToBuffer);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &jsonBuffer);
    curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        free(items);
        return NULL;
    }

    json_object *root = json_tokener_parse(jsonBuffer.data);
    if (!root) {
        free(items);
        return NULL;
    }

    // Iterate through the word list and initialize each data item
    int i = 0;
    json_object_foreach(root, key, value) {
        DataItem *item = &items[i++];
        if (value->type != json_type_string) {
            continue;
        }

        char *word = strdup(json_object_get_string(value));
        item->intValue = rand() % 100;
        item->floatValue = (float)rand() / RAND_MAX;
        item->strValue = word;
    }

    curl_easy_cleanup(curl);
    json_object_put(root);
    return items;
}

// Helper function to write JSON data to a buffer
static size_t writeToBuffer(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct curl_buffer *mem = (struct curl_buffer *)userp;

    mem->data = realloc(mem->data, mem->size + realsize + 1);
    if (!mem->data) {
        return 0;
    }

    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}
```
