// Helper function to validate if a given string is a valid floating-point number
bool isValidNumber(const char* str) {
    int i = 0;
    while (str[i] != '\0' && !isdigit(str[i])) {
        ++i;
    }
    return str[i] == '.' || str[i] == 'e';
}

// Function to read a list of floating-point numbers from standard input, store them in an array, and find the largest number using a helper function
void findLargestNumber(float* numbers, int size) {
    // Initialize variables
    float largest = -INFINITY;
    int i = 0;

    // Read floating-point numbers from standard input until reaching the end of file or reaching the maximum number of elements to read (1000)
    while (i < size && scanf("%f", &numbers[i]) == 1) {
        ++i;
    }

    // Find and print the largest number in the array using a helper function
    if (i > 0) {
        printf("Largest number: %g\n", findLargestNumberHelper(numbers, i));
