}

// Helper function to find the largest number in an array of floating-point numbers
float findLargestNumberHelper(const float* numbers, int size) {
    // Initialize variables
    float largest = -INFINITY;
    int i = 0;

    // Iterate over the array and compare each element to the current largest number
    while (i < size && isValidNumber(numbers[i])) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
        ++i;
    }

    // Return the largest number
    return largest;
}

int main() {
    // Initialize variables
    float numbers[1000];
    int size = 0;

    // Read floating-point numbers from standard input and store them in an array
    while (size < 1000 && scanf("%f", &numbers[size]) == 1) {
        ++size;
    }

    // Find and print the largest number in the array using a helper function
