['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define NAME_SIZE 10
#define ITEM_NAME_SIZE 5
#define NODE_NAME_SIZE 10
#define COUNT 4

struct item {
    int value;
    char name[ITEM_NAME_SIZE];
    struct item *next;
};

struct node {
    char name[NODE_NAME_SIZE];
    struct node *next;
};

void initialize_data(double *floats, char **strings_items, struct item **items, char **strings_nodes, struct node **nodes, size_t count) {
    // Allocate memory for the arrays
    floats = (double *)malloc(sizeof(double) * COUNT);
    strings_items = (char **)malloc(sizeof(char *) * COUNT);
    items = (struct item **)malloc(sizeof(struct item *) * COUNT);
    strings_nodes = (char **)malloc(sizeof(char *) * COUNT);
    nodes = (struct node **)malloc(sizeof(struct node *) * COUNT);

    if (!floats || !strings_items || !items || !strings_nodes || !nodes) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    // Initialize the arrays
    for (size_t i = 0; i < COUNT; i++) {
        floats[i] = rand() % 100;

        strings_items[i] = (char *)malloc(sizeof(char) * ITEM_NAME_SIZE);
        items[i] = (struct item *)malloc(sizeof(struct item));

        if (!strings_items[i] || !items[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }

        snprintf(strings_items[i], ITEM_NAME_SIZE, "item%d", i);
        items[i]->name = strings_items[i];
        items[i]->value = floats[i];
        items[i]->next = NULL;

        strings_nodes[i] = (char *)malloc(sizeof(char) * NODE_NAME_SIZE);
        nodes[i] = (struct node *)malloc(sizeof(struct node));

        if (!strings_nodes[i] || !nodes[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }

        snprintf(strings_nodes[i], NODE_NAME_SIZE, "node%d", i);
        nodes[i]->name = strings_nodes[i];
        nodes[i]->next = NULL;
    }

    // Read initial values for the name field of each struct item from a CSV file
    FILE *items_file = fopen("items.csv", "r");
    if (!items_file) {
        fprintf(stderr, "Error: Failed to open items.csv file.\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), items_file)) {
        char *name = strtok(line, ",");
        if (!name) continue;

        int i = 0;
        for ( ; i < COUNT; i++) {
            if (strcmp(name, strings_items[i]) == 0) break;
        }

        if (i >= COUNT) continue;

        char *value = strtok(NULL, ",");
        if (!value) continue;

        items[i]->value = atoi(value);
    }

    fclose(items_file);

    // Read initial values for the name field of each struct node from a CSV file
    FILE *nodes_file = fopen("nodes.csv", "r");
    if (!nodes_file) {
        fprintf(stderr, "Error: Failed to open nodes.csv file.\n");
        return;
    }

    while (fgets(line, sizeof(line), nodes_file)) {
        char *name = strtok(line, ",");
        if (!name) continue;

        int i = 0;
        for ( ; i < COUNT; i++) {
            if (strcmp(name, strings_nodes[i]) == 0) break;
        }

        if (i >= COUNT) continue;

        nodes[i]->next = NULL;
    }

    fclose(nodes_file);
