    struct active_bearers *active_bearers; // List of active bearers for the UE
} ue_context_t;

// Function to add a new UE context to the list
int add_ue_context(uint64_t id, uint32_t serving_cell_id) {
    int ret = 0;
    pthread_mutex_lock(&ue_context_list_lock);

    // Validate that N (the number of UE contexts to manage) is within a reasonable range
    if (N < 1 || N > 100) {
        ret = -1;
    } else {
        ue_context_t *ue_ctx = malloc(sizeof(ue_context_t));
        if (!ue_ctx) {
            ret = -2; // Memory allocation failure
        } else {
            ue_ctx->id = id;
            ue_ctx->serving_cell_id = serving_cell_id;
