    return ret;
}

// Function to remove an existing UE context from the list
int remove_ue_context(uint64_t id) {
    int ret = 0;
    pthread_mutex_lock(&ue_context_list_lock);

    // Find the UE context with the specified ID and remove it from the list
    ue_context_t *ue_ctx = find_in_list(&ue_context_list, id);
    if (!ue_ctx) {
        ret = -1; // UE context not found
    } else {
        ret = remove_from_list(&ue_context_list, ue_ctx);
    }

    pthread_mutex_unlock(&ue_context_list_lock);
    return ret;
}

// Function to update an existing UE context in the list with new information
int update_ue_context(uint64_t id, uint32_t serving_cell_id) {
    int ret = 0;
    pthread_mutex_lock(&ue_context_list_lock);

    // Find the UE context with the specified ID and update its serving cell ID
    ue_context_t *ue_ctx = find_in_list(&ue_context_list, id);
    if (!ue_ctx) {
        ret = -1; // UE context not found
    } else {
        ue_ctx->serving_cell_id = serving_cell_id;
    }

    pthread_mutex_unlock(&ue_context_list_lock);
    return ret;
}
