        printf("Error: unable to prepare statement\n");
        exit(1);
    }

    // Define parameters for the SQL query
    char *supervisorId = "10";
    sqlite3_bind_text(stmt, 1, supervisorId, strlen(supervisorId), SQLITE_STATIC);

    // Execute the SQL query and retrieve results
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        char *name = (char*) sqlite3_column_text(stmt, 0);
        printf("%s\n", name);
        char *city = (char*) sqlite3_column_text(stmt, 1);
        printf("%s\n", city);
        char *address = (char*) sqlite3_column_text(stmt, 2);
