#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

// Semaphore structure to hold the semaphore value and active operation count
struct Semaphore {
    int value;
    int active_ops;
};

// Global semaphore map to keep track of all semaphores
static std::map<std::string, struct Semaphore> semaphore_map;

// Logging function to log semaphore operations for debugging purposes
void log_semaphore_operation(const std::string& operation, const std::string& semaphore_name) {
    printf("Semaphore operation: %s\n", operation.c_str());
    printf("\tSemaphore name: %s\n", semaphore_name.c_str());
}

// Initialize a semaphore with the specified initial value
void initialize_semaphore(const std::string& semaphore_name, int init_value) {
    struct Semaphore* semaphore = new struct Semaphore;
    semaphore->value = init_value;
    semaphore->active_ops = 0;
    semaphore_map[semaphore_name] = *semaphore;
}

// Destroy a semaphore and delete it from the semaphore map
void destroy_semaphore(const std::string& semaphore_name) {
    struct Semaphore* semaphore = &semaphore_map[semaphore_name];
    if (semaphore->active_ops > 0) {
        printf("Error: Cannot destroy semaphore with active operations\n");
        return;
    }
    semaphore_map.erase(semaphore_name);
}

// Wait on a semaphore and decrement the value by one
void wait_on_semaphore(const std::string& semaphore_name) {
    struct Semaphore* semaphore = &semaphore_map[semaphore_name];
    if (semaphore->value <= 0) {
        printf("Error: Semaphore value is less than or equal to zero\n");
        return;
    }
    log_semaphore_operation("Wait", semaphore_name);
    semaphore->active_ops++;
}

// Signal on a semaphore and increment the value by one
void signal_on_semaphore(const std::string& semaphore_name) {
    struct Semaphore* semaphore = &semaphore_map[semaphore_name];
    log_semaphore_operation("Signal", semaphore_name);
    semaphore->value++;
    semaphore->active_ops--;
}

// Main function to demonstrate the use of the semaphore management functions
int main() {
    // Initialize a semaphore with an initial value of 5
    initialize_semaphore("my_semaphore", 5);

    // Create multiple threads that wait and signal on the semaphore
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy the semaphore and clean up resources
    destroy_semaphore("my_semaphore");

    return 0;
}

// Thread function to demonstrate waiting and signaling on a semaphore
void* thread_function(void* arg) {
    wait_on_semaphore("my_semaphore");
    printf("Thread %lu: Semaphore value is now %d\n", pthread_self(), get_semaphore_value("my_semaphore"));
    signal_on_semaphore("my_semaphore");
    return NULL;
}

// Get the current value of a semaphore
int get_semaphore_value(const std::string& semaphore_name) {
    struct Semaphore* semaphore = &semaphore_map[semaphore_name];
    return semaphore->value;
}']

