    srand(time(NULL));

    // Check if any of the input sizes is zero and return immediately if so
    if (offsetSize == 0 || keySize == 0 || recordSize == 0) {
        return;
    }

    // Dynamically allocate memory for each array
    long *offsets = malloc(offsetSize * sizeof(long));
    int *keys = malloc(keySize * sizeof(int));
    record_t *records = malloc(recordSize * sizeof(record_t));

    // Initialize the arrays with random values and labels
    for (size_t i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % 1000;
    }
    for (size_t i = 0; i < keySize; i++) {
        keys[i] = rand() % 1000;
    }
    for (size_t i = 0; i < recordSize; i++) {
        records[i].value = rand() % 1000;
        sprintf(records[i].label, "Record%d", i);
    }

    // Memory management: ensure proper cleanup and avoid leaks
    free(offsets);
    free(keys);
    free(records);
}
