        if (!data[i].data) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i + 1);
            exit(1);
        }
    }
}

// Function to insert a new record into the data structure
void insert_record(int key, int* data) {
    // Lock the mutex before accessing the data array
    pthread_mutex_lock(&data_mutex);

    // Find the first empty slot in the data array
    int i;
    for (i = 0; i < num_records; i++) {
        if (data[i].key == 0) {
            break;
        }
    }

    // Check if there is an empty slot available
    if (i == num_records) {
        fprintf(stderr, "No empty slots available\n");
        pthread_mutex_unlock(&data_mutex);
        return;
    }

    // Insert the new record into the data array
    data[i].key = key;
    memcpy(data[i].data, data, record_size * sizeof(int));

    // Unlock the mutex after accessing the data array
    pthread_mutex_unlock(&data_mutex);
}

// Function to retrieve a record from the data structure
void* get_record(int key) {
    // Lock the mutex before accessing the data array
    pthread_mutex_lock(&data_mutex);

    // Find the record with the given key in the data array
    int i;
    for (i = 0; i < num_records; i++) {
        if (data[i].key == key) {
            break;
        }
    }

    // Check if the record exists
    if (i == num_records) {
        fprintf(stderr, "Record with key %d does not exist\n", key);
        pthread_mutex_unlock(&data_mutex);
        return NULL;
    }

    // Return a pointer to the record
    void* record = data[i].data;

    // Unlock the mutex after accessing the data array
    pthread_mutex_unlock(&data_mutex);

    return record;
}

// Function to delete a record from the data structure
void delete_record(int key) {
    // Lock the mutex before accessing the data array
    pthread_mutex_lock(&data_mutex);

    // Find the record with the given key in the data array
    int i;
    for (i = 0; i < num_records; i++) {
        if (data[i].key == key) {
            break;
        }
    }

    // Check if the record exists
    if (i == num_records) {
        fprintf(stderr, "Record with key %d does not exist\n", key);
        pthread_mutex_unlock(&data_mutex);
        return;
    }

    // Remove the record from the data array
    memcpy(data[i].data, data[i + 1], (num_records - i - 1) * sizeof(record_t));
    num_records--;

    // Unlock the mutex after accessing the data array
    pthread_mutex_unlock(&data_mutex);
}

// Function to update a record in the data structure
void update_record(int key, int* data) {
    // Lock the mutex before accessing the data array
    pthread_mutex_lock(&data_mutex);

    // Find the record with the given key in the data array
    int i;
    for (i = 0; i < num_records; i++) {
        if (data[i].key == key) {
            break;
        }
    }

    // Check if the record exists
    if (i == num_records) {
        fprintf(stderr, "Record with key %d does not exist\n", key);
        pthread_mutex_unlock(&data_mutex);
        return;
    }

    // Update the record in the data array
    memcpy(data[i].data, data, record_size * sizeof(int));

    // Unlock the mutex after accessing the data array
    pthread_mutex_unlock(&data_mutex);
}

// Function to free the memory allocated for the data structure
void free_memory() {
    // Lock the mutex before accessing the data array
    pthread_mutex_lock(&data_mutex);

    // Free the memory allocated for the data array
    free(data);

    // Unlock the mutex after accessing the data array
    pthread_mutex_unlock(&data_mutex);
}

// Main function
int main() {
    // Initialize the data structure
    init();

    // Insert records into the data structure
    insert(1, 5);
    insert(2, 6);
    insert(3, 7);

    // Retrieve a record from the data structure
