// Function to dynamically allocate memory for arrays
void initialize_arrays(int num_records, int offset_min, int offset_max, int key_min, int key_max) {
    // Check if input parameters are valid
    if (num_records <= 0 || offset_min < 0 || offset_max < offset_min || key_min < 0 || key_max < key_min) {
        return;
    }

    // Calculate the total size of memory needed for arrays
    int num_offsets = num_records + 1;
    int num_keys = num_records * sizeof(int);
    int num_bytes = (num_offsets * sizeof(long) + num_keys);

    // Check if total memory size exceeds the maximum allowed size
    if (num_bytes > MAX_MEMORY_SIZE) {
        return;
    }

    // Dynamically allocate memory for arrays
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(num_keys);

    // Initialize arrays with random values within given range
    srand(time(NULL));
    offsets[0] = 0;
    for (int i = 1; i < num_offsets; ++i) {
        offsets[i] = rand() % (offset_max - offset_min + 1) + offset_min;
    }
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (key_max - key_min + 1) + key_min;
    }

    // Return pointers to arrays and their sizes
    return offsets, num_offsets, keys, num_records;
}

// Structure for storing records with 'int' keys
struct record {
