};

// Function to initialize an array of 'record' structures
void initialize_records(int num_records) {
    // Check if input parameter is valid
    if (num_records <= 0) {
        return;
    }

    // Dynamically allocate memory for the array
    struct record* records = malloc(sizeof(struct record) * num_records);

    // Initialize each record with a random value within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % 1000 + 1;
    }

    // Return pointer to array and its size
    return records, num_records;
}

// Function to handle external data sources for initial offset values
void initialize_offsets(int* offsets, int num_offsets) {
    // Check if input parameters are valid
    if (offsets == NULL || num_offsets <= 0) {
        return;
    }

    // Initialize arrays with external data source values
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = get_external_data(i);
    }
}

// Function to handle potential changes in the size of external data sources or record structures
void resize_arrays(int* offsets, int num_offsets, int* keys, int num_records) {
    // Check if input parameters are valid
    if (offsets == NULL || num_offsets <= 0 || keys == NULL || num_records <= 0) {
        return;
    }

    // Reallocate memory for arrays to match new size
    offsets = realloc(offsets, sizeof(long) * num_offsets);
    keys = realloc(keys, num_records * sizeof(int));
