// Structure to represent a record with an int field and a char array
typedef struct {
    int key;
    char label[10];
} Record;

// Function to initialize and allocate memory for records
void init_records(int size, int* offsets, int* keys, Record** records) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Allocate memory for the offset array
    if ((offsets = malloc(size * sizeof(*offsets))) == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset values
    for (int i = 0; i < size; i++) {
        offsets[i] = i * sizeof(Record);
    }

    // Allocate memory for the key array
    if ((keys = malloc(size * sizeof(*keys))) == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for keys\n");
        return;
    }

    // Initialize the key values
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 1000 + 1;
    }

    // Allocate memory for the record array
    if ((records = malloc(size * sizeof(*records))) == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return;
    }

    // Initialize the record structures
    for (int i = 0; i < size; i++) {
        records[i].key = keys[i];
        snprintf(records[i].label, sizeof(records[i].label), "Record %d", i);
    }
}

// Function to sort the records in ascending order based on their int values
void sort_records(int size, Record** records) {
    // Use a quicksort algorithm to sort the records
    for (int i = 0; i < size - 1; i++) {
        int min = i;
        for (int j = i + 1; j < size; j++) {
            if (records[j].key < records[min].key) {
                min = j;
            }
        }
        Record temp = records[i];
        records[i] = records[min];
        records[min] = temp;
    }
}

// Function to filter the records based on a specified key range
void filter_records(int size, int min_key, int max_key, Record** records) {
    // Initialize a new array for the filtered records
    Record* filtered_records = malloc(size * sizeof(*filtered_records));
    if (filtered_records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for filtered records\n");
        return;
    }

    // Count the number of records that fall within the specified key range
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (records[i].key >= min_key && records[i].key <= max_key) {
            count++;
        }
    }

    // Allocate memory for the filtered records
    filtered_records = malloc(count * sizeof(*filtered_records));
    if (filtered_records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for filtered records\n");
        return;
    }

    // Copy the filtered records into the new array
    count = 0;
    for (int i = 0; i < size; i++) {
        if (records[i].key >= min_key && records[i].key <= max_key) {
            filtered_records[count++] = records[i];
        }
    }
}

// Function to save the initialized data to a file in a structured format
void save_to_file(int size, Record** records, const char* filename) {
    // Open the output file for writing
    FILE* out = fopen(filename, "wb");
    if (out == NULL) {
        fprintf(stderr, "Error: failed to open output file '%s' for writing\n", filename);
        return;
    }

    // Write the records to the output file
    for (int i = 0; i < size; i++) {
        Record* record = &records[i];
        fprintf(out, "%d,%s\n", record->key, record->label);
    }

    // Close the output file
    fclose(out);
}
