    // Set the remote address and port in the sockaddr_in structure
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(atoi(port));
    if (inet_pton(AF_INET, addr, &serv_addr.sin_addr) <= 0) {
