// C Function to Establish TCP Socket Connection
void connect_to_server(char* server_ip, int server_port) {
  // Create a socket object
  struct sockaddr_in server;
  memset(&server, 0, sizeof(server));
  server.sin_family = AF_INET;
  server.sin_addr.s_addr = inet_addr(server_ip);
  server.sin_port = htons(server_port);

  // Create a TCP socket
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket failed");
    exit(1);
  }

  // Connect to server
  if (connect(sock, (struct sockaddr*)&server, sizeof(server)) < 0) {
    perror("connect failed");
    exit(1);
  }

  // Set the socket to be non-blocking
  int flags = fcntl(sock, F_GETFL, 0);
  if (flags == -1 || fcntl(sock, F_SETFL, flags | O_NONBLOCK) < 0) {
    perror("fcntl failed");
    exit(1);
  }

  // Start a new thread to handle the connection
  pthread_t tid;
  if (pthread_create(&tid, NULL, handle_connection, sock)) {
    perror("pthread_create failed");
    exit(1);
  }
}

// Function to handle the connection in a separate thread
void* handle_connection(void* arg) {
  int sock = (int)arg;

  // Initialize arrays for offset, key, and record structures
  long offset_array[MAX_ARRAY_SIZE];
  int key_array[MAX_ARRAY_SIZE];
  record rec_array[MAX_ARRAY_SIZE];

  // Set the value of each record's double field to a random value within a specified range
  for (int i = 0; i < MAX_ARRAY_SIZE; ++i) {
    rec_array[i].value = ((double)rand() / RAND_MAX) * MAX_VALUE_RANGE + MIN_VALUE_RANGE;
  }

  // Loop until the connection is closed or an error occurs
  while (true) {
    // Read from the socket into a buffer
    char* buffer = malloc(BUFFER_SIZE);
    int read_size = recv(sock, buffer, BUFFER_SIZE, 0);
    if (read_size < 0) {
      perror("recv failed");
      break;
    } else if (read_size == 0) {
      // Connection closed by the remote server
      break;
    }

    // Parse the data in the buffer and update the arrays accordingly
    for (int i = 0; i < read_size; ++i) {
      offset_array[i] = buffer[i];
      key_array[i] = buffer[i + 1];
      rec_array[i].value = *((double*)buffer + 2);
    }

    // Free the buffer since it is no longer needed
    free(buffer);
  }

  // Close the socket and exit the thread
  close(sock);
  pthread_exit(NULL);
}
