// Recursive Function to Traverse DOM Tree
function traverseDOM(element, selector) {
  // Check if the current element matches the selector
  if (element.matches(selector)) {
    return [element];
  }

  // Iterate over all child elements and recurse on them
  let results = [];
  for (let i = 0; i < element.childNodes.length; ++i) {
    results = results.concat(traverseDOM(element.childNodes[i], selector));
  }

  return results;
}
