    free(events[index].payload);

    // Shift all events after the deleted one to the left
    for (int i = index; i < numEvents - 1; ++i) {
        memcpy(&events[i], &events[i + 1], sizeof(struct Event));
    }

    // Decrement the number of events and free the last event
    --numEvents;
    free(events[numEvents]);
}

