        perror("Error getting address info");
        return -1;
    }

    // Copy the IP address into the u_char array
    memcpy(ip_address, res->ai_addr, res->ai_addrlen);

    // Free the address info structure
    freeaddrinfo(res);

    return 0;
}

// Function to read a log file and process each line dynamically
void read_log_file(char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    // Allocate memory for the longest line in the log file
    size_t max_line_length = 0;
    char* line = NULL;
    size_t len = 0;
    while ((len = getline(&line, &max_line_length, fp)) != -1) {
        // Dynamically allocate memory for the line
        char** fields = (char**)malloc(sizeof(char*) * len);
        if (fields == NULL) {
            perror("Error allocating memory for line");
            return;
        }

        // Split the line into fields using strtok()
        int field_count = 0;
        char* token = strtok(line, ",");
        while (token != NULL) {
            fields[field_count++] = token;
            token = strtok(NULL, ",");
        }

        // Process each field in the line
        for (int i = 0; i < field_count; i++) {
            if (i == 0) {
                // Handle the first field (hostname)
                char* hostname = fields[i];
                u_char ip_address[4];
                if (dns_resolve(hostname, ip_address) != 0) {
                    perror("Error resolving DNS");
                    return;
                }
                printf("%s,%u.%u.%u.%u\n", hostname, ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
            } else {
                // Handle the remaining fields (average of last two fields)
                char* field = fields[i];
                int value = atoi(field);
                if (value == 0) {
                    perror("Error converting field to integer");
                    return;
                }
                printf("%s,%d\n", field, value / 2);
            }
        }

        // Free the memory allocated for the line
        free(fields);
    }

    // Free the memory allocated for the longest line
    if (line != NULL) {
        free(line);
    }

    fclose(fp);
}

// Function to read a list of integers from standard input and store them in an array
void read_integer_list() {
    int* list = malloc(sizeof(int));
    if (list == NULL) {
        perror("Error allocating memory for integer list");
        return;
    }

    // Read the list of integers from standard input
    int i, n;
    for (i = 0; scanf("%d", &n) != EOF; i++) {
        if (i == 0) {
            // Allocate memory for the first integer
            list[i] = n;
        } else {
            // Reallocate memory for the next integer
            list = realloc(list, sizeof(int) * (i + 1));
            if (list == NULL) {
                perror("Error reallocating memory for integer list");
                return;
            }
            // Set the value of the next integer
            list[i] = n;
        }
    }

    // Print the contents of the list
    printf("Integer list: ");
    for (i = 0; i < n; i++) {
        printf("%d ", list[i]);
    }
    printf("\n");

    free(list);
}

// Function to allocate memory for and initialize two arrays: one for long offset values and one for int keys
void allocate_arrays() {
    // Allocate memory for the array of long offsets
    long* offsets = malloc(sizeof(long) * 10);
    if (offsets == NULL) {
        perror("Error allocating memory for long offset array");
        return;
    }

    // Initialize each value in the array with a random long offset value within a given range
    int i, j;
    srand(time(NULL));
    for (i = 0; i < 10; i++) {
        offsets[i] = rand() % 1000000 + 1;
    }

    // Print the contents of the array
    printf("Long offset values: ");
    for (i = 0; i < 10; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");

    // Allocate memory for the array of int keys
    int* keys = malloc(sizeof(int) * 10);
    if (keys == NULL) {
        perror("Error allocating memory for int key array");
        return;
    }

    // Initialize each value in the array with a random integer key within a given range
    for (i = 0; i < 10; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Print the contents of the array
    printf("Integer keys: ");
    for (i = 0; i < 10; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
}

int main() {
    read_integer_list();
    allocate_arrays();
    return 0;
}
```

This program uses a variety of techniques to illustrate the concepts of memory management and error handling. It includes:

