    for (int i = 0; i < initial_size; i++) {
        offsets[i] = rand() % random_value_range;
        keys[i] = i + 1;
        records[i].value = rand() % random_value_range;
    }

    // Define variable to track number of successfully initialized records
    int num_records = initial_size;

    // Define error mechanism for memory allocation and random value generation failures
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Memory allocation failed. Exiting...\n");
        return 1;
    } else if (rand() % 10 > 8) {
        printf("Error: Random value generation failed. Exiting...\n");
        return 1;
    }

    // Define loop to resize arrays when necessary
    while (num_records >= initial_size) {
        // Allocate new memory block for records
        long *new_offsets = realloc(offsets, (num_records + growth_increment) * sizeof(long));
        int *new_keys = realloc(keys, (num_records + growth_increment) * sizeof(int));
        record *new_records = realloc(records, (num_records + growth_increment) * sizeof(record));

        // Check for memory allocation failures
        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            printf("Error: Memory allocation failed. Exiting...\n");
            return 1;
        }

        // Update variables to point to new memory block
        offsets = new_offsets;
        keys = new_keys;
        records = new_records;

        // Resize arrays and structures
        for (int i = initial_size; i < num_records + growth_increment; i++) {
            offsets[i] = rand() % random_value_range;
            keys[i] = i + 1;
            records[i].value = rand() % random_value_range;
        }

        // Increment number of records
        num_records += growth_increment;
    }

    // Define function to handle synchronization and return record structure
    void sync_and_return(record *record) {
        pthread_mutex_lock(&mutex);
        printf("Thread %d returned value: %d\n", pthread_self(), record->value);
        pthread_mutex_unlock(&mutex);
    }

    // Define loop to handle multiple threads concurrently
    for (int i = 0; i < num_records; i++) {
        // Spawn new thread to access database and return value
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, sync_and_return, &records[i]);
    }

    // Free memory for arrays of offsets, keys, and records
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
