// Define a structure to store DNS query results
typedef struct {
    char ip_address[16]; // IP address in an array of 16 characters
} dns_result_t;

// Function to perform DNS resolution for a given hostname
int dns_resolve(char* hostname, dns_result_t* result) {
    struct addrinfo hints, *addr_list;
    int status, i;

    // Initialize the addrinfo structure with flags and query type
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM; // TCP

    if ((status = getaddrinfo(hostname, NULL, &hints, &addr_list)) != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(status));
        return EXIT_FAILURE;
    }

    // Loop through the list of results and find the first IPv4 address
    for (i = 0; addr_list != NULL; i++) {
        if (addr_list->ai_family == AF_INET) {
            // Convert the sockaddr structure to a human-readable string
            getnameinfo(addr_list->ai_addr, addr_list->ai_addrlen, result->ip_address, sizeof(result->ip_address), NULL, 0, NI_NUMERICHOST);
            freeaddrinfo(addr_list); // Free the memory allocated for this result
            return EXIT_SUCCESS;
        }
    }

    // If no IPv4 address was found, return an error code
    fprintf(stderr, "No IPv4 address found for %s\n", hostname);
    return EXIT_FAILURE;
}
