// Function to convert an image file to a PDF using a third-party tool
int convert_image_to_pdf(const char* input_file, const char* output_dir, int max_retries) {
    // Check if the input file exists
    if (!input_file || !input_file[0]) {
        fprintf(stderr, "Error: Input file does not exist\n");
        return -1;
    }

    // Check if the output directory exists and has sufficient space available
    struct stat dir_stat;
    if (stat(output_dir, &dir_stat) == 0 && dir_stat.st_size >= 1024 * 1024 * 512) { // 512 MB
        fprintf(stderr, "Error: Insufficient space available in output directory\n");
        return -2;
    }

    // Allocate memory for the command line arguments
    const size_t argv_size = 7;
    char* argv[argv_size];

    // Set the command line arguments
    argv[0] = "convert";
    argv[1] = "-density";
    argv[2] = "300";
    argv[3] = "-quality";
    argv[4] = "85";
    argv[5] = input_file;
    argv[6] = output_dir;

    // Execute the conversion command and monitor the disk space in the output directory
    int retries = 0;
    while (1) {
        FILE* pipe = popen("du -ks | awk '{print $1}'", "r");
        char buf[256];
        size_t dir_size = 0;
        if (fgets(buf, sizeof(buf), pipe)) {
            sscanf(buf, "%zu", &dir_size);
        }
        pclose(pipe);

        // Check if the output directory has sufficient space available
        if (dir_size < 1024 * 1024 * 512) { // 512 MB
            retries++;
            if (retries > max_retries) {
                fprintf(stderr, "Error: Maximum number of retries exceeded\n");
                return -3;
            } else {
                continue;
            }
        }

        // Execute the conversion command
        int status = system("convert -density 300 -quality 85 input_file output_dir");
        if (status == 0) {
            return 0;
        } else {
            fprintf(stderr, "Error: Conversion failed with status %d\n", status);
            return -4;
        }
    }
}

// Function to handle dynamic memory allocation and deallocation for the record array
