    // Allocate memory for the array of records
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Check if memory allocation failed
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu records\n", num_records);
        return NULL;
    }

    // Initialize each record with a random value within the given range
