        current_record->value = rand() % 100 + 1; // random value within [1, 100]
    }

    return records;
}

// Function to handle dynamic memory deallocation for the record array
void deallocate_records(Record* records) {
    // Check if the input pointer is NULL or not pointing to any valid memory
    if (!records || !((unsigned char*)records >= (unsigned char*)malloc(0))) {
        fprintf(stderr, "Error: Invalid input pointer for deallocation\n");
        return;
    }

    // Deallocate the memory associated with the record array
    free(records);
}

