    int *rank = (int *)malloc(num_sensors * sizeof(int));

    // Initialize the Union-Find data structure
    for (i = 0; i < num_sensors; i++) {
        parent[i] = i;
        rank[i] = 1;
    }

    // Start timer to measure time taken to initialize sensor data
    start = clock();

    // Initialize the Union-Find data structure for each temperature reading
    for (i = 0; i < num_sensors; i++) {
        int root = find_root(parent, rank, i);
        temperatures[i] /= 100; // divide by 100 to reduce precision
        keys[i] = root;
    }

    // End timer and calculate time taken to initialize sensor data
    end = clock();
    time_taken = (double)(end - start) / CLOCKS_PER_SEC * 1000;

    // Find disjoint pairs of elements in the array of sensor data based on their temperature readings
    for (i = 0; i < num_sensors; i++) {
        int root1 = find_root(parent, rank, keys[i]);
        for (j = i + 1; j < num_sensors; j++) {
            int root2 = find_root(parent, rank, keys[j]);
            if (temperatures[i] != temperatures[j]) continue;
            if (root1 == root2) continue;
            // Merge the sets containing elements i and j
            merge_sets(parent, rank, root1, root2);
            num_pairs++;
        }
    }

    // Print the number of milliseconds taken to perform the check for each pair
    printf("Time taken: %.3f ms\n", time_taken);

    // Free memory allocated for arrays
    free(temperatures);
    free(keys);
    free(parent);
    free(rank);

    return num_pairs;
}

// Function to find the root of an element in the Union-Find data structure
int find_root(int *parent, int *rank, int i) {
    if (i == parent[i]) return i;
    else return find_root(parent, rank, parent[i]);
}

// Function to merge two sets in the Union-Find data structure
void merge_sets(int *parent, int *rank, int x, int y) {
    if (rank[x] < rank[y]) {
        parent[x] = y;
    } else if (rank[x] > rank[y]) {
        parent[y] = x;
    } else {
        parent[y] = x;
        rank[x]++;
    }
}
