typedef struct record {
    int key;
    long offset;
    float value;
} record_t;

// Union-Find data structure to efficiently check for disjoint pairs of elements in the array of records
typedef struct uf_node {
    int parent;
    int rank;
} uf_node_t;

int num_disjoint_pairs = 0;

// Function to initialize arrays and records dynamically
int init_arrays(config_t *config) {
    // Allocate memory for offset array
    long *offset_arr = (long *)malloc(sizeof(long) * config->num_records);
    if (!offset_arr) {
        fprintf(stderr, "Failed to allocate memory for offset array: %s\n", strerror(errno));
