    }

    // Allocate memory for value array
    float *value_arr = (float *)malloc(sizeof(float) * config->num_records);
    if (!value_arr) {
        fprintf(stderr, "Failed to allocate memory for value array: %s\n", strerror(errno));
        return -1;
    }

    // Initialize value array with random values within specified range
    srand(config->seed);
    for (int i = 0; i < config->num_records; i++) {
        value_arr[i] = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }

    // Allocate memory for record array
    record_t *record_arr = (record_t *)malloc(sizeof(record_t) * config->num_records);
    if (!record_arr) {
        fprintf(stderr, "Failed to allocate memory for record array: %s\n", strerror(errno));
        return -1;
    }

    // Initialize records with values from offset, key, and value arrays
    for (int i = 0; i < config->num_records; i++) {
        record_arr[i].key = key_arr[i];
        record_arr[i].offset = offset_arr[i];
        record_arr[i].value = value_arr[i];
    }

    // Print memory allocation details for debugging purposes
    printf("Offset array size: %ld bytes\n", sizeof(long) * config->num_records);
    printf("Key array size: %d bytes\n", sizeof(int) * config->num_records);
    printf("Value array size: %f bytes\n", sizeof(float) * config->num_records);
    printf("Record array size: %ld bytes\n", sizeof(record_t) * config->num_records);

    // Return the number of disjoint pairs found after checking for disjointness
    return num_disjoint_pairs;
}

// Function to check for disjoint pairs of elements in the array of records based on their 'int' values
int find_disjoint_pairs(record_t *record_arr, int size) {
    // Initialize Union-Find data structure for checking disjointness
    uf_node_t *uf_nodes = (uf_node_t *)malloc(sizeof(uf_node_t) * size);
    if (!uf_nodes) {
        fprintf(stderr, "Failed to allocate memory for Union-Find data structure: %s\n", strerror(errno));
        return -1;
    }

    // Initialize Union-Find data structure with each node as its own parent and rank 0
    for (int i = 0; i < size; i++) {
        uf_nodes[i].parent = i;
        uf_nodes[i].rank = 0;
    }

    // Check for disjoint pairs by finding the root node for each 'int' value in the array
    int num_disjoint_pairs = 0;
    for (int i = 0; i < size - 1; i++) {
        int key_i = record_arr[i].key;
        int parent_i = find(uf_nodes, key_i);

        // Skip this pair if the keys are already connected in the Union-Find data structure
        if (parent_i == key_i) {
            continue;
        }

        // Find the root node for each 'int' value in the next record
        int key_j = record_arr[i + 1].key;
        int parent_j = find(uf_nodes, key_j);

        // If the keys are not connected in the Union-Find data structure, connect them with a union operation
        if (parent_j != key_j) {
            union(uf_nodes, parent_i, parent_j);
            num_disjoint_pairs++;
        }
    }

    // Print the number of disjoint pairs found for debugging purposes
    printf("Number of disjoint pairs found: %d\n", num_disjoint_pairs);

    // Return the number of disjoint pairs found
    return num_disjoint_pairs;
}

// Union-Find algorithm operations
int find(uf_node_t *uf_nodes, int key) {
    while (key != uf_nodes[key].parent) {
        key = uf_nodes[key].parent;
    }
    return key;
}

void union(uf_node_t *uf_nodes, int parent_i, int parent_j) {
    if (uf_nodes[parent_i].rank > uf_nodes[parent_j].rank) {
        uf_nodes[parent_j].parent = parent_i;
    } else {
        uf_nodes[parent_i].parent = parent_j;
        if (uf_nodes[parent_i].rank == uf_nodes[parent_j].rank) {
            uf_nodes[parent_j].rank++;
        }
    }
}

int main() {
