using namespace std;

struct OffsetKey {
  int offset;
  string key;
};

class MemoryManager {
 public:
  MemoryManager() : memory_usage_(0), peak_memory_usage_(0) {}

  ~MemoryManager() {
    cout << "Total memory usage: " << memory_usage_ << endl;
    cout << "Peak memory usage: " << peak_memory_usage_ << endl;
  }

  void* allocate(size_t size) {
    if (size == 0) {
      return nullptr;
    }
    mutex_.lock();
    void* memory = malloc(size);
    if (memory != nullptr) {
      memory_usage_ += size;
      peak_memory_usage_ = max(peak_memory_usage_, memory_usage_);
    }
    mutex_.unlock();
    return memory;
  }

  void deallocate(void* memory, size_t size) {
    if (size == 0 || memory == nullptr) {
      return;
    }
    mutex_.lock();
    free(memory);
    memory_usage_ -= size;
    mutex_.unlock();
  }

 private:
  size_t memory_usage_;
  size_t peak_memory_usage_;
  mutex mutex_;
};

