        memory_manager_(new MemoryManager()),
        mutexes_(),
        cond_var_(new condition_variable()) {}

  ~DataInitializer() { delete memory_manager_; }

  void start() {
    for (int i = 0; i < num_records_; ++i) {
      OffsetKey offset_key;
      generateOffsetKey(offset_key);
      storeOffsetKey(offset_key);
    }
    cond_var_->notify_all();
  }

  void join() { cond_var_->wait(); }

 private:
