    }
    offset_key.key = key;
  }

  void storeOffsetKey(const OffsetKey& offset_key) {
    // Store the generated values in the data array.
    mutexes_[offset_key.offset].lock();
    data_[offset_key.offset] = offset_key.key;
    mutexes_[offset_key.offset].unlock();
  }

