      }
      mutexes_[offset_key.offset].lock();
      data_.push_back(data[offset_key.offset]);
      mutexes_[offset_key.offset].unlock();
    }
  }

  int num_records_;
  int offset_size_;
  int key_size_;
  int data_size_;
  map<int, string> data_;
  MemoryManager* memory_manager_;
  vector<mutex> mutexes_;
  condition_variable* cond_var_;
};

