int init_records(record **records, size_t n) {
    if (n == 0) {
        return -1; // No records to initialize
    }

    // Allocate memory for the arrays
    long *offsets = malloc(sizeof(long) * n);
    int *keys = malloc(sizeof(int) * n);
    record *records_arr = malloc(sizeof(record) * n);
    if (offsets == NULL || keys == NULL || records_arr == NULL) {
        // Memory allocation failed
        free(offsets);
        free(keys);
        free(records_arr);
        return -2; // Out of memory error
    }

    // Initialize the arrays
    for (size_t i = 0; i < n; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        records_arr[i].value = 0;
        records_arr[i].offset_ptr = &offsets[i];
        records_arr[i].key_ptr = &keys[i];
    }

    // Store the arrays in a single memory block
    void *block = malloc(sizeof(long) * n + sizeof(int) * n + sizeof(record) * n);
    if (block == NULL) {
        free(offsets);
        free(keys);
        free(records_arr);
        return -2; // Out of memory error
    }

    memcpy(block, offsets, sizeof(long) * n);
    memcpy((char *) block + sizeof(long) * n, keys, sizeof(int) * n);
    memcpy((char *) block + sizeof(long) * n + sizeof(int) * n, records_arr, sizeof(record) * n);

    // Free the temporary arrays
    free(offsets);
    free(keys);
    free(records_arr);

    *records = block;

    return 0; // Success
}

void cleanup_records(record **records) {
    if (*records != NULL) {
        void *block = *records;
        size_t n = *((size_t *) block);
        free(block);
        *records = NULL;
    }
}
