            return NULL; // Error handling: unable to allocate memory
        }

        void *memory = malloc(size);
        if (memory != NULL) {
            current_pool_size -= size;
            current_pool->size -= size;
        }
        return memory;
    }

    void deallocate(void *memory) {
        // Deallocate memory back to pool
        if (current_pool == NULL || current_pool->memory != memory) {
            return; // Error handling: invalid deallocation attempt
        }

        free(memory);
        current_pool->size += sizeof(record_t);
        current_pool = NULL;
