#include <pthread.h>
#include <stdbool.h>

// Struct to hold socket information
typedef struct {
    int sock;
    bool connected;
} socket_t;

// Function to establish a TCP connection using connection pooling
socket_t establish_connection(const char *host, const char *port) {
    // Initialize the socket structure
    socket_t socket = {0};

    // Try to connect to the host and port specified
    while (1) {
        socket.sock = socket(AF_INET, SOCK_STREAM, 0);
        if (socket.sock == -1) {
            fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
            sleep(1);
            continue;
        } else {
            break;
        }
    }

    // Set the address family and port number
    struct sockaddr_in server_address = {0};
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(atoi(port));

    // Try to connect to the host and port specified
    while (1) {
        if (connect(socket.sock, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
            fprintf(stderr, "Error connecting to server: %s\n", strerror(errno));
            close(socket.sock);
            sleep(1);
            continue;
        } else {
            break;
        }
    }

    // Set the socket as non-blocking
    int flags = fcntl(socket.sock, F_GETFL, 0);
    if (flags == -1 || fcntl(socket.sock, F_SETFL, flags | O_NONBLOCK) == -1) {
        fprintf(stderr, "Error setting non-blocking socket: %s\n", strerror(errno));
        close(socket.sock);
        return (socket_t){0};
    }

    // Set the connected flag to true
    socket.connected = true;

    return socket;
}

// Function to manage a pool of connections and allocate sockets from it
int manage_connections(const char *host, const char *port, int num_connections) {
    // Initialize the connection pool
    struct connection_pool *pool = NULL;

    // Try to establish the specified number of connections
    while (num_connections > 0) {
        socket_t socket = establish_connection(host, port);
        if (!socket.connected) {
            fprintf(stderr, "Error establishing connection: %s\n", strerror(errno));
            close(socket.sock);
            sleep(1);
            continue;
        } else {
            // Add the socket to the pool
            struct connection_pool *new_pool = malloc(sizeof(struct connection_pool));
            new_pool->next = pool;
            new_pool->socket = socket.sock;
            pool = new_pool;
            num_connections--;
        }
    }

    // Return the number of connections allocated
    return (int)pool;
}

// Function to close a connection and release its resources
void close_connection(socket_t socket) {
    if (close(socket.sock) == -1) {
        fprintf(stderr, "Error closing socket: %s\n", strerror(errno));
    }
}
