int main() {
    // Open the external text file for reading
    FILE* fp = fopen("identifiers.txt", "r");
    if (fp == NULL) {
        printf("Error: Unable to open file.\n");
        return 1;
    }

    // Read unique identifiers from the file
    char identifier[256];
    int numIdentifiers = 0;
    while (fscanf(fp, "%s", identifier) != EOF) {
        numIdentifiers++;
    }
    fclose(fp);

    // Allocate memory for the arrays
    long* offsets = malloc(numIdentifiers * sizeof(long));
    int* keys = malloc(numIdentifiers * sizeof(int));
    double* values = malloc(numIdentifiers * sizeof(double));
    DataRecord* dataRecords = malloc(numIdentifiers * sizeof(DataRecord));

    // Initialize the arrays and allocate memory for each identifier string
    int i;
    for (i = 0; i < numIdentifiers; i++) {
        offsets[i] = i;
        keys[i] = i + 1;
        values[i] = i * 0.1;
        dataRecords[i].id = i + 1;
        dataRecords[i].value = i * 0.1;
        dataRecords[i].string = malloc(strlen(identifier) + 1);
        strcpy(dataRecords[i].string, identifier);
    }

    // Clean up and exit
    free(offsets);
    free(keys);
    free(values);
    for (i = 0; i < numIdentifiers; i++) {
        free(dataRecords[i].string);
    }
    free(dataRecords);
    return 0;
}
