// Function to dynamically allocate memory for and initialize an array of 'node' structures
Node** create_nodes(int num_nodes, long* offsets, float* weights) {
    if (num_nodes <= 0 || !offsets || !weights) {
        return NULL;
    }

    // Allocate memory for the array of nodes and initialize each node's offset and weight values
    Node** nodes = malloc(sizeof(Node*) * num_nodes);
    if (!nodes) {
        return NULL;
    }
    for (int i = 0; i < num_nodes; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            free(nodes);
            return NULL;
        }
        node->value = weights[i];
        node->next = NULL;
        node->aux_data = NULL;  // Optional auxiliary data structure (e.g., hash table)
        nodes[i] = node;
    }

    // Initialize the offset values for each node
    for (int i = 0; i < num_nodes; i++) {
        nodes[i]->offset = offsets[i];
    }

    return nodes;
}

// Function to traverse the linked list and print the values of each node
void traverse_and_print(Node** nodes) {
