        Node* node = nodes[i];
        printf("%d: %f\n", node->offset, node->value);
        if (node->aux_data) {
            // Print the optional auxiliary data structure (e.g., hash table)
            // ...
        }
    }
}

// Function to add nodes to the list while maintaining order based on their offset values
void add_nodes(Node** nodes, int num_new_nodes, long* new_offsets, float* new_weights) {
    if (!nodes || !new_offsets || !new_weights) {
        return;
    }

    // Allocate memory for the new nodes and initialize each node's offset and weight values
    Node** new_nodes = malloc(sizeof(Node*) * num_new_nodes);
    if (!new_nodes) {
        return;
    }
    for (int i = 0; i < num_new_nodes; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            free(new_nodes);
            return;
        }
        node->value = new_weights[i];
        node->next = NULL;
        node->aux_data = NULL;  // Optional auxiliary data structure (e.g., hash table)
        new_nodes[i] = node;
    }

    // Initialize the offset values for each new node
    for (int i = 0; i < num_new_nodes; i++) {
        new_nodes[i]->offset = new_offsets[i];
    }

    // Insert the new nodes into the list in order based on their offset values
    int curr_idx = 0;
    for (int i = 0; i < num_new_nodes; i++) {
        while (curr_idx < num_nodes && nodes[curr_idx]->offset <= new_offsets[i]) {
            curr_idx++;
        }
        if (curr_idx == num_nodes) {
            // Insert the new node at the end of the list
            Node* node = new_nodes[i];
            nodes[num_nodes - 1]->next = node;
            node->next = NULL;
            num_nodes++;
        } else {
            // Insert the new node before the current node in the list
            Node* node = new_nodes[i];
            node->next = nodes[curr_idx];
            nodes[curr_idx - 1]->next = node;
            num_nodes++;
        }
    }
}

// Function to delete a node from the list and maintain order based on their offset values
void delete_node(Node** nodes, int index) {
    if (!nodes || index < 0 || index >= num_nodes) {
        return;
    }

    // Remove the node at the specified index from the list
    Node* node = nodes[index];
    if (index == 0) {
        // The deleted node is at the beginning of the list
        nodes[0]->next = node->next;
    } else if (index == num_nodes - 1) {
        // The deleted node is at the end of the list
        nodes[num_nodes - 2]->next = NULL;
    } else {
        // The deleted node is in the middle of the list
        nodes[index - 1]->next = node->next;
    }
    num_nodes--;
}

// Function to free all dynamically allocated memory
void free_memory(Node** nodes) {
    if (!nodes) {
        return;
    }
    for (int i = 0; i < num_nodes; i++) {
        Node* node = nodes[i];
        if (node->aux_data) {
            // Free the optional auxiliary data structure (e.g., hash table)
            // ...
        }
        free(node);
    }
    free(nodes);
}
