int main(int argc, char** argv) {
    // Check for proper usage
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [number of records]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_records = atoi(argv[1]);
    if (num_records <= 0 || num_records > 1000) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        return EXIT_FAILURE;
    }

    // Generate random seed from system metrics
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    srand((unsigned int)ts.tv_sec * 1000 + (unsigned int)ts.tv_nsec / 1000000);

    // Allocate memory for offset and key arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for arrays\n");
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    // Generate offset and key values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = get_offset();
        keys[i] = get_key(offsets[i]);
    }

    // Allocate memory for record structures
    struct record* records = malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    // Initialize record structures with key values
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
    }

    // Free memory upon exit, even in the case of errors
    atexit(free_memory);

    return EXIT_SUCCESS;
}

// Generate random offset value based on current system load
long get_offset() {
    long offset = (long)((double)RAND_MAX * system_load());
    return offset;
}

// Generate random key value for given offset
int get_key(long offset) {
    int key = rand() % 2000 - 1000;
    return key;
}

// Return current system load as a floating-point value between 0 and 1
double system_load() {
    // Implement a simple method to calculate system load based on CPU utilization
    double cpu_utilization = (float)sysconf(_SC_NPROCESSORS_ONLN) / (float)sysconf(_SC_NPROC_ONLN);
    return cpu_utilization;
}

// Free memory allocated for arrays and record structures
void free_memory() {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}
