  angular.module('myApp', []).controller('MyController', MyController);

  function MyController($scope, $http) {
    $scope.offsetValues = [];
    $scope.keyValues = [];
    $scope.records = [];

    // Refresh dialog fields using resource ID and URL
    $scope.refresh = function() {
      const url = 'https://example.com/api/data';
      const params = {
        offset_values: $scope.offsetValues,
        key_values: $scope.keyValues
      };

      // Send message to parent window with field name
      $http.post(url, params).then((response) => {
        if (response.data.success) {
          const fieldNames = ['offset_values', 'key_values'];
          for (let i = 0; i < fieldNames.length; i++) {
            const fieldName = fieldNames[i];
            if ($scope[fieldName].includes(response.data.field)) {
              $scope[fieldName][$scope[fieldName].indexOf(response.data.field)] = response.data.value;
            }
          }
        }
      }).catch((error) => {
        console.log('Error:', error);
      });
    };
  }
})();
