// Additionally, the function should allocate memory for and initialize an array of 'record' structures, where each record contains a single 'int' value.
void allocate_memory(long **offsets, int **keys, Record **records) {
    // Allocate memory for the offset and key arrays
    *offsets = (long *)malloc(sizeof(long) * 10);
    *keys = (int *)malloc(sizeof(int) * 10);

    // Initialize the offset and key arrays to zero
    memset(*offsets, 0, sizeof(long) * 10);
    memset(*keys, 0, sizeof(int) * 10);

    // Allocate memory for the record array
    *records = (Record *)malloc(sizeof(Record) * 10);

    // Initialize each record in the record array with a random value within the given range
    for (int i = 0; i < 10; i++) {
        (*records)[i].value = rand() % 100 + 1;
    }
}

// Function to handle dynamically changing ranges for the random values assigned to each record's int field.
void update_ranges(long *offsets, int *keys, Record *records) {
    // Update the offset and key arrays with new values
    for (int i = 0; i < 10; i++) {
        offsets[i] = rand() % 100 + 1;
        keys[i] = rand() % 100 + 1;
    }

    // Update each record in the record array with a new random value within the given range
    for (int i = 0; i < 10; i++) {
        records[i].value = rand() % 100 + 1;
    }
}

// Function to handle dynamically changing sizes of the arrays and records.
void update_sizes(long **offsets, int **keys, Record **records) {
    // Reallocate memory for the offset and key arrays with a new size
    *offsets = (long *)realloc(*offsets, sizeof(long) * 10);
    *keys = (int *)realloc(*keys, sizeof(int) * 10);

    // Initialize any newly allocated memory to zero
    memset(*offsets + 10, 0, sizeof(long) * 10 - 10);
    memset(*keys + 10, 0, sizeof(int) * 10 - 10);

    // Reallocate memory for the record array with a new size
    *records = (Record *)realloc(*records, sizeof(Record) * 10);
}
