// Define the record structure
typedef struct {
    int key;
    double value;
    char* string;
} Record;

// Define the maximum allowed size for each array
#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 1000
#define MAX_VALUE_SIZE 1000
#define MAX_STRING_SIZE 256

// Define the external configuration file format
typedef struct {
    int num_records;
    int max_offset_size;
    int max_key_size;
    int max_value_size;
    int max_string_size;
} ConfigFileFormat;

// Define the function that initializes the arrays and reads the configuration file
int init_arrays(ConfigFileFormat* config) {
    // Check if the configuration file is missing or invalid
    if (config == NULL || config->num_records <= 0) {
        fprintf(stderr, "Invalid configuration file\n");
        return -1;
    }

    // Allocate memory for the arrays
    long* offset_array = malloc(sizeof(long) * MAX_OFFSET_SIZE);
    int* key_array = malloc(sizeof(int) * MAX_KEY_SIZE);
    double* value_array = malloc(sizeof(double) * MAX_VALUE_SIZE);
    char** string_array = malloc(sizeof(char*) * MAX_STRING_SIZE);

    // Check if memory allocation failed
    if (offset_array == NULL || key_array == NULL || value_array == NULL || string_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize the arrays with default values
    for (int i = 0; i < MAX_OFFSET_SIZE; i++) {
        offset_array[i] = 0;
    }
    for (int i = 0; i < MAX_KEY_SIZE; i++) {
        key_array[i] = 0;
    }
    for (int i = 0; i < MAX_VALUE_SIZE; i++) {
        value_array[i] = 0.0;
    }
    for (int i = 0; i < MAX_STRING_SIZE; i++) {
        string_array[i] = NULL;
    }

    // Read the number of records from the configuration file
    int num_records = config->num_records;

    // Initialize the record structures
    Record* records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].key = 0;
        records[i].value = 0.0;
        records[i].string = NULL;
    }

    // Seed the random number generator with the current timestamp
    srand(time(NULL));

    // Generate random values for each record's int field within a specified range defined in the configuration file
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % config->max_offset_size + 1;
    }

    // Generate random values for each record's double field within a specified range defined in the configuration file
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() / (double)RAND_MAX * (config->max_value_size - config->min_value_size) + config->min_value_size;
    }

    // Generate random strings for each record's string field within a specified range defined in the configuration file
    for (int i = 0; i < num_records; i++) {
        records[i].string = malloc(sizeof(char) * config->max_string_size);
        if (records[i].string == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        for (int j = 0; j < config->max_string_size; j++) {
            records[i].string[j] = rand() % 26 + 'A';
        }
    }

    // Return the initialized arrays and record structures
    return records;
}

// Define the function that frees the allocated memory
void free_arrays(Record* records) {
    // Check if the input is valid
    if (records == NULL) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    // Free the allocated memory for each record's string field
    for (int i = 0; i < num_records; i++) {
        free(records[i].string);
    }

    // Free the allocated memory for the array of records
    free(records);
