#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

// Macros for error checking
#define CHECK_ERROR(x) if((x)==-1){perror("Error");exit(1);}
#define INPUT_FILE "urls.txt"
#define OUTPUT_FILE "output.txt"

// Structure to store HTTP response data
struct HttpResponse {
    int statusCode;
    size_t contentLength;
};

// Function to perform an HTTP GET request and return the response data
struct HttpResponse httpGet(char *url) {
    struct HttpResponse resp;
    resp.statusCode = -1;
    resp.contentLength = 0;

    // Create a socket file descriptor
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("Socket creation failed");
        return resp;
    }

    // Construct the server address structure
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, url, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address");
        return resp;
    }

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return resp;
    }

    // Send an HTTP GET request to the server
    char *get_request = "GET / HTTP/1.1\r\nHost: www.example.com\r\nConnection: close\r\n\r\n";
    int req_size = strlen(get_request);
    if (send(sockfd, get_request, req_size, 0) != req_size) {
        perror("Send failed");
        return resp;
    }

    // Receive the HTTP response from the server
    char recv_buf[1024];
    memset(recv_buf, 0, sizeof(recv_buf));
    int bytes_received = recv(sockfd, recv_buf, sizeof(recv_buf) - 1, 0);
    if (bytes_received == -1) {
        perror("Recv failed");
        return resp;
    }

    // Close the socket
    close(sockfd);

    // Parse the HTTP response headers and extract the status code and content length
    char *token = strtok(recv_buf, "\r\n");
    while (token != NULL) {
        if (strncmp(token, "HTTP/", 5) == 0) {
            resp.statusCode = atoi(token + 9);
        } else if (strncmp(token, "Content-Length: ", 16) == 0) {
            resp.contentLength = atoi(token + 16);
        }
        token = strtok(NULL, "\r\n");
    }

    return resp;
}

// Function to read a list of integers from standard input and store them in an array
int *readIntegerList() {
    int numInts = 0;
    while (true) {
        // Read an integer from standard input
        int num;
        if (scanf("%d", &num) != 1) {
            break;
        }

        // Increment the number of integers read
        numInts++;
    }

    // Allocate memory for the array of integers
    int *intList = malloc(sizeof(int) * numInts);
    if (intList == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Read each integer from standard input and store it in the array
    for (int i = 0; i < numInts; i++) {
        if (scanf("%d", &intList[i]) != 1) {
            break;
        }
    }

    return intList;
}

// Function to find the largest integer in an array of integers and print it
void printLargestInteger(int *intList, int numInts) {
    // Find the largest integer in the array
    int largest = 0;
    for (int i = 0; i < numInts; i++) {
        if (intList[i] > largest) {
            largest = intList[i];
        }
    }

    // Print the largest integer
    printf("%d\n", largest);
}

// Function to process a text file and print the contents in a comma-separated format
void processTextFile(char *filename) {
    // Open the text file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open input file");
        return;
    }

    // Read each line from the file and process it
    char *line = malloc(1024);
    while (fgets(line, 1024, file) != NULL) {
        // Parse the URL from the line
        char url[1024];
        sscanf(line, "%s", url);

        // Perform an HTTP GET request to the URL and print the response data
        struct HttpResponse resp = httpGet(url);
        if (resp.statusCode == 200) {
            printf("%d,%zu\n", resp.statusCode, resp.contentLength);
        } else {
            printf("Error: %d\n", resp.statusCode);
        }
    }

    // Close the text file
    fclose(file);
}

// Main function that reads a list of URLs from standard input and processes them
int main() {
    // Read a list of integers from standard input
    int *intList = readIntegerList();
    if (intList == NULL) {
        return 1;
    }

    // Find the largest integer in the list and print it
    printLargestInteger(intList, numInts);

    // Process each text file specified as input
    for (int i = 0; i < numInts; i++) {
        processTextFile(intList[i]);
    }

    return 0;
}
```

This code first reads a list of integers from standard input using the `readIntegerList` function. It then finds the largest integer in the list using the `printLargestInteger` function and prints it to the console. Finally, it processes each text file specified as input by calling the `processTextFile` function for each one.

In this code, we use the `scanf` function to read an integer from standard input and store it in the `intList` array. We then use a loop to continue reading integers until there are no more integers available. If the user enters nothing (i.e., presses enter without typing anything), the loop will exit and we will return from the function with the `numInts` variable containing the number of integers read.

In the `printLargestInteger` function, we use a for loop to find the largest integer in the array by comparing each element to the current largest value until we reach the end of the array. We then print the largest integer to the console using the `printf` function.

In the `processTextFile` function, we open the text file specified as input using the `fopen` function and read each line from it using the `fgets` function. We then parse the URL from the line using the `sscanf` function and perform an HTTP GET request to the URL using the `httpGet` function. If the status code of the response is 200, we print the response data to the console using the `printf` function. Otherwise, we print an error message to the console. We close the text file using the `fclose` function when we are done with it.

In the main function, we call the `readIntegerList` and `printLargestInteger` functions to read a list of integers from standard input and find the largest integer in the list. We then process each text file specified as input by calling the `processTextFile` function for each one.']

