typedef struct node {
    float value;
    struct node *next;
} node_t;

// Custom allocator that supports aligned memory blocks for efficient memory management
void *my_alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        return NULL;
    }
    // Allocate extra space for alignment
    char *aligned_ptr = (char *)ptr + sizeof(void *) - 1;
    aligned_ptr -= ((uintptr_t)aligned_ptr % sizeof(void *));
    return aligned_ptr;
}

// Custom deallocator that handles node removal efficiently
void my_free(node_t *node) {
    if (node == NULL) {
        return;
    }
    node_t *next = node->next;
    free(node);
    my_free(next);
}

// Read JSON configuration file and initialize arrays
int read_config(const char *filename, long **offsets, float **weights, int *num_nodes) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return 1; // Error opening file
    }
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Parse JSON object and extract float values for weights and long offsets
        if (sscanf(line, "{\"weights\": [%f], \"offsets\": [%ld]}", &(*weights)[*num_nodes], &(*offsets)[*num_nodes]) != 2) {
            fclose(file);
            return 2; // Error parsing JSON object
        }
        (*num_nodes)++;
    }
    fclose(file);
    return 0; // Success
}

// Initialize and resize node array based on configuration file data
node_t *init_nodes(long **offsets, float **weights, int num_nodes) {
    node_t *nodes = (node_t *)my_alloc(num_nodes * sizeof(node_t));
    if (nodes == NULL) {
        return NULL; // Error allocating memory for nodes
    }
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].value = (*weights)[i];
        nodes[i].next = (i == num_nodes - 1) ? NULL : &(nodes[i + 1]);
    }
    return nodes;
}

// Print values of each node in the linked list
void print_list(node_t *head) {
    printf("Linked List:\n");
    while (head != NULL) {
        printf("%.2f ", head->value);
        head = head->next;
    }
    puts("");
}

// Free memory allocated for linked list and arrays
void free_memory(node_t *nodes, long *offsets, float *weights, int num_nodes) {
    my_free(nodes);
    free(offsets);
    free(weights);
}

int main() {
    const char *filename = "config.json";
    long *offsets = NULL;
    float *weights = NULL;
    int num_nodes = 0;
    if (read_config(filename, &offsets, &weights, &num_nodes) != 0) {
        printf("Error reading configuration file\n");
        return 1;
    }
    node_t *nodes = init_nodes(&offsets, &weights, num_nodes);
    if (nodes == NULL) {
        free_memory(nodes, offsets, weights, num_nodes);
        printf("Error initializing linked list\n");
        return 1;
    }
    print_list(nodes);
    free_memory(nodes, offsets, weights, num_nodes);
    return 0;
}
