char* append_slash(const char* input, size_t limit) {
    // Check if the input string is null or empty
    if (!input || strlen(input) == 0) {
        return NULL;
    }

    // Calculate the length of the output string
    size_t len = strlen(input);
    size_t new_len = len + (len >= limit ? 0 : 1);

    // Allocate memory for the output string
    char* output = malloc(new_len + 1);
    if (!output) {
        return NULL;
    }

    // Copy the input string to the output string
    strcpy(output, input);

    // Append a slash to the end of the output string if necessary
    if (len < limit) {
        output[new_len] = '/';
    }

    return output;
}
