function getElementsBySelector(selector, rootNode) {
    const elements = [];

    // Iterate through the DOM tree starting from the given root node
    for (const node of rootNode.querySelectorAll(selector)) {
        // Check if the element matches the selector
        if (node.matches(selector)) {
            elements.push(node);
        }

        // Handle circular references and dynamic updates to the DOM tree
        if (node.children) {
            const children = node.querySelectorAll(selector);
            for (const child of children) {
                elements.push(child);
            }
        }
    }

    return elements;
}
