} Record;

// Function to allocate memory for arrays of longs, ints, and doubles, as well as records, and initialize them with random data
void allocate_memory(int num_records, int max_key, int min_key, double max_value, double min_value, char *filename) {
    // Allocate memory for the arrays of longs, ints, and doubles
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    double *values = malloc(num_records * sizeof(double));

    // Initialize the arrays with random data within the specified range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_value - min_value) + min_value;
        keys[i] = rand() % (max_key - min_key) + min_key;
        values[i] = offsets[i] * keys[i];
    }

    // Allocate memory for the records
    Record **records = malloc(num_records * sizeof(Record));

    // Initialize the records with random data within the specified range and dynamically allocate char arrays
    for (int i = 0; i < num_records; i++) {
        int len = rand() % 10 + 5;
        Record *record = malloc(sizeof(Record));
        record->key = keys[i];
        record->value = values[i];
        record->data = malloc(len);
        for (int j = 0; j < len; j++) {
            record->data[j] = rand() % 26 + 'a';
        }
        records[i] = record;
    }

    // Free memory if any allocation fails
    if (offsets == NULL || keys == NULL || values == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(values);
        for (int i = 0; i < num_records; i++) {
            Record *record = records[i];
            free(record->data);
            free(record);
        }
        free(records);
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    // Log information about each allocation attempt and store the allocated memory in a thread-local variable for later use
    #ifdef THREADSAFE
        pthread_key_t key;
        pthread_once(&key, NULL);
        void **memory = (void **)pthread_getspecific(key);
        if (memory == NULL) {
            memory = malloc(3 * num_records * sizeof(void*));
            pthread_setspecific(key, memory);
        }
        memory[0] = offsets;
        memory[1] = keys;
        memory[2] = records;
    #else
        static void **memory = NULL;
        if (memory == NULL) {
            memory = malloc(3 * num_records * sizeof(void*));
        }
        memory[0] = offsets;
        memory[1] = keys;
        memory[2] = records;
    #endif
}

// Function to modify the extension of a filename and append ".txt" if necessary
void modify_filename(char *filename, int num_records) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Check if the new filename exceeds the maximum length
    if (len + 10 > 25) {
        fprintf(stderr, "Error: New filename exceeds maximum length\n");
        exit(EXIT_FAILURE);
    }

    // Modify the extension of the filename and append ".txt" if necessary
    char *new_filename = malloc((len + 10) * sizeof(char));
    memcpy(new_filename, filename, len);
    new_filename[len] = '.';
    int num_digits = ceil(log10(num_records));
    for (int i = 1; i <= num_digits; i++) {
        new_filename[len + i] = '0' + (num_records % 10);
        num_records /= 10;
    }
    strcpy(new_filename + len + 1, ".txt");

    // Free memory if any allocation fails
    if (new_filename == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    // Log information about each modification attempt and store the modified filename in a thread-local variable for later use
    #ifdef THREADSAFE
        pthread_key_t key;
        pthread_once(&key, NULL);
        char **new_filenames = (char **)pthread_getspecific(key);
        if (new_filenames == NULL) {
            new_filenames = malloc(num_records * sizeof(char*));
            pthread_setspecific(key, new_filenames);
        }
        new_filenames[0] = new_filename;
    #else
        static char **new_filenames = NULL;
        if (new_filenames == NULL) {
            new_filenames = malloc(num_records * sizeof(char*));
        }
        new_filenames[0] = new_filename;
    #endif
}

int main() {
    // Define the input and output filenames
    char *input_filename = "input.txt";
    char *output_filename = "output.txt";

    // Define the parameters for allocating memory
    int num_records = 10;

    // Allocate memory for storing the offsets, keys, and records in a thread-local variable for later use
    allocate_memory(num_records);

    // Modify the extension of the input filename to include the number of records
    modify_filename(input_filename, num_records);

    // Free memory if any allocation fails
    if (input_filename == NULL || output_filename == NULL) {
        free(input_filename);
        free(output_filename);
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}
