    char *input_filename = "input.txt";
    char *output_filename = "output.txt";

    // Create a dynamic array to store the records
    int num_records = 0;
    Record *records = NULL;

    // Read the input file and add each record to the dynamic array
    FILE *input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error: Failed to open input file\n");
        exit(EXIT_FAILURE);
    }
    char line[100];
    while (fgets(line, sizeof(line), input_file)) {
        // Parse the record from the current line and add it to the dynamic array
        int offset = atoi(strtok(line, " "));
        char *key = strtok(NULL, " ");
        Record record;
        record.offset = offset;
        strcpy(record.key, key);
        records = realloc(records, (num_records + 1) * sizeof(Record));
        records[num_records] = record;
        num_records++;
    }
    fclose(input_file);

    // Write the output file
    FILE *output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_records; i++) {
        Record record = records[i];
        fprintf(output_file, "%d %s\n", record.offset, record.key);
    }
    fclose(output_file);

    // Free memory if any allocation fails
    free(records);
    return 0;
}
