    // Use gethostbyname() function to resolve the hostname.
    addr = gethostbyname(hostname);
    if (addr == NULL) {
        perror("gethostbyname");
        return 1;
    }

    // Return IP address as a u_char array.
    unsigned char ip[4];
    memcpy(ip, &addr->s_addr, 4);

    printf("%u.%u.%u.%u\n", ip[0], ip[1], ip[2], ip[3]);

    return 0;
}

