        char buffer[256];
        int n = read(sock, buffer, sizeof(buffer));
        if (n < 0) {
            perror("read failed");
            exit(EXIT_FAILURE);
        } else if (n == 0) {
            printf("Client disconnected\n");
            break;
        }

        // Process the received data and handle errors
        for (int i = 0; i < n; i++) {
            char c = buffer[i];
            switch (c) {
                case '+':
                    offset_array[i]++;
