// Function to recursively traverse a DOM tree and return a list of elements that match a given selector
function getElementsBySelector(selector) {
    // Use the provided selector to select all matching elements in the document
    const matchingElements = document.querySelectorAll(selector);

    // Create an empty array to store the selected elements
    const selectedElements = [];

    // Recursively traverse the DOM tree and add each element that matches the selector to the list of selected elements
    function traverse(element) {
        if (element.matches(selector)) {
            selectedElements.push(element);
        }

        for (let childElement of element.childNodes) {
            if (childElement instanceof Element) {
                traverse(childElement);
            }
        }
    }

    // Recursively traverse the DOM tree and add each element that matches the selector to the list of selected elements
    function main(rootElement) {
        for (let childElement of rootElement.childNodes) {
            if (childElement instanceof Element) {
                traverse(childElement);
            }
        }
    }

    // Call the main function with the document element as the argument and return the list of selected elements
    main(document);
    return selectedElements;
}
