void allocateAndInitializeMemory(int numRecords, long **offsets, int **keys, double **values, record ***records) {
    // Allocate memory for arrays of offsets, keys, and values.
    *offsets = (long *)malloc(numRecords * sizeof(long));
    *keys = (int *)malloc(numRecords * sizeof(int));
    *values = (double *)malloc(numRecords * sizeof(double));

    // Initialize arrays of offsets, keys, and values.
    for (int i = 0; i < numRecords; ++i) {
        (*offsets)[i] = i * sizeof(record);
        (*keys)[i] = rand() % MAX_NUM_RECORDS;
        (*values)[i] = ((double)rand() / (RAND_MAX)) * 100.0;
    }

    // Allocate memory for array of records.
    *records = (record **)malloc(numRecords * sizeof(record));

    // Initialize each record in the array with a single integer, double, and dynamically allocated string.
    for (int i = 0; i < numRecords; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        (*records)[i]->key = (*keys)[i];
        (*records)[i]->value = (*values)[i];
        (*records)[i]->string = (char *)malloc(KEY_LEN + VALUE_LEN + 1);
        sprintf((*records)[i]->string, "%d,%lf", (*keys)[i], (*values)[i]);
    }
}

void deallocateMemory(long *offsets, int *keys, double *values, record **records) {
    // Deallocate memory for arrays of offsets, keys, and values.
    free(offsets);
    free(keys);
    free(values);

    // Deallocate memory for array of records.
    for (int i = 0; i < numRecords; ++i) {
        free((*records)[i]->string);
        free(*records[i]);
    }
    free(records);
}

