    if (strlen(inputFilename) > MAX_FILENAME_LENGTH - 4) {
        // Add ".txt" extension if necessary.
        char *extension = strrchr(inputFilename, '.');
        if (!extension || strcmp(extension, ".txt") != 0) {
            strcat(inputFilename, ".txt");
        }
    }

    // Copy the input filename to the output filename.
    strcpy(outputFilename, inputFilename);
}

void handleOutOfMemory(int allocationSize, int attemptNumber, char *allocationStrategy) {
    // Log information about each allocation attempt.
    printf("Allocation size: %d bytes\n", allocationSize);
    printf("Attempt number: %d\n", attemptNumber);
