// C++ function to insert a string into a forward list after the first occurrence of another string
void insertStringIntoForwardList(forward_list<string>& fl, const string& str1, const string& str2) {
    // Check if the first string is in the list
    auto it = find(fl.begin(), fl.end(), str1);
    if (it != fl.end()) {
        // Insert the second string after the first occurrence of the first string
        fl.insert_after(it, str2);
    } else {
        // If the first string is not in the list, insert it at the end
        fl.push_back(str1);
        fl.push_back(str2);
    }
}

