// Function to dynamically allocate memory for arrays and initialize them
void allocateArrays(size_t *offset, size_t *key, size_t numRecords, size_t maxMemUsage) {
    // Calculate the total amount of memory required
    size_t memRequired = sizeof(Record) * numRecords;

    // Check if the total memory usage exceeds the maximum limit
    if (memRequired > maxMemUsage) {
        fprintf(stderr, "Error: Total memory usage exceeds maximum limit\n");
        return;
    }

    // Allocate memory for the offset array
    *offset = (size_t *)malloc(sizeof(size_t) * numRecords);
    if (*offset == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    *key = (size_t *)malloc(sizeof(size_t) * numRecords);
    if (*key == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        free(*offset);
        return;
    }

    // Initialize the offset and key arrays with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; i++) {
        (*offset)[i] = rand() % maxMemUsage;
        (*key)[i] = rand() % INT_MAX;
    }
}

// Function to generate random values within a given range
int randomInt(int min, int max) {
    return min + (rand() % (max - min));
}

// Main function to handle concurrent access and caching
void cacheAllocateArrays(size_t *offset, size_t *key, size_t numRecords, size_t maxMemUsage) {
    // Create a cache for previously allocated records
    Record **cache = (Record **)malloc(sizeof(Record *) * numRecords);
    if (cache == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for cache\n");
        return;
    }

    // Initialize the cache with null pointers
    for (size_t i = 0; i < numRecords; i++) {
        cache[i] = NULL;
    }

    // Loop through the number of records and allocate memory as needed
    size_t curIndex = 0;
    while (curIndex < numRecords) {
        // Check if a record is already allocated in the cache
        Record *record = cache[curIndex];
        if (record == NULL) {
            // Allocate memory for a new record and initialize its key and offset fields
            record = (Record *)malloc(sizeof(Record));
            if (record == NULL) {
                fprintf(stderr, "Error: Failed to allocate memory for record\n");
                break;
            }

            // Set the record's key and offset fields with random values within a given range
            record->key = randomInt(0, INT_MAX);
            (*offset)[curIndex] = rand() % maxMemUsage;
        }

        // Add the allocated record to the cache
        cache[curIndex++] = record;
    }

    // Free any remaining memory in the cache
    for (size_t i = curIndex; i < numRecords; i++) {
        if (cache[i] != NULL) {
            free(cache[i]);
        }
    }

    // Clean up the cache array
    free(cache);
}
