    if (num_records < 1 || num_records > NUM_RECORDS) {
        return NULL;
    }

    data_t *data = malloc(sizeof(data_t));
    if (!data) {
        return NULL;
    }

    data->offsets = malloc(num_records * sizeof(long));
    if (!data->offsets) {
        free(data);
        return NULL;
    }

