    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1;
    }

    size_t num_records = sizeof(data->offsets) / sizeof(long);
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&data->offsets[i], sizeof(long), 1, file);
        fwrite(&data->keys[i], sizeof(int), 1, file);
        fwrite(&data->records[i].value, sizeof(int), 1, file);
