mutex mtx;

// Vector to store all records
vector<data_entry> records;

// Function to initialize the system with a given number of records and record size
void init(int num_records, int record_size) {
    // Lock the mutex before modifying shared data
    mtx.lock();

    // Clear the vector of records
    records.clear();

    // Allocate memory for each record
    for (int i = 0; i < num_records; ++i) {
        data_entry entry;
        entry.data = new vector<int>(record_size);
        records.push_back(entry);
    }

    // Unlock the mutex after modifying shared data
    mtx.unlock();
}

// Function to insert a new record into the system
void insert(long offset, int key, vector<int> &data) {
    // Lock the mutex before modifying shared data
    mtx.lock();

    // Insert the new record into the vector of records
    records[offset].key = key;
    records[offset].data->assign(data.begin(), data.end());
    records[offset].size = data.size();

    // Unlock the mutex after modifying shared data
    mtx.unlock();
}

// Function to retrieve a record from the system
void retrieve(long offset, int &key, vector<int> &data) {
    // Lock the mutex before accessing shared data
