void update(long offset, int key, vector<int> &data) {
    // Lock the mutex before modifying shared data
    mtx.lock();

    // Update the record in the vector of records
    records[offset].key = key;
    records[offset].data->assign(data.begin(), data.end());
    records[offset].size = data.size();

    // Unlock the mutex after modifying shared data
    mtx.unlock();
}

// Function to delete a record from the system
void delete_(long offset) {
    // Lock the mutex before modifying shared data
    mtx.lock();

    // Delete the record from the vector of records
    records[offset].data->clear();
    records[offset].key = 0;
    records[offset].size = 0;

    // Unlock the mutex after modifying shared data
    mtx.unlock();
}

// Function to check for inconsistencies in the offset and key arrays
void check_inconsistencies(vector<long> &offsets, vector<int> &keys) {
    // Lock the mutex before accessing shared data
    mtx.lock();

