#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

typedef struct {
    char *hostname;
    unsigned char ip[4];
} dns_result;

dns_result *resolve(const char *hostname) {
    int sockfd, ret, err;
    struct addrinfo hints, *res;
    struct in_addr addr;

    // Initialize the hints structure with the AI_ADDRCONFIG flag set
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_ADDRCONFIG;

    // Perform DNS resolution using getaddrinfo()
    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        printf("DNS resolution failed: %s\n", gai_strerror(ret));
        return NULL;
    }

    // Get the IP address of the first result
    memcpy(&addr, res->ai_addr, sizeof(struct in_addr));

    // Free the memory allocated by getaddrinfo()
    freeaddrinfo(res);

    // Create a dns_result structure to return the IP address
    dns_result *result = (dns_result *)malloc(sizeof(dns_result));
    if (!result) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Copy the hostname and IP address into the structure
    result->hostname = strdup(hostname);
    memcpy(result->ip, &addr.s_addr, sizeof(result->ip));

    return result;
}
