// Struct to represent a record with an int value
typedef struct {
    int value;
} Record;

// Struct to represent the data management system
typedef struct {
    // Array of long offsets for the records
    long *offsets;
    // Array of int keys for the records
    int *keys;
    // Array of record structures
    Record **records;
    // Maximum number of entries allowed
    size_t max_entries;
    // Maximum size of each entry's data array
    size_t max_data_size;
} DataManagementSystem;

// Function to initialize the data management system
DataManagementSystem* init_system(size_t max_entries, size_t max_data_size) {
    DataManagementSystem *sys = (DataManagementSystem*)malloc(sizeof(DataManagementSystem));
    sys->offsets = (long*)malloc(max_entries * sizeof(long));
    sys->keys = (int*)malloc(max_entries * sizeof(int));
    sys->records = (Record**)malloc(max_entries * sizeof(Record*));
    sys->max_entries = max_entries;
    sys->max_data_size = max_data_size;
    return sys;
}

// Function to add a new record to the system
int add_record(DataManagementSystem *sys, int key, size_t data_size) {
    pthread_mutex_lock(&sys->mutex);
    if (sys->num_entries >= sys->max_entries) {
        // Error: max number of entries reached
        return -1;
    }
    Record *record = (Record*)malloc(sizeof(Record));
    record->value = rand() % data_size;
    sys->records[sys->num_entries] = record;
    sys->offsets[sys->num_entries] = sizeof(Record);
    sys->keys[sys->num_entries] = key;
    sys->num_entries++;
    pthread_mutex_unlock(&sys->mutex);
    return 0;
}

// Function to get a record from the system by key
int* get_record(DataManagementSystem *sys, int key) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->num_entries; i++) {
        if (sys->keys[i] == key) {
            Record *record = sys->records[i];
            pthread_mutex_unlock(&sys->mutex);
            return record->value;
        }
    }
    // Error: no such key found
    pthread_mutex_unlock(&sys->mutex);
    return NULL;
}

// Function to remove a record from the system by key
void remove_record(DataManagementSystem *sys, int key) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->num_entries; i++) {
        if (sys->keys[i] == key) {
            Record *record = sys->records[i];
            free(record);
            sys->offsets[i] = -1;
            sys->keys[i] = -1;
            sys->num_entries--;
        }
    }
    pthread_mutex_unlock(&sys->mutex);
}

// Function to clean up the data management system
void cleanup_system(DataManagementSystem *sys) {
    free(sys->offsets);
    free(sys->keys);
    for (size_t i = 0; i < sys->num_entries; i++) {
        Record *record = sys->records[i];
        free(record);
    }
    free(sys->records);
}
