    long numItems = 0;
    fread(&numItems, sizeof(long), 1, resourceFile);
    numItems = ntohl(numItems); // convert to host byte order

    if (numItems <= 0 || numItems > ITEM_COUNT) {
        printf("Error: invalid number of items in bundle\n");
        fclose(resourceFile);
        return NULL;
    }

    // Allocate memory for the offset and key arrays
    long* offsetArray = malloc(OFFSET_ARRAY_SIZE);
    int* keyArray = malloc(KEY_ARRAY_SIZE);
    if (offsetArray == NULL || keyArray == NULL) {
