        fclose(resourceFile);
        free(offsetArray);
        free(keyArray);
        return NULL;
    }

    // Read the offset and key values from the file
    size_t bytesRead = fread(offsetArray, sizeof(long), numItems, resourceFile);
    if (bytesRead != numItems) {
        printf("Error: could not read %ld offsets from resource file\n", numItems);
        fclose(resourceFile);
        free(offsetArray);
        free(keyArray);
        return NULL;
    }
    bytesRead = fread(keyArray, sizeof(int), numItems, resourceFile);
    if (bytesRead != numItems) {
        printf("Error: could not read %ld keys from resource file\n", numItems);
        fclose(resourceFile);
        free(offsetArray);
        free(keyArray);
        return NULL;
    }

    // Close the resource file
    fclose(resourceFile);

    // Initialize the item array with random values within a given range
