int read_log(const char* file_path) {
    // Open the log file
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    // Get the number of entries in the log file
    int num_entries = 0;
    while (!feof(file)) {
        char* line = fgets(line, sizeof(line), file);
        if (line == NULL) break;
        num_entries++;
    }

    // Close the log file
    fclose(file);

    // Allocate memory for the arrays
    long *timestamps = malloc(num_entries * sizeof(long));
    int *event_types = malloc(num_entries * sizeof(int));
    log_entry* entries = malloc(num_entries * sizeof(log_entry));

    // Initialize the arrays with zeros
    memset(timestamps, 0, num_entries * sizeof(long));
    memset(event_types, 0, num_entries * sizeof(int));
    for (int i = 0; i < num_entries; i++) {
        entries[i].message = NULL;
    }

    // Read the log file and populate the arrays
    file = fopen(file_path, "r");
    int line_number = 0;
    while (!feof(file)) {
        char* line = fgets(line, sizeof(line), file);
        if (line == NULL) break;

        // Parse the timestamp and event type from the current line
        long timestamp = atol(line + strlen("timestamp: "));
        int event_type = atoi(line + strlen("event_type: "));

        // Allocate memory for the message string
        char* message = malloc(strlen(line) - strlen("message: ") + 1);
        memcpy(message, line + strlen("message: "), strlen(line) - strlen("message: "));
        message[strlen(line) - strlen("message: ")] = '\0';

        // Add the log entry to the array
        entries[line_number].timestamp = timestamp;
        entries[line_number].event_type = event_type;
        entries[line_number].message = message;

        line_number++;
    }
    fclose(file);

    return 0;
}
