```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Structure for storing data entries
typedef struct {
    long offset;
    int key;
    char data[];
} data_entry;

// Buffer manager for managing memory allocation and deallocation
struct buffer_manager {
    // Pointer to the start of the buffer
    char *buffer_start;

    // Pointer to the current position in the buffer
    char *current_pos;

    // Total size of the buffer
    int total_size;

    // Size of each data entry
    int data_entry_size;
};

// Data structure for storing data entries
struct data_store {
    // Linked list of data entries
    struct data_entry *head;

    // Mutex for protecting concurrent access to the data store
    pthread_mutex_t mutex;

    // Condition variable for waiting on a full buffer
    pthread_cond_t is_full;
};

// Function to initialize the buffer manager and the data store
void init_buffer_manager(struct buffer_manager *bm, int max_entries, int max_data_size) {
    // Allocate memory for the buffer
    bm->total_size = (max_entries * sizeof(data_entry)) + (max_data_size * max_entries);
    bm->buffer_start = (char *)malloc(bm->total_size);

    // Initialize the current position to the start of the buffer
    bm->current_pos = bm->buffer_start;

    // Initialize the data entry size
    bm->data_entry_size = sizeof(data_entry) + max_data_size;
}

// Function to allocate memory for a new data entry in the buffer manager
void *allocate_memory(struct buffer_manager *bm, int max_data_size) {
    // Check if there is enough space in the buffer
    if (bm->current_pos + bm->data_entry_size > bm->buffer_start + bm->total_size) {
        return NULL;
    }

    // Allocate memory for the data entry
    char *memory = bm->current_pos;
    bm->current_pos += bm->data_entry_size;

    // Initialize the data entry structure
    struct data_entry *data_entry = (struct data_entry *)memory;
    data_entry->offset = rand() % (1000 - 50) + 50;
    data_entry->key = rand() % (10 - 1) + 1;
    for (int i = 0; i < max_data_size; i++) {
        data_entry->data[i] = 'a' + rand() % ('z' - 'a');
    }

    return memory;
}

// Function to deallocate memory for a data entry in the buffer manager
void deallocate_memory(struct buffer_manager *bm, void *memory) {
    // Do nothing since we are not using malloc/free
}

// Function to add a new data entry to the data store
void add_data_entry(struct data_store *ds, struct data_entry *data_entry) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&ds->mutex);

    // Check if the buffer is full
    while (ds->head == NULL || ds->head->next != NULL) {
        // Wait for a signal on the condition variable
        pthread_cond_wait(&ds->is_full, &ds->mutex);
    }

    // Add the data entry to the linked list of data entries
    struct data_entry *tmp = ds->head;
    ds->head = data_entry;
    data_entry->next = NULL;

    // Signal a waiter on the condition variable
    pthread_cond_signal(&ds->is_full);

    // Release the lock on the mutex
    pthread_mutex_unlock(&ds->mutex);
}

// Function to retrieve a data entry from the data store
struct data_entry *get_data_entry(struct data_store *ds) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&ds->mutex);

    // Check if there are any data entries in the linked list
    while (ds->head == NULL) {
        // Wait for a signal on the condition variable
        pthread_cond_wait(&ds->is_full, &ds->mutex);
    }

    // Retrieve the first data entry from the linked list
    struct data_entry *data_entry = ds->head;
    ds->head = ds->head->next;

    // Signal a waiter on the condition variable
    pthread_cond_signal(&ds->is_full);

    // Release the lock on the mutex
    pthread_mutex_unlock(&ds->mutex);

    return data_entry;
}
```
