Here is an example implementation of a C function that dynamically allocates memory for and initializes a log system capable of handling up to 1000 log entries. Each log entry should contain a timestamp, an event type, and a dynamic string message. The string message should be dynamically allocated based on the length of a provided input string. Additionally, implement functionality to log the total number of bytes allocated for all log entries and ensure this information is included in the final output.
```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdio.h>

// Log entry structure
typedef struct {
    time_t timestamp;
    int event_type;
    char *message;
} log_entry;

int init_log_system(log_entry *entries, const char *message_template) {
    // Check if the input parameters are valid
    if (entries == NULL || message_template == NULL) {
        return -1;
    }

    // Allocate memory for the log entries and initialize them
    for (int i = 0; i < 1000; i++) {
        log_entry *entry = &entries[i];
        entry->timestamp = time(NULL);
        entry->event_type = i % 3;
        int message_length = strlen(message_template) + 1;
        entry->message = (char *)malloc(message_length);
        if (entry->message == NULL) {
            return -1;
        }
        snprintf(entry->message, message_length, message_template, i);
    }

    // Initialize the total number of bytes allocated for all log entries
    int total_bytes = 0;
    for (int i = 0; i < 1000; i++) {
        total_bytes += strlen(entries[i].message);
    }

    // Print the final output
    printf("Total number of log entries: %d\n", 1000);
    printf("Total number of bytes allocated: %d\n", total_bytes);
    for (int i = 0; i < 1000; i++) {
        printf("%lu | %d | %s\n", entries[i].timestamp, entries[i].event_type, entries[i].message);
    }

    return 0;
}
```
