#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Macro for error handling
#define FAILURE -1

// Struct for storing connection information
typedef struct {
    int socket; // Socket file descriptor
    char* host; // Host address
    unsigned short port; // Port number
} ConnectionInfo;

// Function to establish a new connection
int connect_to_server(ConnectionInfo* info) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == FAILURE) {
        printf("Socket creation failed.\n");
        return FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(info->port);
    if (inet_pton(AF_INET, info->host, &server_addr.sin_addr) <= 0) {
        printf("Invalid host address.\n");
        return FAILURE;
    }

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == FAILURE) {
        printf("Connection failed.\n");
        close(sockfd);
        return FAILURE;
    }

    info->socket = sockfd;
    return 0;
}

// Function to send data over a connection
int send_data(ConnectionInfo* info, void* data, int length) {
    if (info->socket == FAILURE) {
        printf("Invalid socket.\n");
        return FAILURE;
    }

    ssize_t sent = send(info->socket, data, length, 0);
    if (sent < 0) {
        printf("Send failed.\n");
        close(info->socket);
        info->socket = FAILURE;
        return FAILURE;
    }

    return sent;
}

// Function to receive data over a connection
int receive_data(ConnectionInfo* info, void* buffer, int length) {
    if (info->socket == FAILURE) {
        printf("Invalid socket.\n");
        return FAILURE;
    }

    ssize_t received = recv(info->socket, buffer, length, 0);
    if (received < 0) {
        printf("Receive failed.\n");
        close(info->socket);
        info->socket = FAILURE;
        return FAILURE;
    }

    return received;
}

// Function to manage connections in a pool
void connection_pool_manager(ConnectionInfo* connections[], int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->socket == FAILURE) continue; // Skip invalid connections

        // Handle connection errors and close the socket
        int error = getsockopt(connections[i]->socket, SOL_SOCKET, SO_ERROR);
        if (error != 0) {
            printf("Connection error: %d\n", error);
            close(connections[i]->socket);
            connections[i]->socket = FAILURE;
            continue;
        }

        // Check if the connection is still valid and reconnect if necessary
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(connections[i]->port);
        if (inet_pton(AF_INET, connections[i]->host, &server_addr.sin_addr) <= 0) {
            printf("Invalid host address.\n");
            close(connections[i]->socket);
            connections[i]->socket = FAILURE;
            continue;
        }

        if (connect(connections[i]->socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) == FAILURE) {
            printf("Connection reestablishment failed.\n");
            close(connections[i]->socket);
            connections[i]->socket = FAILURE;
            continue;
        }
    }
}

// Function to perform asynchronous I/O operations using non-blocking sockets
void async_io_operations(ConnectionInfo* connections[], int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->socket == FAILURE) continue; // Skip invalid connections

        // Set the socket to non-blocking mode
        int flags = fcntl(connections[i]->socket, F_GETFL);
        if (flags < 0 || fcntl(connections[i]->socket, F_SETFL, flags | O_NONBLOCK) < 0) {
            printf("Failed to set non-blocking mode for socket %d.\n", connections[i]->socket);
            continue;
        }

        // Perform asynchronous I/O operations using send and recv
        struct timespec timeout = { 5, 0 }; // Set a 5 second timeout
        while (1) {
            ssize_t sent = send(connections[i]->socket, NULL, 0, MSG_DONTWAIT);
            if (sent < 0 && errno == EAGAIN) break; // Exit the loop on success or failure

            ssize_t received = recv(connections[i]->socket, NULL, 0, MSG_DONTWAIT);
            if (received < 0 && errno == EAGAIN) break; // Exit the loop on success or failure

            if (sent > 0) {
                printf("Sent %zd bytes.\n", sent);
                fflush(stdout);
            } else if (sent == 0) {
                printf("Connection closed by remote end.\n");
                close(connections[i]->socket);
                connections[i]->socket = FAILURE;
                break; // Exit the loop on connection closure
            } else {
                printf("Send failed: %d\n", errno);
                close(connections[i]->socket);
                connections[i]->socket = FAILURE;
                break; // Exit the loop on failure
            }

            if (received > 0) {
                printf("Received %zd bytes.\n", received);
                fflush(stdout);
            } else if (received == 0) {
                printf("Connection closed by remote end.\n");
                close(connections[i]->socket);
                connections[i]->socket = FAILURE;
                break; // Exit the loop on connection closure
            } else {
                printf("Receive failed: %d\n", errno);
                close(connections[i]->socket);
                connections[i]->socket = FAILURE;
                break; // Exit the loop on failure
            }
        }
    }
}

// Function to handle multiple connections simultaneously
void multi_connection_handler(ConnectionInfo* connections[], int num_connections) {
    while (1) {
        connection_pool_manager(connections, num_connections); // Manage the connections in a pool
        async_io_operations(connections, num_connections); // Perform asynchronous I/O operations using non-blocking sockets
    }
}
```
This code uses a `ConnectionInfo` struct to store information about each connection, including the socket file descriptor. It also defines functions for sending and receiving data over a connection, as well as managing connections in a pool and performing asynchronous I/O operations using non-blocking sockets. The `multi_connection_handler` function is responsible for handling multiple connections simultaneously by calling the other functions in turn.

### Caveats

There are several caveats to consider when using this approach:

1. **Non-blocking I/O**: Asynchronous I/O operations must be performed using non-blocking sockets, which can cause performance issues if not implemented correctly.
2. **Error handling**: Error handling is crucial in asynchronous I/O, and it's easy to forget to check for errors when performing operations such as `send` and `recv`.
3. **Connection pooling**: Managing connections in a pool can be complex, especially if the connections are established using a third-party library or framework.
4. **Thread safety**: Asynchronous I/O operations must be performed in separate threads to avoid blocking other operations on the same connection. This can lead to additional complexity and performance issues if not implemented correctly.']

