// Define the data structure to store records
typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
} Record;

// Define a linked list node for storing records
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Define the data structure to store all nodes
typedef struct LinkedList {
    Node* head;
    size_t total_allocated_memory;
    size_t max_memory_limit; // maximum memory limit in bytes
} LinkedList;

// Define a log level enum for logging initialization process
typedef enum LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

// Function to initialize the linked list and allocate memory for it
void init_linked_list(LinkedList* ll, size_t max_memory_limit) {
    ll->head = NULL;
    ll->total_allocated_memory = 0;
    ll->max_memory_limit = max_memory_limit;
}

// Function to allocate memory for a new record and add it to the linked list
void add_record(LinkedList* ll, int key, long offset) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        // Memory allocation failed, handle error
    }
    node->record.key = key;
    node->record.offset = offset;
    node->record.timestamp = time(NULL);
    node->next = ll->head;
    ll->head = node;
    ll->total_allocated_memory += sizeof(Node);
}

// Function to deallocate memory for a record and remove it from the linked list
void delete_record(LinkedList* ll, int key) {
    Node* prev = NULL;
    Node* current = ll->head;
    while (current != NULL && current->record.key != key) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        // Record not found, handle error
    } else {
        if (prev == NULL) {
            ll->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        ll->total_allocated_memory -= sizeof(Node);
    }
}

// Function to log the initialization process with customizable log levels
void log_init(LogLevel level, const char* message) {
    switch (level) {
        case DEBUG:
            printf("DEBUG: %s\n", message);
            break;
        case INFO:
            printf("INFO: %s\n", message);
            break;
        case WARNING:
            printf("WARNING: %s\n", message);
            break;
        case ERROR:
            printf("ERROR: %s\n", message);
            break;
    }
}
