// Function to perform DNS resolution for a given hostname using standard library functions and return the IP address in a u_char array
u_char* dns_resolve(const char* hostname) {
    // Check if the hostname is already cached
    if (cache.find(hostname) != cache.end()) {
        return cache[hostname];
    } else {
        struct addrinfo hints;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET; // IPv4 only
        hints.ai_socktype = SOCK_STREAM;
        struct addrinfo* result;
        int rc = getaddrinfo(hostname, NULL, &hints, &result);
        if (rc != 0) {
            printf("Error in DNS resolution: %s\n", gai_strerror(rc));
            return NULL;
        } else {
            struct sockaddr_in* addr = (struct sockaddr_in*)result->ai_addr;
            char ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &addr->sin_addr, ip, INET_ADDRSTRLEN);
            printf("DNS resolution for %s: %s\n", hostname, ip);
            cache[hostname] = strdup(ip);
            return cache[hostname];
        }
    }
}

// Function to handle errors and return an appropriate error code if necessary
void* handle_error(void* thread_info) {
    struct thread_info* info = (struct thread_info*)thread_info;
    if (info->file == NULL || feof(info->file)) {
        printf("Error reading file: %s\n", info->filename);
        return NULL;
    } else {
        return (void*)info;
    }
}

// Function to read multiple text files concurrently using threads, each processing lines by dynamically allocating memory and printing the contents in a comma-separated format
void* process_file(void* thread_info) {
    struct thread_info* info = (struct thread_info*)thread_info;
    FILE* file = info->file;
    int file_index = info->file_index;
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file) != NULL) {
        // Split the line into tokens using "," as delimiter
        char* token = strtok(line, ",");
        int token_count = 1;
        while (token != NULL) {
            if (token_count == 2 || token_count == 3) {
                // Convert the token to a float and compute the average
                float value = atof(token);
                printf("%s, %.2f\n", info->filename, (value + atof(token - 1)) / 2.0);
            } else {
                // Print the token as is
                printf("%s\n", token);
            }
            token_count++;
            token = strtok(NULL, ",");
        }
    }
}

// Function to manage memory efficiently by freeing allocated memory after use
void* free_memory(void* thread_info) {
    struct thread_info* info = (struct thread_info*)thread_info;
    fclose(info->file);
    free(info->filename);
}

// Function to handle concurrent processing of multiple input files, ensuring thread safety and efficient resource management
void process_files(int file_count) {
    pthread_t threads[MAX_THREADS];
    struct thread_info info[MAX_THREADS];
    for (int i = 0; i < file_count && i < MAX_THREADS; i++) {
        info[i].file_index = i;
        info[i].filename = strdup(filenames[i]);
        info[i].file = fopen(info[i].filename, "r");
        if (info[i].file == NULL) {
            printf("Error opening file: %s\n", info[i].filename);
            return;
        }
        pthread_create(&threads[i], NULL, process_file, &info[i]);
    }
    for (int i = 0; i < file_count && i < MAX_THREADS; i++) {
        void* thread_result = NULL;
        pthread_join(threads[i], &thread_result);
        if (thread_result == NULL) {
            printf("Error in thread %d: %s\n", info[i].file_index, strerror(errno));
        } else {
            free_memory(thread_result);
        }
    }
}

// Function to include a caching mechanism for DNS resolution results to improve performance when processing multiple files or repeated queries for the same hostnames. The cache should be managed efficiently to avoid excessive memory usage and ensure it does not become a bottleneck.
void* dns_cache(void* thread_info) {
    struct thread_info* info = (struct thread_info*)thread_info;
    char* hostname = info->filename;
    if (cache.find(hostname) != cache.end()) {
        return cache[hostname];
    } else {
        u_char* ip = dns_resolve(hostname);
        if (ip == NULL) {
            printf("Error in DNS resolution: %s\n", hostname);
            return NULL;
        } else {
            // Add the IP to the cache with a TTL of 10 minutes
            cache[hostname] = ip;
            time_t ttl = time(NULL) + (10 * 60);
            cache[hostname].ttl = &ttl;
        }
    }
}

// Function to manage memory efficiently by freeing allocated memory after use
void* free_memory(void* thread_info) {
    struct thread_info* info = (struct thread_info*)thread_info;
    fclose(info->file);
    free(info->filename);
}

int main(int argc, char* argv[]) {
    // Initialize the cache with a TTL of 10 minutes
    time_t ttl = time(NULL) + (10 * 60);
    cache.ttl = &ttl;

    // Check if there are any command line arguments
    if (argc == 2) {
        char* filenames = argv[1];
        process_files(filenames);
    } else {
        printf("Usage: %s [filename]\n", argv[0]);
    }
}']

