#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_REQUESTS 10 // maximum number of concurrent DNS resolution requests
#define DNS_SERVER "8.8.8.8" // default DNS server

struct dns_resolution_thread_args {
    char *hostname;
    struct in_addr *ip_address;
    int error_code;
};

void* dns_resolution_thread(void* args) {
    struct dns_resolution_thread_args* thread_args = (struct dns_resolution_thread_args*)args;

    // create a mutex for the thread to avoid race conditions and deadlocks
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // acquire the mutex before starting the DNS resolution
    pthread_mutex_lock(&mutex);

    // perform DNS resolution using standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int error_code = getaddrinfo(thread_args->hostname, NULL, &hints, &res);
    if (error_code != 0) {
        // handle DNS resolution errors by returning an appropriate error code
        thread_args->error_code = error_code;
    } else {
        // copy the IP address to the output argument
        memcpy(thread_args->ip_address, res->ai_addr, sizeof(struct in_addr));
    }

    // release the mutex after finishing the DNS resolution
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int dns_resolution(char *hostname, struct in_addr *ip_address) {
    // create a semaphore for the DNS resolution function to limit the number of concurrent requests
    sem_t *sem = sem_open("dns_resolution", O_CREAT, 0644, MAX_CONCURRENT_REQUESTS);
    if (sem == SEM_FAILED) {
        return -1;
    }

    // create a thread for the DNS resolution function and pass the hostname and output arguments as arguments to the thread
    struct dns_resolution_thread_args thread_args;
    thread_args.hostname = hostname;
    thread_args.ip_address = ip_address;
    pthread_t thread;
    int error_code = pthread_create(&thread, NULL, dns_resolution_thread, &thread_args);
    if (error_code != 0) {
        return error_code;
    }

    // wait for the DNS resolution to complete and handle any errors that may occur
    pthread_join(thread, NULL);
    if (thread_args.error_code != 0) {
        return thread_args.error_code;
    }

    // release the semaphore after finishing the DNS resolution
    sem_post(sem);
    return 0;
}
```
