// Key stretching constants
#define KEY_STRETCH_ITERATIONS 1000

/**
 * Encryption structure
 */
typedef struct {
    // Encryption mode
    int mode;

    // Key for encryption/decryption
    unsigned char key[32];

    // Initialization vector for CBC and CTR modes
    unsigned char iv[16];

    // HMAC-based message authentication code (MAC) for data integrity checks
    unsigned char mac[32];
} Encryption;

/**
 * Initialize encryption object with given mode, key, and initialization vector.
 *
 * @param enc Encryption object to initialize
 * @param mode Encryption mode (ECB, CBC, CTR, or GCM)
 * @param key Key for encryption/decryption
 * @param iv Initialization vector for CBC and CTR modes
 */
void init_encryption(Encryption *enc, int mode, unsigned char *key, unsigned char *iv);

/**
 * Set the key for the encryption object.
 *
 * @param enc Encryption object
 * @param key Key for encryption/decryption
 */
void set_key(Encryption *enc, unsigned char *key);

/**
 * Set the initialization vector for the encryption object.
 *
 * @param enc Encryption object
 * @param iv Initialization vector for CBC and CTR modes
 */
void set_iv(Encryption *enc, unsigned char *iv);

/**
 * Generate a secure key from a given password using PBKDF2.
 *
 * @param password Password to use as input for the KDF function
 * @param salt Salt value for randomizing the output of the KDF function
 * @param iterations Number of iterations for the KDF function
 * @return Secure key generated from the given password using PBKDF2
 */
unsigned char *generate_key_pbkdf2(const unsigned char *password, const unsigned char *salt, int iterations);

/**
 * Generate a secure key from a given password using HKDF.
 *
 * @param password Password to use as input for the KDF function
 * @param salt Salt value for randomizing the output of the KDF function
 * @param hash Hash algorithm used by the KDF function (e.g., SHA-256)
 * @return Secure key generated from the given password using HKDF
 */
unsigned char *generate_key_hkdf(const unsigned char *password, const unsigned char *salt, int hash);

/**
 * Encrypt data using the encryption object.
 *
 * @param enc Encryption object
 * @param plaintext Plaintext to be encrypted
 * @param ciphertext Ciphertext generated by encrypting the plaintext
 */
void encrypt(Encryption *enc, unsigned char *plaintext, unsigned char *ciphertext);

/**
 * Decrypt data using the encryption object.
 *
 * @param enc Encryption object
 * @param ciphertext Ciphertext to be decrypted
 * @param plaintext Plaintext generated by decrypting the ciphertext
 */
void decrypt(Encryption *enc, unsigned char *ciphertext, unsigned char *plaintext);

/**
 * Generate a message authentication code (MAC) for the given data using HMAC-SHA256.
 *
 * @param key Key used in the HMAC algorithm
 * @param data Data to be authenticated
 * @return MAC generated by the HMAC algorithm
 */
unsigned char *generate_mac(const unsigned char *key, const unsigned char *data);

/**
 * Verify a message authentication code (MAC) for the given data using HMAC-SHA256.
 *
 * @param key Key used in the HMAC algorithm
 * @param mac MAC to be verified
 * @param data Data that was used to generate the MAC
 * @return 1 if the MAC is valid, 0 otherwise
 */
int verify_mac(const unsigned char *key, const unsigned char *mac, const unsigned char *data);

/**
 * Free any allocated memory for the encryption object.
 *
 * @param enc Encryption object to free
 */
void free_encryption(Encryption *enc);

#endif //ENCRYPTION_H
