#define MAX_RECORDS 10000
#define MAX_VALUE_LENGTH 50

// Struct to represent a record in the dataset
struct record {
	char id[MAX_VALUE_LENGTH];
	char value[MAX_VALUE_LENGTH];
};

// Array to store the records
struct record records[MAX_RECORDS];

// Mutex for protecting access to the dataset
pthread_mutex_t mutex;

// Function to initialize the dataset
void init_dataset() {
	for (int i = 0; i < MAX_RECORDS; i++) {
		sprintf(records[i].id, "ID%d", i);
		sprintf(records[i].value, "%d", i);
	}
}

// Function to read a record from the dataset
void read_record(char *id) {
	pthread_mutex_lock(&mutex);
	for (int i = 0; i < MAX_RECORDS; i++) {
		if (strcmp(records[i].id, id) == 0) {
			printf("Reading record %s with value %s\n", records[i].id, records[i].value);
			break;
		}
	}
	pthread_mutex_unlock(&mutex);
}

// Function to write a record to the dataset
void write_record(char *id, char *value) {
	pthread_mutex_lock(&mutex);
	for (int i = 0; i < MAX_RECORDS; i++) {
		if (strcmp(records[i].id, id) == 0) {
			sprintf(records[i].value, "%s", value);
			printf("Writing record %s with new value %s\n", records[i].id, records[i].value);
			break;
		}
	}
	pthread_mutex_unlock(&mutex);
}

// Function to deallocate a record from the dataset
void delete_record(char *id) {
	pthread_mutex_lock(&mutex);
	for (int i = 0; i < MAX_RECORDS; i++) {
		if (strcmp(records[i].id, id) == 0) {
			printf("Deleting record %s\n", records[i].id);
			memset(&records[i], 0, sizeof(struct record));
			break;
		}
	}
	pthread_mutex_unlock(&mutex);
}

