// Structures for data store and entry
typedef struct {
    int offset;
    char key;
    void* record;
} DataEntry;

typedef struct {
    DataEntry** entries;
    size_t capacity;
    size_t count;
} DataStore;

// Initialize data store with given capacity
void initialize_data(DataStore* data_store, size_t capacity) {
    // Allocate memory for the array of pointers to entries
    data_store->entries = (DataEntry**)malloc(sizeof(DataEntry*) * capacity);
    if (!data_store->entries) {
        fprintf(stderr, "Failed to allocate memory for data store\n");
        exit(1);
    }
    // Initialize the count and capacity of the data store
    data_store->count = 0;
    data_store->capacity = capacity;
}

// Add entry to the data store
void add_entry(DataStore* data_store, DataEntry* entry) {
    pthread_mutex_lock(&data_store->entries[data_store->count]->offset);
    // Check if there is enough space in the array of pointers to entries
    if (data_store->count >= data_store->capacity) {
        fprintf(stderr, "Data store is full\n");
        exit(1);
    }
    // Allocate memory for the entry and copy the values from the given entry
    DataEntry* new_entry = (DataEntry*)malloc(sizeof(DataEntry));
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for new entry\n");
        exit(1);
    }
    memcpy(new_entry, entry, sizeof(DataEntry));
    // Add the new entry to the array of pointers to entries
    data_store->entries[data_store->count] = new_entry;
    data_store->count++;
    pthread_mutex_unlock(&data_store->entries[data_store->count]->offset);
}

// Process each entry in the data store
void process_entries(DataStore* data_store) {
    // Create a worker thread for each entry in the data store
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * data_store->count);
    if (!threads) {
        fprintf(stderr, "Failed to allocate memory for threads\n");
        exit(1);
    }
    // Create a thread for each entry in the data store
    for (size_t i = 0; i < data_store->count; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, &data_store->entries[i]) != 0) {
            fprintf(stderr, "Failed to create thread for entry %zu\n", i);
            exit(1);
        }
    }
    // Wait for each worker thread to finish processing its entry
    for (size_t i = 0; i < data_store->count; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread for entry %zu\n", i);
            exit(1);
        }
    }
}

// Check consistency of the data store
void check_consistency(DataStore* data_store) {
    // Iterate over each entry in the data store
    for (size_t i = 0; i < data_store->count; i++) {
        pthread_mutex_lock(&data_store->entries[i]->offset);
        if (data_store->entries[i]->offset != i * 4) {
            fprintf(stderr, "Inconsistent offset for entry %zu: expected %d but got %d\n", i, i * 4, data_store->entries[i]->offset);
        }
        if (data_store->entries[i]->key != i) {
            fprintf(stderr, "Inconsistent key for entry %zu: expected %c but got %c\n", i, i, data_store->entries[i]->key);
        }
        pthread_mutex_unlock(&data_store->entries[i]->offset);
    }
}

// Worker thread function to process each entry in the data store
void* worker_thread(void* args) {
    DataEntry* entry = (DataEntry*)args;
    // Simulate processing by sleeping for 1 second per entry
    sleep(1);
    return NULL;
}

// Free resources allocated for the data store
void free_resources(DataStore* data_store) {
    // Iterate over each entry in the data store and free its memory
    for (size_t i = 0; i < data_store->count; i++) {
        pthread_mutex_lock(&data_store->entries[i]->offset);
        free(data_store->entries[i]);
        data_store->entries[i] = NULL;
        pthread_mutex_unlock(&data_store->entries[i]->offset);
    }
    // Free the array of pointers to entries and reset the count and capacity of the data store
    free(data_store->entries);
    data_store->count = 0;
    data_store->capacity = 0;
}

// Main function for testing the data store implementation
