  size_t length; // Length of the buffer in bytes
} BUFFER_CTX;

// Function signature for performing a buffer operation
BUFFER_CTX* perform_buffer_operation(const char* input_buffer, const char* option) {
  // Validate that the input buffer is non-null and not empty
  if (!input_buffer || !strlen(input_buffer)) {
    return NULL;
  }

  // Parse the command line options
  char* cmd = strdup(option);
  int opt;
  while ((opt = getopt(cmd, "r:w:s:k:c")) != -1) {
    switch (opt) {
      case 'r':
        // Read a file into the buffer
        input_buffer = fread(input_buffer, sizeof(char), 1024, stdin);
        break;
      case 'w':
        // Write the buffer content to a file
        fwrite(input_buffer, sizeof(char), strlen(input_buffer), stdout);
        break;
      case 's':
        // Perform a checksum calculation on the buffer content using SHA256
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256(input_buffer, strlen(input_buffer), digest);
        printf("Checksum: %s\n", digest);
        break;
      case 'k':
        // Set a custom key for file encryption/decryption operations (optional)
        char* key = optarg;
        if (!key || strlen(key) < 16) {
          return NULL;
        }
        break;
      case 'c':
        // Use a configuration file to load default settings (optional)
        FILE* config_file = fopen("config.ini", "r");
        if (!config_file) {
          return NULL;
        }
        // Load the default settings from the configuration file
        // ...
    }
  }

  // Create a new buffer context and initialize it with the input buffer data
  BUFFER_CTX* ctx = (BUFFER_CTX*)malloc(sizeof(BUFFER_CTX));
  if (!ctx) {
    return NULL;
  }
  ctx->buffer = strdup(input_buffer);
  ctx->length = strlen(input_buffer);

  // Perform any additional operations based on the command line options
  // ...

  return ctx;
}
```
