void *pool_alloc(size_t size) {
    // Check if the size is valid
    if (size == 0 || size > MAX_POOL_SIZE) {
        return NULL;
    }

    // Allocate memory from the pool
    void *mem = malloc(size);
    if (!mem) {
        return NULL;
    }

    // Initialize the allocated memory to zero
    memset(mem, 0, size);

    // Return the allocated memory
    return mem;
}

