void establish_connection(const char* host, const char* port) {
    int sock;
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, host, &server_address.sin_addr);
    server_address.sin_port = htons(atoi(port));

    // Create a socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Connect to server
    if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("connect failed");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offset and key arrays
    long* offsets = malloc(sizeof(long) * NUM_OFFSETS);
    int* keys = malloc(sizeof(int) * NUM_KEYS);

    // Initialize the offset and key arrays
    for (int i = 0; i < NUM_OFFSETS; i++) {
        offsets[i] = rand() % MAX_OFFSET;
    }
    for (int i = 0; i < NUM_KEYS; i++) {
        keys[i] = rand() % MAX_KEY;
    }

    // Allocate memory for record structures
