    // Initialize the record structures
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].double_value = rand() % MAX_DOUBLE;
    }

    // Set up buffer sizes and optimize data copying operations
    int buffer_size = BUFFER_SIZE;
    char* buffer = malloc(buffer_size);
    int bytes_read, bytes_written;

    while (1) {
        // Read from socket
        if ((bytes_read = recv(sock, buffer, buffer_size, 0)) < 0) {
            perror("recv failed");
            exit(EXIT_FAILURE);
        } else if (bytes_read == 0) {
            // Connection closed
            break;
        }

        // Write to socket
        if ((bytes_written = send(sock, buffer, bytes_read, 0)) < 0) {
            perror("send failed");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up resources
    free(buffer);
    free(records);
    free(offsets);
    free(keys);
}
