        int* keys = (int*)calloc(numRecords, sizeof(int));
        long* offsets = (long*)calloc(numRecords, sizeof(long));
    } catch (std::bad_alloc& e) {
        LOG_ERROR("Memory allocation failed due to %s", e.what());
        return;
