    for (int i = 0; i < numRecords; ++i) {
        try {
            keys[i] = rand() % keyRangeMax + keyRangeMin;
            offsets[i] = rand() % offsetRangeMax + offsetRangeMin;
        } catch (std::bad_alloc& e) {
