                       numRecords * sizeof(Record), numRecords, numRecords, numRecords);
        LOG_MEMORY("Initialized %d records with random values within the specified ranges", numRecords);
    } catch (std::bad_alloc& e) {
        LOG_ERROR("Memory allocation failed due to %s", e.what());
        return;
    }

    // Free memory when no longer needed in a try-catch block
    if (records != NULL) {
        free(records);
    }
