// Function to insert records into the array of records based on their corresponding keys.
// Handles collisions by using a simple hash table with separate chaining.
void insertRecord(HashTable *ht, int key, Record record) {
    // Calculate the index in the hash table for the given key
    size_t index = key % ht->capacity;

    // Check if there is already a collision at this index
    if (ht->records[index].key != -1) {
        // If there is a collision, add the new record to the end of the linked list
        Record *head = &ht->records[index];
        while (head->next != NULL) {
            head = head->next;
        }
        head->next = malloc(sizeof(Record));
        head->next->key = key;
        head->next->value = record.value;
    } else {
        // If there is no collision, add the new record to the beginning of the linked list
        ht->records[index].key = key;
        ht->records[index].value = record.value;
    }
}

// Function to deallocate memory for the arrays and hash table.
void destroyArrays(HashTable *ht) {
    // Deallocate memory for the offset array
    free(ht->offsets);

    // Deallocate memory for the key array
    free(ht->keys);

    // Deallocate memory for the hash table
    free(ht);
}
