// Thread-safe memory management for network monitoring module
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_PACKETS 1024 // Maximum number of packets to store in the memory buffer
#define PAYLOAD_LEN 64   // Length of each payload string
#define PACKET_TYPE_NUM 3 // Number of packet types

typedef struct {
    long timestamp; // Timestamp for the packet
    char* payload;  // Payload pointer for the packet
    int type;       // Packet type (0-2)
} packet_record;

// Predefined payload templates
char* payload_templates[PACKET_TYPE_NUM] = {
    "Hello, world!",
    "This is a test message.",
    "This is a second test message."
};

// Memory management variables
pthread_mutex_t mem_lock; // Mutex for thread-safe memory allocation
size_t current_mem = 0;   // Current memory usage in bytes
size_t max_mem = 1024 * 1024; // Maximum allowed memory usage in bytes (1 MB)
char* mem_block = NULL;    // Memory block for storing packet timestamps and payloads
packet_record* packet_records = NULL; // Array of packet records
int num_packets = 0;       // Number of packets currently stored in the memory buffer

// Initialize memory management variables
void init_mem_management() {
    pthread_mutex_init(&mem_lock, NULL);
    current_mem = 0;
}

// Allocate and initialize memory for an array of 'packet_record' structures
packet_record* allocate_packet_records(int num) {
    packet_record* records = (packet_record*)malloc(sizeof(packet_record) * num);
    if (!records) {
        return NULL;
    }
    memset(records, 0, sizeof(packet_record) * num);
    for (int i = 0; i < num; ++i) {
        records[i].payload = allocate_payload();
    }
    return records;
}

// Allocate and initialize memory for a payload string
char* allocate_payload() {
    char* payload = (char*)malloc(PAYLOAD_LEN);
    if (!payload) {
        return NULL;
    }
    memset(payload, 0, PAYLOAD_LEN);
    return payload;
}

// Add a new packet to the memory buffer
void add_packet(long timestamp, int type) {
    // Lock the mutex before modifying shared data
    pthread_mutex_lock(&mem_lock);
    if (num_packets >= MAX_PACKETS || current_mem > max_mem - PAYLOAD_LEN) {
        pthread_mutex_unlock(&mem_lock);
        return; // Memory full, drop the packet
    }
    // Allocate memory for the new packet and initialize it
    packet_record* record = &(packet_records[num_packets++]);
    record->timestamp = timestamp;
    record->type = type;
    record->payload = allocate_payload();
    if (record->payload) {
        strncpy(record->payload, payload_templates[type], PAYLOAD_LEN);
    } else {
        num_packets--;
    }
    current_mem += PAYLOAD_LEN;
    // Unlock the mutex and return
    pthread_mutex_unlock(&mem_lock);
}

// Free memory allocated for a packet record
void free_packet_record(packet_record* record) {
    if (record->payload) {
        free(record->payload);
    }
    free(record);
}

// Free all memory allocated for the packet records and reset the memory management variables
void free_all_mem() {
    // Lock the mutex before modifying shared data
    pthread_mutex_lock(&mem_lock);
    for (int i = 0; i < num_packets; ++i) {
        packet_record* record = &(packet_records[i]);
        free_packet_record(record);
    }
    if (mem_block) {
        free(mem_block);
    }
    current_mem = 0;
    num_packets = 0;
    // Unlock the mutex and return
    pthread_mutex_unlock(&mem_lock);
}

// Implement error handling for memory allocation failures
void* malloc_with_error(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed. Size = %d\n", (int)size);
    }
    return ptr;
}

// Implement error handling for memory deallocation failures
void free_with_error(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Error: Memory deallocation failed. Pointer = %p\n", ptr);
    } else {
        free(ptr);
    }
}']

