        records[i].key = keys[i];
        records[i].important = important;

        if (!records[i].important) {
            records[i].value = random() % MAX_VALUE + MIN_VALUE;
        } else {
            // Set the value to a specific default value if no random value is generated within the specified range
            records[i].value = DEFAULT_VALUE;
        }
    }

    // Free the memory for the key and offset arrays since they are not needed anymore
    free(keys);
    free(offsets);
}

