```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int intValue;
    float floatValue;
    char charArray[50];
} record;

void dynamicAllocation(int size) {
    // Check if the input size is valid
    if (size <= 0) {
        printf("Error: Invalid input size\n");
        return;
    }

    // Allocate memory for the arrays and initialize them with random values
    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    srand((unsigned)time(NULL));

    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand();
        records[i].intValue = rand();
        records[i].floatValue = (float)rand() / RAND_MAX;
        strcpy(records[i].charArray, "Random string");
    }

    // Save the initialized records to a file in binary format
    FILE *file = fopen("records.bin", "wb");
    if (file == NULL) {
        printf("Error: Could not open file\n");
        return;
    }
    for (int i = 0; i < size; i++) {
        fwrite(&offsets[i], sizeof(long), 1, file);
        fwrite(&keys[i], sizeof(int), 1, file);
        fwrite(&records[i].intValue, sizeof(int), 1, file);
        fwrite(&records[i].floatValue, sizeof(float), 1, file);
        fwrite(records[i].charArray, 50 * sizeof(char), 1, file);
    }
    fclose(file);

    // Free the allocated memory to prevent memory leaks
    free(offsets);
    free(keys);
    free(records);
}
