#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to store records
typedef struct {
    int key;
} record;

void initializeRecords(int size, char *filename) {
    // Allocate memory for keys and offsets
    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));

    // Initialize keys and offsets randomly
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 100 + 1;
        offsets[i] = rand() % 100 + 1;
    }

    // Allocate memory for records and initialize them
    record *records = malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i].key = keys[i];
    }

    // Save records to file in binary format
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file for writing\n");
        return;
    }
    fwrite(records, sizeof(record), size, file);
    fclose(file);

    // Free memory allocated for keys, offsets, and records
    free(keys);
    free(offsets);
    free(records);
}
```
