```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the record structure
typedef struct {
    int intValue;
    float floatValue;
    char charArray[50];
} record;

// Function to initialize records with random values and save them to disk
void initializeRecords(int size, const char* filename) {
    // Validate the input parameters
    if (size <= 0 || filename == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for arrays and records
    int *keys = malloc(size * sizeof(int));
    long *offsets = malloc(size * sizeof(long));
    record *records = malloc(size * sizeof(record));
    if (keys == NULL || offsets == NULL || records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(keys);
        free(offsets);
        free(records);
        return;
    }

    // Initialize keys and offsets randomly
    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % 100;
        offsets[i] = rand() % 500;
        records[i].intValue = keys[i];
        records[i].floatValue = (float)keys[i] / 100.0f;
        strcpy(records[i].charArray, "Hello World!");
    }

    // Save records to disk
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        free(keys);
        free(offsets);
        free(records);
        return;
    }
    for (int i = 0; i < size; ++i) {
        if (!fwrite(&records[i], sizeof(record), 1, file)) {
            fprintf(stderr, "Failed to write record %d\n", i);
            break;
        }
    }
    fclose(file);

    // Free allocated memory
    free(keys);
    free(offsets);
    free(records);
}

int main() {
    int size = 100;
    const char* filename = "data.bin";
    initializeRecords(size, filename);
    return 0;
}
