    long max;
} range_t;

void initialize_records(record *records, size_t num_records, range_t *ranges) {
    // Validate the input parameters
    if (records == NULL || ranges == NULL || num_records == 0) {
        return;
    }

    // Allocate memory for the arrays of offsets and keys
    records->offset = (long *)malloc(num_records * sizeof(long));
    records->key = (int *)malloc(num_records * sizeof(int));
    records->value = (double *)malloc(num_records * sizeof(double));
    if (records->offset == NULL || records->key == NULL || records->value == NULL) {
        // Handle out-of-memory conditions gracefully by checking return values from malloc() and free()
        printf("Failed to allocate memory for the arrays of offsets, keys, and values. Aborting.\n");
        return;
    }

    // Initialize the arrays of offsets and keys with random values within the specified ranges
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        records->offset[i] = rand() % ranges->max + ranges->min;
        records->key[i] = rand() % ranges->max + ranges->min;
        records->value[i] = (double)rand() / RAND_MAX;
