        return 0;
    }
    int numThreads = 0;
    char* outputFile = NULL;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--manpage")) {
            printf("Manual page for %s\n", argv[0]);
            return 0;
        } else if (!strcmp(argv[i], "-cs")) {
            numThreads = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-o")) {
            outputFile = argv[++i];
        }
    }

    // Check for valid input
    if (numThreads < 1) {
        fprintf(stderr, "Error: Invalid number of threads\n");
        return 1;
    }
    if (outputFile == NULL) {
        fprintf(stderr, "Error: No output file specified\n");
        return 1;
    }

    // Initialize data structures for each thread
    pthread_key_t tlsKey;
    pthread_key_create(&tlsKey, NULL);
    int numRecords = numThreads * 1000;
    long* offsetArray = (long*)malloc(numRecords * sizeof(long));
    if (offsetArray == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
        return 1;
    }
    int* keyArray = (int*)malloc(numRecords * sizeof(int));
    if (keyArray == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        free(offsetArray);
        return 1;
    }
    Record** recordArray = (Record**)malloc(numRecords * sizeof(Record*));
    if (recordArray == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(offsetArray);
        free(keyArray);
        return 1;
    }
    initDataStructures(numThreads, numRecords, offsetArray, keyArray, recordArray);

    // Process data concurrently using threads
    pthread_t* threadIds = (pthread_t*)malloc(numThreads * sizeof(pthread_t));
    if (threadIds == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for thread IDs\n");
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        return 1;
    }
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threadIds[i], NULL, processData, &numRecords);
    }
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threadIds[i], NULL);
    }
    free(threadIds);

    // Output results to file
    FILE* fp = fopen(outputFile, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return 1;
    }
    for (int i = 0; i < numRecords; i++) {
