    }
    fclose(fp);

    // Clean up memory
    free(offsetArray);
    free(keyArray);
    free(recordArray);
    return 0;
}

int processData(void* args) {
    int numRecords = *(int*)args;
    long* offsetArray = (long*)pthread_getspecific(tlsKey);
    int* keyArray = (int*)pthread_getspecific(tlsKey);
    Record** recordArray = (Record**)pthread_getspecific(tlsKey);

    // Process data concurrently using threads
    for (int i = 0; i < numRecords; i++) {
        offsetArray[i]++;
        keyArray[i] += offsetArray[i];
        recordArray[i]->value += offsetArray[i];
    }
