// Structure for storing record data
typedef struct {
    int key;
} record_t;

// Function to initialize arrays and allocate memory
int init_arrays(long **offsets, int **keys, record_t **records, size_t key_count) {
    // Check input parameters for validity
    if (offsets == NULL || keys == NULL || records == NULL || key_count <= 0) {
        fprintf(stderr, "Invalid input parameter\n");
        return -1;
    }

    // Allocate memory for the offsets array
    *offsets = malloc(sizeof(long) * (key_count * 2));
    if (*offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return -1;
    }

    // Allocate memory for the keys array
    *keys = malloc(sizeof(int) * key_count);
    if (*keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(*offsets);
        return -1;
    }

    // Allocate memory for the records array
    *records = malloc(sizeof(record_t) * key_count);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize the offsets array with random values between 0 and 100
    for (size_t i = 0; i < key_count * 2; i++) {
        (*offsets)[i] = rand() % 100 + 1;
    }

    // Initialize the keys array with random values between 1 and 100
    for (size_t i = 0; i < key_count; i++) {
        (*keys)[i] = rand() % 100 + 1;
    }

    // Initialize the records array with random values between 1 and 100
    for (size_t i = 0; i < key_count; i++) {
        (*records)[i].key = rand() % 100 + 1;
    }

    return 0;
}

// Function to free all allocated memory
void cleanup(long *offsets, int *keys, record_t *records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}
