    // Initialize variables for file size and output file stream
    long file_size = 0;
    FILE* output_stream = NULL;

    // Open the input file in binary mode
    FILE* input_stream = fopen(input_file, "rb");
    if (input_stream == NULL) {
        printf("Error: failed to open input file\n");
        return 1;
    }

    // Get the size of the input file in bytes
    fseek(input_stream, 0, SEEK_END);
    file_size = ftell(input_stream);
    rewind(input_stream);

    // Create a buffer for reading the input file
    char* buffer = malloc(file_size * sizeof(char));
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for buffer\n");
        fclose(input_stream);
        return 1;
    }

    // Read the input file into the buffer
    size_t bytes_read = fread(buffer, sizeof(char), file_size, input_stream);
    if (bytes_read != file_size) {
        printf("Error: failed to read entire input file\n");
        free(buffer);
        fclose(input_stream);
        return 1;
    }

    // Close the input file stream
    fclose(input_stream);

    // Create a new output file stream in binary mode
    output_stream = fopen(output_file, "wb");
    if (output_stream == NULL) {
