// Function to add a new UE context to the list
void add_ue_context(char *imsi, struct radio_bearer *rb) {
    // Create a new UE context structure
    struct ue_context *new_ctx = malloc(sizeof(struct ue_context));
    new_ctx->imsi = strdup(imsi);
    new_ctx->rb = rb;

    // Add the new UE context to the list
    pthread_mutex_lock(&ue_ctx_lock);
    if (ue_ctx_list == NULL) {
        ue_ctx_list = new_ctx;
    } else {
        struct ue_context *curr = ue_ctx_list;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_ctx;
