    // Find the UE context with the specified IMSI
    struct ue_context *curr = ue_ctx_list;
    while (curr != NULL && strcmp(curr->imsi, imsi) != 0) {
        curr = curr->next;
    }

    // Remove the UE context from the list
    if (curr != NULL) {
        pthread_mutex_lock(&ue_ctx_lock);
        if (curr == ue_ctx_list) {
            ue_ctx_list = curr->next;
        } else {
            struct ue_context *prev = ue_ctx_list;
            while (prev->next != curr) {
                prev = prev->next;
            }
            prev->next = curr->next;
        }
        pthread_mutex_unlock(&ue_ctx_lock);
        free(curr->imsi);
