// Function to insert a new node into the array based on its offset value
void insert_node(size_t offset, int key) {
    // Find the position where the new node should be inserted
    size_t pos = 0;
    while (pos < num_nodes && nodes[pos].offset <= offset) {
        pos++;
    }

    // Allocate memory for the new node and initialize its values
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) {
        perror("Error allocating memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->offset = offset;
    new_node->key = key;

    // Insert the new node into the array
    memmove(&nodes[pos + 1], &nodes[pos], (num_nodes - pos) * sizeof(node_t));
    nodes[pos] = *new_node;
}

// Function to remove a node from the array based on its offset value
void remove_node(size_t offset) {
    // Find the position where the node should be removed
    size_t pos = 0;
    while (pos < num_nodes && nodes[pos].offset <= offset) {
        pos++;
    }

    // Remove the node from the array
    memmove(&nodes[pos], &nodes[pos + 1], (num_nodes - pos - 1) * sizeof(node_t));
}

// Function to free memory for all arrays and nodes
void cleanup() {
    // Free the offset and key arrays
    free(offsets);
    free(keys);

    // Free the node array
    for (size_t i = 0; i < num_nodes; i++) {
        free(nodes[i]);
    }
    free(nodes);
}

