    int derivedKeyLen = PBKDF2((const unsigned char*)password, strlen(password), HASH_ALG, HKDF_SALT_SIZE, KEY_SIZE, derivedKey);
    if (!derivedKeyLen) {
        printf("Error: failed to derive key\n");
        return 1;
