    int initResult = EVP_EncryptInit(ctx, cipher, derivedKey, NULL);
    if (!initResult) {
        printf("Error: failed to initialize encryption\n");
        return 1;
    }

    // Free memory for the key and close the key file
    free(derivedKey);
    fclose(keyFilePtr);

    return 0;
}

