    if (!derivedKeyLen) {
        printf("Error: failed to derive key using HKDF\n");
        return;
    }
}

// Function to handle memory allocation for keys securely
void secureAllocateMemory(int size, unsigned char* buffer) {
    // Allocate memory for the buffer using OpenSSL's CRYPTO_malloc function
    void* mallocResult = CRYPTO_malloc(size);
    if (!mallocResult) {
        printf("Error: failed to allocate memory for buffer\n");
        return;
    }

    // Zero out the memory using OpenSSL's OPENSSL_cleanse function
    OPENSSL_cleanse((unsigned char*)buffer, size);
}

// Function to handle memory deallocation for keys securely
void secureFreeMemory(int size, unsigned char* buffer) {
    // Free the memory for the buffer using OpenSSL's CRYPTO_free function
    CRYPTO_free((void*)buffer);
}
