// Define the sensor data structure
typedef struct {
    int value_int;
    float value_float;
    char* value_str;
    time_t timestamp;
    int sensor_id;
} sensor_data;

// Define the cache for storing previously allocated memory
#define MAX_CACHE 1024
static void* cache[MAX_CACHE];
static size_t cache_size = 0;

void allocate_memory(size_t size) {
    // Check if there is any available space in the cache
    for (size_t i = 0; i < cache_size; i++) {
        if (cache[i] != NULL && cache[i] >= size) {
            return cache[i];
        }
    }

    // If there is no available space in the cache, allocate new memory
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error: failed to allocate memory\n");
        exit(1);
    }

    return ptr;
}

void deallocate_memory(void* ptr, size_t size) {
    // Check if the pointer is in the cache
    for (size_t i = 0; i < cache_size; i++) {
        if (cache[i] == ptr) {
            cache[i] = NULL;
            return;
        }
    }

    // If the pointer is not in the cache, deallocate it
    free(ptr);
}

void init_sensor_data(int num_ints, int num_floats, int num_strings) {
    size_t size = sizeof(sensor_data) + (num_ints * sizeof(int)) + (num_floats * sizeof(float)) + (num_strings * sizeof(char*));
