    // Initialize the sensor data structure
    data->value_int = 42;
    data->value_float = 3.14;
    data->value_str = *(str_array + num_strings - 1);
    data->timestamp = time(NULL);
    data->sensor_id = 0;

    // Store the pointer in the cache for later reuse
