function updateUserPassword($userId, $newPassword) {
    // Validate the new password
    if (!validateNewPassword($newPassword)) {
        throw new InvalidArgumentException('Invalid new password');
    }

    // Prepare the SQL statement for updating the user's password
    $sql = "UPDATE users SET password = :password WHERE id = :userId";

    // Create a prepared statement to prevent SQL injection
    $stmt = $this->dbh->prepare($sql);

    // Bind the user ID and new password to the prepared statement
    $stmt->bindParam(':userId', $userId, PDO::PARAM_INT);
    $stmt->bindParam(':password', $newPassword, PDO::PARAM_STR);

    // Execute the prepared statement
    $result = $stmt->execute();

    // Check if there were any errors during execution
    if ($result === false) {
        throw new RuntimeException("Error updating user's password");
    }

    // Log any errors or exceptions to a separate error log file
    $this->logError($stmt->errorInfo());

    // Implement rate limiting to prevent brute-force attacks by limiting password change attempts to once every 5 minutes per user
    $rateLimit = 120; // seconds
    if (isset($_SESSION['passwordChangeAttempts'])) {
        $attempts = $_SESSION['passwordChangeAttempts'];
        if ($attempts >= $rateLimit) {
            throw new RuntimeException("Rate limit exceeded");
        } else {
            $_SESSION['passwordChangeAttempts'] += 1;
        }
    } else {
        $_SESSION['passwordChangeAttempts'] = 1;
    }

    // Validate the current password before updating the new one to ensure the user is authenticated
    if (!validateCurrentPassword($userId, $newPassword)) {
        throw new RuntimeException("Invalid current password");
    }

    // Check if the new password is different from the current password to avoid unnecessary database updates
    if ($newPassword === $currentPassword) {
        return;
    }

    // Integrate with an external authentication service to verify the user's credentials before updating the password in the database
    $authService = new AuthService();
    if (!$authService->verifyCredentials($userId, $newPassword)) {
        throw new RuntimeException("Invalid credentials");
    }

    // Handle concurrent updates by ensuring atomic operations when updating user data in the database
    $this->dbh->beginTransaction();
    try {
        $stmt = $this->dbh->prepare($sql);
        $result = $stmt->execute();
        if ($result === false) {
            throw new RuntimeException("Error updating user's password");
        }
        $this->dbh->commit();
    } catch (PDOException $e) {
        $this->dbh->rollBack();
        throw new RuntimeException("Error updating user's password: " . $e->getMessage());
    }

    // Implement a mechanism to temporarily lock users who fail more than three consecutive authentication attempts for 30 minutes
    if (isset($_SESSION['failedLoginAttempts'])) {
        $attempts = $_SESSION['failedLoginAttempts'];
        if ($attempts >= 3) {
            // Temporarily lock the user account for 30 minutes
            $lockTime = time() + 30 * 60;
            setcookie('userLocked', 'true', $lockTime, '/');
            throw new RuntimeException("User account temporarily locked");
        } else {
            $_SESSION['failedLoginAttempts'] += 1;
        }
    } else {
        $_SESSION['failedLoginAttempts'] = 1;
    }
}
