struct mempool {
    int size; // total size of the memory pool
    char *data; // pointer to the start of the memory pool
};

// Initialize memory pool
struct mempool* init_mempool(int size) {
    struct mempool *mp = (struct mempool*)malloc(sizeof(struct mempool));
    mp->size = size;
    mp->data = (char*)malloc(size);
    return mp;
}

// Allocate memory from the memory pool
void* mempool_alloc(struct mempool *mp, int size) {
    if (mp->size < size) { // check if there is enough space in the pool
        fprintf(stderr, "Error: Not enough space in memory pool.\n");
        return NULL;
    }
    char *data = mp->data + mp->size - size;
    mp->size -= size;
    return data;
}

