    // Array of 'long' offset values
    long* offsets;
    // Array of 'int' keys
    int* keys;
    // Array of 'Record' structures
    Record* records;
};

// Function to initialize the database index system data structures
void initDatabaseIndexSystem(struct DatabaseIndexSystem* db) {
    assert(db != NULL);

    // Allocate memory for the offset array
    db->offsets = (long*)malloc(sizeof(long) * 1024);
    if (db->offsets == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the key array
    db->keys = (int*)malloc(sizeof(int) * 1024);
    if (db->keys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the record array
    db->records = (Record*)malloc(sizeof(Record) * 1024);
    if (db->records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the offset array with default values
    for (int i = 0; i < 1024; i++) {
        db->offsets[i] = -1;
    }

    // Initialize the key array with default values
    for (int i = 0; i < 1024; i++) {
        db->keys[i] = -1;
    }
}

// Function to insert a new record into the database index system
void insertRecord(struct DatabaseIndexSystem* db, int key, long offset) {
    assert(db != NULL);

    // Check if the key is already present in the database
    for (int i = 0; i < 1024; i++) {
        if (db->keys[i] == key) {
            printf("Error: Key %d already exists in the database\n", key);
            return;
        }
    }

    // Find an empty slot in the offset and key arrays
    int index = -1;
    for (int i = 0; i < 1024; i++) {
        if (db->offsets[i] == -1) {
            index = i;
            break;
        }
    }

    // Check if an empty slot was found
    if (index == -1) {
        printf("Error: Offset array is full\n");
        return;
    }

    // Update the offset and key arrays
    db->offsets[index] = offset;
    db->keys[index] = key;
}

// Function to delete a record from the database index system
void deleteRecord(struct DatabaseIndexSystem* db, int key) {
    assert(db != NULL);

    // Find the index of the key in the key array
    int index = -1;
    for (int i = 0; i < 1024; i++) {
        if (db->keys[i] == key) {
            index = i;
            break;
        }
    }

    // Check if the key was found
    if (index == -1) {
        printf("Error: Key %d does not exist in the database\n", key);
        return;
    }

    // Update the offset and key arrays
    db->offsets[index] = -1;
    db->keys[index] = -1;
}

// Function to update an existing record in the database index system
void updateRecord(struct DatabaseIndexSystem* db, int key, long offset) {
    assert(db != NULL);

    // Find the index of the key in the key array
    int index = -1;
    for (int i = 0; i < 1024; i++) {
        if (db->keys[i] == key) {
            index = i;
            break;
        }
    }

    // Check if the key was found
    if (index == -1) {
        printf("Error: Key %d does not exist in the database\n", key);
        return;
    }

    // Update the offset array
    db->offsets[index] = offset;
}

// Function to retrieve a record from the database index system
Record* getRecord(struct DatabaseIndexSystem* db, int key) {
    assert(db != NULL);

    // Find the index of the key in the key array
    int index = -1;
    for (int i = 0; i < 1024; i++) {
        if (db->keys[i] == key) {
            index = i;
            break;
        }
    }

    // Check if the key was found
    if (index == -1) {
        printf("Error: Key %d does not exist in the database\n", key);
        return NULL;
    }

    // Return the corresponding record structure
    return &db->records[index];
}

// HTTP PUT method to update an existing resource in the database index system using a unique identifier and a request body containing the updated data
void putResource(int key, char* requestBody) {
    assert(requestBody != NULL);

    // Create a new record structure with the updated data
    Record record;
    memcpy(&record.data, requestBody, strlen(requestBody));

    // Update the corresponding record in the database index system
    updateRecord(&db, key, record.offset);
}

// HTTP DELETE method to delete a resource from the database index system using a unique identifier
void deleteResource(int key) {
    assert(key != NULL);

    // Delete the corresponding record in the database index system
    deleteRecord(&db, key);
}

// HTTP GET method to retrieve a resource from the database index system using a unique identifier
