  // Initialize the data record array with random values and strings
  srand(time(NULL));
  for (int i = 0; i < num_records; i++) {
    records[i].value = doubles[i];
    records[i].string = strings[rand() % num_strings];
  }
}

// A function that deallocates memory for a data record
