#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int value;
} record;

void create_records(size_t num_records, size_t offset_array_size, size_t key_array_size, int min_key_value, int max_key_value, int persist) {
    // Allocate memory for the offset array
    long *offset_array = malloc(offset_array_size * sizeof(long));
    if (offset_array == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for the offset array\n");
        return;
    }

    // Initialize the offset array with random values within the given range
    srand(time(NULL));
    for (size_t i = 0; i < offset_array_size; i++) {
        long offset = rand() % (max_offset - min_offset + 1) + min_offset;
        offset_array[i] = offset;
    }

    // Allocate memory for the key array
    int *key_array = malloc(key_array_size * sizeof(int));
    if (key_array == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for the key array\n");
        free(offset_array);
        return;
    }

