#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Data structure to represent a record in the complex data structure
typedef struct {
    int value;
} record_t;

// Function to initialize the complex data structure with random values within specified ranges
void init_complex_data(long* offset, int* key, record_t** records, size_t num_records) {
    // Initialize the arrays of offsets and keys with random values
    for (size_t i = 0; i < num_records; i++) {
        offset[i] = rand() % 1000;
        key[i] = rand() % 1000;
    }

    // Initialize the array of records with random values
    for (size_t i = 0; i < num_records; i++) {
        records[i]->value = rand() % 1000;
    }
}

// Function to allocate and initialize memory for the complex data structure in a thread-safe manner
void* alloc_complex_data(size_t num_records) {
    // Allocate memory for the arrays of offsets, keys, and records
    long* offset = malloc(num_records * sizeof(long));
    int* key = malloc(num_records * sizeof(int));
    record_t** records = malloc(num_records * sizeof(record_t*));

    // Initialize the memory for the arrays of offsets and keys with random values
    init_complex_data(offset, key, records, num_records);

    return (void*)records;
}

// Function to free the memory allocated for the complex data structure in a thread-safe manner
void free_complex_data(void* records) {
    // Free the memory allocated for the arrays of offsets, keys, and records
    record_t** records_ptr = (record_t**)records;
    free(records_ptr);
}

// Example usage demonstrating how to create `data_entry` structures and initialize them in a multi-threaded environment using `pthread_create` and `pthread_join`
int main() {
    size_t num_records = 100;

    // Allocate memory for the complex data structure in a thread-safe manner
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    void* records = alloc_complex_data(num_records);

    // Create threads to initialize the complex data structure
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, init_complex_data, (void*)records);
    pthread_create(&thread2, NULL, init_complex_data, (void*)records);

    // Wait for the threads to finish initializing the complex data structure
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Free the memory allocated for the complex data structure in a thread-safe manner
    free_complex_data(records);

    return 0;
}
