    int num_algorithms = 0;
    for (const char *token = strtok(config, ","); token != NULL && num_algorithms < 10; token = strtok(NULL, ",")) {
        algorithms[num_algorithms++] = token;
    }

    // Add each algorithm to the library
    for (int i = 0; i < num_algorithms; ++i) {
        const char *algorithm = algorithms[i];
        if (!strcmp(algorithm, "AES128")) {
