        } else if (!strcmp(algorithm, "Camellia256")) {
            EVP_add_cipher("camellia-256-cbc", NULL);
        } else if (!strcmp(algorithm, "MD5")) {
            EVP_add_digest("md5", NULL);
        } else if (!strcmp(algorithm, "SHA256")) {
            EVP_add_digest("sha256", NULL);
        } else if (!strcmp(algorithm, "RSA1024")) {
            EVP_add_cipher("rsa-1024-cbc", NULL);
        } else {
            // Unsupported algorithm
            ERR_raise(ERR_LIB_EVP, EVP_R_UNSUPPORTED_ALGORITHM);
            return 0;
        }
    }

    // Add any necessary aliases for the added algorithms
    for (int i = 0; i < num_algorithms; ++i) {
        const char *algorithm = algorithms[i];
        if (!strcmp(algorithm, "AES128") || !strcmp(algorithm, "Camellia256")) {
            EVP_add_digest_alias("aes-128-cbc", "md5");
        } else if (!strcmp(algorithm, "RSA1024")) {
            EVP_add_digest_alias("rsa-1024-cbc", "sha256");
        }
    }

    // Verify that the added algorithms are supported by the current OpenSSL version
    for (int i = 0; i < num_algorithms; ++i) {
        const char *algorithm = algorithms[i];
        if (!EVP_is_supported(algorithm)) {
            ERR_raise(ERR_LIB_EVP, EVP_R_UNSUPPORTED_ALGORITHM);
            return 0;
        }
    }

    // Return success
    return 1;
}
