// Function to dynamically allocate memory for and initialize a linked list of nodes
void create_node_list(double* values, char* keys, size_t count) {
    // Check input parameters for validity
    if (values == NULL || keys == NULL || count < 1) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Create a pointer to the head node of the list
    node_t* head = NULL;

    // Loop through each value and key in the input arrays
    for (size_t i = 0; i < count; i++) {
        // Allocate memory for the current node
        node_t* current = malloc(sizeof(node_t));
        if (current == NULL) {
            fprintf(stderr, "Failed to allocate memory\n");
            break;
        }

        // Set the value and key of the current node
        current->value = values[i];
        current->key = keys[i];

        // If this is the first node in the list, set it as the head
        if (head == NULL) {
            head = current;
        } else {
            // Otherwise, link the current node to the previous one
            current->next = head;
            head = current;
        }
    }

    // Terminate the list with a null pointer
    head->next = NULL;

    return head;
}

