using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using Docker.DotNet;
using Docker.DotNet.Models;

public class ContainerManager
{
    private readonly DockerClient _dockerClient;
    private readonly List<string> _imageTags = new List<string>();

    public ContainerManager(DockerClient dockerClient)
    {
        _dockerClient = dockerClient;
    }

    public async Task<string> StartContainerAsync(string imageName, string directoryPath)
    {
        // Check if the specified image exists in the Docker repository
        if (!await DoesImageExistAsync(imageName))
        {
            return null;
        }

        // Validate that the directory path is not null or empty and contains a 'docker-compose.yml' file
        if (string.IsNullOrEmpty(directoryPath) || !File.Exists(Path.Combine(directoryPath, "docker-compose.yml")))
        {
            throw new ArgumentException("Invalid directory path");
        }

        // Log any errors encountered during the process
        try
        {
            // Start the container and return a confirmation message if successful
            var container = await _dockerClient.Containers.CreateContainerAsync(new CreateContainerParameters
            {
                Image = imageName,
                HostConfig = new HostConfig
                {
                    Mounts = new List<Mount>
                    {
                        new Mount(directoryPath, "/app")
                    }
                }
            });

            await _dockerClient.Containers.StartContainerAsync(container.ID, new StartContainerParameters());
            return $"Container started successfully with ID: {container.ID}";
        }
        catch (Exception ex)
        {
            // Log the error and return null if an exception is thrown
            Console.WriteLine($"Error starting container: {ex.Message}");
            return null;
        }
    }

    private async Task<bool> DoesImageExistAsync(string imageName)
    {
        var imageTags = await _dockerClient.Images.ListImagesAsync(new ImagesListParameters
        {
            Filters = new Dictionary<string, IDictionary<string, bool>>
            {
                { "reference", new Dictionary<string, bool> { { $"{imageName}", true } } } }
            }
        });

        return imageTags.Any();
    }
}
```
