function dom_traverse(selector, parentElement = document) {
    // Create an array to store the matched elements
    const matchedElements = [];

    // Recursively traverse the DOM tree starting from the parent element
    function traverse(element) {
        if (element.matches(selector)) {
            // Add the current element to the matched elements array
            matchedElements.push(element);
        }

        // Recursively traverse the child elements of the current element
