```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    int key;
    char *str;
} data_entry;

void initialize_data_entries(data_entry **entries, int num_entries, const char *values_file, const char *strings_file) {
    // Open the files
    FILE *values_fp = fopen(values_file, "r");
    if (values_fp == NULL) {
        perror("Failed to open values file");
        return;
    }
    FILE *strings_fp = fopen(strings_file, "r");
    if (strings_fp == NULL) {
        perror("Failed to open strings file");
        fclose(values_fp);
        return;
    }

    // Read the values from the files
    data_entry *entries = malloc(num_entries * sizeof(*entries));
    if (entries == NULL) {
        perror("Failed to allocate memory for entries");
        fclose(values_fp);
        fclose(strings_fp);
        return;
    }
    for (int i = 0; i < num_entries; i++) {
        // Read the value from the values file
        if (fscanf(values_fp, "%lf", &entries[i].value) != 1) {
            perror("Failed to read value");
            fclose(values_fp);
            fclose(strings_fp);
            free(entries);
            return;
        }
        // Read the string from the strings file
        if (fscanf(strings_fp, "%s", entries[i].str) != 1) {
            perror("Failed to read string");
            fclose(values_fp);
            fclose(strings_fp);
            free(entries);
            return;
        }
        // Allocate memory for the string
        entries[i].str = malloc(strlen(entries[i].str) + 1);
        if (entries[i].str == NULL) {
            perror("Failed to allocate memory for string");
            fclose(values_fp);
            fclose(strings_fp);
            free(entries);
            return;
        }
    }

    // Close the files
    fclose(values_fp);
    fclose(strings_fp);

    // Initialize the keys
    for (int i = 0; i < num_entries; i++) {
        entries[i].key = i + 1;
    }
}
```
