// Define the function to initialize records
void initialize_records(int num_records, int min_offset, int max_offset, void (*error_handler)(const char*), record_t** records) {
    // Allocate memory for the offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        error_handler("Failed to allocate memory for offset array");
        return;
    }

    // Initialize the offset array with random values within the given range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset);
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        error_handler("Failed to allocate memory for key array");
        free(offsets);
        return;
    }

    // Initialize the key array with random values within the given range
    for (int i = 0; i < num_records; i++) {
        keys[i] = min_offset + rand() % (max_offset - min_offset);
    }

    // Allocate memory for the record structure array
    record_t* records_arr = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records_arr) {
        error_handler("Failed to allocate memory for record structure array");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record structure array with the random values from the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        records_arr[i].key = keys[i];
