['```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Net;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace ResourceManager
{
    public class ResourceLoader
    {
        private readonly Dictionary<string, ResourceBundle> _bundles = new Dictionary<string, ResourceBundle>();
        private readonly object _lock = new object();
        private readonly int _cooldownPeriod = 9 * 1000; // 9 seconds

        public DataTableReader LoadResource(byte[] resourceData)
        {
            string resourceName = GetResourceNameFromData(resourceData);
            ResourceBundle bundle = GetResourceBundle(resourceName);

            if (bundle == null)
            {
                Console.WriteLine($"Resource '{resourceName}' not found.");
                return null;
            }

            int selectedItemCount = LoadSelectedItemsFromBundle(bundle);
            Console.WriteLine($"Loaded {selectedItemCount} items from resource '{resourceName}'.");

            return bundle.Reader;
        }

        public void LoadResourceAsync(byte[] resourceData)
        {
            Task.Run(() =>
            {
                lock (_lock)
                {
                    string resourceName = GetResourceNameFromData(resourceData);
                    ResourceBundle bundle = GetResourceBundle(resourceName);

                    if (bundle == null)
                    {
                        Console.WriteLine($"Resource '{resourceName}' not found.");
                        return;
                    }

                    LoadSelectedItemsFromBundleAsync(bundle).Wait();
                    Console.WriteLine($"Loaded items from resource '{resourceName}' asynchronously.");
                }
            });
        }

        private ResourceBundle GetResourceBundle(string resourceName)
        {
            lock (_lock)
            {
                if (!_bundles.TryGetValue(resourceName, out var bundle))
                {
                    return null;
                }

                DateTime lastAccessed = bundle.LastAccessed;
                TimeSpan elapsed = DateTime.Now - lastAccessed;

                if (elapsed.TotalSeconds > _cooldownPeriod)
                {
                    LoadSelectedItemsFromBundle(bundle);
                    bundle.LastAccessed = DateTime.Now;
                }

                return bundle;
            }
        }

        private async Task LoadSelectedItemsFromBundleAsync(ResourceBundle bundle)
        {
            await Task.Run(() =>
            {
                lock (bundle.Lock)
                {
                    bundle.Reader = new DataTableReader(bundle.DataTable);
                }
            });
        }

        private int LoadSelectedItemsFromBundle(ResourceBundle bundle)
        {
            lock (bundle.Lock)
            {
                bundle.Reader = new DataTableReader(bundle.DataTable);
                return bundle.DataTable.Rows.Count;
            }
        }

        private string GetResourceNameFromData(byte[] resourceData)
        {
            using var memoryStream = new MemoryStream(resourceData);
            using var reader = new BinaryReader(memoryStream, Encoding.UTF8, true);

            // Read the header information to determine the resource format
            string header = reader.ReadString();
            if (header == "version1")
            {
                return GetResourceNameFromData_Version1(reader);
            }
            else if (header == "version2")
            {
                return GetResourceNameFromData_Version2(reader);
            }

            throw new NotSupportedException("The specified resource format is not supported.");
        }

        private string GetResourceNameFromData_Version1(BinaryReader reader)
        {
            // Read the resource name from the data stream
            return reader.ReadString();
        }

        private string GetResourceNameFromData_Version2(BinaryReader reader)
        {
            // Read the resource name from the data stream
            return reader.ReadString();
        }
    }

    public class ResourceBundle
    {
        public DataTable DataTable;
        public DataTableReader Reader;
        public DateTime LastAccessed;
        public object Lock = new object();
    }
}
```
