```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

/* Define structure for sensor data */
typedef struct {
    double value;
    char *string;
} sensor_data;

/* Function to initialize and manage memory for sensor data */
void init_sensor_data(size_t num_sensors, size_t string_len) {
    /* Allocate memory for array of sensor data structures */
    sensor_data *data = malloc(num_sensors * sizeof(*data));
    if (data == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for sensor data\n");
        exit(EXIT_FAILURE);
    }

    /* Initialize array of random values and strings */
    size_t i;
    for (i = 0; i < num_sensors; i++) {
        data[i].value = generate_random_double();
        data[i].string = malloc(string_len * sizeof(char));
        if (data[i].string == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for string\n");
            exit(EXIT_FAILURE);
        }
        generate_random_string(data[i].string, string_len);
    }

    /* Log allocation and deallocation of memory */
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    printf("Allocated %lu bytes for sensor data\n", num_sensors * sizeof(*data));
    pthread_mutex_unlock(&mutex);
}

/* Function to generate random double values within specified range */
double generate_random_double(void) {
    return (rand() / (RAND_MAX + 1.0)) * 2.0 - 1.0;
}

/* Function to generate random alphanumeric strings of given length */
char *generate_random_string(char *str, size_t len) {
    /* Generate random characters using rand() and isalpha() function */
    for (size_t i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }

    return str;
}
```
