struct weather_data {
    float temperature;
    char* weather_description;
};

// Function to add a new weather station to the array
void add_weather_station(struct weather_data** weather_array, int* size, int* capacity) {
    // Check if the array needs to be resized
    if (*size == *capacity) {
        // Reallocate memory for the array
        *capacity += 10;
        struct weather_data* new_weather_array = realloc(*weather_array, sizeof(struct weather_data) * (*capacity));
        if (new_weather_array == NULL) {
            // Log error and handle appropriately
            fprintf(stderr, "Error: Failed to allocate memory for weather array\n");
            exit(1);
        }
        *weather_array = new_weather_array;
    }
    // Generate random values for the float field and a random alphanumeric string for the string field
    (*weather_array)[*size].temperature = (float)rand() / RAND_MAX * 100;
    sprintf((*weather_array)[*size].weather_description, "%s", generate_random_string(5));
    // Increment the size of the array
    (*size)++;
}

// Function to generate a random alphanumeric string
char* generate_random_string(int length) {
    char* str = malloc(length + 1);
    if (str == NULL) {
        // Log error and handle appropriately
        fprintf(stderr, "Error: Failed to allocate memory for random string\n");
        exit(1);
    }
    for (int i = 0; i < length; i++) {
        str[i] = 'a' + (rand() % 26);
    }
    str[length] = '\0';
    return str;
}

// Main function to dynamically allocate memory for and initialize the arrays
int main() {
    // Define the initial size and capacity of the array
    int size = 0;
    int capacity = 10;

    // Allocate memory for the two arrays
    struct weather_data* weather_array = malloc(sizeof(struct weather_data) * capacity);
    if (weather_array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for weather array\n");
        exit(1);
    }

    // Initialize the arrays with random values
    for (int i = 0; i < size; i++) {
        add_weather_station(&weather_array, &size, &capacity);
    }

    // Free memory when no longer needed
    free(weather_array);

    return 0;
}
