    char *str = malloc(len + 1);
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + (rand() % ('z' - 'a'));
    }
    str[len] = '\0';
    return str;
}

// Function to allocate memory for an array of sensor data structures
sensor_data *allocate_sensor_data(int num_sensors, int string_length) {
    // Allocate memory for the array of sensor data structures
    sensor_data *data = malloc(num_sensors * sizeof(sensor_data));
    if (data == NULL) {
        printf("Failed to allocate memory for sensor data\n");
        exit(-1);
    }

    // Allocate memory for the string fields in each structure
    for (int i = 0; i < num_sensors; i++) {
        data[i].str = malloc(string_length + 1);
        if (data[i].str == NULL) {
            printf("Failed to allocate memory for sensor string\n");
            exit(-1);
        }
    }

    return data;
}

// Function to initialize the sensor data with random values within specified ranges and generate random alphanumeric strings for the string fields
void init_sensor_data(int num_sensors, double min_value, double max_value, int string_length) {
    // Allocate memory for the array of sensor data structures
    sensor_data *data = allocate_sensor_data(num_sensors, string_length);

    // Initialize the value fields with random values within specified ranges
    for (int i = 0; i < num_sensors; i++) {
        data[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }

    // Initialize the string fields with random alphanumeric strings
    for (int i = 0; i < num_sensors; i++) {
        data[i].str = generate_random_string(string_length);
    }
}

// Function to deallocate memory for an array of sensor data structures
void deallocate_sensor_data(sensor_data *data, int num_sensors) {
    // Deallocate memory for the string fields in each structure
    for (int i = 0; i < num_sensors; i++) {
        free(data[i].str);
    }

    // Deallocate memory for the array of sensor data structures
    free(data);
}

// Function to manage concurrent access while ensuring data integrity
void *manage_sensor_data(void *args) {
    int num_sensors = 10;
    double min_value = 0.0;
    double max_value = 10.0;
    int string_length = 256;

    // Initialize the sensor data with random values within specified ranges and generate random alphanumeric strings for the string fields
    init_sensor_data(num_sensors, min_value, max_value, string_length);

    // Perform some operations on the sensor data in a thread-safe manner
    for (int i = 0; i < num_sensors; i++) {
        printf("Sensor %d: value = %f, str = %s\n", i, data[i].value, data[i].str);
    }

    // Deallocate memory for the sensor data structures
    deallocate_sensor_data(data, num_sensors);

    return NULL;
}

// Function to implement multi-threading support
void *manage_sensor_data_multi_threaded(void *args) {
    int num_threads = 10;
    int num_sensors = 10;
    double min_value = 0.0;
    double max_value = 10.0;
    int string_length = 256;

    // Initialize the sensor data with random values within specified ranges and generate random alphanumeric strings for the string fields in each thread
    init_sensor_data(num_sensors, min_value, max_value, string_length);

    // Create a pool of threads to manage the sensor data concurrently
    pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
    if (threads == NULL) {
        printf("Failed to allocate memory for thread pool\n");
        exit(-1);
    }

    // Create a thread for each sensor data structure and perform some operations on the sensor data in a thread-safe manner
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, manage_sensor_data, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory for the thread pool and sensor data structures
    free(threads);
    deallocate_sensor_data(data, num_sensors);

    return NULL;
}

int main() {
    int num_sensors = 10;
    double min_value = 0.0;
    double max_value = 10.0;
    int string_length = 256;

    // Initialize the sensor data with random values within specified ranges and generate random alphanumeric strings for the string fields
    init_sensor_data(num_sensors, min_value, max_value, string_length);

    // Perform some operations on the sensor data in a thread-safe manner using a single thread
    manage_sensor_data(NULL);

    // Deallocate memory for the sensor data structures
    deallocate_sensor_data(data, num_sensors);

    return 0;
}
