// Custom string comparison function that supports case-insensitive and case-sensitive modes
class StringComparator {
public:
    explicit StringComparator(bool caseSensitive = false) : caseSensitive_(caseSensitive) {}

    bool operator()(const std::string& lhs, const std::string& rhs) const {
        if (caseSensitive_) {
            return lhs == rhs;
        } else {
            return std::equal(lhs.begin(), lhs.end(), rhs.begin(), rhs.end());
        }
    }

private:
    bool caseSensitive_;
};

// Function to insert a string after the first occurrence of a search term in a forward list
void InsertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& searchTerm, const std::string& insertString) {
    // Search for the first occurrence of the search term in the list
    auto it = std::find_if(list.begin(), list.end(), StringComparator(true /*caseSensitive*/));

    if (it != list.end()) {
        // Insert the insert string after the current position of the iterator
        list.insert_after(it, insertString);
    } else {
        // If no occurrence was found, append the insert string to the end of the list
        list.push_back(insertString);
    }
}
