    if (new_UE_context == NULL) {
        syslog(LOG_ERR, "Memory allocation failed while creating UE context");
        return NULL;
    }
    new_UE_context->UE_id = UE_id;
    new_UE_context->active_radio_bearers = malloc(sizeof(struct ActiveRadioBearer*) * 10);
    if (new_UE_context->active_radio_bearers == NULL) {
        syslog(LOG_ERR, "Memory allocation failed while creating active radio bearer list");
        return NULL;
    }
    for (int i = 0; i < 10; i++) {
        new_UE_context->active_radio_bearers[i] = malloc(sizeof(struct ActiveRadioBearer));
        if (new_UE_context->active_radio_bearers[i] == NULL) {
            syslog(LOG_ERR, "Memory allocation failed while creating active radio bearer list");
            return NULL;
        }
    }
    return new_UE_context;
}

void add_record(struct UEContext* UE_context) {
    struct record* new_record = malloc(sizeof(struct record));
    if (new_record == NULL) {
        syslog(LOG_ERR, "Memory allocation failed while adding record");
        return;
    }
    new_record->value = (rand() % 100 - 50) * 2.0f; // random value between -50 and 50
    UE_context->records[UE_context->num_records++] = new_record;
}

void update_database(struct UEContext* UE_context) {
