    if (ret != 0) {
        syslog(LOG_ERR, "Failed to update user data in database");
        return;
    }
}

void *populate_ue_context(struct UEContext* UE_context) {
    for (int i = 0; i < 10; i++) {
        int radio_bearer_id = rand() % 10 + 1; // random value between 1 and 10
        float qos_params = (rand() % 100 - 50) * 2.0f; // random value between -50 and 50
        struct ActiveRadioBearer* new_active_radio_bearer = malloc(sizeof(struct ActiveRadioBearer));
        if (new_active_radio_bearer == NULL) {
            syslog(LOG_ERR, "Memory allocation failed while populating active radio bearer list");
            return;
        }
        new_active_radio_bearer->radio_bearer_id = radio_bearer_id;
        new_active_radio_bearer->qos_params = qos_params;
        UE_context->active_radio_bearers[i] = new_active_radio_bearer;
    }
}

void *allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        return NULL;
    }
    return ptr;
}

void free_memory(void** ptr) {
