    struct ActiveRadioBearer* new_active_radio_bearer = malloc(sizeof(struct ActiveRadioBearer));
    if (new_active_radio_bearer == NULL) {
        syslog(LOG_ERR, "Memory allocation failed while adding active radio bearer");
        return NULL;
    }
    new_active_radio_bearer->radio_bearer_id = radio_bearer_id;
    new_active_radio_bearer->qos_params = qos_params;
    UE_context->active_radio_bearers[UE_context->num_active_radio_bearers++] = new_active_radio_bearer;
}

void remove_active_radio_bearer(struct UEContext* UE_context, int radio_bearer_id) {
    for (int i = 0; i < UE_context->num_active_radio_bearers; i++) {
        if (UE_context->active_radio_bearers[i]->radio_bearer_id == radio_bearer_id) {
            free(UE_context->active_radio_bearers[i]);
            UE_context->active_radio_bearers[i] = NULL;
        }
    }
}

int main() {
    struct UEContext* UE_context = create_UE_context();
    populate_ue_context(UE_context);
    update_database(UE_context);
    return 0;
}']

