char* append_slash(char* str, int size) {
    // Check if the input string is NULL or empty
    if (str == NULL || *str == '\0') {
        return NULL;
    }

    // Get the length of the input string
    int len = strlen(str);

    // Check if the input string exceeds the specified size limit
    if (len >= size) {
        return NULL;
    }

    // Allocate memory for the appended string
    char* append_str = (char*)malloc((size - len + 1) * sizeof(char));
    if (append_str == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for appended string\n");
        exit(1);
    }

    // Copy the input string into the appended string
    memcpy(append_str, str, len * sizeof(char));

    // Append a slash to the end of the appended string
    append_str[len] = '/';
    append_str[len + 1] = '\0';

    return append_str;
}
