    return (rand() % (max - min + 1)) + min;
}

// Define function to handle database connections and data retrieval
void connectToDatabase(MYSQL *conn) {
    // Connect to MySQL server
    if (mysql_real_connect(conn, "localhost", "username", "password", "database", 0, NULL, 0) == NULL) {
        fprintf(stderr, "Error connecting to MySQL server: %s\n", mysql_error(conn));
        exit(1);
    }
}

// Define function to handle data retrieval from database
void retrieveDataFromDatabase(MYSQL *conn, int recordId) {
    // Prepare SQL query for retrieving data from database
    MYSQL_STMT *stmt = mysql_prepare(conn, "SELECT key, value FROM records WHERE id = ?");
    if (stmt == NULL) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", mysql_error(conn));
        exit(1);
    }

    // Bind parameters for prepared statement
    MYSQL_BIND bind;
    memset(&bind, 0, sizeof(bind));
    bind.buffer = (char *)&recordId;
    bind.is_unsigned = true;
    if (mysql_stmt_bind_param(stmt, &bind) != 0) {
        fprintf(stderr, "Error binding parameters: %s\n", mysql_error(conn));
        exit(1);
    }

    // Execute SQL query and retrieve result set
    MYSQL_RES *result = mysql_stmt_execute(stmt);
    if (result == NULL) {
        fprintf(stderr, "Error executing SQL statement: %s\n", mysql_error(conn));
        exit(1);
    }

    // Read data from result set and update record
    MYSQL_ROW row;
    while ((row = mysql_fetch_row(result)) != NULL) {
        records[recordId].key = atoi(row[0]);
        records[recordId].value = atof(row[1]);
    }
}

// Define function to handle data persistence in database
void persistDataInDatabase(MYSQL *conn, int recordId) {
    // Prepare SQL query for inserting or updating data in database
    MYSQL_STMT *stmt = mysql_prepare(conn, "INSERT INTO records (id, key, value) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE id = ?, key = ?, value = ?");
    if (stmt == NULL) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", mysql_error(conn));
        exit(1);
    }

    // Bind parameters for prepared statement
    MYSQL_BIND bind;
    memset(&bind, 0, sizeof(bind));
    bind.buffer = (char *)&recordId;
    bind.is_unsigned = true;
    if (mysql_stmt_bind_param(stmt, &bind) != 0) {
        fprintf(stderr, "Error binding parameters: %s\n", mysql_error(conn));
        exit(1);
    }

    // Execute SQL query and retrieve result set
    MYSQL_RES *result = mysql_stmt_execute(stmt);
    if (result == NULL) {
        fprintf(stderr, "Error executing SQL statement: %s\n", mysql_error(conn));
        exit(1);
    }
}

// Define function to periodically check for inconsistencies in offset and key arrays
void checkInconsistencies() {
    // Loop through all records and check if offset or key is inconsistent
    for (int i = 0; i < 1000000; i++) {
        if (records[i].offset != generateRandomValue(0, 999) || records[i].key != generateRandomValue(0, 999)) {
            printf("Inconsistency found in record %d\n", i);
        }
    }
}

int main() {
    // Initialize random seed for generating random values
    srand(time(NULL));

    // Connect to MySQL server
    MYSQL *conn = mysql_init(NULL);
    connectToDatabase(conn);

    // Loop through all records and initialize them with random values
    for (int i = 0; i < 1000000; i++) {
        records[i].offset = generateRandomValue(0, 999);
        records[i].key = generateRandomValue(0, 999);
        records[i].value = generateRandomValue(0.0, 100.0);

        // Create unique identifier for record
        char *identifier = (char *)malloc(16 * sizeof(char));
        sprintf(identifier, "record%d", i);
        records[i].identifier = identifier;
    }

    // Periodically check for inconsistencies in offset and key arrays
    while (true) {
        checkInconsistencies();
        sleep(60);
    }
}
