    // open file for writing
    FILE *file = fopen("records.bin", "wb");
    if (!file) {
        printf("Error: Failed to open records file for writing\n");
        return;
    }

    // write records to file
    for (int i = 0; i < num_keys; i++) {
        Record record = records[i];
        fwrite(&record, sizeof(Record), 1, file);
    }

    // close file
    fclose(file);
}

// function to load records from disk
void load_records(int num_keys) {
    // open file for reading
    FILE *file = fopen("records.bin", "rb");
    if (!file) {
        printf("Error: Failed to open records file for reading\n");
        return;
    }

    // allocate memory for record array
    Record *records = (Record *)malloc(num_keys * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        fclose(file);
        return;
    }

    // read records from file
    for (int i = 0; i < num_keys; i++) {
        Record record;
        fread(&record, sizeof(Record), 1, file);
        records[i] = record;
    }

    // close file
    fclose(file);
}
