#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Configuration settings for the list
#define MAX_RECORDS 1000
#define SYNC_STRATEGY MUTEXES
#define ERROR_HANDLING_POLICY GRACEFUL

// Struct for storing records
typedef struct {
    float value;
} record;

// List of records
record* list = NULL;
size_t num_records = 0;

// Mutexes for synchronizing access to the list
pthread_mutex_t mutex1, mutex2;

// Function to allocate memory for a new record and insert it into the list
void insert(float value) {
    // Allocate memory for the new record
    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        printf("Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record with the given value
    new_record->value = value;

    // Lock the mutexes to synchronize access to the list
    pthread_mutex_lock(&mutex1);

    // Insert the new record into the list
    list = realloc(list, (num_records + 1) * sizeof(record));
    if (list == NULL) {
        printf("Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&mutex1);
        return;
    }
    list[num_records] = *new_record;
    num_records++;

    // Unlock the mutexes and free the memory for the new record
    pthread_mutex_unlock(&mutex1);
    free(new_record);
}

// Function to delete a record from the list by its index
void delete(size_t index) {
    // Lock the mutexes to synchronize access to the list
    pthread_mutex_lock(&mutex2);

    // Check if the given index is valid
    if (index >= num_records) {
        printf("Invalid record index: %zu\n", index);
        pthread_mutex_unlock(&mutex2);
        return;
    }

    // Remove the record from the list by shifting all subsequent records down one index
    for (size_t i = index; i < num_records - 1; i++) {
        list[i] = list[i + 1];
    }
    num_records--;

    // Reallocate the memory for the updated list
    list = realloc(list, num_records * sizeof(record));
    if (list == NULL) {
        printf("Failed to allocate memory for updated record\n");
        pthread_mutex_unlock(&mutex2);
        return;
    }

    // Unlock the mutexes and free the memory for the deleted record
    pthread_mutex_unlock(&mutex2);
}

// Function to read records from an external data source (e.g., CSV or JSON) and insert them into the list
void populate_list(char* filepath) {
    // Open the file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Failed to open data source: %s\n", filepath);
        return;
    }

    // Read records from the file and insert them into the list
    while (!feof(fp)) {
        float value = 0.0f;
        char* line = NULL;
        size_t line_len = 0;
        if (getline(&line, &line_len, fp) == -1) {
            break;
        }
        sscanf(line, "%f", &value);
        insert(value);
    }

    // Close the file and free the memory for the line buffer
    fclose(fp);
    free(line);
}

// Function to handle memory allocation failures gracefully
void handle_memory_error() {
    printf("Memory allocation failed. Exiting...\n");
    exit(-1);
}

int main() {
    // Initialize the mutexes and allocate memory for the list
    pthread_mutex_init(&mutex1, NULL);
    pthread_mutex_init(&mutex2, NULL);
    list = malloc(MAX_RECORDS * sizeof(record));
    if (list == NULL) {
        handle_memory_error();
    }

    // Populate the list with records from an external data source
    populate_list("data.csv");

    // Print the current state of the list
    printf("List: ");
    for (size_t i = 0; i < num_records; i++) {
        printf("%f ", list[i].value);
    }
    printf("\n");

    // Insert a new record into the list
    insert(5.0f);

    // Print the updated state of the list
    printf("List: ");
    for (size_t i = 0; i < num_records; i++) {
        printf("%f ", list[i].value);
    }
    printf("\n");

    // Delete a record from the list by its index
    delete(1);

    // Print the updated state of the list
    printf("List: ");
    for (size_t i = 0; i < num_records; i++) {
        printf("%f ", list[i].value);
    }
    printf("\n");

    // Free the memory for the list and mutexes
    free(list);
    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);

    return 0;
}
```
