void init_arrays(int num_records, int key_range[2], int offset_range[2]) {
    // Allocate memory for record array
    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        return;
    }

    // Initialize key and offset arrays
    int* keys = malloc(num_records * sizeof(int));
    long* offsets = malloc(num_records * sizeof(long));
    if (!keys || !offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for key and offset arrays\n");
        free(records);
        return;
    }

    // Initialize random seed for generating keys and offsets
    srand((unsigned int)time(NULL));

    // Generate keys and offsets within specified ranges
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (key_range[1] - key_range[0]) + key_range[0];
        offsets[i] = rand() % (offset_range[1] - offset_range[0]) + offset_range[0];
    }

    // Set values in record array
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Free memory for key and offset arrays
    free(keys);
    free(offsets);
}

// Function to generate random values within specified range
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to set record value to a random value within specified range
void set_record_value(Record* record, int key_range[2], long offset_range[2]) {
    record->key = rand_range(key_range[0], key_range[1]);
    record->offset = rand_range(offset_range[0], offset_range[1]);
}

// Function to add a new record to the end of the array
void add_record(Record* records, int num_records, Record* new_record) {
    // Check if there is enough memory for another record
    if (num_records >= MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records exceeded\n");
        return;
    }

    // Allocate memory for new record and copy values from input
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new record\n");
        return;
    }

    memcpy(new_record, new_record, sizeof(Record));

    // Add new record to end of array and increment number of records
    records[num_records++] = *new_record;
}

// Function to load records from disk into memory
void load_records(char* filename, Record** records, int* num_records) {
    // Open file for reading
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return;
    }

    // Allocate memory for record array and initialize it to 0 records
    *records = malloc(sizeof(Record));
    if (!*records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        fclose(file);
        return;
    }

    // Read file and parse records into the array
    while (fscanf(file, "%d %ld", &(*records)[*num_records].key, &(*records)[*num_records++].offset) == 2);

    fclose(file);
}

// Function to save records to disk
void save_records(char* filename, Record* records, int num_records) {
    // Open file for writing
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return;
    }

    // Write records to file
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d %ld\n", records[i].key, records[i].offset);
    }

