    pthread_rwlock_destroy(&db_lock);
    EVP_CIPHER_CTX_free(db_ctx);

    return 0;
}

// Initialize data entries with random values
void* initialize_data(void* arg) {
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        entries[i].value = rand();
    }
    return NULL;
}

// Process data in parallel
void* process_data(void* arg) {
    // Lock database connection pool
    pthread_rwlock_wrlock(&db_lock);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        // Update offsets and keys
        entries[i].offset += rand() % 1000;
        entries[i].key += rand() % 32;

        // Save updated data to database using EVP_CIPHER_CTX
        persist_data_to_db(DB_PATH, TABLE_NAME);
    }

    // Unlock database connection pool
    pthread_rwlock_unlock(&db_lock);

    return NULL;
}

// Persist data to database using EVP_CIPHER_CTX
void persist_data_to_db(const char* db_path, const char* table_name) {
    // Create EVP_CIPHER_CTX for encryption/decryption
    EVP_CIPHER_CTX *ctx = create_cipher_ctx("aes-256-cbc");

    // Open database connection using EVP_CIPHER_CTX
    FILE* db_file = fopen(db_path, "r+");
    if (db_file == NULL) {
        printf("Failed to open database file: %s\n", strerror(errno));
        exit(1);
    }

    // Encrypt/decrypt data using EVP_CIPHER_CTX
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        // Encrypt data
        EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);
        int len = sizeof(record);
        EVP_EncryptUpdate(ctx, entries[i].data, &len, entries[i].data, sizeof(record));

        // Decrypt data
        EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL);
        len = sizeof(record);
        EVP_DecryptUpdate(ctx, entries[i].data, &len, entries[i].data, sizeof(record));
    }

    // Close database connection
    fclose(db_file);
}

// Check consistency of data
void check_consistency(data_entry* entries, int n) {
    for (int i = 0; i < n; ++i) {
        if (entries[i].offset != entries[i].value % MAX_DATA_SIZE ||
                entries[i].key != entries[i].value % MAX_KEY_SIZE) {
            printf("Data inconsistency detected!\n");
            exit(1);
        }
    }
}
```

