// Define the data structures used in the forward list and the C function
struct sensor_data {
    double value;
    std::string key;
};

typedef std::forward_list<std::string> string_list;

void insert_string(string_list& list, const std::string& str, size_t pos) {
    // Check if the position is valid and return if it's not
    if (pos > list.size()) {
        return;
    }

    // Create a new node for the string and insert it at the specified position
    auto node = std::make_shared<std::string>(str);
    list.insert_after(list.begin() + pos, node);
}

void update_offset_or_key(sensor_data* data, size_t offset_or_key) {
    // Check if the index is valid and return if it's not
    if (offset_or_key >= data.size()) {
        return;
    }

    // Update the value at the specified offset or key
    data[offset_or_key].value = generate_random_double();
}

void sort_list(string_list& list, const std::function<bool(const std::string&, const std::string&)>& compare) {
    // Create a copy of the list and sort it using the provided comparison function
    string_list sorted = list;
    std::sort(sorted.begin(), sorted.end(), compare);
}

void serialize_list(const string_list& list, const std::string& filepath) {
    // Create a JSON array and add each string in the list to it
    Json::Value json_array;
    for (auto& str : list) {
        json_array.append(str);
    }

    // Write the JSON array to a file at the specified path
    std::ofstream outfile(filepath);
    if (!outfile.is_open()) {
        std::cerr << "Error: Could not open file for writing." << std::endl;
        return;
    }
    outfile << json_array;
}

void deserialize_list(string_list& list, const std::string& filepath) {
    // Open the file at the specified path and read its contents into a string
    std::ifstream infile(filepath);
    if (!infile.is_open()) {
        std::cerr << "Error: Could not open file for reading." << std::endl;
        return;
    }
    std::string json_str((std::istreambuf_iterator<char>(infile)), std::istreambuf_iterator<char>());

    // Create a JSON array from the string and iterate through it to create the forward list
    Json::Value json_array;
    if (!json_array.parse(json_str).isObject()) {
        std::cerr << "Error: Could not parse JSON array." << std::endl;
        return;
    }
    for (auto& str : json_array) {
        list.push_back(str.asString());
    }
}

void generate_random_values(sensor_data* data, size_t num_elements) {
    // Generate random values for the sensor data structures
    for (size_t i = 0; i < num_elements; ++i) {
        data[i].value = generate_random_double();
    }
}

int main() {
    // Create an empty forward list and a JSON array to store the data
    string_list list;
    Json::Value json_array;

    // Generate random sensor data structures and add them to the forward list
    size_t num_elements = 10;
    sensor_data* data = new sensor_data[num_elements];
    generate_random_values(data, num_elements);
    for (size_t i = 0; i < num_elements; ++i) {
        list.push_back(data[i].key);
    }

    // Insert a string at the specified position in the forward list
    std::string str("hello");
    size_t pos = 3;
    insert_string(list, str, pos);

    // Update the value at the specified offset or key in the sensor data structures
    size_t offset_or_key = 2;
    update_offset_or_key(data, offset_or_key);

    // Sort the forward list using a user-defined comparison function
    std::function<bool(const std::string&, const std::string&)> compare([](const std::string& str1, const std::string& str2) {
        return str1.compare(str2) < 0;
    });
    sort_list(list, compare);

    // Serialize the forward list to a JSON array and write it to a file
    serialize_list(list, "data.json");

    // Deserialize the JSON array from the file and create a new forward list
    deserialize_list(list2, "data.json");

    // Print the contents of both lists
    std::cout << "List 1: ";
    for (auto& str : list) {
        std::cout << str << " ";
