function manageProductListings($_REQUEST) {
    // Validate the input data
    $validatedData = validateInput($_REQUEST);
    if ($validatedData['error']) {
        return json_encode(['message' => 'error', 'error' => $validatedData['error']]);
    }

    // Connect to the database
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    } catch (PDOException $e) {
        return json_encode(['message' => 'error', 'error' => $e->getMessage()]);
    }

    // Check if the listing exists and update it if necessary
    if ($validatedData['id']) {
        $listing = getListing($db, $validatedData['id']);
        if (!$listing) {
            return json_encode(['message' => 'error', 'error' => 'Listing not found']);
        }

        // Update the listing with the provided data
        saveListing($db, $validatedData['id'], $validatedData['title'], $validatedData['description'], $validatedData['price']);
    } else {
        // Create a new listing
        saveListing($db, null, $validatedData['title'], $validatedData['description'], $validatedData['price']);
    }

    // Check if the deletion request is valid
    if ($validatedData['sub_action'] === 'delete') {
        // Confirm that there are no associated reviews before deleting the listing
        $reviews = getReviews($db, $validatedData['id']);
        if (!empty($reviews)) {
            return json_encode(['message' => 'error', 'error' => 'Cannot delete a listing with associated reviews']);
        }
    }

    // Save the changes to the database and close the connection
    $db->commit();
    $db = null;

    return json_encode(['message' => 'success']);
}

function validateInput($input) {
    // Check if the required fields are present
    if (!isset($input['title']) || !isset($input['description']) || !isset($input['price'])) {
        return ['error' => 'Required fields are missing'];
    }

    // Validate the input data
    $validatedData = [
        'id' => isset($input['id']) ? (int) $input['id'] : null,
        'title' => $input['title'],
        'description' => $input['description'],
        'price' => (float) $input['price'],
        'sub_action' => isset($input['sub_action']) ? $input['sub_action'] : null,
    ];

    // Check if the listing exists and update it if necessary
    if ($validatedData['id']) {
        $listing = getListing($db, $validatedData['id']);
        if (!$listing) {
            return ['error' => 'Listing not found'];
        }

        // Update the listing with the provided data
        saveListing($db, $validatedData['id'], $validatedData['title'], $validatedData['description'], $validatedData['price']);
    } else {
        // Create a new listing
        saveListing($db, null, $validatedData['title'], $validatedData['description'], $validatedData['price']);
    }

    return $validatedData;
}

function getListing($db, $id) {
    $stmt = $db->prepare("SELECT * FROM listings WHERE id = ?");
    $stmt->bindValue(1, $id);
    $stmt->execute();
    $result = $stmt->fetch();
    return $result ?: null;
}

function saveListing($db, $id, $title, $description, $price) {
    // Update the listing with the provided data
    $stmt = $db->prepare("UPDATE listings SET title = ?, description = ?, price = ? WHERE id = ?");
    $stmt->bindValue(1, $title);
    $stmt->bindValue(2, $description);
    $stmt->bindValue(3, $price);
    $stmt->bindValue(4, $id);
    $stmt->execute();
}

function getReviews($db, $listingId) {
    $stmt = $db->prepare("SELECT * FROM reviews WHERE listing_id = ?");
    $stmt->bindValue(1, $listingId);
    $stmt->execute();
    return $stmt->fetchAll();
}
```
This code uses a PDO connection to interact with the database and validate user input. It also includes error handling for database connection issues and ensures that all database interactions are properly closed after execution.

