    // Allocate memory for the data entries
    entries = (data_entry*)malloc(sizeof(data_entry) * num_entries);
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for data entries\n");
        return 1;
    }

    // Initialize the data entries
    void* initialize_data_arg = (void*)&entries;
    pthread_t init_thread = pthread_self();
    if (pthread_create(&init_thread, NULL, initialize_data, initialize_data_arg) != 0) {
        fprintf(stderr, "Failed to create initialization thread\n");
        free(entries);
        return 1;
    }

    // Process the data entries in parallel
