        pthread_t process_thread = pthread_self();
        if (pthread_create(&process_thread, NULL, process_data, process_data_arg) != 0) {
            fprintf(stderr, "Failed to create processing thread\n");
            free(entries);
            return 1;
        }
    }

    // Wait for the initialization and processing threads to complete
    pthread_join(init_thread, NULL);
    for (int i = 0; i < num_entries; i++) {
        void* process_data_arg = (void*)&entries[i];
        pthread_join(process_thread, NULL);
    }

    // Persist the data to a database
