            return NULL;
        }
    }

    return records;
}

// Function to free the memory allocated for an array of records
void freeRecords(Record* records) {
    // Free each record's data array and then free the array of records itself
    for (int i = 0; i < MAX_ENTRIES; i++) {
        free(records[i].data);
    }
    free(records);
}

// Function to handle concurrent access to the data array using mutexes
void lockDataArray(Record* records) {
    pthread_mutex_lock(&mutex);
}

void unlockDataArray(Record* records) {
    pthread_mutex_unlock(&mutex);
}

