    if (argc > 1) {
        maxEntries = atoi(argv[1]);
        if (maxEntries <= 0 || maxEntries > MAX_ENTRIES) {
            printf("Error: invalid maximum number of entries\n");
            return 1;
        }
    }
    if (argc > 2) {
        maxDataSize = atoi(argv[2]);
        if (maxDataSize <= 0 || maxDataSize > MAX_DATA_SIZE) {
            printf("Error: invalid maximum size of data array\n");
            return 1;
        }
    }

    // Allocate memory for the array of records and initialize each record with a random value and an empty data array
    Record* records = allocateRecords(maxEntries, maxDataSize);
    if (!records) {
        printf("Error: failed to allocate memory for the record array\n");
        return 1;
    }

    // Perform some operations on the records using mutexes to prevent race conditions
    lockDataArray(records);
    // Do something with the records here, e.g. read from an external database or file
    unlockDataArray(records);

    // Periodically check for inconsistencies in the offset and key arrays using a separate thread
    pthread_t checkInconsistenciesThread;
    if (pthread_create(&checkInconsistenciesThread, NULL, checkInconsistencies, NULL)) {
        printf("Error: failed to create the check inconsistencies thread\n");
        return 1;
    }

    // Clean up resources and exit
