using json = nlohmann::json;

struct record {
  int value;
};

void insert_after(std::forward_list<int>& list, int val, int pos) {
  auto it = std::find(list.begin(), list.end(), val);
  if (it != list.end()) {
    list.insert_after(it, pos);
  } else {
    list.push_back(pos);
  }
}

void update_existing(std::forward_list<int>& list, int idx, int val) {
  auto it = std::find(list.begin(), list.end(), idx);
  if (it != list.end()) {
    *it = val;
  }
}

void sort_custom(std::forward_list<int>& list, std::function<bool(int, int)> compare) {
  std::sort(list.begin(), list.end(), compare);
}

void serialize(const std::forward_list<int>& list, const char* filename) {
  std::ofstream ofs(filename);
  for (auto it = list.begin(); it != list.end(); ++it) {
    json j;
    j["value"] = *it;
    ofs << j.dump() << "\n";
  }
}

void deserialize(std::forward_list<int>& list, const char* filename) {
  std::ifstream ifs(filename);
  json j;
  while (ifs >> j) {
    int val = j["value"];
    list.push_back(val);
  }
}

void randomize_values(std::forward_list<int>& list, int min, int max) {
  for (auto& record : list) {
    record.value = std::rand() % (max - min + 1) + min;
  }
}

int main() {
  // forward list of integers
  std::forward_list<int> list;

  // insert values into the list
  list.push_back(5);
  list.push_back(10);
  list.push_back(15);
  list.push_back(20);

  // print the list before inserting a new value
  std::cout << "Before inserting 10: ";
  for (auto& val : list) {
    std::cout << val << " ";
  }
  std::cout << "\n";

  // insert 10 after the first occurrence of 5
  insert_after(list, 10, 5);

  // print the list after inserting a new value
  std::cout << "After inserting 10: ";
  for (auto& val : list) {
    std::cout << val << " ";
  }
  std::cout << "\n";

  // update the existing value at index 2 with 15
  update_existing(list, 2, 15);

  // print the updated list
  std::cout << "After updating 2: ";
  for (auto& val : list) {
    std::cout << val << " ";
  }
  std::cout << "\n";

  // sort the list based on custom comparison function
  struct compare_int {
    bool operator()(const int& a, const int& b) { return a < b; }
  };
  sort_custom(list, compare_int());

  // print the sorted list
  std::cout << "Sorted list: ";
  for (auto& val : list) {
    std::cout << val << " ";
  }
  std::cout << "\n";

  // serialize the list to a file
  serialize(list, "example.json");

  // deserialize the list from the file
  deserialize(list, "example.json");

