function extractProducts(text, productNames) {
  // Define regular expressions for delimiters and punctuation characters
  const delimiterRegex = /\s|_|\-/g;
  const punctuationRegex = /[^a-zA-Z0-9]/g;

  // Initialize an object to store the extracted product names and their counts
  const products = {};

  // Iterate over each product name in the list
  for (const productName of productNames) {
    // Convert the product name to lowercase to handle case-insensitive search
    const lowerCaseProductName = productName.toLowerCase();

    // Initialize a variable to store the number of matches found
    let matchCount = 0;

    // Split the text into individual words using the delimiter regular expression
    const words = text.split(delimiterRegex);

    // Iterate over each word in the text
    for (const word of words) {
      // Remove any punctuation characters from the word using a positive lookahead assertion
      const cleanWord = word.replace(punctuationRegex, '');

      // Check if the cleaned word matches the lowercase product name
      if (cleanWord === lowerCaseProductName) {
        // Increment the match count for this product name
        matchCount++;
      } else if (lowerCaseProductName.includes(cleanWord)) {
        // If the product name is part of a larger word, check if it's a complete match
        const prefix = lowerCaseProductName.split('').slice(0, cleanWord.length).join('');
        if (prefix === cleanWord) {
          // Increment the match count for this product name
          matchCount++;
        }
      }
    }

    // Add the product name and its match count to the products object
    products[productName] = matchCount;
  }

  return products;
}

// Example usage:
const text = 'This is a sample text with laptops, smartphones, and tablets.';
const productNames = ['laptop', 'smartphone', 'tablet'];
console.log(extractProducts(text, productNames)); // Output: { laptop: 2, smartphone: 1, tablet: 1 }"]

