class Cache {
  private:
    mutex cacheMutex_;
    condition_variable cv_;
    queue<Node> cache_;
    size_t cacheSize_;
    bool cacheFull_;
    bool isCacheFull() {
      return (cache_.size() == cacheSize_);
    }
    void evictCache() {
      while (!cache_.empty()) {
        Node* node = cache_.front();
        if (node->next != nullptr) {
          cache_.erase(cache_.begin());
          delete node;
        } else {
          break;
        }
      }
    }
  public:
    Cache(size_t size) : cacheSize_(size), cacheFull_(false) {}
    void put(string key, string value) {
      Node* newNode = new Node;
      newNode->key = key;
      newNode->value = value;
      newNode->next = nullptr;
      cacheMutex_.lock();
      if (isCacheFull()) {
        evictCache();
      }
      cache_.push_back(newNode);
      cacheFull_ = true;
      cv_.notify_one();
      cacheMutex_.unlock();
    }
    string get(string key) {
      string value = "";
      Node* node = nullptr;
      cacheMutex_.lock();
      for (auto it = cache_.begin(); it != cache_.end(); ++it) {
        if ((*it)->key == key) {
          node = *it;
          break;
        }
      }
      if (node != nullptr) {
        value = node->value;
        Node* newNode = new Node;
        newNode->key = key;
        newNode->value = value;
        newNode->next = node->next;
        cache_.erase(cache_.begin());
        delete node;
      } else {
        cv_.wait(cacheMutex_);
      }
      cacheFull_ = false;
      cacheMutex_.unlock();
      return value;
    }
};
