}

// Thread-safe mechanism to handle concurrent access to this data without causing race conditions or deadlocks
void freeMemoryLocked(Record** records, long** offsets, int** keys) {
    // Lock the memory allocation mutex to prevent concurrent access
    pthread_mutex_lock(&memoryAllocationMutex);

    // Free the record array
    free(*records);
    *records = NULL;

