// Function to establish a connection to a remote address using TCP socket
int connect_to_remote(const char *address, int port) {
    // Create a socket for the client
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set up connection to remote address and port
    struct sockaddr_in server_address = {0};
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, address, &server_address.sin_addr);
    server_address.sin_port = htons(port);

    // Connect to remote address and port
    if (connect(sock, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("connection failed");
        return -1;
    }

    return sock;
}
```
