// Function to log messages with different levels
void logMessage(int level, const char *message, ...) {
    // Check if logging is enabled for the specified level
    if (level > LOG_LEVEL) {
        return;
    }

    // Prepare and format the message using vsprintf()
    va_list args;
    va_start(args, message);
    char buffer[4096];
    int size = vsprintf(buffer, message, args);
    va_end(args);

    // Write the formatted message to the log file using fwrite()
    FILE *logFile = fopen(*logFile, "a+");
    if (logFile) {
        fwrite(buffer, size, 1, logFile);
        fclose(logFile);
    }
}
