    // Allocate memory for the arrays
    *offsets = malloc(numRecords * sizeof(long));
    *keys = malloc(numRecords * sizeof(int));
    *values = malloc(numRecords * sizeof(double));
    if (*offsets == NULL || *keys == NULL || *values == NULL) {
