        char *token = strtok(line, ",");
        (*offsets)[i] = atol(token);
        token = strtok(NULL, ",");
        (*keys)[i] = atoi(token);
        token = strtok(NULL, ",");
        (*values)[i] = atof(token);
        i++;
    }
    fclose(file);

    // Allocate memory for the records array
    *records = malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        printf("Error allocating memory\n");
        free(*offsets);
        free(*keys);
        free(*values);
        return;
