void initialize_arrays(size_t size, int key_range_min, int key_range_max, int value_range_min, int value_range_max) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(sizeof(long) * size);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Initialize the offset array with sequential values starting from 0
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(struct record);
    }

    // Allocate memory for the key and value arrays
    int *keys = (int *)malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(1);
    }
    struct record *values = (struct record *)malloc(sizeof(struct record) * size);
    if (!values) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        exit(1);
    }

    // Initialize the key and value arrays with random integers within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        values[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    }

    // Allocate memory for the string pointers and initialize them with null
    char **strs = (char **)malloc(sizeof(char *) * size);
    if (!strs) {
        fprintf(stderr, "Failed to allocate memory for string pointers\n");
        exit(1);
    }
    for (size_t i = 0; i < size; ++i) {
        strs[i] = NULL;
    }

    // Allocate memory for the strings and initialize them with the corresponding keys as null-terminated strings
    for (size_t i = 0; i < size; ++i) {
        char *str = malloc(sizeof(char) * strlen(keys[i]) + 1);
        if (!str) {
            fprintf(stderr, "Failed to allocate memory for string %zu\n", i);
            exit(1);
        }
        strcpy(str, keys[i]);
        values[i].str = str;
    }
}

void cleanup_arrays() {
    // Free the memory allocated for the offset array
    free(offsets);

    // Free the memory allocated for the key and value arrays
    free(keys);
    free(values);

    // Free the memory allocated for the string pointers
    free(strs);
}
```
