typedef struct {
    double offset;
    char key[10];
} Data;

void initialize_data(int size, int range) {
    // allocate memory for the arrays
    Data *offset_array = (Data *)malloc(size * sizeof(Data));
    char **key_array = (char **)malloc(size * sizeof(char*));
    Data *data_array = (Data *)malloc(size * sizeof(Data));

    // check for memory allocation errors
    if (offset_array == NULL || key_array == NULL || data_array == NULL) {
        printf("Memory allocation error\n");
        return;
    }

    // set the values of each data's double field to a random value within a given range
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        offset_array[i].offset = rand() % range + 1.0;
        key_array[i] = malloc(10 * sizeof(char));
        strcpy(key_array[i], "Data");
        data_array[i].key = key_array[i];
