    struct Record *records;
    size_t capacity;
    size_t count;
};

struct FSA {
    // Define FSA structure fields here
};

struct StateList* createStateList(int *states, int numStates, struct FSA* fsa, int lastState) {
    if (states == NULL || numStates <= 0 || fsa == NULL || lastState < 0) {
        return NULL;
    }

    // Allocate memory for the two arrays
    long *offsetValues = malloc(sizeof(long) * numStates);
    if (offsetValues == NULL) {
        return NULL;
    }
    int *keyValues = malloc(sizeof(int) * numStates);
    if (keyValues == NULL) {
        free(offsetValues);
        return NULL;
    }

    // Initialize the two arrays with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < numStates; i++) {
        offsetValues[i] = rand() % 100000;
        keyValues[i] = rand() % 26 + 97;
    }

    // Allocate memory for the record array and initialize it with random values within a specified range
    struct Record *records = malloc(sizeof(struct Record) * numStates);
    if (records == NULL) {
        free(offsetValues);
        free(keyValues);
        return NULL;
    }
    for (int i = 0; i < numStates; i++) {
        records[i].value = rand() % 100 + 1;
    }

    // Find the list of states in the FSA and store it in a newly created state list
    struct StateList *stateList = malloc(sizeof(struct StateList));
    if (stateList == NULL) {
        free(offsetValues);
        free(keyValues);
        free(records);
        return NULL;
    }
    stateList->capacity = numStates;
    stateList->count = 0;
    stateList->records = records;

    // Set the 'next' pointer of the last state in the list to point to the newly created state list
    for (int i = 0; i < numStates - 1; i++) {
        if (states[i] == lastState) {
            stateList->records[i].next = &stateList->records[i + 1];
        }
    }

    return stateList;
}
