['Here is an example implementation of the `initialize_records` function that meets the requirements you described:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_records(const char *file_path, long *offsets, int *keys, record **records, int *num_records,
                        int min_value, int max_value) {
    // Open the file for reading
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(1024);
    size_t bytes_read = fread(buffer, 1, 1024, file);
    if (bytes_read == 0) {
        printf("Error reading from file: %s\n", strerror(errno));
        return;
    }

    // Close the file
    fclose(file);

    // Parse the contents of the buffer to extract the offsets and keys
    char *token = strtok(buffer, ",");
    while (token != NULL) {
        long offset = atol(token);
        int key = atoi(token + 1);
        token = strtok(NULL, ",");

        // Add the offset and key to the arrays
        offsets[*num_records] = offset;
        keys[*num_records] = key;
        (*num_records)++;
    }

    // Allocate memory for the records array
    *records = malloc(*num_records * sizeof(record));
    if (*records == NULL) {
        printf("Error allocating memory for records: %s\n", strerror(errno));
        return;
    }

    // Initialize the values of each record's `int` field to a random value within the specified range
    srand((unsigned int) time(NULL));
    for (int i = 0; i < *num_records; i++) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}
```
