    for (int i = 0; i < num_states; i++) {
        records[i].value = generate_random_value();
    }

    // Return a pointer to the newly created state list
    return state_list;
}

// Function to find a list of states in a given finite state automaton (FSA)
struct StateList *find_states(struct FSA *fsa, int num_states) {
    // Check if the input pointers are valid
    if (fsa == NULL || num_states <= 0) {
        return NULL;
    }

    // Create a new state list to store the found states
    struct StateList *state_list = malloc(sizeof(struct StateList));
    if (state_list == NULL) {
        return NULL;
    }

    // Initialize the first state in the list
    state_list->next = NULL;
    state_list->state_id = fsa->initial_state_id;
    struct StateList *current_state = state_list;

    // Iterate through the FSA and find states that are reachable from the initial state
    for (int i = 0; i < num_states; i++) {
        struct Node *node = fsa->states[i];
        while (node != NULL) {
            if (node->state_id == current_state->state_id) {
                // Add the state to the list
                struct StateList *new_state = malloc(sizeof(struct StateList));
                if (new_state == NULL) {
                    return NULL;
                }
                new_state->next = current_state;
                new_state->state_id = node->state_id;
                current_state = new_state;
            }
            node = node->next;
        }
    }

    // Return the list of found states
    return state_list;
}

// Function to generate a random value within a given range
int generate_random_value() {
    // Generate a random number between 0 and 10000
    int random_number = (rand() % 10000) + 1;

    // Return the generated random value
    return random_number;
}
