            fclose(file);
            free(data[row]);
            free(data);
            return NULL;
        }

        data[row]->key = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: unable to parse int key for line %d of CSV file\n", row + 1);
            fclose(file);
            free(data[row]);
            free(data);
            return NULL;
        }

        data[row]->string_value = (char*)malloc(strlen(token) + 1);
        if (data[row]->string_value == NULL) {
            printf("Error: unable to allocate memory for string value for line %d of CSV file\n", row + 1);
            fclose(file);
            free(data[row]);
            free(data);
            return NULL;
        }

        strcpy(data[row]->string_value, token);
        row++;
    }

    // Close the file and return the data entries array
    fclose(file);
    return data;
}

// Function to free the memory allocated for an array of data entries
void free_data(data_entry** data) {
