// Function to perform DNS resolution and return the IP address in a u_char array
u_char* dns_resolve(const char* hostname, int* error) {
    // Check if the hostname is valid
    if (!hostname || !strlen(hostname)) {
        *error = 1;
        LOG("Invalid hostname");
        return NULL;
    }

    // Acquire mutex to prevent race conditions and deadlocks
    pthread_mutex_lock(&mutex);

    // Check if the hostname is in the cache
    struct cache_entry* entry = NULL;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (!strcmp(cache[i].hostname, hostname)) {
            entry = &cache[i];
            break;
        }
    }

    // If the hostname is not in the cache, perform DNS resolution and add it to the cache
    if (!entry) {
        struct addrinfo* res = NULL;
        int rc = getaddrinfo(hostname, NULL, NULL, &res);
        if (rc != 0) {
            *error = 1;
            LOG("DNS resolution failed: %s", gai_strerror(rc));
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        // Allocate memory for the cache entry and copy the IP address
        entry = malloc(sizeof(*entry));
        if (!entry) {
            *error = 1;
            LOG("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        strcpy(entry->hostname, hostname);
        entry->ip = ((struct sockaddr_in*)res->ai_addr)->sin_addr.s_addr;

        // Add the cache entry to the end of the list and evict the least recently used entry if necessary
        if (cache_size < CACHE_SIZE) {
            cache[cache_size++] = *entry;
        } else {
            struct cache_entry* oldest = NULL;
            time_t oldest_time = 0;
            for (int i = 0; i < CACHE_SIZE; i++) {
                if (!oldest || cache[i].last_used < oldest_time) {
                    oldest = &cache[i];
                    oldest_time = oldest->last_used;
                }
            }
            free(oldest);
            *oldest = *entry;
        }
    }

    // Update the last used timestamp for the cache entry
    entry->last_used = time(NULL);

    // Release mutex and return the IP address in a u_char array
    pthread_mutex_unlock(&mutex);
    *error = 0;
    return (u_char*)&entry->ip;
}
