// Function to create and populate a list of LTE UE contexts
LTE_UE_Context* create_lte_ue_contexts(int num_ues) {
    LTE_UE_Context* ue_contexts = malloc(num_ues * sizeof(LTE_UE_Context));
    if (ue_contexts == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

