        LTE_UE_Context* ue_context = &ue_contexts[i];
        // Set the UE identifier (IMSI)
        char imsi[16];
        sprintf(imsi, "ims%d", i);
        ue_context->imsi = strdup(imsi);

        // Set the number of active radio bearers
        ue_context->num_active_bearers = 2;

        // Set the QoS parameters for each active radio bearer
        ue_context->qos_params = malloc(ue_context->num_active_bearers * sizeof(int));
        if (ue_context->qos_params == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        ue_context->qos_params[0] = 10; // QoS parameter for bearer 0
        ue_context->qos_params[1] = 20; // QoS parameter for bearer 1

        // Set the radio bearer identifiers for each active bearer
        ue_context->bearer_ids = malloc(ue_context->num_active_bearers * sizeof(int));
        if (ue_context->bearer_ids == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        ue_context->bearer_ids[0] = 1000; // Radio bearer identifier for bearer 0
        ue_context->bearer_ids[1] = 2000; // Radio bearer identifier for bearer 1
    }

    return ue_contexts;
}
