void initialize_data_points(data_point **points, int num_points, double min_val, double max_val, const char *csv_file) {
    // Allocate memory for the arrays of doubles and integers
    *points = (double *)malloc(num_points * sizeof(double));
    if (*points == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the double array.\n");
        exit(EXIT_FAILURE);
    }
    int *keys = (int *)malloc(num_points * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the integer array.\n");
        free(*points);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the data_point structs
    data_point *data_points = (data_point *)malloc(num_points * sizeof(data_point));
    if (data_points == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the data_point array.\n");
        free(*points);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Read data from the CSV file and initialize the arrays
    FILE *file = fopen(csv_file, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file %s.\n", csv_file);
        free(*points);
        free(keys);
        free(data_points);
        exit(EXIT_FAILURE);
    }
    int i = 0;
    while (fscanf(file, "%lf,%d,%s\n", &(*points)[i], &keys[i], data_points[i].identifier) == 3) {
        // Initialize the double value to a random value within the given range
        (*points)[i] = ((double)rand() / (RAND_MAX)) * (max_val - min_val) + min_val;
        // Increment i and continue reading data from the file
        ++i;
