    state->units = malloc(sizeof(struct unit) * 5000);
    state->num_units = 0;
    state->healths = malloc(sizeof(int) * 5000);
    state->types = malloc(sizeof(int) * 5000);
}

// Function to allocate memory for a new unit and add it to the server state structure
void add_unit(struct server_state* state, struct unit* unit) {
    // Increment the number of units in the array
    state->num_units++;

    // Allocate memory for the new unit
    state->units = realloc(state->units, sizeof(struct unit) * state->num_units);

    // Copy the new unit into the array
    memcpy(&state->units[state->num_units - 1], unit, sizeof(struct unit));
}

// Function to update the health value of a unit
void update_unit_health(struct server_state* state, int index, int new_health) {
    // Acquire the mutex lock to ensure thread safety during updates
    pthread_mutex_lock(&state->mutex);

    // Update the health value of the unit
    state->healths[index] = new_health;

    // Release the mutex lock
    pthread_mutex_unlock(&state->mutex);
}

