    pthread_mutex_lock(&state->mutex);

    // Update the position of the unit
    state->units[index].position[0] = x;
    state->units[index].position[1] = y;

    // Release the mutex lock
    pthread_mutex_unlock(&state->mutex);
}

// Function to handle cooldowns and resets for certain actions
void handle_cooldowns(struct server_state* state) {
    // Acquire the mutex lock to ensure thread safety during updates
    pthread_mutex_lock(&state->mutex);

    // Check if any cooldowns or resets need to be performed
    for (int i = 0; i < state->num_units; i++) {
        struct unit* unit = &state->units[i];

        // Handle cooldowns and resets for moving units
        if (unit->type == MOVING && unit->cooldown > 0) {
            unit->cooldown--;

            if (unit->cooldown == 0) {
                unit->can_move = true;
            }
        }

        // Handle cooldowns and resets for attacking other units
        if (unit->type == ATTACKING && unit->cooldown > 0) {
            unit->cooldown--;

            if (unit->cooldown == 0) {
                unit->can_attack = true;
            }
        }

        // Handle cooldowns and resets for using abilities
        if (unit->type == USING_ABILITY && unit->cooldown > 0) {
            unit->cooldown--;

            if (unit->cooldown == 0) {
                unit->can_use_ability = true;
            }
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&state->mutex);
}

// Function to handle update messages from other players
void handle_update_messages(struct server_state* state) {
    // Acquire the mutex lock to ensure thread safety during updates
    pthread_mutex_lock(&state->mutex);

    // Check if there are any update messages from other players
    for (int i = 0; i < state->num_players; i++) {
        struct player* player = &state->players[i];

