    if (*entries == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu entries\n", num_entries);
        exit(EXIT_FAILURE);
    }
}

void initialize_data(data_entry* entries, size_t num_entries) {
    // Initialize the values of each data_entry structure
    srand(time(NULL));
    for (size_t i = 0; i < num_entries; ++i) {
        double value = MIN_DOUBLE_VALUE + ((double)rand() / RAND_MAX) * (MAX_DOUBLE_VALUE - MIN_DOUBLE_VALUE);
        entries[i].value = value;
    }
}

void read_strings(char*** strings, size_t num_strings) {
    // Read the predefined list of strings from an external file or database
    *strings = (char**)malloc(sizeof(char*) * num_strings);
    for (size_t i = 0; i < num_strings; ++i) {
        (*strings)[i] = (char*)malloc(MAX_STRING_LENGTH);
        if ((*strings)[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for string %zu\n", i + 1);
            exit(EXIT_FAILURE);
