void update_location(const char* username, const char* location) {
    // Initialize a DAO object for accessing the database
    dao* db = new dao("wifi_database", "username");

    // Check if the location exists in the database
    bool location_exists = false;
    int num_locations = 0;
    while (db->fetch(num_locations, &location_record) != NULL) {
        if (strcmp(location_record.location, location) == 0) {
            location_exists = true;
            break;
        }
        num_locations++;
    }

    // If the location does not exist in the database, create a new record for it
    if (!location_exists) {
        location_record new_location;
        strcpy(new_location.location, location);
        db->insert(&new_location);
    }

    // Update the user's location in the database
    db->update("username", "location = ?", &location);
}

