    inet_pton(AF_INET, "192.168.0.1", &server_addr.sin_addr); // Replace with the IP address of your API server

    // Send an HTTP GET request to fetch weather data for the location
    char* get_request = "GET /weather/location HTTP/1.1\r\nHost: 192.168.0.1\r\n\r\n";
