    while (data[0] != '{' || data[1] != '"' || data[2] != '"') {
        data++;
    }
    int index = 3;
    while (data[index] != '"' && data[index + 1] != '"' && data[index + 2] != ':') {
        index++;
    }
    *temperature = atof(data + index + 3); // Parse the temperature value as a float
    while (data[index] != '"' || data[index + 1] != '"' || data[index + 2] != ',' || data[index + 3] != '"') {
        index++;
    }
    *weather_code = atoi(data + index + 4); // Parse the weather code as an integer
