// Structure to represent a LTE UE context
typedef struct {
    char* imsi; // IMSI of the UE
    struct {
        int qci; // QoS Class Identifier
        unsigned char mbr; // Maximum Bit Rate (MBR)
        unsigned char gbr; // Guaranteed Bit Rate (GBR)
    } bearers[4]; // Array to store active radio bearers
} LTE_UE_Context;

// Structure to represent a list of LTE UE contexts
typedef struct {
    LTE_UE_Context* entries; // List of LTE UE context structures
    int capacity; // Capacity of the list
    int size; // Number of elements in the list
} LTE_UE_List;

// Function to create and populate a new LTE UE context structure
LTE_UE_Context* lte_ue_create(char* imsi) {
    LTE_UE_Context* ue = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!ue) {
        // Handle memory allocation failure gracefully
        perror("Memory allocation failed");
        return NULL;
    }
    strcpy(ue->imsi, imsi);
    ue->size = 0;
    return ue;
}

// Function to add a new active radio bearer to an existing LTE UE context structure
void lte_ue_add_bearer(LTE_UE_Context* ue, int qci, unsigned char mbr, unsigned char gbr) {
    if (ue->size >= 4) {
        // Handle case where too many radio bearers are added to the UE context structure
        printf("Error: Too many radio bearers added to LTE UE context\n");
        return;
    }
    ue->bearers[ue->size].qci = qci;
    ue->bearers[ue->size].mbr = mbr;
    ue->bearers[ue->size].gbr = gbr;
    ue->size++;
}

// Function to remove an active radio bearer from an existing LTE UE context structure
void lte_ue_remove_bearer(LTE_UE_Context* ue, int index) {
    if (index < 0 || index >= ue->size) {
        // Handle case where invalid index is specified for removing a radio bearer
        printf("Error: Invalid index specified for removing radio bearer\n");
        return;
    }
    for (int i = index; i < ue->size - 1; i++) {
        ue->bearers[i] = ue->bearers[i + 1];
    }
    ue->size--;
}

// Function to create and populate a new list of LTE UE context structures
LTE_UE_List* lte_ue_list_create() {
    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (!list) {
        // Handle memory allocation failure gracefully
        perror("Memory allocation failed");
        return NULL;
    }
    list->entries = (LTE_UE_Context*)calloc(1, sizeof(LTE_UE_Context));
    if (!list->entries) {
