        int new_capacity = list->capacity * 2;
        LTE_UE_Context* new_entries = (LTE_UE_Context*)realloc(list->entries, sizeof(LTE_UE_Context) * new_capacity);
        if (!new_entries) {
            // Handle memory allocation failure gracefully
