Here is a possible implementation of the C function that establishes a connection to a remote address using a TCP socket channel and handles the connection state changes:
```c
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

#define BUFFER_SIZE 1024

int main()
{
    // Declare variables
    int sockfd, portno, n;
    char buffer[BUFFER_SIZE];
    struct sockaddr_in serv_addr;

    // Set up the connection to the remote address
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
    {
        perror("ERROR opening socket");
        return -1;
    }

    portno = atoi(argv[2]);

    // Set up the remote address information
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(portno);
    if (inet_pton(AF_INET, argv[1], &serv_addr.sin_addr) <= 0)
    {
        perror("ERROR converting IP address");
        return -1;
    }

    // Connect to the remote address
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
    {
        perror("ERROR connecting");
        close(sockfd);
        return -1;
    }

    // Read data from the socket and print it to standard output
    while ((n = read(sockfd, buffer, BUFFER_SIZE)) > 0)
    {
        printf("%s", buffer);
    }

    // Close the connection to the remote address
    close(sockfd);

    return 0;
}
```
