['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Thread-local storage for logging
__thread char log_buf[1024];

struct record {
    int key;
};

struct config {
    int num_records;
    int min_value;
    int max_value;
    char *log_file_path;
};

void* allocate_memory(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate %d bytes of memory\n", size);
        return NULL;
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

int generate_offset_values(struct config *config) {
    int i, j;
    long *offsets = allocate_memory(sizeof(long) * config->num_records);
    if (!offsets) {
        return -1;
    }
    for (i = 0; i < config->num_records; i++) {
        offsets[i] = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }
    return 0;
}

int generate_keys(struct config *config, struct record **records) {
    int i;
    for (i = 0; i < config->num_records; i++) {
        (*records)[i].key = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }
    return 0;
}

void log_message(char *msg, struct config *config) {
    time_t t = time(NULL);
    char buf[64];
    strftime(buf, sizeof(buf), "%F %T", localtime(&t));
    fprintf(stderr, "[%s] [%d] %s\n", buf, getpid(), msg);
}

struct record* initialize_records(struct config *config) {
    struct record *records = allocate_memory(sizeof(struct record) * config->num_records);
    if (!records) {
        return NULL;
    }
    int i;
    for (i = 0; i < config->num_records; i++) {
        records[i].key = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }
    return records;
}

void* allocate_and_initialize_memory(struct config *config, struct record **records) {
    if (!records) {
        return NULL;
    }
    int ret = generate_offset_values(config);
    if (ret < 0) {
        log_message("Error: Failed to generate offset values", config);
        free_memory(records);
        records = NULL;
    } else {
        log_message("Offset values generated successfully", config);
    }
    ret = generate_keys(config, records);
    if (ret < 0) {
        log_message("Error: Failed to generate key values", config);
        free_memory(records);
        records = NULL;
    } else {
        log_message("Key values generated successfully", config);
    }
    return records;
}

void deallocate_and_free_memory(struct record **records) {
    if (!records) {
        return;
    }
    free_memory(*records);
    *records = NULL;
