// Define the maximum number of records that can be created at any given time
#define MAX_NUM_RECORDS 10000

// Define the function to initialize and manage an array of custom record structures
int init_record_array(size_t num_records, int range_start, int range_end, bool use_thread_local_storage) {
    // Validate input parameters
    if (num_records == 0 || range_start > range_end) {
        return -1;
    }

    // Determine whether to use thread-local storage or global storage for the records array
    bool use_global_storage = !use_thread_local_storage;

    // Allocate memory for the records array
    Record* records = (Record*)malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        return -2;
    }

