    }

    // Store the allocated records array in the caching mechanism if possible
    if (!use_global_storage && num_cached_arrays < MAX_NUM_RECORDS) {
        cached_arrays[num_cached_arrays++] = records;
    }

    // Return a pointer to the initialized records array
    return (int)records;
}

// Define the function to deallocate an array of custom record structures
void free_record_array(Record* records, size_t num_records, bool use_thread_local_storage) {
