    if (!use_global_storage && num_cached_arrays > 0) {
        cached_arrays[--num_cached_arrays] = NULL;
    }
}

// Define the function to retrieve a previously allocated records array from the caching mechanism
Record* get_record_array(size_t num_records, bool use_thread_local_storage) {
    // Validate input parameters
