    }

    // Determine whether to use thread-local storage or global storage for the records array
    bool use_global_storage = !use_thread_local_storage;

    // Search for a matching previously allocated records array in the caching mechanism
    Record* found_records = NULL;
    for (size_t i = 0; i < num_cached_arrays; i++) {
        if (cached_arrays[i] != NULL && cached_arrays[i]->num_records == num_records) {
            found_records = cached_arrays[i];
            break;
        }
    }

    // Return the matching records array or allocate a new one if none was found in the caching mechanism
    if (found_records != NULL) {
        return found_records;
