// Define a thread-safe mutex to protect the allocation of memory
pthread_mutex_t mem_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize memory for arrays
void init_arrays(Config *config) {
    // Validate all configuration parameters before use
    if (config == NULL || config->num_records <= 0 || config->min_value < 0 || config->max_value <= 0) {
        printf("Invalid configuration provided\n");
        return;
    }

    // Determine the total size of memory to allocate based on the number of records and key values
    int num_keys = config->num_records * sizeof(int);
    int num_offsets = config->num_records * sizeof(long);
    long total_size = num_keys + num_offsets;

    // Allocate memory for the arrays using a thread-safe method
    pthread_mutex_lock(&mem_mutex);
    Record *records = malloc(total_size);
    memset(records, 0, total_size);
    pthread_mutex_unlock(&mem_mutex);

    // Initialize the arrays with random values within the specified range
    for (int i = 0; i < config->num_records; i++) {
        records[i].key = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }

    // Initialize the offset values to the starting position of each record in memory
    long *offsets = (long *)(records + config->num_records);
    for (int i = 0; i < config->num_records; i++) {
        offsets[i] = (char *)&records[i].key - (char *)records;
    }

    // Log the allocation of memory and the initialization of the arrays
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char log_entry[64];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm);
    printf("Log entry: %s\n", log_entry);
    printf("Allocated memory for %d records\n", config->num_records);
    printf("Initialized keys with random values within range [%d, %d]\n", config->min_value, config->max_value);

    // Clean up the memory allocation if an error occurs
    if (records == NULL) {
        pthread_mutex_lock(&mem_mutex);
        free(records);
        pthread_mutex_unlock(&mem_mutex);
        printf("Error: Failed to allocate memory for %d records\n", config->num_records);
    }
}
