// Define data structures for arrays of different types
typedef struct {
    long* offset_values;
    int* keys;
    record* records;
    data_point* data_points;
} dynamic_memory;

// Define function to dynamically allocate memory for multiple data structures
int allocate_dynamic_memory(dynamic_memory* mem, size_t num_offset_values, size_t num_keys, size_t num_records, size_t num_data_points) {
    // Validate input parameters
    if (num_offset_values == 0 || num_keys == 0 || num_records == 0 || num_data_points == 0) {
        return -1;
    }

    // Allocate memory for arrays of different types
    mem->offset_values = (long*) malloc(num_offset_values * sizeof(long));
    mem->keys = (int*) malloc(num_keys * sizeof(int));
    mem->records = (record*) malloc(num_records * sizeof(record));
    mem->data_points = (data_point*) malloc(num_data_points * sizeof(data_point));

    // Initialize arrays of different types with random values within specified ranges
    for (size_t i = 0; i < num_offset_values; i++) {
        mem->offset_values[i] = rand() % 100 + 1;
    }
    for (size_t i = 0; i < num_keys; i++) {
        mem->keys[i] = rand() % 10000 + 1;
    }
    for (size_t i = 0; i < num_records; i++) {
        mem->records[i].value = rand() % 10000000 + 1;
    }
    for (size_t i = 0; i < num_data_points; i++) {
        mem->data_points[i].value = rand() % 100.0 + 1.0;
        mem->data_points[i].string = malloc(256 * sizeof(char));
        sprintf(mem->data_points[i].string, "Data point string #%lu", i);
    }

    // Log memory allocation events for debugging and performance monitoring
    printf("Allocated %lu offset values, %lu keys, %lu records, and %lu data points\n", num_offset_values, num_keys, num_records, num_data_points);

    return 0;
}

// Define function to release memory for multiple data structures
void free_dynamic_memory(dynamic_memory* mem) {
    // Free memory for arrays of different types
    if (mem->offset_values != NULL) {
        free(mem->offset_values);
    }
    if (mem->keys != NULL) {
        free(mem->keys);
    }
    if (mem->records != NULL) {
        free(mem->records);
    }
    if (mem->data_points != NULL) {
        for (size_t i = 0; i < mem->num_data_points; i++) {
            if (mem->data_points[i].string != NULL) {
                free(mem->data_points[i].string);
            }
        }
        free(mem->data_points);
    }
}

// Define function to handle memory allocation failures gracefully
void* safe_malloc(size_t size, void** data) {
    // Allocate memory for the requested size
    *data = malloc(size);

    // Check if memory allocation failed
    if (*data == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize memory to a valid value
    memset(*data, 0, size);

    return *data;
}

// Define function to handle multiple threads concurrently calling the allocator safely
void* thread_safe_malloc(size_t size, void** data) {
    // Create mutex for synchronizing memory allocation operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock mutex before allocating memory
    pthread_mutex_lock(&mutex);

    // Allocate memory for the requested size
    *data = malloc(size);

    // Check if memory allocation failed
    if (*data == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize memory to a valid value
    memset(*data, 0, size);

    // Unlock mutex after allocating memory
    pthread_mutex_unlock(&mutex);

    return *data;
}

// Define function to handle multiple threads concurrently calling the allocator safely using thread-local storage
void* tls_safe_malloc(size_t size, void** data) {
    // Create thread-local storage for maintaining state across multiple calls
    pthread_key_t key;
    if (pthread_key_create(&key, NULL)) {
        printf("Failed to create thread-local storage\n");
        return NULL;
    }

    // Lock mutex before allocating memory
    pthread_mutex_lock(key);

    // Allocate memory for the requested size
    *data = malloc(size);

    // Check if memory allocation failed
    if (*data == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize memory to a valid value
    memset(*data, 0, size);

    // Unlock mutex after allocating memory
    pthread_mutex_unlock(key);

    return *data;
}

// Define function to handle integer overflow when calculating array sizes safely
size_t safe_array_size(size_t num_elements, size_t element_size) {
    // Check if the requested number of elements will cause an integer overflow
    if (num_elements > SIZE_MAX / element_size) {
        printf("Integer overflow when calculating array size\n");
        return 0;
    }

    // Calculate the safe size for the array
    size_t safe_size = num_elements * element_size;

    return safe_size;
}

// Define function to handle memory leaks safely
void safe_free(void* data) {
    // Check if the data pointer is NULL
    if (data == NULL) {
        printf("Data pointer is NULL\n");
        return;
    }

    // Free the allocated memory
    free(data);
}
