    if (!user->records) {
        return -1;
    }
    user->numRecords = numRecords;
    user->recordSize = recordSize;
    user->minValue = minValue;
    user->maxValue = maxValue;
    user->updateFrequency = updateFrequency;

    // Set the values of each record's float field to a random value within the given range
    for (int i = 0; i < numRecords; i++) {
        user->records[i].value = minValue + ((float) rand() / RAND_MAX) * (maxValue - minValue);
    }

    // Set the integer key of each record to a random value within the specified range using another loop
    for (int i = 0; i < numRecords; i++) {
        user->records[i].key = rand() % numRecords;
