    // Populate the float array with values calculated based on the integer key using another loop
    for (int i = 0; i < numRecords; i++) {
        user->records[i].value = user->minValue + ((float) rand() / RAND_MAX) * (user->maxValue - user->minValue);
    }

    // Initialize the database connection
    sqlite3* db;
    if (sqlite3_open("data.db", &db)) {
        return -1;
    }

    // Create a table in the database for storing the data
    char* createTable = "CREATE TABLE IF NOT EXISTS userData (key INTEGER, value FLOAT)";
    if (sqlite3_exec(db, createTable, NULL, NULL, NULL)) {
        sqlite3_close(db);
        return -1;
    }

    // Insert the data into the database
    char* insertData = "INSERT INTO userData VALUES(?, ?)";
    for (int i = 0; i < numRecords; i++) {
        sqlite3_stmt* stmt;
        if (sqlite3_prepare(db, insertData, -1, &stmt, NULL)) {
            sqlite3_close(db);
            return -1;
        }
        sqlite3_bind_int(stmt, 1, user->records[i].key);
        sqlite3_bind_float(stmt, 2, user->records[i].value);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            return -1;
        }
    }

    // Close the database connection
    if (sqlite3_close(db)) {
        return -1;
    }

    // Set up logging mechanisms to track allocation and deallocation of memory
    ...

    return 0;
}
