dataRecord* readJSONFile(const char* filename) {
    // open the file and check for errors
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // create an array to store the key-value pairs
    dataRecord* records = malloc(sizeof(dataRecord));
    if (!records) {
        perror("Error allocating memory for records");
        fclose(file);
        return NULL;
    }

    // initialize a JSON parser object
    json_parser_t parser = json_parser_create();
    if (!parser) {
        perror("Error creating JSON parser");
        free(records);
        fclose(file);
        return NULL;
    }

    // parse the JSON data in the file
    while (json_parser_next(parser, file)) {
        // check if we have a JSON object
        if (json_parser_is_object(parser)) {
            // get the object's key-value pairs
            json_object_t* obj = json_parser_get_object(parser);
            if (!obj) {
                perror("Error getting JSON object");
                free(records);
                fclose(file);
                return NULL;
            }

            // add the key-value pairs to our array
            int i = 0;
            while (json_object_next(obj, &i)) {
                const char* key = json_object_get_key(obj, i);
                if (!key) {
                    perror("Error getting JSON object key");
                    free(records);
                    fclose(file);
                    return NULL;
                }
                const char* value = json_object_get_value(obj, i);
                if (!value) {
                    perror("Error getting JSON object value");
                    free(records);
                    fclose(file);
                    return NULL;
                }
                records[i].key = atoi(key);
                records[i].value = atof(value);
            }
        }
    }

    // clean up the JSON parser and close the file
    json_parser_destroy(parser);
    fclose(file);

    return records;
}

// function to save the initialized data records back into a configuration file in JSON format
void writeJSONFile(const char* filename, dataRecord* records) {
    // open the file and check for errors
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Error opening file");
        return;
    }

    // initialize a JSON object to store the key-value pairs
    json_object_t* obj = json_object_create();
    if (!obj) {
        perror("Error creating JSON object");
        fclose(file);
        return;
    }

    // add each record's key and value to the JSON object
    for (int i = 0; i < numRecords; ++i) {
        const char* key = malloc(16); // 16-bit integer in hexadecimal format
        if (!key) {
            perror("Error allocating memory for key");
            free(records);
            fclose(file);
            return;
        }
        sprintf(key, "%x", records[i].key); // convert integer to hexadecimal string
        json_object_add_field(obj, key, records[i].value);
    }

    // serialize the JSON object and write it to the file
    json_serialize(obj, file);

    // clean up the JSON object and close the file
    json_destroy(obj);
    fclose(file);
}
