#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

// Function to establish and manage a pool of TCP connections using non-blocking sockets
void connection_pool(int num_connections, int socket_array[]) {
    // Initialize the socket array with empty sockets
    for (int i = 0; i < num_connections; i++) {
        socket_array[i] = -1;
    }

    // Establish connections to remote addresses using non-blocking sockets
    int connection_index = 0;
    while (connection_index < num_connections) {
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80); // Default port for HTTP
        if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
            perror("inet_pton() failed");
            return;
        }

        int sock = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, IPPROTO_TCP);
        if (sock < 0) {
            perror("socket() failed");
            return;
        }

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("connect() failed");
            close(sock);
            continue;
        }

        // Add the socket to the array of connected sockets
        if (connection_index >= num_connections) {
            fprintf(stderr, "Too many connections, skipping...\n");
            continue;
        }

        socket_array[connection_index++] = sock;
    }

    // Manage the pool of connections
    while (1) {
        // Check for incoming data on each connected socket
        for (int i = 0; i < connection_index; i++) {
            int sock = socket_array[i];
            if (sock < 0) {
                continue;
            }

            char buffer[1024];
            memset(buffer, 0, sizeof(buffer));
            ssize_t read_bytes = recv(sock, buffer, sizeof(buffer), MSG_DONTWAIT);
            if (read_bytes <= 0) {
                if (errno == EWOULDBLOCK || errno == EAGAIN) {
                    // Socket is non-blocking, no data available yet
                    continue;
                } else {
                    perror("recv() failed");
                    close(sock);
                    socket_array[i] = -1;
                    continue;
                }
            }

            // Process the received data
            printf("Received %d bytes on socket %d\n", read_bytes, sock);
        }

        // Check for outgoing data to be sent on each connected socket
        for (int i = 0; i < connection_index; i++) {
            int sock = socket_array[i];
            if (sock < 0) {
                continue;
            }

            char buffer[1024];
            memset(buffer, 0, sizeof(buffer));
            ssize_t write_bytes = send(sock, buffer, sizeof(buffer), MSG_DONTWAIT);
            if (write_bytes <= 0) {
                perror("send() failed");
                close(sock);
                socket_array[i] = -1;
                continue;
            }
        }

        // Sleep for a short period to avoid busy-looping
        sleep(1);
    }
}
