// Function to traverse the DOM tree and return a list of elements that match a given selector
function dom_traversal(root_element, selector) {
    const result = [];

    // Iterate over the root element's children
    for (let i = 0; i < root_element.children.length; i++) {
        const child = root_element.children[i];

        // Check if the current child matches the selector
        if (child.matches(selector)) {
            result.push(child);
        }

        // Recursively traverse the child element's children
        const recursive_result = dom_traversal(child, selector);
        for (let j = 0; j < recursive_result.length; j++) {
            result.push(recursive_result[j]);
        }
    }

    return result;
}
