#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <assert.h>
#include <stdbool.h>

// Define the data structure for a record in the resource bundle
typedef struct {
    int value;
} Record;

// Define the data structure for a resource bundle
typedef struct {
    long* offsets; // Array of 'long' offset values
    int* keys; // Array of 'int' keys
    Record* records; // Array of record structures
    size_t num_records; // Number of records in the bundle
} ResourceBundle;

// Define a function to load a resource bundle from a file and return its number of items
size_t LoadResourceBundleFromFile(const char* path) {
    // Open the file for reading
    FILE* fp = fopen(path, "r");
    if (!fp) {
        printf("Error opening file: %s\n", strerror(errno));
        return 0;
    }

    // Read the header information from the file
    size_t num_records = 0;
    fread(&num_records, sizeof(size_t), 1, fp);

    // Allocate memory for the resource bundle and its items
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    bundle->offsets = malloc(num_records * sizeof(long));
    bundle->keys = malloc(num_records * sizeof(int));
    bundle->records = malloc(num_records * sizeof(Record));
    bundle->num_records = num_records;

    // Initialize the arrays of offset values and keys
    for (size_t i = 0; i < num_records; ++i) {
        fread(&bundle->offsets[i], sizeof(long), 1, fp);
        fread(&bundle->keys[i], sizeof(int), 1, fp);
    }

    // Read the record data from the file and populate the records array
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &bundle->records[i];
        fread(&record->value, sizeof(int), 1, fp);
    }

    // Close the file
    fclose(fp);

    return bundle->num_records;
}

// Define a function to free the memory allocated for a resource bundle
void FreeResourceBundle(ResourceBundle* bundle) {
    if (!bundle) return;
    free(bundle->offsets);
    free(bundle->keys);
    free(bundle->records);
    free(bundle);
}

// Define a function to get the value of a record in a resource bundle given its key
int GetRecordValue(ResourceBundle* bundle, int key) {
    if (!bundle || !bundle->records) return 0;
    for (size_t i = 0; i < bundle->num_records; ++i) {
        if (bundle->keys[i] == key) {
            return bundle->records[i].value;
        }
    }
    return 0;
}

// Define a function to set the value of a record in a resource bundle given its key
void SetRecordValue(ResourceBundle* bundle, int key, int value) {
    if (!bundle || !bundle->records) return;
    for (size_t i = 0; i < bundle->num_records; ++i) {
        if (bundle->keys[i] == key) {
            bundle->records[i].value = value;
            return;
        }
    }
}

// Define a function to get the number of records in a resource bundle
size_t GetNumRecords(ResourceBundle* bundle) {
    if (!bundle) return 0;
    return bundle->num_records;
}

// Define a function to iterate over all records in a resource bundle and perform some action on each record
void IterateOverRecords(ResourceBundle* bundle, void (*action)(Record*)) {
    if (!bundle || !bundle->records) return;
    for (size_t i = 0; i < bundle->num_records; ++i) {
        action(&bundle->records[i]);
    }
}

// Define a function to iterate over all records in a resource bundle and perform some action on each record, returning the total number of records that meet a certain condition
size_t CountRecords(ResourceBundle* bundle, bool (*condition)(Record*)) {
    if (!bundle || !bundle->records) return 0;
    size_t count = 0;
    for (size_t i = 0; i < bundle->num_records; ++i) {
        if (condition(&bundle->records[i])) {
            count++;
        }
    }
    return count;
}

// Define a function to iterate over all records in a resource bundle and perform some action on each record, returning the total number of records that meet a certain condition
size_t FilterRecords(ResourceBundle* bundle, bool (*condition)(Record*), Record*** filtered) {
    if (!bundle || !bundle->records) return 0;
    size_t count = CountRecords(bundle, condition);
    *filtered = malloc(count * sizeof(Record*));
    size_t i = 0;
    for (size_t j = 0; j < bundle->num_records; ++j) {
        if (condition(&bundle->records[j])) {
            (*filtered)[i++] = &bundle->records[j];
        }
    }
    return count;
}

// Define a function to iterate over all records in a resource bundle and perform some action on each record, returning the total number of records that meet a certain condition
size_t MapRecords(ResourceBundle* bundle, int (*action)(Record*), Record** mapped) {
    if (!bundle || !bundle->records) return 0;
    size_t count = GetNumRecords(bundle);
    *mapped = malloc(count * sizeof(Record));
    for (size_t i = 0; i < bundle->num_records; ++i) {
        (*mapped)[i] = action(&bundle->records[i]);
    }
    return count;
}

// Define a function to iterate over all records in a resource bundle and perform some action on each record, returning the total number of records that meet a certain condition
size_t ReduceRecords(ResourceBundle* bundle, int (*action)(Record*, Record*), Record** reduced) {
    if (!bundle || !bundle->records) return 0;
    size_t count = GetNumRecords(bundle);
    *reduced = malloc(count * sizeof(Record));
    for (size_t i = 0; i < bundle->num_records; ++i) {
