// Function to load a resource bundle from a file and return the number of items in the bundle.
int load_resource_bundle(const char* path, struct ResourceBundle** bundle) {
    // Open the file for reading.
    FILE* fp = fopen(path, "r");
    if (fp == NULL) {
        return -1;  // Error: file not found
    }

    // Read the header of the file to determine the version and compression type.
    struct ResourceFileHeader header;
    size_t bytes_read = fread(&header, sizeof(struct ResourceFileHeader), 1, fp);
    if (bytes_read != 1) {
        return -2;  // Error: invalid file format
    }

    // Determine the version and compression type of the file.
    int version = header.version;
    int compression_type = header.compression_type;

    // Dynamically allocate memory for the resource bundle.
    struct ResourceBundle* new_bundle = malloc(sizeof(struct ResourceBundle) + (sizeof(struct ResourceItem*) * header.num_items));
    if (new_bundle == NULL) {
        return -3;  // Error: insufficient memory allocation
    }

    // Initialize the bundle with the number of items and a pointer to the first item.
    new_bundle->num_items = header.num_items;
    new_bundle->items[0] = malloc(sizeof(struct ResourceItem) * header.num_items);
    if (new_bundle->items[0] == NULL) {
        free(new_bundle);
        return -3;  // Error: insufficient memory allocation
    }

    // Read the items from the file and store them in the bundle.
    for (int i = 0; i < header.num_items; i++) {
        struct ResourceItem* item = &new_bundle->items[i];
        size_t bytes_read = fread(item, sizeof(struct ResourceItem), 1, fp);
        if (bytes_read != 1) {
            return -2;  // Error: invalid file format
        }
    }

    // Close the file and return the bundle.
    fclose(fp);
    *bundle = new_bundle;
    return header.num_items;
}

// Function to free a resource bundle and its items.
void free_resource_bundle(struct ResourceBundle* bundle) {
    for (int i = 0; i < bundle->num_items; i++) {
        struct ResourceItem* item = &bundle->items[i];
        free(item);
    }
    free(bundle);
}
```
