And here is a sample C function that establishes a connection to a remote address using a TCP socket channel and handles the connection state changes:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

void establishConnection(const char* ipAddress, int portNumber)
{
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        exit(1);
    }

    // Setup address
    struct sockaddr_in serverAddress;
    memset(&serverAddress, 0, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(portNumber);
    inet_pton(AF_INET, ipAddress, &serverAddress.sin_addr);

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&serverAddress, sizeof(serverAddress)) < 0) {
        perror("connection failed");
        exit(1);
    }

    printf("Connected to server\n");
}

void handleConnectionStateChanges()
{
    // Check if the socket is connected
    if (connected) {
        // Read data from the socket
        char buffer[1024];
        read(sock, buffer, 1024);

        printf("Received data: %s\n", buffer);

        // Close the socket
        close(sock);
    } else {
        perror("connection failed");
        exit(1);
    }
}
