#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/ssl.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/des.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <sqlite3.h>

int updateFirmware(const char* deviceId, const char* firmwareVersion)
{
    // Connect to the database
    sqlite3* db = NULL;
    int rc = sqlite3_open("firmware.db", &db);
    if (rc != SQLITE_OK) {
        printf("Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Check if the device exists in the database
    char query[256];
    snprintf(query, sizeof(query), "SELECT COUNT(*) FROM devices WHERE id = '%s'", deviceId);
    sqlite3_stmt* statement = NULL;
    rc = sqlite3_prepare_v2(db, query, -1, &statement, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing database query: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Execute the query and get the result
    int numDevices = 0;
    rc = sqlite3_step(statement);
    if (rc != SQLITE_DONE) {
        printf("Error executing database query: %s\n", sqlite3_errmsg(db));
        return -1;
    }
    numDevices = sqlite3_column_int(statement, 0);
    if (numDevices == 0) {
        printf("Device not found in the database\n");
        return -1;
    }

    // Check if the firmware version is valid
    char* validVersions[] = {"v1.2", "v1.3", "v1.4"};
    int i = 0;
    for (i = 0; i < sizeof(validVersions) / sizeof(char*); ++i) {
        if (strcmp(firmwareVersion, validVersions[i]) == 0) {
            break;
        }
    }
    if (i >= sizeof(validVersions) / sizeof(char*)) {
        printf("Invalid firmware version\n");
        return -1;
    }

    // Update the device's firmware in the database
    snprintf(query, sizeof(query), "UPDATE devices SET firmware_version = '%s' WHERE id = '%s'", firmwareVersion, deviceId);
    rc = sqlite3_prepare_v2(db, query, -1, &statement, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing database query: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    rc = sqlite3_step(statement);
    if (rc != SQLITE_DONE) {
        printf("Error executing database query: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Close the database connection
    sqlite3_finalize(statement);
    sqlite3_close(db);

    return 0;
}
