    // Initialize the arrays for offset, key, and value.
    offsets = (int*)malloc(sizeof(int) * num_records);
    keys = (int*)malloc(sizeof(int) * num_records);
    values = (double*)malloc(sizeof(double) * num_records);

    // Initialize the record array.
    record_t* records = (record_t*)malloc(sizeof(record_t) * num_records);
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    // Initialize the data array in each record.
