        return -1;
    }

    // Add the new record to the end of the array.
    records[num_records] = new_record;
    num_records++;

    return num_records;
}

int remove_record(record_t* records, int num_records, int index) {
    // Check if the index is valid.
    if (index < 0 || index >= num_records) {
        return -1;
    }

    // Shift all the elements after the specified index to the left by one position.
    for (int i = index + 1; i < num_records; i++) {
        records[i - 1] = records[i];
    }

    // Decrement the number of records.
    num_records--;

    return num_records;
}

int update_record(record_t* records, int num_records, int index, record_t new_record) {
    // Check if the index is valid.
    if (index < 0 || index >= num_records) {
        return -1;
    }

    // Update the record at the specified index.
