dataSet *allocateDataSets(size_t numSets) {
    // Allocate memory for the array of sets
    dataSet *sets = (dataSet *)malloc(sizeof(dataSet) * numSets);
    if (!sets) {
        printf("Memory allocation failed!\n");
        return NULL;
