    // Initialize each set with an empty linked list
    for (size_t i = 0; i < numSets; i++) {
        sets[i].records = NULL;
        sets[i].numRecords = 0;
        sets[i].next = NULL;
    }

    return sets;
}

// Function to add a new set of data records to the linked list
void addDataSet(dataSet *sets, size_t numRecords) {
    // Allocate memory for the new set of records
    dataRecord *records = allocateDataRecords(numRecords);
    if (!records) {
        return;
    }

    // Create a new linked list node for the set of records
    dataSet *newSet = (dataSet *)malloc(sizeof(dataSet));
    if (!newSet) {
        free(records);
        return;
    }

    // Initialize the new linked list node with the new set of records
    newSet->records = records;
    newSet->numRecords = numRecords;
    newSet->next = NULL;

    // Add the new linked list node to the end of the linked list
    if (sets == NULL) {
        sets = newSet;
    } else {
        dataSet *current = sets;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newSet;
    }
}

// Function to remove a set of data records from the linked list
void removeDataSet(dataSet *sets, size_t index) {
    // Check if the linked list is empty
    if (sets == NULL) {
        return;
    }

    // Find the node at the specified index in the linked list
    dataSet *current = sets;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
        if (current == NULL) {
            return;
        }
    }

    // Remove the node from the linked list by linking the previous and next nodes together
    dataSet *prev = current->prev;
    dataSet *next = current->next;
    if (prev != NULL) {
        prev->next = next;
    } else {
        sets = next;
    }
    if (next != NULL) {
        next->prev = prev;
    }

    // Free the memory allocated for the node and its records
    free(current->records);
    free(current);
}

// Function to sort a linked list of sets of data records based on the sum of the float values in each set
void sortDataSets(dataSet *sets) {
    // Check if the linked list is empty
    if (sets == NULL) {
        return;
    }

    // Create an array of pointers to the nodes in the linked list
    dataSet **nodes = (dataSet **)malloc(sizeof(dataSet *) * sets->numRecords);
    if (!nodes) {
        return;
    }

    // Populate the array of pointers with the nodes from the linked list
    size_t i = 0;
    dataSet *current = sets;
    while (current != NULL) {
        nodes[i++] = current;
        current = current->next;
    }

    // Sort the array of pointers using a custom comparison function
    qsort(nodes, i, sizeof(dataSet *), compareRecords);

    // Update the linked list by linking the sorted nodes together
    for (size_t j = 0; j < i - 1; j++) {
        nodes[j]->next = nodes[j + 1];
    }
    nodes[i - 1]->next = NULL;
}

// Custom comparison function to sort data records based on the sum of their float values
int compareRecords(const void *a, const void *b) {
    // Cast the void pointers to dataSet pointers
    dataSet *setA = (dataSet *)a;
    dataSet *setB = (dataSet *)b;

    // Calculate the sum of the float values in each set
    float sumA = 0.0f;
    for (size_t i = 0; i < setA->numRecords; i++) {
        sumA += setA->records[i].value;
    }
    float sumB = 0.0f;
    for (size_t j = 0; j < setB->numRecords; j++) {
        sumB += setB->records[j].value;
    }

    // Compare the sums and return the difference
    if (sumA > sumB) {
        return -1;
    } else if (sumA < sumB) {
        return 1;
    } else {
        return 0;
    }
}

// Function to free memory allocated for a linked list of sets of data records
void freeDataSets(dataSet *sets) {
    // Check if the linked list is empty
    if (sets == NULL) {
        return;
    }

    // Free the memory allocated for each node in the linked list
    while (sets != NULL) {
        dataSet *next = sets->next;
        free(sets->records);
        free(sets);
        sets = next;
    }
}

