    }

    // Initialize the log record array with the key and value from the corresponding arrays
    for (int i = 0; i < numElements; ++i) {
        records[i].key = (*keys)[i];
        records[i].value = (*data)[i];
    }
}

// Function to handle potential memory allocation failures gracefully and free all allocated memory before returning
void cleanup(double **offsets, char **keys, int **data) {
    if (*offsets != NULL) {
        free(*offsets);
    }
    if (*keys != NULL) {
        free(*keys);
    }
    if (*data != NULL) {
        free(*data);
    }
}

