    // Parse the data and extract the number of elements
    int numElements = 0;
    for (int i = 0; i < strlen(data); ++i) {
        if (isdigit(data[i])) {
            numElements++;
        } else {
            return -1;
        }
    }

    // Return the number of elements
    return numElements;
}
