// Custom structure for managing nodes in the BST
struct node {
    int id;
    struct node *left, *right;
};

// List of UE contexts
struct ue_context_list {
    struct node *root;
};

// Function to add a new UE context to the list
void add_ue_context(struct ue_context_list *list, int id) {
    // Check if the ID is already in the list
    if (search_ue_context(list, id)) {
        return;
    }

    // Allocate memory for the new node
    struct node *new_node = malloc(sizeof(struct node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the new node with the given ID
    new_node->id = id;
    new_node->left = NULL;
    new_node->right = NULL;

    // Add the new node to the list
    if (!list->root) {
        list->root = new_node;
    } else {
        struct node *temp = list->root;
        while (temp && temp->id < id) {
            temp = temp->right;
        }
        if (temp) {
            new_node->left = temp;
            new_node->right = temp->right;
            temp->right = new_node;
        } else {
            new_node->left = NULL;
            new_node->right = list->root;
            list->root = new_node;
        }
    }
}

// Function to remove a UE context from the list
void remove_ue_context(struct ue_context_list *list, int id) {
    // Check if the ID is in the list
    struct node *temp = search_ue_context(list, id);
    if (!temp) {
        return;
    }

    // Remove the node from the list
    if (temp->left) {
        temp->left->right = temp->right;
    } else {
        list->root = temp->right;
    }
    free(temp);
}

// Function to search for a UE context in the list
struct node *search_ue_context(struct ue_context_list *list, int id) {
    struct node *temp = list->root;
    while (temp && temp->id != id) {
        temp = temp->right;
    }
    return temp;
}

// Function to initialize cryptographic primitives
void init_cryptography() {
    // Initialize AES, Camellia block ciphers, MD5, SHA-1, SHA-256 digests, and RSA with SHA1 signatures
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_cipher(EVP_camellia_128_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
    EVP_add_signature(EVP_PKEY_RSA, NID_sha1WithRSAEncryption);
}

