void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to handle concurrent access from multiple threads without causing data races or deadlocks
void *threadsafe_malloc(size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&mem_lock);
    ptr = safe_malloc(size);
    pthread_mutex_unlock(&mem_lock);
    return ptr;
}

