#define MAX_NFAPI_CRC_INDICATION_PDU 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNfapiCrcIndicationList(NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationList) {
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU; i++) {
        // Randomly set CRCFLAG in CRC_INDICATION_REL8_TAG
        nfapiCrcIndicationList[i].crcIndicationRel8Tag.CRCFlag = (rand() % 2) ? 1 : 0;

        // Populate RX_UE_INFORMATION_TAG and RNTI fields
        nfapiCrcIndicationList[i].rxUeInfoTag.RNTI = rand();
        nfapiCrcIndicationList[i].rxUeInfoTag.SRI_PDU = rand() % 2;
        nfapiCrcIndicationList[i].rxUeInfoTag.SR_CONFIG = rand() % 3;
        nfapiCrcIndicationList[i].rxUeInfoTag.DRX_INFORMATION = rand();
        nfapiCrcIndicationList[i].rxUeInfoTag.PHYSICAL_CELL_ID = rand() % 20;

        // Populate RNTI field in CRC_INDICATION_REL8_TAG
        nfapiCrcIndicationList[i].crcIndicationRel8Tag.RNTI = nfapiCrcIndicationList[i].rxUeInfoTag.RNTI;
    }
}

void createNfapiCrcIndicationList(int numPdus) {
    NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numPdus);
    if (nfapiCrcIndicationList == NULL) {
        fprintf(stderr, "Failed to allocate memory for NFAPI CRC indication list\n");
        return;
    }

    populateNfapiCrcIndicationList(nfapiCrcIndicationList);

    // Manage memory properly
    free(nfapiCrcIndicationList);
}

void handleNfapiCrcIndicationList(NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationList) {
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU; i++) {
        printf("RX Ue Info Tag: RNTI=%d, SRI_PDU=%d, SR_CONFIG=%d, DRX_INFORMATION=%d, PHYSICAL_CELL_ID=%d\n",
                nfapiCrcIndicationList[i].rxUeInfoTag.RNTI,
                nfapiCrcIndicationList[i].rxUeInfoTag.SRI_PDU,
                nfapiCrcIndicationList[i].rxUeInfoTag.SR_CONFIG,
                nfapiCrcIndicationList[i].rxUeInfoTag.DRX_INFORMATION,
                nfapiCrcIndicationList[i].rxUeInfoTag.PHYSICAL_CELL_ID);
        printf("CR Indication Rel8 Tag: RNTI=%d, CRCFlag=%d\n",
                nfapiCrcIndicationList[i].crcIndicationRel8Tag.RNTI,
                nfapiCrcIndicationList[i].crcIndicationRel8Tag.CRCFlag);
    }
}

int main() {
    int numPdus = 10;
    createNfapiCrcIndicationList(numPdus);
    NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numPdus);
    handleNfapiCrcIndicationList(nfapiCrcIndicationList);

    // Manage memory properly
    free(nfapiCrcIndicationList);

    return 0;
}']

