struct nfapi_pdu* read_pdu(const char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        printf("Error opening file: %s\n", strerror(errno));
        return NULL;
    }

    // Read the number of elements in the array from the first line of the file
    int num_elements = 0;
    if (fscanf(fp, "%d", &num_elements) != 1) {
        printf("Error reading number of elements\n");
        fclose(fp);
        return NULL;
    }

    // Allocate memory for the array of structures
    struct nfapi_pdu* pdu = (struct nfapi_pdu*)malloc(sizeof(struct nfapi_pdu) * num_elements);
    if (!pdu) {
        printf("Error allocating memory for array of structures\n");
        fclose(fp);
        return NULL;
    }

    // Read the data from the file and populate the array of structures
    int i = 0;
    while (fscanf(fp, "%d %d %d", &pdu[i].rx_ue_info_tag, &pdu[i].rnti, &pdu[i].crc_flag) == 3) {
        // Randomly set the crc_flag to 1 for demonstration purposes
        pdu[i].crc_flag = (rand() % 2) ? 1 : 0;
        i++;
    }
    fclose(fp);

    // Find and print the largest number in the array
    float largest_number = -FLT_MAX;
    for (int i = 0; i < num_elements; i++) {
        if (pdu[i].rx_ue_info_tag == RX_UE_INFO_TAG_LARGEST) {
            largest_number = MAX(largest_number, pdu[i].rnti);
        }
    }
    printf("Largest number in the array is: %f\n", largest_number);

    // Clean up and return the array of structures
    free(pdu);
    return NULL;
}
