    uint32_t s_tmsi;
    char imsi[15];
    bool validity_flag;
};

// Define a list data structure to store the generated messages
typedef struct nas_message_list {
    size_t count;
    struct nas_message* messages;
} nas_message_list;

// Function to fetch UE IDs and IMSIs from an external database
static int get_ue_ids(sqlite3 *db, nas_message_list *list) {
    int rc = SQLITE_OK;
    char *errmsg = NULL;
    sqlite3_stmt *stmt = NULL;

    // Prepare a statement to retrieve UE IDs and IMSIs from the database
    const char *sql = "SELECT ue_id, imsi FROM ue_info";
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error while preparing statement: %s\n", sqlite3_errmsg(db));
        return rc;
    }

    // Iterate over the rows in the result set and populate the list of messages
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        struct nas_message *message = malloc(sizeof(struct nas_message));
        if (!message) {
            fprintf(stderr, "Error: out of memory\n");
            break;
        }

        message->ue_id = sqlite3_column_int64(stmt, 0);
        strcpy(message->imsi, (const char*)sqlite3_column_text(stmt, 1));
        message->validity_flag = true;

        // Generate a random S-TMSI for the message
        message->s_tmsi = (uint32_t)(rand() % INT32_MAX);

        list->messages = realloc(list->messages, (list->count + 1) * sizeof(struct nas_message));
        if (!list->messages) {
            fprintf(stderr, "Error: out of memory\n");
            free(message);
            break;
        }

        list->messages[list->count++] = *message;
    }

    sqlite3_finalize(stmt);
    return rc;
}

// Function to create and populate a list of LTE NAS messages
int generate_nas_messages(sqlite3 *db, nas_message_list *list) {
    int rc = SQLITE_OK;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Fetch UE IDs and IMSIs from the external database
    rc = get_ue_ids(db, list);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error while fetching UE IDs: %s\n", sqlite3_errmsg(db));
        return rc;
    }

    // Generate a random S-TMSI for each message
    for (int i = 0; i < list->count; i++) {
        struct nas_message *message = &list->messages[i];
        message->s_tmsi = (uint32_t)(rand() % INT32_MAX);
    }

    // Ensure thread safety when accessing the list of messages concurrently
    pthread_mutex_lock(&lock);

    // Handle potential inconsistencies between generated messages and data from external database
    for (int i = 0; i < list->count; i++) {
        struct nas_message *message = &list->messages[i];
        if (!get_ue_id(db, message->ue_id)) {
            fprintf(stderr, "Error: UE ID not found in database\n");
            break;
        }
    }

    pthread_mutex_unlock(&lock);

    return rc;
}
