function getElementList(root, selector, testElement) {
    const elements = [];

    // Recursively traverse the DOM tree starting from the root node
    traverseDOMTree(root, (node) => {
        if (matchesSelector(node, selector)) {
            elements.push(node);
        }
    });

    return elements;
}

function matchesSelector(element, selector) {
    // Use a provided callback function to test the element's class or ID
    return testElement(element);
}

function traverseDOMTree(root, visitor) {
    if (root.nodeType === Node.ELEMENT_NODE && visitor(root)) {
        for (let i = 0; i < root.childNodes.length; i++) {
            traverseDOMTree(root.childNodes[i], visitor);
        }
    }
}
