// C# class for generating random values within a specified range using UnityEngine.Random.Range
public class RandomValueGenerator {
    private int minimum;
    private int maximum;

    public RandomValueGenerator(int minimum, int maximum) {
        this.minimum = minimum;
        this.maximum = maximum;
    }

    public float NextFloat() {
        return UnityEngine.Random.Range(this.minimum, this.maximum);
    }

    public int NextInt() {
        return UnityEngine.Random.Range(this.minimum, this.maximum + 1);
    }
