// C function for establishing a connection to a remote address using TCP socket channel and handling connection state changes
void ConnectToRemoteAddress(const char* remoteAddress) {
    // Create a new TCP socket channel
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return;
    }

    // Set the IP address and port number of the remote address to connect to
    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    inet_pton(AF_INET, remoteAddress, &serverAddr.sin_addr);
    serverAddr.sin_port = htons(80); // Default port number for HTTP requests

    // Connect to the remote address using the TCP socket channel
    if (connect(sock, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("connect failed");
        return;
    }

    // Handle connection state changes
    char buffer[1024];
    while (true) {
        ssize_t readBytes = recv(sock, buffer, sizeof(buffer), 0);
        if (readBytes < 0) {
            perror("recv failed");
            break;
        } else if (readBytes == 0) {
            printf("Connection closed by remote address\n");
            break;
        } else {
            // Handle received data
        }
    }

    close(sock);
}

