  // Extract the id, name, email, and password fields from the request
  int id = json_get_int(req, "id");
  const char* name = json_get_string(req, "name");
  const char* email = json_get_string(req, "email");
  const char* password = json_get_string(req, "password");

  // Check if the request is valid
  if (id < 0 || !name || !email || !password) {
    return -2;
  }

  // Open a connection to the database
  sqlite3* db = sqlite3_open("users.db", NULL);
  if (!db) {
    return -3;
  }

  // Create a new user account or update an existing one
  int result = -1;
  if (id >= 0) {
    char* query = "UPDATE users SET name=?, email=?, password=? WHERE id=?";
    sqlite3_stmt* stmt = sqlite3_prepare_v2(db, query, -1, NULL);
    if (!stmt) {
      return -4;
    }
    sqlite3_bind_text(stmt, 1, name, strlen(name), SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, email, strlen(email), SQLITE_STATIC);
    sqlite3_bind_text(stmt, 3, password, strlen(password), SQLITE_STATIC);
    sqlite3_bind_int(stmt, 4, id);
    result = sqlite3_step(stmt);
  } else {
    char* query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
    sqlite3_stmt* stmt = sqlite3_prepare_v2(db, query, -1, NULL);
    if (!stmt) {
      return -5;
    }
    sqlite3_bind_text(stmt, 1, name, strlen(name), SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, email, strlen(email), SQLITE_STATIC);
    sqlite3_bind_text(stmt, 3, password, strlen(password), SQLITE_STATIC);
    result = sqlite3_step(stmt);
  }

  // Close the database connection
  sqlite3_close(db);

  // Return a JSON response based on the result of the query
  if (result == SQLITE_OK) {
    return json_encode("{'message': 'success'}");
  } else {
    return json_encode("{'message': 'error', 'error': -4}");
  }
}

