// Define the connection pool structure
typedef struct {
    int size; // The number of connections in the pool
    int num_active; // The number of active connections
    int *active; // Array of active connections
    int *idle; // Array of idle connections
} ConnectionPool;

// Define the function to establish and manage a connection pool
void connection_pool_init(ConnectionPool *pool) {
    // Initialize the pool structure
    memset(pool, 0, sizeof(ConnectionPool));

    // Create an array for active connections
    pool->active = (int*)malloc(sizeof(int) * INITIAL_CONNECTIONS);
    if (!pool->active) {
        fprintf(stderr, "Failed to allocate memory for active connections\n");
        exit(1);
    }

    // Create an array for idle connections
    pool->idle = (int*)malloc(sizeof(int) * INITIAL_CONNECTIONS);
    if (!pool->idle) {
        fprintf(stderr, "Failed to allocate memory for idle connections\n");
        exit(1);
    }
}

// Define the function to add a connection to the pool
void connection_pool_add(ConnectionPool *pool) {
    // Check if there are any available connections in the pool
    if (pool->num_active < INITIAL_CONNECTIONS) {
        int new_connection = socket(AF_INET, SOCK_STREAM, 0);
        if (new_connection == -1) {
            fprintf(stderr, "Failed to create new connection\n");
            exit(1);
        }

        // Add the new connection to the pool of active connections
        pool->active[pool->num_active++] = new_connection;
    } else {
        // If there are no available connections, add the new connection to the pool of idle connections
        pool->idle[pool->size++] = socket(AF_INET, SOCK_STREAM, 0);
    }
}

// Define the function to remove a connection from the pool
void connection_pool_remove(ConnectionPool *pool, int connection) {
    // Check if the connection is active or idle
    if (connection == -1) {
        fprintf(stderr, "Invalid connection\n");
        exit(1);
    } else if (connection < pool->num_active) {
        // If the connection is active, remove it from the array of active connections
        memmove(&pool->active[connection], &pool->active[connection + 1], (pool->size - (connection + 1)) * sizeof(int));
        pool->num_active--;
    } else {
        // If the connection is idle, remove it from the array of idle connections
        memmove(&pool->idle[connection], &pool->idle[connection + 1], (pool->size - (connection + 1)) * sizeof(int));
        pool->size--;
    }
}

// Define the function to get a connection from the pool
int connection_pool_get(ConnectionPool *pool) {
    // Check if there are any available connections in the pool
    if (pool->num_active > 0) {
        // If there are active connections, return one of them
        return pool->active[--pool->num_active];
    } else if (pool->size > 0) {
        // If there are no active connections but there are idle connections, return one of them
        int connection = pool->idle[--pool->size];
        memmove(&pool->idle[connection], &pool->idle[connection + 1], (pool->size - (connection + 1)) * sizeof(int));
        return connection;
    } else {
        // If there are no connections in the pool, create a new one and add it to the array of active connections
        int new_connection = socket(AF_INET, SOCK_STREAM, 0);
        if (new_connection == -1) {
            fprintf(stderr, "Failed to create new connection\n");
            exit(1);
        }

        pool->active[pool->num_active++] = new_connection;
        return new_connection;
    }
}

// Define the function to release a connection back to the pool
void connection_pool_release(ConnectionPool *pool, int connection) {
    // Check if the connection is active or idle
    if (connection == -1) {
        fprintf(stderr, "Invalid connection\n");
        exit(1);
    } else if (connection < pool->num_active) {
        // If the connection is active, add it to the array of idle connections
        memmove(&pool->idle[pool->size++], &pool->active[connection], sizeof(int));
    } else {
        fprintf(stderr, "Invalid connection\n");
        exit(1);
    }
}
