```javascript
const traverseDOM = (element, selector) => {
    // Check if the element matches the selector
    if (matches(element, selector)) {
        return [element];
    }

    // Recursively traverse the children of the element
    let children = [];
    for (let i = 0; i < element.childNodes.length; i++) {
        children = children.concat(traverseDOM(element.childNodes[i], selector));
    }

    return children;
};

const matches = (element, selector) => {
    // Check if the element matches the selector
    if (element.tagName === selector) {
        return true;
    }

    // Check if the element has any matching attributes
    let found = false;
    for (let attribute in selector) {
        if (attribute !== 'tagName') {
            if (selector[attribute] === element.getAttribute(attribute)) {
                found = true;
                break;
            }
        }
    }

    return found;
};
```
