// Function to establish a connection to a remote address using TCP sockets
int establish_connection(char* hostname, char* port) {
  // Check if there is an existing connection in the pool that has not timed out
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    if (connections[i] != NULL && connections[i]->timestamp > time(NULL) - CONN_TIMEOUT) {
      // Return an existing connection from the pool
      return i;
    }
  }

  // If there is no available connection, create a new one and add it to the pool
  struct sockaddr_in server_address;
  int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (socket_fd < 0) {
    printf("Error creating socket: %s\n", strerror(errno));
    return -1;
  }

  server_address.sin_family = AF_INET;
  server_address.sin_port = htons(atoi(port));
  if (inet_pton(AF_INET, hostname, &server_address.sin_addr) <= 0) {
    printf("Error resolving hostname: %s\n", strerror(errno));
    return -1;
  }

  int connect_status = connect(socket_fd, (struct sockaddr*)&server_address, sizeof(server_address));
  if (connect_status < 0) {
    printf("Error connecting to server: %s\n", strerror(errno));
    close(socket_fd);
    return -1;
  }

  // Add the new connection to the pool
  connections[i] = (struct socket*)malloc(sizeof(struct socket));
  if (connections[i] == NULL) {
    printf("Error allocating memory for connection: %s\n", strerror(errno));
    close(socket_fd);
    return -1;
  }

  connections[i]->socket_fd = socket_fd;
  connections[i]->timestamp = time(NULL);
  printf("New connection established with host %s and port %s\n", hostname, port);
  return i;
}

// Function to handle connection state changes
void handle_connection_state_changes() {
  // Check if there are any connections that have timed out
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    if (connections[i] != NULL && connections[i]->timestamp <= time(NULL) - CONN_TIMEOUT) {
      // Close the connection and remove it from the pool
      close(connections[i]->socket_fd);
      free(connections[i]);
      connections[i] = NULL;
    }
  }
}

// Function to allocate memory for and initialize two arrays: one for 'long' offset values and one for 'int' keys
