            printf("Error: unable to open file %s\n", file_name[i]);
            continue;
        }
        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        rewind(file);
        buffer = malloc(size + 1);
        if (!buffer) {
            printf("Error: unable to allocate memory for file %s\n", file_name[i]);
            fclose(file);
            continue;
        }
        size = fread(buffer, sizeof(char), size, file);
        buffer[size] = '\0';
