        if (strcmp(file_name[i], "json") == 0) {
            json_t *root = json_parse(buffer, size);
            if (!root) {
                printf("Error: unable to parse JSON file %s\n", file_name[i]);
                continue;
            }
            // populate offset array with offsets from JSON data
