struct DataEntry {
    std::string key;
    std::string value;
};

class DataManager {
public:
    void insert(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        dataMap_[key] = value;
    }

    std::optional<DataEntry> query(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = dataMap_.find(key);
        if (it == dataMap_.end()) {
            return {};
        }
        return DataEntry{key, it->second};
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        dataMap_.erase(key);
    }

private:
    std::map<std::string, std::string> dataMap_;
    std::mutex mutex_;
};

class DataManagerPool {
public:
    void insert(const std::string& key, const std::string& value) {
        for (auto& manager : managers_) {
            manager.insert(key, value);
        }
    }

    std::optional<DataEntry> query(const std::string& key) {
        for (auto& manager : managers_) {
            auto result = manager.query(key);
            if (result) {
                return result;
            }
        }
        return {};
    }

    void remove(const std::string& key) {
        for (auto& manager : managers_) {
            manager.remove(key);
        }
    }

    void addManager(std::shared_ptr<DataManager> manager) {
        managers_.push_back(manager);
    }

private:
    std::vector<std::shared_ptr<DataManager>> managers_;
};

class DataSyncService {
public:
    void sync() {
        for (auto& manager : managers_) {
            manager->sync();
        }
    }

    void addManager(std::shared_ptr<DataManager> manager) {
        managers_.push_back(manager);
    }

private:
    std::vector<std::shared_ptr<DataManager>> managers_;
};
