    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file %s\n", input_file);
        return;
    }

    // Read the metadata from the CSV file and store it in an array
    char **metadata = malloc(sizeof(char *) * 1000);
    int num_records = 0;
    while (fscanf(fp, "%s", metadata[num_records]) != EOF) {
        num_records++;
    }
    fclose(fp);

    // Allocate memory for the arrays and initialize them
    long *offset_array = malloc(sizeof(long) * num_records);
    int *key_array = malloc(sizeof(int) * num_records);
    double *value_array = malloc(sizeof(double) * num_records);
    char **string_array = malloc(sizeof(char *) * num_records);
    data_record *data = malloc(sizeof(data_record) * num_records);

    for (int i = 0; i < num_records; i++) {
        // Generate random values within the specified ranges for the record's key and value
        int key = min_key + rand() % (max_key - min_key + 1);
        double value = min_value + ((double)rand()) / (RAND_MAX + 1.0) * (max_value - min_value);

        // Allocate memory for the string field and initialize it with a unique identifier
        char *string = malloc(sizeof(char) * strlen(metadata[i]) + 1);
        strcpy(string, metadata[i]);

        // Allocate memory for the metadata array and initialize it with the appropriate size
        int metadata_size = strlen(metadata[i]) + 1;
        char **metadata_array = malloc(sizeof(char *) * metadata_size);
        for (int j = 0; j < metadata_size; j++) {
            metadata_array[j] = malloc(sizeof(char) * strlen(metadata[i]) + 1);
            strcpy(metadata_array[j], metadata[i]);
        }

        // Initialize the record with the generated values and metadata
        data[i].key = key;
        data[i].value = value;
        data[i].string = string;
        data[i].metadata = metadata_array;
    }

    // Free the memory allocated for the arrays and close the input file
    free(offset_array);
    free(key_array);
    free(value_array);
    free(string_array);
    free(data);
    fclose(fp);
}
