        return;
    }

    // Retry logic with exponential backoff for temporary network issues
    int retry_count = 0;
    while (retry_count < MAX_RETRY) {
        if (fscanf(csv_file, "%d %lf", &points[i].value, &points[i].identifier) == EOF) {
            fprintf(stderr, "Failed to read from CSV file: %s\n", strerror(errno));
            retry_count++;
