#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Linked list node structure
struct Node {
  int value;
  struct Node* next;
};

// Global mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize memory for a linked list of nodes
struct Node* createList(int numNodes, int initValue) {
  // Allocate memory for the linked list
  struct Node* head = (struct Node*) malloc(sizeof(struct Node));
  if (!head) {
    perror("Error allocating memory for linked list");
    return NULL;
  }

  // Initialize the first node with the specified integer value
  head->value = initValue;
  head->next = NULL;

  // Allocate memory for additional nodes and link them together
  struct Node* currNode = head;
  for (int i = 1; i < numNodes; i++) {
    pthread_mutex_lock(&mutex);
    struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
    if (!newNode) {
      perror("Error allocating memory for linked list node");
      freeList(head);
      return NULL;
    }
    currNode->next = newNode;
    currNode = newNode;
    pthread_mutex_unlock(&mutex);
  }

  // Return the head of the linked list
  return head;
}

// Function to free memory for a linked list of nodes
void freeList(struct Node* head) {
  if (!head) {
    return;
  }

  struct Node* currNode = head;
  while (currNode->next != NULL) {
    pthread_mutex_lock(&mutex);
    struct Node* nextNode = currNode->next;
    free(currNode);
    currNode = nextNode;
    pthread_mutex_unlock(&mutex);
  }
  free(head);
}
