#include <stdlib.h>
#include <stdio.h>

// Structure to represent a node in the linked list
struct Node {
  int value;
  struct Node* next;
};

// Function to dynamically allocate memory for and initialize a new node
struct Node* create_node(int value) {
  // Allocate memory for the new node
  struct Node* new_node = malloc(sizeof(struct Node));

  if (new_node == NULL) {
    printf("Error: unable to allocate memory for a new node\n");
    return NULL;
  }

  // Initialize the value of the new node
  new_node->value = value;
  new_node->next = NULL;

  return new_node;
}

// Function to free the allocated memory for a linked list
void destroy_list(struct Node* head) {
  struct Node* current = head;

  // Free the memory for each node in the list, starting from the head
  while (current != NULL) {
    struct Node* next = current->next;
    free(current);
    current = next;
  }
}

// Function to insert a new node at the beginning of the list
void insert_node(struct Node** head, int value) {
  // Create a new node with the given value
  struct Node* new_node = create_node(value);

  if (new_node == NULL) {
    printf("Error: unable to create a new node\n");
    return;
  }

  // Insert the new node at the beginning of the list
  new_node->next = *head;
  *head = new_node;
}

// Function to traverse and print the values of all nodes in the list
void traverse_list(struct Node* head) {
  struct Node* current = head;

  // Traverse the list and print the values of each node
  while (current != NULL) {
    printf("%d\n", current->value);
    current = current->next;
  }
}

// Function to search for a specific value within the list
struct Node* find_node(struct Node* head, int value) {
  struct Node* current = head;

  // Search for the given value in the list
  while (current != NULL) {
    if (current->value == value) {
      return current;
    }
    current = current->next;
  }

  return NULL;
}
```
