// Structures to represent nodes and edges in the graph
struct node {
    int id;
    struct node* next;
};

struct edge {
    int weight;
    struct node* from;
    struct node* to;
};

// Function to dynamically allocate memory for a graph structure
// with up to 10,000 nodes and 50,000 edges
struct graph* allocate_graph() {
    // Allocate memory for the node array
    struct node** nodes = malloc(sizeof(struct node*) * 10000);
    if (nodes == NULL) {
        return NULL;
    }

    // Allocate memory for the edge array
    struct edge** edges = malloc(sizeof(struct edge*) * 50000);
    if (edges == NULL) {
        free(nodes);
        return NULL;
    }

    // Initialize the node and edge arrays with NULL pointers
    for (int i = 0; i < 10000; i++) {
        nodes[i] = NULL;
    }
    for (int j = 0; j < 50000; j++) {
        edges[j] = NULL;
    }

    // Allocate memory for the graph structure
    struct graph* graph = malloc(sizeof(struct graph));
    if (graph == NULL) {
        free(nodes);
        free(edges);
        return NULL;
    }

    // Initialize the graph structure with pointers to the node and edge arrays
    graph->nodes = nodes;
    graph->edges = edges;

    // Return the graph structure
    return graph;
}

// Function to validate the integrity of a graph structure
// by checking that all pointers are correctly set up
void validate_graph(struct graph* graph) {
    // Check that each node is pointed to by at least one edge
    for (int i = 0; i < 10000; i++) {
        if (graph->nodes[i] == NULL) {
            continue;
        }
        bool found_edge = false;
        for (int j = 0; j < 50000; j++) {
            if (graph->edges[j]->from == graph->nodes[i]) {
                found_edge = true;
                break;
            }
        }
        if (!found_edge) {
            printf("Node %d is not pointed to by any edge\n", i);
        }
    }

    // Check that each edge points to two different nodes
    for (int j = 0; j < 50000; j++) {
        if (graph->edges[j] == NULL) {
            continue;
        }
        struct node* first_node = graph->edges[j]->from;
        struct node* second_node = graph->edges[j]->to;
        if (first_node == second_node) {
            printf("Edge %d points to the same node\n", j);
        } else if (first_node < second_node) {
            if (!(graph->nodes[first_node] && graph->nodes[second_node])) {
                printf("Edge %d points to nonexistent nodes\n", j);
            }
        } else {
            if (!(graph->nodes[second_node] && graph->nodes[first_node])) {
                printf("Edge %d points to nonexistent nodes\n", j);
            }
        }
    }
}

// Function to free the memory allocated for a graph structure
void free_graph(struct graph* graph) {
    // Free the node and edge arrays
    free(graph->nodes);
    free(graph->edges);

    // Free the graph structure itself
    free(graph);
}
