        if (entries[i].offset != entries[i + 1].offset || entries[i].key != entries[i + 1].key) {
            printf("Inconsistency detected: Offset %ld, Key %d\n", entries[i].offset, entries[i].key);
        }
    }
}

void free_resources(data_entry* entries, int count) {
    for (int i = 0; i < count; ++i) {
        free(entries[i].data);
    }
    free(entries);
}
