int add_ue_context(char *imsi, int num_active_bearers, char **qos_params, char **rb_ids) {
    if (num_active_bearers > MAX_NUM_RADIO_BEARERS) {
        // Error: Number of active bearers exceeds maximum allowed value
        return -1;
