int remove_ue_context(char *imsi) {
    for (int i = 0; i < get_size(ue_contexts); i++) {
        if (strcmp(((UEContext *) get_from_list(ue_contexts, i))->imsi, imsi) == 0) {
            // Remove the UE context from the list
            remove_from_list(ue_contexts, i);
            return 0;
        }
    }

    // Error: Could not find UE context with IMSI
    return -1;
}

// Update an existing UE context in the list
int update_ue_context(char *imsi, int num_active_bearers, char **qos_params, char **rb_ids) {
    for (int i = 0; i < get_size(ue_contexts); i++) {
        if (strcmp(((UEContext *) get_from_list(ue_contexts, i))->imsi, imsi) == 0) {
            UEContext *ue_context = ((UEContext *) get_from_list(ue_contexts, i));
            ue_context->num_active_bearers = num_active_bearers;

            for (int j = 0; j < num_active_bearers; j++) {
                ue_context->active_bearers[j].qos_params = qos_params[j];
                ue_context->active_bearers[j].rb_id = rb_ids[j];
            }

            return 0;
        }
    }

    // Error: Could not find UE context with IMSI
    return -1;
}

// Get the UE context for a given IMSI
UEContext *get_ue_context(char *imsi) {
    for (int i = 0; i < get_size(ue_contexts); i++) {
        if (strcmp(((UEContext *) get_from_list(ue_contexts, i))->imsi, imsi) == 0) {
            return ((UEContext *) get_from_list(ue_contexts, i));
        }
    }

    // Error: Could not find UE context with IMSI
    return NULL;
}

// Free the memory of the list of UE contexts
void free_ue_contexts() {
    while (get_size(ue_contexts) > 0) {
        UEContext *ue_context = ((UEContext *) get_from_list(ue_contexts, 0));
        remove_from_list(ue_contexts, 0);
        free(ue_context->imsi);
        for (int i = 0; i < ue_context->num_active_bearers; i++) {
            free(ue_context->active_bearers[i].qos_params);
            free(ue_context->active_bearers[i].rb_id);
        }
    }
}
