#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef struct {
    int key;
} record;

void handle_connection(int sockfd) {
    // Allocate memory for offset and key arrays
    long *offset_array = (long *) malloc(sizeof(long) * 10);
    int *key_array = (int *) malloc(sizeof(int) * 10);
    record *records = (record *) malloc(sizeof(record) * 10);

    // Initialize arrays with random values within a given range
    for (int i = 0; i < 10; i++) {
        offset_array[i] = rand() % 1000;
        key_array[i] = rand() % 1000;
        records[i].key = rand() % 1000;
    }

    // Handle connection state changes using a loop
    while (true) {
        char buffer[256];

        // Read from the socket
        int bytes_read = read(sockfd, buffer, sizeof(buffer));

        if (bytes_read < 0) {
            perror("Error reading from socket");
            break;
        } else if (bytes_read == 0) {
            printf("Socket closed\n");
            break;
        }

        // Process the data received from the server
        for (int i = 0; i < bytes_read; i++) {
            switch (buffer[i]) {
                case 'A':
                    printf("Pokemon name: %s\n", get_pokemon_name(key_array[i]));
                    break;
                case 'B':
                    printf("Pokemon weaknesses: %s\n", get_weaknesses(key_array[i]));
                    break;
            }
        }

        // Retry the connection with exponential backoff if it fails
        if (bytes_read < 0) {
            printf("Error reading from socket, retrying in %d seconds...\n", EXPONENTIAL_BACKOFF);
            sleep(EXPONENTIAL_BACKOFF);
        }
    }

    // Free memory allocated for offset and key arrays
    free(offset_array);
    free(key_array);

    // Close the socket
    close(sockfd);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return EXIT_FAILURE;
    }

    // Connect to the remote server using a Unix socket channel
    struct sockaddr_in serv_addr = {
        .sin_family = AF_INET,
        .sin_port = htons(PORT),
        .sin_addr = inet_addr(SERVER_IP)
    };

    if (connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error connecting to socket");
        return EXIT_FAILURE;
    }

    // Handle the connection in a separate thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, handle_connection, sockfd) < 0) {
        perror("Error creating thread");
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
