    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    record_t* records = malloc(num_records * sizeof(record_t));

    // Initialize each record with a random value within the given range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
    }

    // Handle allocation failures gracefully by printing an error message and returning
    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        return;
    }

    // Log memory allocation and initialization steps for debugging and monitoring
    printf("Allocated %lu bytes for offsets\n", offset_size * sizeof(long));
    printf("Allocated %lu bytes for keys\n", key_size * sizeof(int));
    printf("Allocated %lu bytes for records\n", num_records * sizeof(record_t));
    printf("Initialized each record with a random value within the range [%d, %d]\n", min_value, max_value);
}
