void readDirectory(const char* dir_path) {
    // Check if the directory exists in the environment variable
    const char* env_dir_path = getenv("DIR_PATH");
    if (env_dir_path == NULL || strcmp(env_dir_path, dir_path) != 0) {
        // Create a new directory and set the environment variable to the path of the directory
        char* new_dir_path = createDirectory(dir_path);
        if (new_dir_path == NULL) {
            fprintf(stderr, "Error: Failed to create directory\n");
            return;
        }
        setenv("DIR_PATH", new_dir_path, 1);
    }

    // Open the directory and iterate through each file in it
    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        fprintf(stderr, "Error: Failed to open directory\n");
        return;
    }
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file has a specific extension
        const char* ext = strrchr(entry->d_name, '.');
        if (ext == NULL || strcmp(ext, ".txt") != 0 && strcmp(ext, ".log") != 0 && strcmp(ext, ".csv") != 0) {
            continue;
        }

        // Allocate memory for the record and initialize it with random data
        Record* new_record = malloc(sizeof(Record));
        if (new_record == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record\n");
            continue;
        }
        new_record->filename = entry->d_name;
        new_record->extension = ext;
        records[num_records++] = new_record;
    }
}

// Define a function to create a new directory
char* createDirectory(const char* dir_path) {
    // Check if the directory already exists
    struct stat st;
    if (stat(dir_path, &st) == 0) {
        return NULL;
    }

    // Create the directory and set its permissions
    int rc = mkdir(dir_path, S_IRWXU | S_IRGRP | S_IXGRP);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to create directory\n");
        return NULL;
    }

    // Return the path of the new directory
    return dir_path;
}
