```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Record structure for storing double values
typedef struct {
    double value;
} record_t;

int main() {
    // Set the range of random values
    long lower_bound = 0;
    long upper_bound = 100;

    // Allocate memory for the offset array
    long *offsets = malloc(sizeof(long) * 10);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return -1;
    }

    // Allocate memory for the key array
    int *keys = malloc(sizeof(int) * 10);
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return -1;
    }

    // Allocate memory for the record array
    record_t *records = malloc(sizeof(record_t) * 10);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }

    // Initialize the arrays with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        offsets[i] = lower_bound + rand() % (upper_bound - lower_bound);
        keys[i] = lower_bound + rand() % (upper_bound - lower_bound);
        records[i].value = lower_bound + rand() % (upper_bound - lower_bound);
    }

    // Loop to set the value of each record's double field to a random value within the given range
    for (int i = 0; i < 10; i++) {
        records[i].value = lower_bound + rand() % (upper_bound - lower_bound);
    }

    // Free memory allocated for the arrays and the record array
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
