            exit(1);
        }
    }

    // Sort the floating-point numbers in ascending order before finding the largest number
    qsort(arr, size, sizeof(float), compare_floats);

    // Find the largest number in the sorted array
    largest = find_largest(size, arr);
    printf("Largest number after sorting: %f\n", largest);

    // Calculate and print statistics such as mean, median, and standard deviation of the floating-point numbers
