// Compare two floating-point numbers and return -1, 0, or 1 depending on whether the first number is smaller, equal to, or larger than the second number
int compare_floats(const void* a, const void* b) {
    float f1 = *(const float*)a;
    float f2 = *(const float*)b;
    if (f1 < f2) return -1;
    else if (f1 > f2) return 1;
    else return 0;
}

// Calculate the mean of an array of floating-point numbers
float calculate_mean(float* arr, int size) {
    float sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += arr[i];
    }
    return sum / size;
}

// Calculate the median of an array of floating-point numbers
float calculate_median(float* arr, int size) {
    qsort(arr, size, sizeof(float), compare_floats);
    if (size % 2 == 0) return ((float)arr[size / 2 - 1] + (float)arr[size / 2]) / 2;
    else return (float)arr[size / 2];
}

// Calculate the standard deviation of an array of floating-point numbers
float calculate_stddev(float* arr, int size) {
    float mean = calculate_mean(arr, size);
    float sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += pow((arr[i] - mean), 2);
    }
    return sqrt(sum / size);
}
