        (*ints)[i] = rand() % (INT_MAX - INT_MIN) + INT_MIN;
        (*vectors)[i].x = rand() % (max_range - min_range + 1) + min_range;
        (*vectors)[i].y = rand() % (max_range - min_range + 1) + min_range;
    }
}

// Function to free the allocated memory for arrays of doubles, ints, and vectors
