['```
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <openssl/ssl.h>
#include <pthread.h>

// Structure to represent a network server context
struct NetworkServerContext {
    char *hostname; // Valid hostname of the server
    int port; // Port number for the server
    SSL_CTX *ssl_ctx; // SSL/TLS context for secure connections
    pthread_mutex_t mutex; // Mutex for thread-safe access to the server context
    struct ListNode *connections; // List of active client connections
};

// Structure to represent a client connection in the network server context
struct ClientConnection {
    int socket_fd; // File descriptor for the client socket
    SSL *ssl; // SSL/TLS object for secure connections
    char *ip_address; // IP address of the client
    enum ConnectionState {
        CONNECTED, // The connection is established and active
        DISCONNECTED // The connection has been closed or lost
    } state; // Current state of the connection
    int data_transmission_rate; // Data transmission rate in bytes per second
};

// Function to create a new network server context
struct NetworkServerContext *create_network_server_context(char *hostname, int port) {
    struct NetworkServerContext *ctx = malloc(sizeof(struct NetworkServerContext));
    if (!ctx) {
        return NULL; // Memory allocation failed
    }
    ctx->hostname = hostname;
    ctx->port = port;
    ctx->ssl_ctx = SSL_CTX_new(TLS_client_method()); // Create a new SSL/TLS context for secure connections
    if (!ctx->ssl_ctx) {
        free(ctx); // Release memory for the network server context
        return NULL; // SSL/TLS context creation failed
    }
    ctx->connections = NULL; // Initialize the list of active client connections as empty
    pthread_mutex_init(&ctx->mutex, NULL); // Initialize the mutex for thread-safe access to the server context
    return ctx;
}

// Function to add a new client connection to the network server context
int add_client_connection(struct NetworkServerContext *ctx, int socket_fd) {
    struct ClientConnection *conn = malloc(sizeof(struct ClientConnection));
    if (!conn) {
        return -1; // Memory allocation failed
    }
    conn->socket_fd = socket_fd;
    conn->ssl = SSL_new(ctx->ssl_ctx); // Create a new SSL/TLS object for secure connections
    if (!conn->ssl) {
        free(conn); // Release memory for the client connection
        return -1; // SSL/TLS object creation failed
    }
    conn->ip_address = malloc(INET_ADDRSTRLEN * sizeof(char)); // Allocate memory for the IP address string
    if (!conn->ip_address) {
        SSL_free(conn->ssl); // Release memory for the SSL/TLS object
        free(conn); // Release memory for the client connection
        return -1; // Memory allocation failed
    }
    conn->state = CONNECTED; // Initialize the state of the connection as connected
    conn->data_transmission_rate = 0; // Initialize the data transmission rate to zero
    struct ListNode *new_node = malloc(sizeof(struct ListNode));
    if (!new_node) {
        free(conn->ip_address); // Release memory for the IP address string
        SSL_free(conn->ssl); // Release memory for the SSL/TLS object
        free(conn); // Release memory for the client connection
        return -1; // Memory allocation failed
    }
    new_node->data = conn;
    new_node->next = NULL;
    pthread_mutex_lock(&ctx->mutex); // Acquire the mutex for thread-safe access to the server context
    struct ListNode *curr_node = ctx->connections;
    while (curr_node) {
        if (curr_node->data == conn) { // Check for duplicates
            pthread_mutex_unlock(&ctx->mutex); // Release the mutex
            free(new_node); // Release memory for the new list node
            return 0; // Connection already exists, do nothing
        }
        curr_node = curr_node->next;
    }
    if (ctx->connections) {
        curr_node = ctx->connections;
        while (curr_node->next) {
            curr_node = curr_node->next;
        }
        curr_node->next = new_node; // Add the new list node to the end of the list
    } else {
        ctx->connections = new_node; // Initialize the list with the first element
    }
    pthread_mutex_unlock(&ctx->mutex); // Release the mutex
    return 0; // Connection added successfully
}

// Function to remove a client connection from the network server context
int remove_client_connection(struct NetworkServerContext *ctx, int socket_fd) {
    struct ListNode *curr_node = ctx->connections;
    while (curr_node) {
        if (curr_node->data->socket_fd == socket_fd) { // Find the list node for the client connection
            pthread_mutex_lock(&ctx->mutex); // Acquire the mutex for thread-safe access to the server context
            struct ListNode *prev_node = curr_node;
            while (curr_node && curr_node->data->socket_fd != socket_fd) {
                prev_node = curr_node;
                curr_node = curr_node->next;
            }
            if (curr_node) { // Remove the list node from the linked list
                struct ListNode *next_node = curr_node->next;
                free(curr_node->data); // Release memory for the client connection
                free(curr_node); // Release memory for the list node
                prev_node->next = next_node;
            }
            pthread_mutex_unlock(&ctx->mutex); // Release the mutex
            return 0; // Connection removed successfully
        } else {
            curr_node = curr_node->next;
        }
    }
    return -1; // Connection not found, do nothing
}

// Function to update the data transmission rate of a client connection in the network server context
void update_data_transmission_rate(struct NetworkServerContext *ctx, int socket_fd, int new_rate) {
    struct ListNode *curr_node = ctx->connections;
    while (curr_node) {
        if (curr_node->data->socket_fd == socket_fd) { // Find the list node for the client connection
            curr_node->data->data_transmission_rate = new_rate; // Update the data transmission rate of the client connection
            break;
        } else {
            curr_node = curr_node->next;
        }
    }
}

// Function to check if a client connection exists in the network server context
int client_connection_exists(struct NetworkServerContext *ctx, int socket_fd) {
    struct ListNode *curr_node = ctx->connections;
    while (curr_node) {
        if (curr_node->data->socket_fd == socket_fd) { // Find the list node for the client connection
            return 1;
        } else {
            curr_node = curr_node->next;
        }
    }
    return 0;
}

// Function to retrieve a pointer to a client connection in the network server context
struct ClientConnection *get_client_connection(struct NetworkServerContext *ctx, int socket_fd) {
    struct ListNode *curr_node = ctx->connections;
    while (curr_node) {
        if (curr_node->data->socket_fd == socket_fd) { // Find the list node for the client connection
            return curr_node->data;
        } else {
            curr_node = curr_node->next;
        }
    }
    return NULL;
}']

