void handleGetRequest(Session *sessions, size_t num_sessions) {
    // Initialize variables for HTTP request and response headers
    char request[1024];
    memset(&request, 0, sizeof(request));
    int response_code = 0;

    // Create socket file descriptor and establish connection with server
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
