    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);
    connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));

    // Send HTTP GET request and receive response
    send(sockfd, REQUEST_HEADER, strlen(REQUEST_HEADER), 0);
    recv(sockfd, &response_code, 4, 0);
    if (response_code != 200) {
        printf("HTTP GET request failed: %d\n", response_code);
        close(sockfd);
        return;
    }

    // Process HTTP response and extract session metadata
    char response[1024];
    memset(&response, 0, sizeof(response));
    recv(sockfd, &response, 1024, 0);
    printf("HTTP GET response: %s\n", response);
    close(sockfd);

    // Manage session metadata and query list of sessions for specific user ID or permission ID
    manageSessions(&sessions, num_sessions);
}

// Define main function to handle HTTP GET requests and manage session metadata concurrently
int main(void) {
    // Initialize variables for session metadata and number of active sessions
    Session *sessions = NULL;
    size_t num_sessions = 0;

    // Handle HTTP GET requests using non-blocking I/O
    handleGetRequest(sessions, num_sessions);

    // Close socket file descriptor and free memory for session metadata
    close(sockfd);
    free(sessions);

    return 0;
}
