    while (fgets(line, sizeof(line), file) != NULL) {
        char *token = strtok(line, ",");
        entries[i].val = atof(token);
        token = strtok(NULL, ",");
        entries[i].str = malloc(sizeof(char) * (strlen(token) + 1));
        strcpy(entries[i].str, token);
