#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

// Define constants for array sizes and data types
#define NUM_OFFSETS 3
#define NUM_KEYS 3
#define NUM_RECORDS 10
#define RECORD_SIZE sizeof(double) + sizeof(char*)
#define MAX_BUFFER_SIZE (NUM_RECORDS * RECORD_SIZE)
#define KEY_TYPE int
#define OFFSET_TYPE long
#define DATA_TYPE double

// Define structures for records and offsets
struct record {
    DATA_TYPE value;
    char* string;
};
struct offset {
    OFFSET_TYPE offset;
    KEY_TYPE key;
};

// Define functions to manage arrays and connections
void initArrays(struct offset** offsets, struct record** records) {
    // Initialize arrays with NULL pointers
    *offsets = malloc(NUM_OFFSETS * sizeof(struct offset));
    *records = malloc(NUM_RECORDS * sizeof(struct record));
}
void freeArrays(struct offset* offsets, struct record* records) {
    // Free memory allocated to arrays
    free(offsets);
    free(records);
}
int connectToServer(const char* serverAddress, const char* portNumber) {
    // Connect to remote address using TCP sockets
    int socketFd = socket(AF_INET, SOCK_STREAM, 0);
    if (socketFd == -1) {
        perror("socket");
        return EXIT_FAILURE;
    }
    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(atoi(portNumber));
    if (inet_pton(AF_INET, serverAddress, &serverAddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", serverAddress);
        close(socketFd);
        return EXIT_FAILURE;
    }
    if (connect(socketFd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("connect");
        close(socketFd);
        return EXIT_FAILURE;
    }
    return socketFd;
}
int sendData(int socketFd, char* buffer, size_t bufferSize) {
    // Send data to remote address using TCP sockets
    if (send(socketFd, buffer, bufferSize, 0) < 0) {
        perror("send");
        close(socketFd);
        return EXIT_FAILURE;
    }
    return socketFd;
}
int receiveData(int socketFd, char* buffer, size_t bufferSize) {
    // Receive data from remote address using TCP sockets
    if (recv(socketFd, buffer, bufferSize, 0) < 0) {
        perror("receive");
        close(socketFd);
        return EXIT_FAILURE;
    }
    return socketFd;
}
int disconnectFromServer(int socketFd) {
    // Disconnect from remote address using TCP sockets
    if (close(socketFd) < 0) {
        perror("close");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

// Define functions to handle record insertion and retrieval
int insertRecord(struct offset* offsets, struct record** records, DATA_TYPE value, const char* string) {
    // Insert new record into existing dataset without reallocating memory unnecessarily
    if (offsets->offset + 1 >= NUM_OFFSETS || records[offsets->offset].value != value) {
        fprintf(stderr, "Cannot insert record with key %d\n", value);
        return EXIT_FAILURE;
    }
    offsets->key++;
    records[offsets->offset].value = value;
    records[offsets->offset].string = string;
    offsets->offset++;
    return EXIT_SUCCESS;
}
int searchRecordByKey(struct offset* offsets, struct record** records, KEY_TYPE key) {
    // Search for record by key within specified range
    int i;
    for (i = 0; i < NUM_RECORDS; i++) {
        if (records[i].value == key) {
            return i;
        }
    }
    fprintf(stderr, "Record with key %d not found\n", key);
    return EXIT_FAILURE;
}
int searchRecordByOffset(struct offset* offsets, struct record** records, OFFSET_TYPE offset) {
    // Search for record by offset within specified range
    int i;
    for (i = 0; i < NUM_RECORDS; i++) {
        if (offsets->offset == offset) {
            return i;
        }
    }
    fprintf(stderr, "Record with offset %ld not found\n", offset);
    return EXIT_FAILURE;
}

// Define functions to manage buffer sizes and optimize data copying operations
int setBufferSize(size_t* bufferSize) {
    // Set buffer size based on maximum record size
    *bufferSize = MAX_BUFFER_SIZE;
    return EXIT_SUCCESS;
}
int copyDataToBuffer(struct record* records, char* buffer, size_t bufferSize) {
    // Copy data from records to buffer
    int i;
    for (i = 0; i < NUM_RECORDS; i++) {
        memcpy(&buffer[i * sizeof(struct record)], &records[i], sizeof(struct record));
    }
    return EXIT_SUCCESS;
}
int copyDataFromBuffer(char* buffer, struct record* records, size_t bufferSize) {
    // Copy data from buffer to records
    int i;
    for (i = 0; i < NUM_RECORDS; i++) {
        memcpy(&records[i], &buffer[i * sizeof(struct record)], sizeof(struct record));
    }
    return EXIT_SUCCESS;
}

// Define functions to handle connection and data transfer
int handleConnection(const char* serverAddress, const char* portNumber) {
    // Establish connection with remote address using TCP sockets
    int socketFd = connectToServer(serverAddress, portNumber);
    if (socketFd == EXIT_FAILURE) {
        return EXIT_FAILURE;
    }
    // Send data to remote address using TCP sockets
    char* buffer;
    size_t bufferSize;
    setBufferSize(&bufferSize);
    buffer = (char*)malloc(sizeof(char) * bufferSize);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return EXIT_FAILURE;
    }
    int result = sendData(socketFd, buffer, bufferSize);
    free(buffer);
    disconnectFromServer(socketFd);
    if (result == EXIT_FAILURE) {
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
int handleDataTransfer() {
    // Receive data from remote address using TCP sockets
    int socketFd = connectToServer("localhost", "8000");
    if (socketFd == EXIT_FAILURE) {
        return EXIT_FAILURE;
    }
    char* buffer;
    size_t bufferSize;
    setBufferSize(&bufferSize);
    buffer = (char*)malloc(sizeof(char) * bufferSize);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return EXIT_FAILURE;
    }
    int result = receiveData(socketFd, buffer, bufferSize);
    free(buffer);
    disconnectFromServer(socketFd);
    if (result == EXIT_FAILURE) {
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

// Define functions to handle record retrieval and manipulation
int retrieveRecordByKey(struct offset* offsets, struct record** records, KEY_TYPE key) {
