    return (response->status_code == status_code);
}

// Define function to parse HTTP response body as JSON object
struct JSONObject *parseJSONResponseBody(char *body) {
    // Declare variables for JSON parser and error message
    struct JSONParser json_parser;
    char *error_message = NULL;

    // Initialize JSON parser with specified HTTP response body
    if (!json_init(&json_parser, body)) {
