}

// Define function to persist entries to SQLite database
void persist_entries(struct entry* entries, int num_entries) {
    // Open SQLite database
    sqlite3* db = NULL;
    char* errmsg = NULL;
    if (sqlite3_open("/var/lib/db/data.db", &db)) {
        fprintf(stderr, "Failed to open SQLite database: %s\n", sqlite3_errmsg(db));
        return;
    }

    // Create table for entries if it doesn't exist
    char* sql = "CREATE TABLE IF NOT EXISTS entries (offset INTEGER, key TEXT, num_records INTEGER)";
    if (sqlite3_exec(db, sql, NULL, NULL, &errmsg)) {
        fprintf(stderr, "Failed to create table: %s\n", errmsg);
        sqlite3_free(errmsg);
        return;
    }

    // Insert each entry into the database
    for (int i = 0; i < num_entries; ++i) {
        struct entry* entry = &entries[i];
        char sql[1024];
        snprintf(sql, sizeof(sql), "INSERT INTO entries VALUES (%d, '%s', %d)", entry->offset, entry->key, entry->num_records);
        if (sqlite3_exec(db, sql, NULL, NULL, &errmsg)) {
            fprintf(stderr, "Failed to insert entry: %s\n", errmsg);
            sqlite3_free(errmsg);
            return;
        }
    }

    // Close SQLite database
    if (sqlite3_close(db)) {
        fprintf(stderr, "Failed to close SQLite database: %s\n", sqlite3_errmsg(db));
    }
}

// Define function to establish and manage TCP connections using non-blocking sockets
int open_socket(int* socket) {
    // Create a new non-blocking socket
    int s = socket(AF_INET, SOCK_STREAM, 0);
    if (s < 0) {
        perror("Failed to create non-blocking socket");
        return -1;
    }

    // Set the socket to be non-blocking
    if (fcntl(s, F_SETFL, O_NONBLOCK)) {
        perror("Failed to set non-blocking flag on socket");
        close(s);
        return -1;
    }

    // Return the new socket
    *socket = s;
    return 0;
}

// Define function to manage existing connections in a connection pool
int get_connection_from_pool(int* socket) {
    // Check if there are any available connections in the pool
    int num_connections = MAX_CONNECTIONS;
    for (int i = 0; i < num_connections; ++i) {
        if (!socket_array[i]) {
            *socket = i;
            return 0;
        }
    }

    // If no available connections, create a new one
    if (open_socket(socket)) {
        fprintf(stderr, "Failed to open new socket\n");
        return -1;
    }

    // Add the new connection to the pool
    socket_array[*socket] = 1;
    return 0;
}

// Define function to release a socket back to the pool
int release_connection(int socket) {
    if (socket < 0 || socket >= MAX_CONNECTIONS) {
        fprintf(stderr, "Invalid socket\n");
        return -1;
    }

    // Remove the socket from the pool
    socket_array[socket] = 0;
    return 0;
}

// Define function to handle errors in the connection pool
int handle_pool_error(int* socket) {
    fprintf(stderr, "Failed to get socket from pool\n");
    *socket = -1;
    return -1;
}

// Define function to manage connections in a thread-safe manner
void* connection_manager(void* args) {
    int* socket = (int*)args;
    if (!get_connection_from_pool(socket)) {
        fprintf(stderr, "Failed to get socket from pool\n");
        return NULL;
    }

    // Check if there is any data available on the socket
    int num_bytes = read(socket, buffer, BUFFER_SIZE);
    if (num_bytes < 0) {
        perror("Failed to read from socket");
        release_connection(*socket);
        return NULL;
    } else if (num_bytes == 0) {
        // End of file has been reached, close the socket and remove it from the pool
        fprintf(stderr, "End of file reached\n");
        release_connection(*socket);
        *socket = -1;
        return NULL;
    }

    // Handle data on the socket
    handle_data(socket, buffer, num_bytes);

    // Release the socket back to the pool
    if (release_connection(*socket)) {
        fprintf(stderr, "Failed to release connection\n");
    }

    return NULL;
}

