// Define function to establish connections and manage threads in a thread-safe manner
void* establish_connections(void* args) {
    int* socket = (int*)args;
    if (!open_socket(socket)) {
        fprintf(stderr, "Failed to open socket\n");
        return NULL;
    }

    // Check if there are any available threads in the pool
    int num_threads = MAX_THREADS;
    for (int i = 0; i < num_threads; ++i) {
        if (!thread_array[i]) {
            thread_array[i] = pthread_create(&(thread_array[i]), NULL, connection_manager, socket);
            break;
        }
    }

    // If no available threads, create a new one
    if (num_threads == MAX_THREADS) {
        fprintf(stderr, "No available threads in the pool\n");
        return NULL;
    }

    // Wait for thread to complete
    int status = 0;
    pthread_join(thread_array[i], &status);
    if (status) {
        fprintf(stderr, "Failed to join thread\n");
    }

    return NULL;
}

// Define function to manage threads in a thread-safe manner
void* manage_threads(void* args) {
    int* socket = (int*)args;
    if (!open_socket(socket)) {
        fprintf(stderr, "Failed to open socket\n");
        return NULL;
    }

    // Check if there are any available threads in the pool
    int num_threads = MAX_THREADS;
    for (int i = 0; i < num_threads; ++i) {
        if (!thread_array[i]) {
            thread_array[i] = pthread_create(&(thread_array[i]), NULL, connection_manager, socket);
            break;
        }
    }

    // If no available threads, create a new one
    if (num_threads == MAX_THREADS) {
        fprintf(stderr, "No available threads in the pool\n");
        return NULL;
    }

    // Wait for thread to complete
    int status = 0;
    pthread_join(thread_array[i], &status);
    if (status) {
        fprintf(stderr, "Failed to join thread\n");
    }

    return NULL;
}

int main() {
    // Initialize variables and data structures
    int socket = -1;
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    int num_connections = MAX_CONNECTIONS;
    for (int i = 0; i < num_connections; ++i) {
        socket_array[i] = 0;
    }
    int num_threads = MAX_THREADS;
    for (int i = 0; i < num_threads; ++i) {
        thread_array[i] = NULL;
    }

    // Establish connections and manage threads in a thread-safe manner
    void* status = NULL;
    pthread_create(&status, NULL, establish_connections, &socket);
    if (status) {
        fprintf(stderr, "Failed to create connection\n");
        return 1;
    }
    pthread_join(status, NULL);

    // Manage threads in a thread-safe manner
    status = NULL;
    while (socket != -1) {
        pthread_create(&status, NULL, manage_threads, &socket);
        if (status) {
            fprintf(stderr, "Failed to create connection\n");
            return 1;
        }
        pthread_join(status, NULL);
    }

    // Clean up resources
    free(socket);
    free(buffer);

    return 0;
}
