    pthread_mutex_lock(&mutex);
    if (key < 1 || key > 1000) {
        fprintf(stderr, "Error: invalid key provided\n");
        return -1;
    }
    entry* deleted_entry = &entries[key];
    free(deleted_entry->offset);
    records[deleted_entry->offset / sizeof(record)] = NULL;
    entries[key] = NULL;
    num_records--;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int get_record(int key, record* retrieved_record) {
    pthread_mutex_lock(&mutex);
    if (key < 1 || key > 1000) {
        fprintf(stderr, "Error: invalid key provided\n");
        return -1;
    }
    entry* retrieved_entry = &entries[key];
    retrieved_record->key = retrieved_entry->key;
    retrieved_record->value = records[retrieved_entry->offset / sizeof(record)].value;
    pthread_mutex_unlock(&mutex);
    return 0;
}

