    if (length < 8 || length > 32) {
        return -1; // Password is not within the valid range
    }

    for (int i = 0; i < length; i++) {
        if (!isdigit(password[i]) && !ispunct(password[i])) {
            return -1; // Password does not contain enough special characters
        }
    }

    return 0; // Password is valid
}

