}

// Define a function to manage LTE UE context structures and populate them with active radio bearers
int populate_ue_context(const char *imsi, int num_rb) {
    ue_context_t *ue = malloc(sizeof(ue_context_t));
    if (ue == NULL) {
        return -1; // Failed to allocate memory for the UE context
    }

    ue->imsi = strdup(imsi); // Copy the IMSI of the UE
    ue->num_rb = num_rb; // Set the number of active radio bearers
    ue->rb_head = NULL; // Initialize the head of the list of active radio bearers

    for (int i = 0; i < num_rb; i++) {
        rb_node_t *rb = malloc(sizeof(rb_node_t));
        if (rb == NULL) {
            return -1; // Failed to allocate memory for the radio bearer
        }

        // Initialize the QoS parameters and radio bearer ID for the new radio bearer
        rb->qos_params = "default";
        rb->rbid = i;

        // Add the new radio bearer to the list of active radio bearers
        TAILQ_INSERT_TAIL(&ue->rb_head, rb, entries);
    }

    return 0; // Successfully populated the UE context with active radio bearers
}

// Define a function to manage LTE UE context structures and add support for AES, Camellia, DES, MD5, SHA1, and SHA256 encryption and hashing
int add_crypto_support(void) {
    // Initialize the EVP library with the appropriate cipher and hash functions
    if (!EVP_add_cipher("AES", "aes-192-cbc") || !EVP_add_cipher("Camellia", "camellia-128-cbc") ||
            !EVP_add_cipher("DES", "des-ede3-cbc") || !EVP_add_digest("MD5", EVP_md5()) ||
            !EVP_add_digest("SHA1", EVP_sha1()) || !EVP_add_digest("SHA256", EVP_sha256())) {
        return -1; // Failed to initialize the EVP library with appropriate cipher and hash functions
    }

    return 0; // Successfully initialized the EVP library with appropriate cipher and hash functions
}

// Define a function to handle dynamic resizing of UE context structures when new radio bearers are added or removed
int resize_ue_context(const char *imsi, int num_rb) {
    ue_context_t *ue = NULL; // Search for the UE context with the given IMSI
    TAILQ_FOREACH(ue, &ue_head, entries) {
        if (strcmp(ue->imsi, imsi) == 0) {
            break; // Found the UE context with the given IMSI
        }
    }

    if (ue != NULL) {
        // Update the number of active radio bearers for the existing UE context
        ue->num_rb = num_rb;
    } else {
        // Create a new UE context and populate it with the given IMSI and number of active radio bearers
        populate_ue_context(imsi, num_rb);
    }

    return 0; // Successfully updated or created the UE context with the given IMSI and number of active radio bearers
}

