int resize_ue_context_and_add_crypto_support(const char *imsi, int num_rb) {
    // Resize the UE context structures when new radio bearers are added or removed
    if (resize_ue_context(imsi, num_rb) != 0) {
        return -1; // Failed to resize the UE context structures
