Here is a sample code for the plugin manager system with the required features:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <pthread.h>

// Struct to represent a plugin
typedef struct {
    char* name;
    void (*event_handler)(char*, void*);
} plugin_t;

// Struct to store the list of registered plugins
typedef struct {
    int num_plugins;
    plugin_t** plugins;
} plugin_manager_t;

// Function to register a new plugin
void register_plugin(plugin_manager_t* manager, char* name, void (*event_handler)(char*, void*)) {
    // Check if the manager has enough memory allocated for the new plugin
    if (manager->num_plugins == 0 || manager->num_plugins >= manager->plugins_size) {
        int new_size = manager->plugins_size * 2;
        manager->plugins = realloc(manager->plugins, sizeof(plugin_t*) * new_size);
        manager->plugins_size = new_size;
    }

    // Add the new plugin to the list of registered plugins
    manager->num_plugins++;
    manager->plugins[manager->num_plugins - 1] = malloc(sizeof(plugin_t));
    manager->plugins[manager->num_plugins - 1]->name = strdup(name);
    manager->plugins[manager->num_plugins - 1]->event_handler = event_handler;
}

// Function to handle events and route them to the appropriate plugins
void handle_events(plugin_manager_t* manager, char* event) {
    // Iterate over all registered plugins
    for (int i = 0; i < manager->num_plugins; i++) {
        plugin_t* plugin = manager->plugins[i];

        // Check if the current plugin can handle the current event
        if (strcmp(plugin->name, event) == 0) {
            // Call the event handler function for the current plugin
            void (*event_handler)(char*, void*) = plugin->event_handler;
            pthread_mutex_lock(&manager->mutex);
            event_handler(event, NULL);
            pthread_mutex_unlock(&manager->mutex);
        }
    }
}

// Function to load a new plugin at runtime
void* load_plugin(char* path) {
    // Load the shared library containing the plugin implementation
    void* handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading plugin: %s\n", dlerror());
        return NULL;
    }

    // Resolve the event handler function from the shared library
    void (*event_handler)(char*, void*) = dlsym(handle, "event_handler");
    if (!event_handler) {
        fprintf(stderr, "Error resolving event handler function: %s\n", dlerror());
        return NULL;
    }

    // Create a new plugin structure and add it to the list of registered plugins
    plugin_t* plugin = malloc(sizeof(plugin_t));
    plugin->name = strdup(path);
    plugin->event_handler = event_handler;
    register_plugin(manager, path, event_handler);

    // Return the handle to the shared library and the new plugin structure
    return handle;
}

// Function to free memory allocated for a plugin
void unload_plugin(void* handle) {
    dlclose(handle);
}

int main() {
    // Create a new plugin manager struct and initialize its fields
    plugin_manager_t* manager = malloc(sizeof(plugin_manager_t));
    manager->num_plugins = 0;
    manager->plugins = NULL;
    manager->plugins_size = 10;

    // Register some plugins with the manager
    register_plugin(manager, "plugin1", event_handler1);
    register_plugin(manager, "plugin2", event_handler2);
    register_plugin(manager, "plugin3", event_handler3);

    // Load a new plugin at runtime and add it to the list of registered plugins
    void* handle = load_plugin("plugin4.so");
    if (handle) {
        register_plugin(manager, "plugin4", *((void (*)(char*, void*)) dlsym(handle, "event_handler")));
    }

    // Handle some events and route them to the appropriate plugins
    handle_events(manager, "event1");
    handle_events(manager, "event2");
    handle_events(manager, "event3");

    // Unload a plugin from the manager
    unload_plugin(handle);

    // Free memory allocated for the plugin manager
    free(manager->plugins[0]);
    free(manager->plugins[1]);
    free(manager->plugins[2]);
    free(manager->plugins);
    free(manager);

    return 0;
}
```
This code uses a `plugin_manager_t` struct to store the list of registered plugins and their event handler functions. It also defines a `register_plugin` function to add new plugins to the manager, a `handle_events` function to handle events and route them to the appropriate plugins, a `load_plugin` function to load new plugins at runtime, and an `unload_plugin` function to free memory allocated for a plugin.

The `main` function demonstrates how to use the plugin manager system by registering some plugins with the manager, handling some events, and unloading a plugin from the manager. It also includes code for memory management and error handling to ensure that the system behaves correctly in different scenarios.']

