void connectAndInitialize(char* socketPath, int offsetCount, int keyCount, int minRange, int maxRange) {
    // Establish a connection to the specified Unix socket path
    int sockfd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_un serverAddress;
    memset(&serverAddress, 0, sizeof(struct sockaddr_un));
