    if (connect(sockfd, (const struct sockaddr *)&serverAddress, sizeof(struct sockaddr_un)) == -1) {
        perror("connect");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets and initialize with zeros
    long* offsets = (long*)malloc(offsetCount * sizeof(long));
    if (!offsets) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    memset(offsets, 0, offsetCount * sizeof(long));

    // Allocate memory for keys and initialize with unique values from 1 to keyCount
    int* keys = (int*)malloc(keyCount * sizeof(int));
    if (!keys) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < keyCount; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for an array of record structures, where each structure contains an int field initialized randomly within [minRange, maxRange]
    record* records = (record*)malloc(sizeof(record) * keyCount);
    if (!records) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < keyCount; i++) {
        records[i].value = rand() % (maxRange - minRange + 1) + minRange;
    }

    // Manage large strings by efficiently allocating and deallocating memory
    char* largeString = "This is a very large string that will be allocated and deallocated dynamically";
    printf("Allocated memory for large string: %d\n", strlen(largeString));
    free(largeString);
}
