// Define a struct to store file statistics
typedef struct {
    char *file_path;
    size_t line_count;
    size_t word_count;
} file_stats;

// Function to read and process files from standard input
void process_files() {
    // Read the number of files from standard input
    int num_files = 0;
    fscanf(stdin, "%d", &num_files);
    if (num_files < 1) {
        printf("Error: Invalid number of files\n");
        return;
    }

    // Allocate memory for the file path array and the struct array
    char **file_paths = malloc(sizeof(char*) * num_files);
    if (file_paths == NULL) {
        printf("Error: Failed to allocate memory for file paths\n");
        return;
    }
    file_stats *stats = malloc(sizeof(file_stats) * num_files);
    if (stats == NULL) {
        printf("Error: Failed to allocate memory for file statistics\n");
        free(file_paths);
        return;
    }

    // Read the file paths from standard input and store them in the array
    for (int i = 0; i < num_files; i++) {
        fscanf(stdin, "%s", file_paths[i]);
        stats[i].file_path = file_paths[i];
    }

    // Process each file and calculate the line and word counts
    for (int i = 0; i < num_files; i++) {
        FILE *fp = fopen(stats[i].file_path, "r");
        if (fp == NULL) {
            printf("Error: Failed to open file %s\n", stats[i].file_path);
            continue;
        }
        size_t line_count = 0;
        size_t word_count = 0;
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), fp)) {
            line_count++;
            for (int j = 0; j < strlen(buffer); j++) {
                if (isspace(buffer[j])) {
                    word_count++;
                }
            }
        }
        stats[i].line_count = line_count;
        stats[i].word_count = word_count;
        fclose(fp);
    }

    // Print the statistics for each file
    printf("File Statistics:\n");
    for (int i = 0; i < num_files; i++) {
        printf("%s: %zu lines, %zu words\n", stats[i].file_path, stats[i].line_count, stats[i].word_count);
    }

    // Free the memory allocated for the file path array and the struct array
    free(file_paths);
    free(stats);
}
```
