#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Custom data structure for storing session metadata
typedef struct Session {
    int user_id;
    time_t active_time;
    char *permissions;
} Session;

// Global variable to store the list of sessions
Session **sessions = NULL;
int num_sessions = 0;

// Synchronization primitive for protecting access to the session list
pthread_mutex_t session_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new session to the list
void add_session(int user_id, time_t active_time, char *permissions) {
    // Lock the mutex to protect access to the session list
    pthread_mutex_lock(&session_list_lock);

    // Create a new session and add it to the list
    Session *new_session = malloc(sizeof(Session));
    if (!new_session) {
        printf("Error: failed to allocate memory for new session\n");
        exit(1);
    }
    new_session->user_id = user_id;
    new_session->active_time = active_time;
    new_session->permissions = permissions;
    sessions = realloc(sessions, (num_sessions + 1) * sizeof(Session *));
    if (!sessions) {
        printf("Error: failed to allocate memory for session list\n");
        exit(1);
    }
    sessions[num_sessions] = new_session;
    num_sessions++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&session_list_lock);
}

// Function to remove a session from the list based on user ID
void remove_session(int user_id) {
    // Lock the mutex to protect access to the session list
    pthread_mutex_lock(&session_list_lock);

    // Find the index of the session with the specified user ID
    int i;
    for (i = 0; i < num_sessions; i++) {
        if (sessions[i]->user_id == user_id) {
            break;
        }
    }
    if (i >= num_sessions) {
        printf("Error: no session found with user ID %d\n", user_id);
        exit(1);
    }

    // Remove the session from the list and free its memory
    Session *session = sessions[i];
    free(session->permissions);
    free(session);
    for (int j = i; j < num_sessions - 1; j++) {
        sessions[j] = sessions[j + 1];
    }
    sessions = realloc(sessions, (num_sessions - 1) * sizeof(Session *));
    if (!sessions) {
        printf("Error: failed to allocate memory for session list\n");
        exit(1);
    }
    num_sessions--;

    // Unlock the mutex and return
    pthread_mutex_unlock(&session_list_lock);
}

// Function to remove a session from the list based on permission ID
void remove_session_by_permission(int permission_id) {
    // Lock the mutex to protect access to the session list
    pthread_mutex_lock(&session_list_lock);

    // Find the index of the session with the specified permission ID
    int i;
    for (i = 0; i < num_sessions; i++) {
        if (strcmp(sessions[i]->permissions, permission_id) == 0) {
            break;
        }
    }
    if (i >= num_sessions) {
        printf("Error: no session found with permission ID %d\n", permission_id);
        exit(1);
    }

    // Remove the session from the list and free its memory
    Session *session = sessions[i];
    free(session->permissions);
    free(session);
    for (int j = i; j < num_sessions - 1; j++) {
        sessions[j] = sessions[j + 1];
    }
    sessions = realloc(sessions, (num_sessions - 1) * sizeof(Session *));
    if (!sessions) {
        printf("Error: failed to allocate memory for session list\n");
        exit(1);
    }
    num_sessions--;

    // Unlock the mutex and return
    pthread_mutex_unlock(&session_list_lock);
}

// Function to query the list of sessions by user ID or permission ID
void *query_sessions(int user_id, int permission_id) {
    // Lock the mutex to protect access to the session list
    pthread_mutex_lock(&session_list_lock);

    // Find the index of the first session with the specified user ID or permission ID
    int i;
    for (i = 0; i < num_sessions; i++) {
        if ((user_id >= 0 && sessions[i]->user_id == user_id) ||
            (permission_id >= 0 && strcmp(sessions[i]->permissions, permission_id) == 0)) {
            break;
        }
    }
    if (i >= num_sessions) {
        printf("Error: no session found with user ID %d or permission ID %d\n", user_id, permission_id);
        exit(1);
    }

    // Return a copy of the first matching session
    Session *session = malloc(sizeof(Session));
    if (!session) {
        printf("Error: failed to allocate memory for query result\n");
        exit(1);
    }
    memcpy(session, sessions[i], sizeof(Session));
    return session;
}

// Function to free the resources associated with a session
void free_session(Session *session) {
    // Lock the mutex to protect access to the session list
    pthread_mutex_lock(&session_list_lock);

    // Find the index of the specified session in the list
    int i;
    for (i = 0; i < num_sessions; i++) {
        if (sessions[i] == session) {
            break;
        }
    }
    if (i >= num_sessions) {
        printf("Error: no such session\n");
        exit(1);
    }

    // Remove the session from the list and free its memory
    for (int j = i; j < num_sessions - 1; j++) {
        sessions[j] = sessions[j + 1];
    }
    sessions = realloc(sessions, (num_sessions - 1) * sizeof(Session *));
    if (!sessions) {
        printf("Error: failed to allocate memory for session list\n");
        exit(1);
    }
    num_sessions--;

    // Free the resources associated with the specified session
    free(session->permissions);
    free(session);

    // Unlock the mutex and return
    pthread_mutex_unlock(&session_list_lock);
}
