// Define the structure for the record
typedef struct {
    int key;
} Record;

void initialize_arrays(long offset_size, int key_size) {
    // Allocate memory for the two arrays
    long *offset_array = (long *)malloc(offset_size * sizeof(long));
    int *key_array = (int *)malloc(key_size * sizeof(int));

    // Initialize the arrays with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offset_array[i] = rand() % 1000 + 1;
    }
    for (int j = 0; j < key_size; j++) {
        key_array[j] = rand() % 1000 + 1;
    }

    // Allocate memory for the array of records
    int record_count = offset_size / sizeof(Record);
    Record *record_array = (Record *)malloc(record_count * sizeof(Record));

    // Initialize each record's int field with a random value within the given range
    for (int i = 0; i < record_count; i++) {
        record_array[i].key = rand() % 1000 + 1;
    }

    // Handle the case where the size of the 'record' array is not a multiple of 16 bytes, padding the structure to ensure proper alignment
    int remainder = record_count % 16;
    if (remainder != 0) {
        int padding = 16 - remainder;
        record_array = realloc(record_array, (record_count + padding) * sizeof(Record));
        for (int i = 0; i < padding; i++) {
            record_array[i].key = 0;
        }
    }
}
