['Here's an example implementation of a data management system using OpenMP for thread safety and performance optimization:
```c
#include <stdio.h>
#include <stdlib.h>
#include <omp.h>

// Define structures for storing offsets, keys, and data entries
typedef struct {
    int offset;
    char key[32];
    char data[1024];
} entry_t;

// Initialize the data structure with random values
void init_data(entry_t *entries, size_t num_entries) {
    #pragma omp parallel for shared(entries) default(none)
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].offset = rand() % 127;
        srand((unsigned int) time(NULL));
        strcpy(entries[i].key, "Key ");
        strcat(entries[i].key, rand());
        srand((unsigned int) time(NULL));
        strcpy(entries[i].data, "Data ");
        strcat(entries[i].data, rand());
    }
}

// Populate the offset array with random values between 0 and 127
void populate_offsets(entry_t *entries, size_t num_entries) {
    #pragma omp parallel for shared(entries) default(none)
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].offset = rand() % 127;
    }
}

// Populate the key array with random values between 0 and 31
void populate_keys(entry_t *entries, size_t num_entries) {
    #pragma omp parallel for shared(entries) default(none)
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].key[rand() % 32];
    }
}

// Populate the data array with random values between 0 and 31
void populate_data(entry_t *entries, size_t num_entries) {
    #pragma omp parallel for shared(entries) default(none)
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].data[rand() % 1024];
    }
}

// Function to handle thread safety and prevent race conditions
void synchronize(entry_t *entries, size_t num_entries) {
    #pragma omp critical
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].offset = rand() % 127;
        strcpy(entries[i].key, "Key ");
        strcat(entries[i].key, rand());
        strcpy(entries[i].data, "Data ");
        strcat(entries[i].data, rand());
    }
}

int main() {
    // Allocate memory for arrays of offsets, keys, and data entries
    entry_t *entries = (entry_t *) malloc(100000 * sizeof(entry_t));

    if (entries == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Initialize the data structure with random values
    init_data(entries, 100000);

    // Populate the offset array with random values between 0 and 127
    populate_offsets(entries, 100000);

    // Populate the key array with random values between 0 and 31
    populate_keys(entries, 100000);

    // Populate the data array with random values between 0 and 31
    populate_data(entries, 100000);

    // Synchronize access to the arrays to prevent race conditions
    synchronize(entries, 100000);

    return 0;
}
```
This implementation uses OpenMP to parallelize the initialization of the data structure and the population of the offset, key, and data arrays. It also includes a function to handle thread safety and prevent race conditions. The `init_data` function populates the arrays with random values within specified ranges, while the `populate_offsets`, `populate_keys`, and `populate_data` functions populate the corresponding arrays with random values between 0 and 127, 0 and 31, and 0 and 31 respectively. The `synchronize` function ensures that all operations are performed in parallel using OpenMP where appropriate.

