        if (element.matches(selector)) {
            elements.push(element);
        }
    }
    return elements;
}

function traverseDOMTree(root, callback) {
    const elements = getElementsBySelector("*", root);
    for (const element of elements) {
        if (callback(element)) {
            break;
        }
        traverseDOMTree(element, callback);
    }
}
