int establish_connection(char* host, int port) {

    // Create a socket for the connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("socket");
        return -1;
    }

    // Set up the remote address structure
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(port);
    if (inet_pton(AF_INET, host, &server_address.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return -1;
    }

    // Connect to the remote server
    if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    // Set up the buffer for data transfer
    char* buffer = malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        perror("malloc");
        close(sock);
        return -1;
    }

    // Start reading data from the socket
    ssize_t bytes_read = 0;
    do {
        bytes_read = read(sock, buffer + bytes_read, BUFFER_SIZE - bytes_read);
        if (bytes_read < 0) {
            perror("read");
            free(buffer);
            close(sock);
            return -1;
        } else if (bytes_read == 0) {
            break; // No more data available
        }
    } while (true);

    // Close the socket and free the buffer
    close(sock);
    free(buffer);

    return bytes_read;
}

