// Define a function to allocate and initialize an array of records
Record* init_records(int num_records, int min_key, int max_key, int min_offset, int max_offset, int data_length) {
    // Allocate memory for the array of records
    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        // Log an error and exit the function if memory allocation fails
        fprintf(stderr, "Error: Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize each record with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        record->key = rand() % (max_key - min_key + 1) + min_key;
        record->offset = rand() % (max_offset - min_offset + 1) + min_offset;
        record->value = ((double)record->offset * record->key);
        // Allocate memory for the dynamically allocated char array
        record->data = malloc(data_length * sizeof(char));
        if (!record->data) {
            fprintf(stderr, "Error: Failed to allocate memory for %d bytes of data\n", data_length);
            return NULL;
        }
        // Initialize the dynamically allocated char array with random data
        memset(record->data, 0, data_length * sizeof(char));
    }

    // Compute the weighted average of each record's offset and key values
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        record->value = ((double)record->offset * record->key);
    }

    // Compress the dynamically allocated strings using zlib if compression is enabled
    #ifdef ENABLE_COMPRESSION
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        int compressed_size = compressBound(record->data_length);
        char* compressed_data = malloc(compressed_size * sizeof(char));
        if (!compressed_data) {
            fprintf(stderr, "Error: Failed to allocate memory for %d bytes of compressed data\n", compressed_size);
            return NULL;
        }
        int status = compress2(compressed_data, &compressed_size, record->data, record->data_length, Z_BEST_COMPRESSION);
        if (status != Z_OK) {
            fprintf(stderr, "Error: Failed to compress data with error %d\n", status);
            return NULL;
        }
        free(record->data);
        record->data = compressed_data;
        record->data_length = compressed_size;
    }
    #endif

    // Write the records to disk in binary format using standard file I/O functions
    FILE* fp = fopen("records.bin", "wb");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open file for writing\n");
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        fwrite(&record->key, sizeof(int), 1, fp);
        fwrite(&record->offset, sizeof(long), 1, fp);
        fwrite(&record->value, sizeof(double), 1, fp);
        fwrite(record->data, record->data_length, 1, fp);
    }
    fclose(fp);

    return records;
}

// Define a function to free the memory allocated for an array of records
void free_records(Record* records) {
    // Free the dynamically allocated strings and memory for each record
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        if (record->data) {
            #ifdef ENABLE_COMPRESSION
                free(record->data);
            #else
                free(record->data);
            #endif
        }
    }
    // Free the memory for the array of records
    free(records);
}
