// Function to dynamically allocate memory for and initialize two arrays: one for 'long' offset values and one for 'int' keys.
void init_arrays(Record **records, long **offsets, int **keys) {
    // Allocate memory for the record array
    *records = (Record *)malloc(sizeof(Record) * 10);
    assert(*records != NULL);

    // Initialize each element in the record array to zero
    memset(*records, 0, sizeof(Record) * 10);

    // Allocate memory for the offset array
    *offsets = (long *)malloc(sizeof(long) * 10);
    assert(*offsets != NULL);

    // Initialize each element in the offset array to zero
    memset(*offsets, 0, sizeof(long) * 10);

    // Allocate memory for the key array
    *keys = (int *)malloc(sizeof(int) * 10);
    assert(*keys != NULL);

    // Initialize each element in the key array to zero
    memset(*keys, 0, sizeof(int) * 10);
}

// Function to read external data from a CSV file and populate the key and offset arrays.
void read_csv(const char *filename, Record **records, long **offsets, int **keys) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize variables to keep track of the current record and offset values
    int current_record = 0;
    long current_offset = 0;

    // Read each line in the CSV file
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Split the line into tokens using a comma as the delimiter
        char *token = strtok(line, ",");

        // Read the key value from the first token
        int key = atoi(token);

        // If the key is valid, update the current record and offset values
        if (key > 0) {
            (*records)[current_record].key = key;
            (*offsets)[current_record] = current_offset;
            (*keys)[current_record] = key;
            current_record++;
        }

        // Update the offset value for the next record
        if (token != NULL) {
            current_offset += strlen(token);
        }
    }

    // Close the CSV file
    fclose(file);
}

// Function to sort the records based on their corresponding key values in ascending order.
void sort_records(Record *records, int n) {
    // Use a simple bubble sort algorithm to sort the records
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if ((*records)[j].key > (*records)[j + 1].key) {
                Record tmp = (*records)[j];
                (*records)[j] = (*records)[j + 1];
                (*records)[j + 1] = tmp;
            }
        }
    }
}

// Function to set the value of each record's int field to a random value within a given range.
void generate_random(Record *records, int n, int min, int max) {
    // Use a random number generator to set the value of each record's int field
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        (*records)[i].key = rand() % (max - min + 1) + min;
    }
}
