    for (size_t i = 0; i < num_keys - 1; i++) {
        for (size_t j = 0; j < num_keys - i - 1; j++) {
            if ((*key)[j] > (*key)[j + 1]) {
                int tmp_key = (*key)[j];
                long tmp_offset = (*offset)[j];
