                (*offset)[j] = (*offset)[j + 1];
                memcpy((*record)[j]->metadata, (*record)[j + 1]->metadata, strlen((*record)[j + 1]->metadata));

                (*key)[j + 1] = tmp_key;
                (*offset)[j + 1] = tmp_offset;
