            db->offsets[i] = find_alternative_offset(db->records[i], db->record_count - i, unique_keys);
        }
    }

    // Free the set and return success code
    free_set(unique_keys);

    return 0;  // Return success code
}

int find_alternative_offset(record *records, size_t record_count, set *unique_keys) {
    // Iterate over the records and find an alternative offset that has a unique key
    for (size_t i = 0; i < record_count; ++i) {
        if (!is_member(records[i].key, unique_keys)) {
            return records[i].offset;
        }
    }

    // Return an error code if no alternative offset was found
    return -1;
}

int is_member(int key, set *unique_keys) {
    // Check if the key is already a member of the set
    size_t i = 0;
    while (i < unique_keys->count && unique_keys->values[i] != key) {
        ++i;
    }

    return i < unique_keys->count;
}
