memory_pool* allocate_memory(size_t num_offsets, size_t num_keys, size_t num_entries, double offset_range_min, double offset_range_max, char key_range_min, char key_range_max, double entry_value) {
    // Calculate total memory usage for all data structures
    size_t total_memory = (num_offsets * sizeof(double)) + (num_keys * sizeof(char)) + (num_entries * sizeof(data_entry));

    // Check if total memory exceeds maximum limit
    if (total_memory > MAX_MEMORY) {
        return NULL;
    }

    // Allocate memory for offset array
    double* offsets = malloc(num_offsets * sizeof(double));
    if (!offsets) {
        free_memory(offsets, keys, entries);
        return NULL;
    }

    // Initialize offset array with random values within range
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = (offset_range_max - offset_range_min) * rand() / RAND_MAX + offset_range_min;
    }

    // Allocate memory for key array
    char* keys = malloc(num_keys * sizeof(char));
    if (!keys) {
        free_memory(offsets, keys, entries);
