        entries[i].value = entry_value;
    }

    // Create memory pool structure
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (!pool) {
        free_memory(offsets, keys, entries);
        return NULL;
    }

    // Assign pointers to offsets, keys, and data entry array in memory pool
    pool->offsets = offsets;
    pool->keys = keys;
    pool->entries = entries;

    return pool;
}

// Function to free memory allocated by allocate_memory()
