void load_balancer(int* server_index) {
    // Dynamic Load Balancing
    int min_load = servers[0].connected;
    for (int i = 1; i < num_servers; i++) {
        if (servers[i].connected < min_load) {
            min_load = servers[i].connected;
            *server_index = i;
        }
    }
}

void health_checks(int* server_index) {
    // Health Checks
    int alive = 1;
    for (int i = 0; i < num_servers; i++) {
        if (!servers[i].connected) {
            alive = 0;
            *server_index = i;
            break;
        }
    }
}

