    AES_KEY key;
    AES_set_encrypt_key(data, 256, &key);
    AES_ecb_encrypt(data, size, &key);
}

void failover(int* server_index) {
    // Failover Mechanism
    int alive = 1;
    for (int i = 0; i < num_servers; i++) {
        if (!servers[i].connected) {
            alive = 0;
            *server_index = i;
            break;
        }
    }
}

