    // Set the offset and key arrays to their respective values
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i * sizeof(Record);
        keys[i] = i + 1;
    }

    // Return the socket file descriptor, offset and key arrays, and record array
    return sock;
}

// Function to manage buffer sizes and optimize data copying operations during large data transfers
int transfer_data(int sock, long *offsets, int *keys, Record *records) {
    // Calculate the total size of the data to be transferred
    long total_size = MAX_RECORDS * sizeof(Record);

    // Allocate a buffer for transferring data
