    if (input == NULL) {
        return NULL;
    }

    // Read input from standard input and validate each value
    size_t num_elements = 0;
    while (num_elements < max_elements && scanf("%f", &input[num_elements]) != EOF) {
        if (!isfinite(input[num_elements])) {
            continue;
        }

        ++num_elements;
    }

