    for (size_t i = 0; i < max_elements; ++i) {
        structures[i].rx_ue_info = rand() % 100;
        structures[i].rnti = rand() % 100;
        structures[i].crc_flag = (rand() % 2 == 0);
    }

    *out_num_elements = max_elements;
    return structures;
}

// Main function to handle input and output for the program
