// Define the record structure
typedef struct {
    long offset;
    int key;
    // Additional metadata fields here
} Record;

// Define the cache structure
typedef struct {
    size_t capacity;
    size_t size;
    Record** records;
} Cache;

// Initialize a new cache with the given capacity
Cache* initializeCache(size_t capacity) {
    Cache* cache = malloc(sizeof(Cache));
    assert(cache != NULL);
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = malloc(sizeof(Record*) * capacity);
    assert(cache->records != NULL);
    return cache;
}

// Add a new record to the cache, or update an existing one if it already exists
void addToCache(Cache* cache, Record* record) {
    // Check if the record is already in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->records[i] == record) {
            return;
        }
    }

    // If the cache is full, remove the least recently used record from the cache
    if (cache->size >= cache->capacity) {
        size_t lruIndex = 0;
        for (size_t i = 1; i < cache->size; i++) {
            if (cache->records[i]->offset < cache->records[lruIndex]->offset) {
                lruIndex = i;
            }
        }
        free(cache->records[lruIndex]);
        memmove(&cache->records[lruIndex], &cache->records[lruIndex + 1], sizeof(Record*) * (cache->size - lruIndex));
    }

    // Add the new record to the cache
    cache->records = realloc(cache->records, sizeof(Record*) * (cache->size + 1));
    assert(cache->records != NULL);
    cache->records[cache->size++] = record;
}

// Remove a record from the cache if it exists
void removeFromCache(Cache* cache, Record* record) {
    // Check if the record is in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->records[i] == record) {
            free(cache->records[i]);
            memmove(&cache->records[i], &cache->records[i + 1], sizeof(Record*) * (cache->size - i));
            cache->size--;
            return;
        }
    }
}

// Get a record from the cache by its offset value
Record* getFromCache(Cache* cache, long offset) {
    // Check if the record is in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->records[i]->offset == offset) {
            return cache->records[i];
        }
    }
    return NULL;
}

// Update a record in the cache by its offset value, or add it if it does not exist
void updateCache(Cache* cache, Record* record) {
    // Check if the record is already in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->records[i] == record) {
            return;
        }
    }

    // If the cache is full, remove the least recently used record from the cache
    if (cache->size >= cache->capacity) {
        size_t lruIndex = 0;
        for (size_t i = 1; i < cache->size; i++) {
            if (cache->records[i]->offset < cache->records[lruIndex]->offset) {
                lruIndex = i;
            }
        }
        free(cache->records[lruIndex]);
        memmove(&cache->records[lruIndex], &cache->records[lruIndex + 1], sizeof(Record*) * (cache->size - lruIndex));
    }

    // Add the new record to the cache
    cache->records = realloc(cache->records, sizeof(Record*) * (cache->size + 1));
    assert(cache->records != NULL);
    cache->records[cache->size++] = record;
}

// Clean up a cache by freeing all allocated memory
void cleanupCache(Cache* cache) {
    for (size_t i = 0; i < cache->size; i++) {
        free(cache->records[i]);
    }
    free(cache->records);
}

// Implement a background thread that periodically checks for idle records in the cache and reclaims their resources if they have not been accessed within a configurable timeout period
void* backgroundThreadFunc(void* arg) {
    Cache* cache = (Cache*)arg;
    while (1) {
        // Check if any record is idle for more than the configured timeout period
        for (size_t i = 0; i < cache->size; i++) {
            Record* record = cache->records[i];
            if (record != NULL && record->offset == -1) {
                // Remove the idle record from the cache
                free(record);
                memmove(&cache->records[i], &cache->records[i + 1], sizeof(Record*) * (cache->size - i));
                cache->size--;
            }
        }
    }
}
```
This implementation uses a thread-safe caching mechanism based on the `pthread` library to manage memory for the records. The `backgroundThreadFunc()` function is executed in a background thread that periodically checks for idle records in the cache and reclaims their resources if they have not been accessed within a configurable timeout period.

The `cleanupCache()` function frees all allocated memory for the records in the cache when the program exits or when the cache needs to be cleaned up manually. The `getFromCache()`, `updateCache()`, and `removeFromCache()` functions provide convenient ways to retrieve, update, and remove records from the cache, respectively.']

