    size_t currentBufferSize; // The current total buffer size used by all connections
    struct Connection *connections; // An array of pointers to the connections in the pool
};

// Define a function to create a new connection pool with a given number of connections and maximum buffer size
struct ConnectionPool* connectionPoolCreate(size_t numConnections, size_t maxBufferSize) {
    struct ConnectionPool *pool = malloc(sizeof(struct ConnectionPool));
    if (pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for the connection pool\n");
        return NULL;
    }

    pool->numConnections = numConnections;
    pool->maxBufferSize = maxBufferSize;
    pool->currentBufferSize = 0;
    pool->connections = malloc(sizeof(struct Connection) * numConnections);
    if (pool->connections == NULL) {
        fprintf(stderr, "Failed to allocate memory for the connections in the pool\n");
        free(pool);
        return NULL;
    }

    // Initialize each connection in the pool
    for (size_t i = 0; i < numConnections; i++) {
        struct Connection *connection = &pool->connections[i];
        connection->socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (connection->socket == -1) {
            fprintf(stderr, "Failed to create a new socket\n");
            free(pool->connections);
            free(pool);
            return NULL;
        }

        // Set the socket to non-blocking mode
        int flags = fcntl(connection->socket, F_GETFL, 0);
        if (flags == -1) {
            close(connection->socket);
            fprintf(stderr, "Failed to get the current socket flags\n");
            free(pool->connections);
            free(pool);
            return NULL;
        }

        int result = fcntl(connection->socket, F_SETFL, flags | O_NONBLOCK);
        if (result == -1) {
            close(connection->socket);
            fprintf(stderr, "Failed to set the socket to non-blocking mode\n");
            free(pool->connections);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

// Define a function to add a new connection to the pool and increase the buffer size if necessary
int connectionPoolAddConnection(struct ConnectionPool *pool, int socket) {
    // Check if there is enough space in the pool for the new connection
    if (pool->numConnections == pool->maxBufferSize) {
        fprintf(stderr, "The pool is full\n");
        return -1;
    }

    // Add a new connection to the pool and increase the buffer size if necessary
    struct Connection *connection = &pool->connections[pool->numConnections];
    connection->socket = socket;
    connection->bufferSize = 0;
    connection->buffer = NULL;

    pool->numConnections++;
    pool->currentBufferSize += sizeof(struct Connection);

    return 0;
}

// Define a function to remove a connection from the pool and decrease the buffer size if necessary
int connectionPoolRemoveConnection(struct ConnectionPool *pool, int socket) {
    // Check if the pool is empty
    if (pool->numConnections == 0) {
        fprintf(stderr, "The pool is empty\n");
        return -1;
    }

    // Find the connection to remove and decrease the buffer size if necessary
    for (size_t i = 0; i < pool->numConnections; i++) {
