            connection->buffer = NULL;
            connection->bufferSize = 0;

            pool->currentBufferSize -= sizeof(struct Connection);

            // Shift the connections to fill the gap left by the removed connection
            for (size_t j = i + 1; j < pool->numConnections; j++) {
                struct Connection *nextConnection = &pool->connections[j];
                memcpy(connection, nextConnection, sizeof(struct Connection));
            }

            pool->numConnections--;

