}

// Define a function to increase the buffer size for a given connection and allocate memory for it if necessary
int connectionPoolIncreaseBufferSize(struct ConnectionPool *pool, int socket) {
    // Find the connection to increase the buffer size for
    for (size_t i = 0; i < pool->numConnections; i++) {
        struct Connection *connection = &pool->connections[i];
        if (connection->socket == socket) {
            // Increase the buffer size and allocate memory for it if necessary
            connection->bufferSize += pool->maxBufferSize;
            connection->buffer = realloc(connection->buffer, connection->bufferSize);
            if (connection->buffer == NULL) {
                fprintf(stderr, "Failed to allocate memory for the buffer\n");
                return -1;
            }

            return 0;
        }
    }

    fprintf(stderr, "The connection was not found\n");
    return -1;
}

// Define a function to decrease the buffer size for a given connection and free the memory if necessary
int connectionPoolDecreaseBufferSize(struct ConnectionPool *pool, int socket) {
    // Find the connection to decrease the buffer size for
    for (size_t i = 0; i < pool->numConnections; i++) {
        struct Connection *connection = &pool->connections[i];
        if (connection->socket == socket) {
            // Decrease the buffer size and free the memory if necessary
            connection->bufferSize -= pool->maxBufferSize;
            if (connection->bufferSize == 0) {
