}

// Define a function to decrease the maximum buffer size for all connections in the pool and free the memory if necessary
int connectionPoolDecreaseMaxBufferSize(struct ConnectionPool *pool) {
    // Decrease the maximum buffer size for all connections in the pool and free the memory if necessary
    for (size_t i = 0; i < pool->numConnections; i++) {
