                return -1;
            }
        }
    }

    pool->maxBufferSize -= pool->maxBufferSize;

    return 0;
}

// Define a function to send data through all connections in the pool
int connectionPoolSend(struct ConnectionPool *pool, char *data) {
    // Send the data through each connection in the pool
    for (size_t i = 0; i < pool->numConnections; i++) {
        struct Connection *connection = &pool->connections[i];
        if (send(connection->socket, data, strlen(data), 0) == -1) {
            fprintf(stderr, "Failed to send the data\n");
            return -1;
        }
    }

    return 0;
}

// Define a function to receive data through all connections in the pool
int connectionPoolReceive(struct ConnectionPool *pool, char *buffer) {
    // Receive the data through each connection in the pool
