#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_DATA_STRUCTURES 10000 // maximum number of data structures allowed
#define BUFFER_SIZE 256 // buffer size for each data structure

// custom data structure to hold char, int, and double values
typedef struct {
    char buffer[BUFFER_SIZE];
    int value;
    double double_value;
} data_t;

// caching mechanism to reuse previously allocated arrays of data structures
static pthread_key_t cache_key;
static bool use_cache = false; // option for users to specify whether to use cache or not
static size_t cache_size = 0; // maximum number of data structures to store in the cache

// error codes for memory allocation and deallocation errors
#define MEMORY_ALLOCATION_ERROR -1
#define MEMORY_DEALLOCATION_ERROR -2

// function to initialize and manage memory for an array of custom data structures
void* allocate_data(size_t num_elements, size_t buffer_size) {
    // validate input parameters
    if (num_elements > MAX_DATA_STRUCTURES || buffer_size == 0) {
        return NULL;
    }

    // allocate memory for the array of data structures
    data_t* data = malloc(sizeof(data_t) * num_elements);
    if (data == NULL) {
        return MEMORY_ALLOCATION_ERROR;
    }

    // initialize each data structure in the array
    for (size_t i = 0; i < num_elements; i++) {
        memset(data[i].buffer, 0, buffer_size);
        data[i].value = rand() % 100;
        data[i].double_value = (rand() % 100) / 10.0;
    }

    // cache the allocated memory if requested by the user
    if (use_cache && num_elements <= cache_size) {
        pthread_setspecific(cache_key, data);
    }

    return data;
}

// function to deallocate memory for an array of custom data structures
void deallocate_data(void* data) {
    // check if the input is a null pointer
    if (data == NULL) {
        return;
    }

    // check if the input is a cached data structure
    if (pthread_getspecific(cache_key) == data) {
        pthread_setspecific(cache_key, NULL);
        use_cache = false;
    }

    // deallocate the memory for the array of data structures
    free(data);
}

// function to handle potential errors during memory allocation gracefully
void* safe_allocate_data(size_t num_elements, size_t buffer_size) {
    void* data = allocate_data(num_elements, buffer_size);
    if (data == MEMORY_ALLOCATION_ERROR) {
        fprintf(stderr, "Error: Failed to allocate memory for array of data structures\n");
    }
    return data;
}

// function to handle potential errors during memory deallocation gracefully
void safe_deallocate_data(void* data) {
    if (data == NULL) {
        fprintf(stderr, "Error: Failed to deallocate memory for array of data structures\n");
    } else {
        deallocate_data(data);
    }
}
