    if (i < cache->count) {
        cache->count--;
        for (size_t j = i; j < cache->count; j++) {
            cache->data[j] = cache->data[j+1];
        }
    }
}

// Function to access a record from the linked list by index
struct Record* getRecordByIndex(struct LinkedList* list, size_t index) {
    if (index >= list->count) {
        return NULL;
    }
    struct Record* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    return current;
}

// Function to access a record from the cache by value
struct Record* getRecordByValue(struct Cache* cache, int value) {
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->data[i].value == value) {
            return &cache->data[i];
        }
    }
    return NULL;
}

// Function to update the access count of a record in the cache
void updateCache(struct Cache* cache, struct Record* record) {
    size_t i = 0;
    while (i < cache->count && &cache->data[i] != record) {
        i++;
    }
    if (i < cache->count) {
        cache->data[i].accessCount++;
    }
}

// Function to iterate through all records in the linked list and add them to the cache
void updateCache(struct Cache* cache, struct LinkedList* list) {
    for (size_t i = 0; i < list->count; i++) {
        struct Record* current = getRecordByIndex(list, i);
        if (current != NULL) {
            addCache(cache, current);
        }
    }
}
