#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Define the record structure
typedef struct {
  int value;
} Record;

// Define the data structure for storing records and caching frequently accessed records
typedef struct {
  // The array of records
