  struct Node *head;
  // The tail node of the doubly linked list for sequential access
  struct Node *tail;
  // The hash table for fast direct access
  struct HashTable *hash_table;
} DataStructure;

// Define the node structure for the doubly linked list used in sequential access
typedef struct Node {
  Record *record;
  struct Node *next;
  struct Node *prev;
} Node;

// Define the hash table structure
typedef struct HashTable {
  // The array of hash buckets
  struct Bucket **buckets;
  // The number of hash buckets
  int num_buckets;
} HashTable;

// Define the bucket structure for the hash table
typedef struct Bucket {
  // The head node of the doubly linked list for this bucket
  Node *head;
  // The tail node of the doubly linked list for this bucket
  Node *tail;
} Bucket;

// Define the function to allocate memory for a new record
Record* new_record(int value) {
  Record *record = (Record *)malloc(sizeof(Record));
  if (!record) {
    // Handle error: out of memory
    return NULL;
  }
  record->value = value;
  return record;
}

// Define the function to allocate memory for a new data structure
DataStructure* new_data_structure(int num_records, int cache_size) {
  DataStructure *data_structure = (DataStructure *)malloc(sizeof(DataStructure));
  if (!data_structure) {
    // Handle error: out of memory
    return NULL;
  }
  data_structure->records = (Record *)calloc(num_records, sizeof(Record));
  if (!data_structure->records) {
    // Handle error: out of memory
    free(data_structure);
    return NULL;
  }
  data_structure->cache_size = cache_size;
  data_structure->head = NULL;
  data_structure->tail = NULL;
  data_structure->hash_table = new_hash_table(num_records);
  if (!data_structure->hash_table) {
    // Handle error: out of memory
    free(data_structure->records);
    free(data_structure);
    return NULL;
  }
  return data_structure;
}

// Define the function to allocate memory for a new hash table
HashTable* new_hash_table(int num_buckets) {
  HashTable *hash_table = (HashTable *)malloc(sizeof(HashTable));
  if (!hash_table) {
    // Handle error: out of memory
    return NULL;
  }
  hash_table->num_buckets = num_buckets;
  hash_table->buckets = (Bucket **)calloc(num_buckets, sizeof(Bucket *));
  if (!hash_table->buckets) {
    // Handle error: out of memory
    free(hash_table);
    return NULL;
  }
  return hash_table;
}

// Define the function to allocate memory for a new bucket in the hash table
Bucket* new_bucket() {
  Bucket *bucket = (Bucket *)malloc(sizeof(Bucket));
  if (!bucket) {
    // Handle error: out of memory
    return NULL;
  }
  bucket->head = NULL;
  bucket->tail = NULL;
  return bucket;
}

// Define the function to add a new record to the data structure
void add_record(DataStructure *data_structure, int value) {
  // Check if there is space for another record
  if (data_structure->num_records == data_structure->cache_size) {
    // Handle error: no more space in cache
    return;
  }
  // Create a new record and add it to the end of the doubly linked list
  Record *record = new_record(value);
  if (!record) {
    // Handle error: out of memory
    return;
  }
  Node *node = (Node *)malloc(sizeof(Node));
  if (!node) {
    // Handle error: out of memory
    free(record);
    return;
  }
  node->record = record;
  node->next = NULL;
  node->prev = data_structure->tail;
  if (data_structure->tail) {
    data_structure->tail->next = node;
  } else {
    data_structure->head = node;
  }
  data_structure->tail = node;
  // Add the record to the hash table
  int index = calculate_hash(value, data_structure->num_records);
  Node *hash_node = (Node *)malloc(sizeof(Node));
  if (!hash_node) {
    // Handle error: out of memory
    return;
  }
  hash_node->record = record;
  hash_node->next = data_structure->hash_table->buckets[index];
  if (data_structure->hash_table->buckets[index]) {
    data_structure->hash_table->buckets[index]->prev = hash_node;
  } else {
    data_structure->hash_table->tail = hash_node;
  }
  data_structure->hash_table->buckets[index] = hash_node;
}

// Define the function to remove a record from the data structure
void remove_record(DataStructure *data_structure, int value) {
  // Find the record in the doubly linked list and hash table
  Record *record = find_record(data_structure, value);
  if (!record) {
    // Handle error: record not found
    return;
  }
  // Remove the record from the doubly linked list
  Node *node = (Node *)malloc(sizeof(Node));
  node->prev = record->prev;
  node->next = record->next;
  if (record == data_structure->head) {
    data_structure->head = node;
  } else if (record == data_structure->tail) {
    data_structure->tail = node;
  } else {
    if (node->prev) {
      node->prev->next = node;
    }
    if (node->next) {
      node->next->prev = node;
    }
  }
  // Remove the record from the hash table
  int index = calculate_hash(value, data_structure->num_records);
  Node *hash_node = (Node *)malloc(sizeof(Node));
  hash_node->prev = record->prev;
  hash_node->next = record->next;
  if (record == data_structure->hash_table->buckets[index]) {
    data_structure->hash_table->buckets[index] = hash_node;
  } else {
    if (hash_node->prev) {
      hash_node->prev->next = hash_node;
    }
    if (hash_node->next) {
      hash_node->next->prev = hash_node;
    }
  }
}

// Define the function to find a record in the data structure
Record* find_record(DataStructure *data_structure, int value) {
  // Calculate the hash index for the given value
  int index = calculate_hash(value, data_structure->num_records);
  // Search for the record in the doubly linked list and hash table
  Node *node = (Node *)malloc(sizeof(Node));
  node->prev = NULL;
  node->next = data_structure->head;
  while (node) {
    if (node->record->value == value) {
      return node->record;
    } else if (node->next == NULL) {
      break;
    } else {
      node->next->prev = node;
      node = node->next;
    }
  }
  // Handle error: record not found
  return NULL;
}

// Define the function to calculate the hash index for a given value
int calculate_hash(int value, int table_size) {
  return value % table_size;
}

// Define the function to print the contents of the data structure
void print_data_structure(DataStructure *data_structure) {
  // Print the header
  printf("Data Structure:\n");
  // Print the records in the doubly linked list and hash table
  Node *node = (Node *)malloc(sizeof(Node));
