      if (hash_node->next == NULL) {
        break;
      } else {
        hash_node->next->prev = hash_node;
        hash_node = hash_node->next;
      }
    }
  }
}

int main() {
  // Create a new data structure with an initial capacity of 10
  DataStructure *data_structure = (DataStructure *)malloc(sizeof(DataStructure));
  data_structure->num_records = 10;
  data_structure->hash_table = new_hash_table(data_structure->num_records);
  // Add some records to the data structure
  add_record(data_structure, 1);
  add_record(data_structure, 2);
  add_record(data_structure, 3);
  remove_record(data_structure, 2);
  print_data_structure(data_structure);
  return 0;
}']

