    memcpy(identifier, "radio_bearer", id_length);
    radio_bearer->identifier = identifier;

    return 0;
}

// Function to add a new UE context to the list with a given IMSI and list of active radio bearers
int add_ue_context(ue_context_list_t *list, char *imsi, radio_bearer_list_t *radio_bearers) {
    // Check if the list is NULL or already initialized
    if (list == NULL || list->num_ue_contexts > 0) {
        return -1;
    }

    // Allocate memory for the new UE context
    ue_context_t *new_ue_context = malloc(sizeof(ue_context_t));
    if (new_ue_context == NULL) {
        return -1;
    }

    // Initialize the IMSI and list of active radio bearers for the new UE context
    size_t imsi_length = strlen(imsi); // Get the length of the IMSI
    char *new_imsi = malloc((imsi_length + 1) * sizeof(char));
    if (new_imsi == NULL) {
        return -1;
    }
    memcpy(new_imsi, imsi, imsi_length);
    new_imsi[imsi_length] = '\0';
    radio_bearer_list_t *new_radio_bearers = malloc(sizeof(radio_bearer_list_t));
    if (new_radio_bearers == NULL) {
        return -1;
    }

    // Set the IMSI and list of active radio bearers for the new UE context
    new_ue_context->imsi = new_imsi;
    new_ue_context->radio_bearers = new_radio_bearers;
    new_ue_context->radio_bearers->num_radio_bearers = radio_bearers->num_radio_bearers;
    new_ue_context->radio_bearers->radio_bearers = malloc(new_ue_context->radio_bearers->num_radio_bearers * sizeof(radio_bearer_t));
    if (new_ue_context->radio_bearers->radio_bearers == NULL) {
        return -1;
    }
    memcpy(new_ue_context->radio_bearers->radio_bearers, radio_bearers->radio_bearers, new_ue_context->radio_bearers->num_radio_bearers * sizeof(radio_bearer_t));

    // Add the new UE context to the list
    list->num_ue_contexts += 1;
    list->ue_contexts = realloc(list->ue_contexts, list->num_ue_contexts * sizeof(ue_context_t));
    if (list->ue_contexts == NULL) {
        return -1;
    }
    memcpy(&list->ue_contexts[list->num_ue_contexts - 1], new_ue_context, sizeof(ue_context_t));

    return 0;
}

// Function to remove a UE context from the list by its IMSI
int remove_ue_context_by_imsi(ue_context_list_t *list, char *imsi) {
    // Check if the list is NULL or already initialized
    if (list == NULL || list->num_ue_contexts < 1) {
        return -1;
    }

    // Find the UE context with the given IMSI in the list
    int index = -1;
    for (size_t i = 0; i < list->num_ue_contexts; ++i) {
        if (!strcmp(list->ue_contexts[i].imsi, imsi)) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        return -1;
    }

    // Remove the UE context from the list
    size_t num_ue_contexts = list->num_ue_contexts;
    for (size_t i = index + 1; i < num_ue_contexts; ++i) {
        memcpy(&list->ue_contexts[i - 1], &list->ue_contexts[i], sizeof(ue_context_t));
    }
    list->num_ue_contexts -= 1;
    list->ue_contexts = realloc(list->ue_contexts, list->num_ue_contexts * sizeof(ue_context_t));
    if (list->ue_contexts == NULL) {
        return -1;
    }

    return 0;
}
