// Define product structure
typedef struct {
    char* name;
    float price;
    int stock_quantity;
} Product;

// Define linked list node for storing products
typedef struct ProductNode {
    Product* data;
    struct ProductNode* next;
} ProductNode;

// Define dynamic array for storing product nodes
typedef struct DynamicArray {
    int size;
    int capacity;
    ProductNode** nodes;
} DynamicArray;

// Initialize dynamic array with given capacity
void init_dynamic_array(DynamicArray* dyn_arr, int capacity) {
    // Allocate memory for the dynamic array
    dyn_arr->nodes = (ProductNode**)malloc(capacity * sizeof(ProductNode));
    assert(dyn_arr->nodes != NULL);

    // Initialize node pointers to null
    for (int i = 0; i < capacity; i++) {
        dyn_arr->nodes[i] = NULL;
    }

    // Set initial size and capacity
    dyn_arr->size = 0;
    dyn_arr->capacity = capacity;
}

// Insert new product into dynamic array at given index
void insert_product(DynamicArray* dyn_arr, int index, Product* prod) {
    // Check if index is valid
    if (index < 0 || index > dyn_arr->capacity - 1) {
        printf("Index out of bounds\n");
        return;
    }

    // If there are no free nodes, allocate a new node
    if (dyn_arr->size == dyn_arr->capacity) {
        ProductNode* new_node = (ProductNode*)malloc(sizeof(ProductNode));
        assert(new_node != NULL);

        // Initialize the new node's data and next pointer
        new_node->data = prod;
        new_node->next = NULL;

        // If there are existing nodes, link them together
        if (dyn_arr->size > 0) {
            ProductNode* cur_node = dyn_arr->nodes[index];
            while (cur_node->next != NULL) {
                cur_node = cur_node->next;
            }
            cur_node->next = new_node;
        } else {
            // If there are no existing nodes, set the first node
            dyn_arr->nodes[index] = new_node;
        }
    } else {
        // If there is a free node, use it to store the product
        ProductNode* cur_node = dyn_arr->nodes[index];
        while (cur_node != NULL) {
            if (cur_node->data == NULL) {
                cur_node->data = prod;
                break;
            }
            cur_node = cur_node->next;
        }
    }

    // Increment the size of the dynamic array
    dyn_arr->size++;
}

// Delete product at given index from dynamic array
void delete_product(DynamicArray* dyn_arr, int index) {
    // Check if index is valid
    if (index < 0 || index > dyn_arr->capacity - 1) {
        printf("Index out of bounds\n");
        return;
    }

    // If there are no nodes at the given index, do nothing
    ProductNode* cur_node = dyn_arr->nodes[index];
    if (cur_node == NULL) {
        return;
    }

    // If there is only one node at the given index, free it
    if (cur_node->next == NULL) {
        free(cur_node);
        dyn_arr->nodes[index] = NULL;
    } else {
        // Find the previous node to the one to be freed
        ProductNode* prev_node = cur_node;
        while (prev_node != NULL && prev_node->next->data != NULL) {
            prev_node = prev_node->next;
        }

        // Free the node and update the previous node's next pointer
        ProductNode* free_node = cur_node;
        prev_node->next = free_node->next;
        free(free_node);
    }

    // Decrement the size of the dynamic array
    dyn_arr->size--;
}

// Update product at given index with new data
void update_product(DynamicArray* dyn_arr, int index, Product* prod) {
    // Check if index is valid
    if (index < 0 || index > dyn_arr->capacity - 1) {
        printf("Index out of bounds\n");
        return;
    }

    // If there are no nodes at the given index, do nothing
    ProductNode* cur_node = dyn_arr->nodes[index];
    if (cur_node == NULL) {
        return;
    }

    // Update the product data in the first node with new data
    while (cur_node != NULL) {
        if (cur_node->data != NULL) {
            cur_node->data->name = prod->name;
            cur_node->data->price = prod->price;
            cur_node->data->stock_quantity = prod->stock_quantity;
            break;
        }
        cur_node = cur_node->next;
    }
}

// Get product at given index from dynamic array
Product* get_product(DynamicArray* dyn_arr, int index) {
    // Check if index is valid
    if (index < 0 || index > dyn_arr->capacity - 1) {
        printf("Index out of bounds\n");
        return NULL;
    }

    // If there are no nodes at the given index, return null
    ProductNode* cur_node = dyn_arr->nodes[index];
    if (cur_node == NULL) {
        return NULL;
    }

    // Return the product data in the first node
    while (cur_node != NULL) {
        if (cur_node->data != NULL) {
            return cur_node->data;
        }
        cur_node = cur_node->next;
    }

    // If no product data was found, return null
    return NULL;
}

// Get number of products in dynamic array
int get_size(DynamicArray* dyn_arr) {
    return dyn_arr->size;
}

// Free the memory used by a dynamic array
void free_array(DynamicArray* dyn_arr) {
    // If there are no nodes, do nothing
    if (dyn_arr->size == 0) {
        return;
    }

    // Free all of the nodes
    ProductNode* cur_node = dyn_arr->nodes[0];
    while (cur_node != NULL) {
        ProductNode* next_node = cur_node->next;
        free(cur_node);
        cur_node = next_node;
    }

    // Free the nodes array
    free(dyn_arr->nodes);
}
