        tid = pthread_self();
    }

    // Create a record for the file and allocate memory for its metadata
    FileRecord *record = malloc(sizeof(FileRecord));
    record->filename = filename;
    size_t allocation_size = MIN_ALLOCATION_SIZE;

    // Try to allocate memory for the file's metadata, with an exponential backoff strategy
    for (int i = 0; i < ALLOCATION_STRATEGY_COUNT; i++) {
        record->allocation_size = allocation_size;
        record->data = malloc(record->allocation_size);
        if (record->data != NULL) {
            break;
        } else {
            // Log failed allocation attempts and retry with a larger size
            fprintf(stderr, "Failed to allocate memory for file metadata. Retrying with size %zu...\n", allocation_size);
            allocation_size *= 2;
        }
    }

    // Check if the allocation was successful and log detailed information about it
    if (record->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for file metadata after %d attempts. Aborting...\n", ALLOCATION_STRATEGY_COUNT);
        free(record);
        return 1;
    } else {
        // Log successful allocation and write the record to a shared queue for resource management
        fprintf(stderr, "Successfully allocated memory for file metadata. Size: %zu\n", record->allocation_size);
        pthread_mutex_lock(&resource_management_mutex);
        shared_queue[tid] = record;
        pthread_cond_signal(&resource_management_cv);
        pthread_mutex_unlock(&resource_management_mutex);
    }

    return 0;
}

/**
 * Enhances logging for resource management by including detailed information about failed allocation attempts.
 * @param record The file record to log
 */
void log_record(FileRecord *record) {
    // Log the allocation and deallocation of memory, including timestamps, allocation sizes, and success/failure status
    fprintf(stderr, "Allocated memory for file metadata. Size: %zu\n", record->allocation_size);
}
