// Define the structure for a record
typedef struct {
    int key;
} Record;

// Function to initialize and save records
void initializeAndSaveRecords(int numOffsets, int numKeys, const char* filepath) {
    // Validate input parameters
    if (numOffsets < 0 || numOffsets > 1000 || numKeys < 0 || numKeys > 1000) {
        return;
    }

    // Allocate memory for the offset and key arrays
    long* offsets = (long*) malloc(numOffsets * sizeof(long));
    int* keys = (int*) malloc(numKeys * sizeof(int));
    Record* records = (Record*) malloc(numOffsets * sizeof(Record));

    // Initialize the offset and key arrays with random values
    srand(time(NULL));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 10000;
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 10000;
    }

    // Initialize the record array with key and offset values
    for (int i = 0; i < numOffsets; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Save the initialized records to a file in binary format
    FILE* fp = fopen(filepath, "wb");
    if (fp == NULL) {
        return;
    }
    fwrite(records, sizeof(Record), numOffsets, fp);
    fclose(fp);

    // Deallocate memory for the offset and key arrays
    free(offsets);
    free(keys);
    free(records);
}
