// Hash table to map keys to records
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Record* hashTable[1024];

void addRecord(int key, int value) {
    // Acquire lock on the hash table
    pthread_mutex_lock(&mutex);

    // Check if a record with the given key already exists
    if (getRecord(key) != NULL) {
        printf("Error: Record with key %d already exists\n", key);
        return;
    }

    // Create a new record and add it to the hash table
    Record* newRecord = malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->value = value;
    hashTable[key % 1024] = newRecord;

    // Release lock on the hash table
    pthread_mutex_unlock(&mutex);
}

void updateRecord(int key, int value) {
