function getElementsBySelector(selector, context) {
    // Check if the context is provided
    if (context === undefined) {
        context = document;
    }

    // Create an array to store the matched elements
    let elements = [];

    // Iterate over the children of the context element
    for (let child of context.children) {
        // Check if the child matches the selector
        if (child.matches(selector)) {
            // Add the child to the array of matched elements
            elements.push(child);
        }

        // Recursively call the function for the child element's children
        let grandchildren = getElementsBySelector(selector, child);
        if (grandchildren.length > 0) {
            elements = elements.concat(grandchildren);
        }
    }

    return elements;
}
