['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define struct for record with int field and char array to store name
typedef struct {
    int value;
    char name[20];
} Record;

// Define hash table with open addressing scheme and linear probing
typedef struct {
    size_t capacity; // Maximum number of elements in the table
    size_t size; // Current number of elements in the table
    Record** buckets; // Array of pointers to record structures
} HashTable;

// Define function to dynamically allocate memory for arrays and hash table
void allocateMemory(HashTable* ht, int numRecords) {
    // Allocate memory for offset array
    long* offsets = malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for key array
    int* keys = malloc(numRecords * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Allocate memory for record structures
    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for record structures\n");
        free(offsets);
        free(keys);
        return;
    }

    // Allocate memory for hash table
    ht->buckets = malloc(10 * sizeof(Record*));
    if (!ht->buckets) {
        printf("Failed to allocate memory for hash table\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Set capacity and size of hash table
    ht->capacity = 10;
    ht->size = 0;
}

// Define function to initialize arrays with random values and names
void initArrays(long* offsets, int* keys, Record* records, int numRecords) {
    // Set seed for random number generator
    srand((unsigned int) time(NULL));

    // Generate random values and names for each record
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 1000;
        strcpy(records[i].name, "Name");
        records[i].value = rand() % 20;
    }
}

// Define function to insert record into hash table
void insertRecord(HashTable* ht, Record* record) {
    // Calculate hash value for record
    int hashValue = hash(record->key);

    // Check if hash table is full
    if (ht->size == ht->capacity) {
        // Resize hash table by doubling capacity
        ht->buckets = realloc(ht->buckets, 2 * ht->capacity * sizeof(Record*));
        ht->capacity *= 2;
    }

    // Insert record into hash table
    ht->buckets[hashValue] = record;
    ht->size++;
}

// Define function to retrieve record from hash table
Record* getRecord(HashTable* ht, int key) {
    // Calculate hash value for key
    int hashValue = hash(key);

    // Check if hash table contains record with key
    if (ht->buckets[hashValue] != NULL && ht->buckets[hashValue]->key == key) {
        return ht->buckets[hashValue];
    } else {
        return NULL;
    }
}

// Define function to free allocated memory for arrays and hash table
void freeMemory(HashTable* ht, long* offsets, int* keys, Record* records) {
    // Free memory for offset array
    free(offsets);

    // Free memory for key array
    free(keys);

    // Free memory for record structures
    free(records);

    // Free memory for hash table
    free(ht->buckets);
}

int main() {
    // Initialize hash table and arrays
    HashTable ht;
    allocateMemory(&ht, 100);
    long* offsets = malloc(100 * sizeof(long));
    int* keys = malloc(100 * sizeof(int));
    Record* records = malloc(100 * sizeof(Record));

    // Initialize arrays with random values and names
    initArrays(offsets, keys, records, 100);

    // Insert records into hash table
    for (int i = 0; i < 100; i++) {
        Record* record = &records[i];
        insertRecord(&ht, record);
    }

    // Retrieve records from hash table
    for (int i = 0; i < 100; i++) {
        int key = keys[i];
        Record* record = getRecord(&ht, key);
        if (record != NULL) {
            printf("Key: %d, Value: %d, Name: %s\n", key, record->value, record->name);
        } else {
            printf("Key not found in hash table\n");
        }
    }

    // Free allocated memory
    freeMemory(&ht, offsets, keys, records);

    return 0;
}
```
This code defines a C function that dynamically allocates memory for and initializes three arrays: one for 'long' offset values, one for 'int' keys, and one for 'record' structures. Each record structure contains a single 'int' value and a 'char' array to store a name. The function also allocates memory for a hash table using an open addressing scheme with linear probing to handle collisions.

The function uses a loop to set the value of each record's int field to a random value within a given range and stores the corresponding name in the char array. It also includes error handling for memory allocation failures, and it free allocated memory when done.

The implementation takes into account the following:
