['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>

// Macros for error handling and logging
#define ERROR(msg) { perror(msg); exit(EXIT_FAILURE); }
#define LOG(...) fprintf(stderr, __VA_ARGS__)

// Configuration parameters
const int MAX_THREADS = 1000; // Maximum number of threads to create
const int MAX_FILE_PATH_LENGTH = PATH_MAX + NAME_MAX; // Maximum length of a file path
const long CACHE_SIZE = 1024 * 1024 * 1024; // Cache size in bytes
const long MIN_CACHE_SIZE = 512 * 1024 * 1024; // Minimum cache size in bytes
const int EVICTION_INTERVAL = 3600; // Eviction interval in seconds
const int THREAD_LIMIT = 50; // Maximum number of active threads at any given time
const int CACHE_LIFETIME = 600; // Cache lifetime in seconds

// File cache data structure
typedef struct {
    char* path; // Path to the file
    void* contents; // Contents of the file
    size_t length; // Length of the file contents
    time_t modified; // Time of last modification
} file_cache_entry_t;

// Thread-safe cache data structure
typedef struct {
    pthread_mutex_t mutex; // Mutex for synchronizing access to the cache
    file_cache_entry_t* entries; // Cache entries
    size_t num_entries; // Number of cache entries
} file_cache_t;

// Initializes the file cache with a given capacity and eviction interval
void init_file_cache(file_cache_t* cache, size_t capacity, int eviction_interval) {
    cache->num_entries = 0;
    cache->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    cache->entries = malloc(sizeof(file_cache_entry_t) * capacity);
}

// Destroys the file cache and frees all resources
void destroy_file_cache(file_cache_t* cache) {
    for (size_t i = 0; i < cache->num_entries; ++i) {
        free(cache->entries[i].contents);
    }
    pthread_mutex_destroy(&cache->mutex);
    free(cache->entries);
}

// Reads the contents of a file into memory and adds it to the cache if necessary
int read_file(const char* path, size_t* length) {
    struct stat st;
    int fd = open(path, O_RDONLY);
    if (fd == -1) return errno;
    if (fstat(fd, &st) == -1) return errno;
    void* contents = malloc(st.st_size + 1);
    if (contents == NULL) {
        close(fd);
        return ENOMEM;
    }
    ssize_t nread = read(fd, contents, st.st_size);
    if (nread == -1) {
        free(contents);
        close(fd);
        return errno;
    }
    *length = nread;
    close(fd);
    // Add the file to the cache if necessary
    pthread_mutex_lock(&cache->mutex);
    bool found = false;
    for (size_t i = 0; i < cache->num_entries; ++i) {
        if (strcmp(path, cache->entries[i].path) == 0) {
            found = true;
            break;
        }
    }
    if (!found) {
        file_cache_entry_t* entry = &cache->entries[cache->num_entries++];
        entry->path = strdup(path);
        entry->contents = contents;
        entry->length = *length;
        entry->modified = time(NULL);
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Evicts entries from the cache based on least recently used strategy
void evict_entries(file_cache_t* cache) {
    if (cache->num_entries == 0) return;
    // Sort the entries by last modified time in ascending order
    qsort(cache->entries, cache->num_entries, sizeof(file_cache_entry_t),
            (int (*)(const void*, const void*))compare_entries);
    // Evict entries that are older than the eviction interval
    size_t num_to_evict = 0;
    for (size_t i = 0; i < cache->num_entries && num_to_evict == 0; ++i) {
        if (time(NULL) - cache->entries[i].modified >= EVICTION_INTERVAL) {
            num_to_evict++;
        }
    }
    if (num_to_evict == 0) return;
    // Evict the entries that are older than the eviction interval
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < num_to_evict; ++i) {
        free(cache->entries[i].contents);
        cache->entries[i] = cache->entries[--cache->num_entries];
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Compares two file cache entries based on their last modified time
int compare_entries(const file_cache_entry_t* entry1, const file_cache_entry_t* entry2) {
    return entry1->modified - entry2->modified;
}

// Thread-safe function to get the contents of a file from the cache or read it if necessary
void* get_file_contents(const char* path, size_t* length) {
    pthread_mutex_lock(&cache.mutex);
    for (size_t i = 0; i < cache->num_entries; ++i) {
        if (strcmp(path, cache->entries[i].path) == 0) {
            *length = cache->entries[i].length;
            void* contents = malloc(*length);
            memcpy(contents, cache->entries[i].contents, *length);
            pthread_mutex_unlock(&cache.mutex);
            return contents;
        }
    }
    pthread_mutex_unlock(&cache.mutex);
    read_file(path, length);
}

// Thread-safe function to get the last modified time of a file from the cache or read it if necessary
int get_file_modified(const char* path) {
    pthread_mutex_lock(&cache.mutex);
    for (size_t i = 0; i < cache->num_entries; ++i) {
        if (strcmp(path, cache->entries[i].path) == 0) {
            int modified = time(NULL) - cache->entries[i].modified;
            pthread_mutex_unlock(&cache.mutex);
            return modified;
        }
    }
    pthread_mutex_unlock(&cache.mutex);
    read_file(path, NULL);
}

// Main function that demonstrates how to use the file cache
int main() {
    file_cache_t cache;
    init_file_cache(&cache, 1024, EVICTION_INTERVAL);
    // Read a file and add it to the cache if necessary
    size_t length = 0;
    void* contents = get_file_contents("example.txt", &length);
    // Do something with the contents of the file
    free(contents);
    // Evict old entries from the cache
    evict_entries(&cache);
    // Destroy the cache and free all resources
    destroy_file_cache(&cache);
}
