        exit(1);
    }

    // Allocate space for the record array
    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the offset array with random values
