    }

    // Initialize the value array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        values[i] = rand() % (max_val - min_val) + min_val;
    }

    // Initialize each record with a random ID, weighted average value, and dynamically allocated data
    for (int i = 0; i < num_records; i++) {
