            exit(1);
        }
        for (int j = 0; j < data_len; j++) {
            records[i].data[j] = rand() % 256;
        }
    }
}

// Function to modify the file extension based on input parameters
void modify_extension(char *filename, char *output_filename) {
    // Get the length of the original filename
    int orig_len = strlen(filename);

    // If the new filename exceeds the maximum allowable length, return an error
    if (orig_len + 5 > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "New filename exceeds maximum allowable length\n");
        exit(1);
    }

    // Copy the original filename to the new filename
    strncpy(output_filename, filename, orig_len + 1);

    // Modify the file extension based on input parameters
    char *ext = ".txt";
    int ext_len = strlen(ext);
    output_filename[orig_len - 3] = '.';
    memcpy(output_filename + orig_len - 2, ext, ext_len + 1);
}
