#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define MAX_SERVERS 10
#define MAX_CONNECTIONS 50
#define MAX_DATA_RATE 1024

typedef struct {
    char *hostname;
    SSL_CTX *ssl_ctx;
    int num_connections;
    int connection_states[MAX_CONNECTIONS];
    int data_transmission_rates[MAX_CONNECTIONS];
} server_context_t;

server_context_t *create_server_context(char *hostname) {
    server_context_t *ctx = (server_context_t *)malloc(sizeof(server_context_t));
    if (!ctx) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    ctx->hostname = strdup(hostname);
    ctx->ssl_ctx = SSL_CTX_new(TLS_method());
    if (!ctx->ssl_ctx) {
        printf("SSL context creation failed\n");
        free(ctx->hostname);
        free(ctx);
        return NULL;
    }
    SSL_CTX_set_cipher_list(ctx->ssl_ctx, "HIGH:!aNULL:!MD5");
    return ctx;
}

void destroy_server_context(server_context_t *ctx) {
    if (ctx) {
        SSL_CTX_free(ctx->ssl_ctx);
        free(ctx->hostname);
        free(ctx);
    }
}

int add_connection(server_context_t *ctx, int client_fd, SSL *ssl, int state, int data_rate) {
    if (ctx->num_connections >= MAX_CONNECTIONS) {
        return -1;
    }
    ctx->connection_states[ctx->num_connections] = state;
    ctx->data_transmission_rates[ctx->num_connections] = data_rate;
    SSL_set_fd(ssl, client_fd);
    return 0;
}

void remove_connection(server_context_t *ctx, int idx) {
    if (idx < 0 || idx >= ctx->num_connections) {
        return;
    }
    SSL_free(ctx->ssl_ctx);
    ctx->num_connections--;
}

void manage_server_contexts() {
    server_context_t *server_contexts[MAX_SERVERS];
    int num_servers = 0;
    for (int i = 0; i < MAX_SERVERS; i++) {
        server_contexts[i] = create_server_context("example.com");
        if (!server_contexts[i]) {
            continue;
        }
        num_servers++;
    }

    while (1) {
        for (int i = 0; i < num_servers; i++) {
            server_context_t *ctx = server_contexts[i];
            int client_fd = accept(ctx->ssl_ctx->fd, NULL, NULL);
            if (client_fd == -1) {
                continue;
            }
            SSL *ssl = SSL_new(ctx->ssl_ctx);
            if (!ssl) {
                close(client_fd);
                continue;
            }
            int state = SSL_get_state(ssl);
            int data_rate = 0;
            add_connection(ctx, client_fd, ssl, state, data_rate);
        }

        for (int i = 0; i < num_servers; i++) {
            server_context_t *ctx = server_contexts[i];
            int idx = 0;
            while (idx < ctx->num_connections) {
                SSL *ssl = ctx->connection_states[idx];
                if (SSL_get_state(ssl) == SSL_ERROR) {
                    remove_connection(ctx, idx);
                    continue;
                }
                int data_rate = SSL_read(ssl, NULL, 0);
                ctx->data_transmission_rates[idx] += data_rate;
                idx++;
            }
        }
    }
