// Define a cache structure to store recently accessed records
struct Cache {
    int count;
    Record* records[CACHE_SIZE];
};

// Initialize the cache
Cache* cache = NULL;

void initialize() {
    // Allocate memory for the arrays
    record_size = 100 * sizeof(Record);
    keys_size = 100 * sizeof(int);

    records = (Record*)malloc(record_size);
    keys = (int*)malloc(keys_size);

    // Initialize the cache
