    free(records);
    free(keys);

    // Free the memory for the cache
    free(cache);
}

void allocate_and_initialize(size_t size) {
    // Check if the new size is less than or equal to the current size
    if (size <= record_size && size <= key_size) return;

    // Deallocate the existing memory
    deallocate();

    // Allocate new memory for the arrays
    record_size = size * sizeof(Record);
    keys_size = size * sizeof(int);

    records = (Record*)malloc(record_size);
    keys = (int*)malloc(keys_size);

    // Initialize the cache
    cache = (Cache*)malloc(sizeof(Cache));
    memset(cache, 0, sizeof(Cache));
}

void set_key(int index, int key) {
    // Check if the index is within bounds
    if (index < 0 || index >= record_size / sizeof(Record)) return;

    // Set the key for the specified record
    records[index].key = key;
}

void set_offset(int index, long offset) {
    // Check if the index is within bounds
    if (index < 0 || index >= record_size / sizeof(Record)) return;

    // Set the offset for the specified record
    records[index].offset = offset;
}

void add_record() {
    // Get a random key and offset
    int key = rand() % 10000 + 1;
    long offset = rand() % 100000000 + 1;

    // Add the record to the end of the array
    records[record_size / sizeof(Record)].key = key;
    records[record_size / sizeof(Record)].offset = offset;

    // Increment the size of the arrays
    record_size += sizeof(Record);
    keys_size += sizeof(int);
}

void remove_record() {
    // Check if there are any records to remove
    if (record_size <= 0) return;

    // Get the index of the last record
    int index = record_size / sizeof(Record) - 1;

    // Remove the last record from the array
    records[index].key = 0;
    records[index].offset = 0;

    // Decrement the size of the arrays
    record_size -= sizeof(Record);
    keys_size -= sizeof(int);
}

void update_record() {
    // Get a random index and new key and offset
    int index = rand() % (record_size / sizeof(Record));
    int key = rand() % 10000 + 1;
    long offset = rand() % 100000000 + 1;

    // Update the record at the specified index
    records[index].key = key;
    records[index].offset = offset;
}

void clear_cache() {
