    memset(cache, 0, sizeof(Cache));
}

int get_key(int index) {
    // Check if the index is within bounds
    if (index < 0 || index >= record_size / sizeof(Record)) return -1;

    // Get the key for the specified record
    return records[index].key;
}

long get_offset(int index) {
    // Check if the index is within bounds
    if (index < 0 || index >= record_size / sizeof(Record)) return -1;

    // Get the offset for the specified record
    return records[index].offset;
}

void cache_record(int index) {
    // Check if the index is within bounds
    if (index < 0 || index >= record_size / sizeof(Record)) return;

    // Add the record to the cache
    cache->records[cache->count++] = &records[index];
}

void evict_lru_record() {
    // Check if there are any records in the cache
    if (cache->count == 0) return;

    // Find the least recently used record
    int lru = -1;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (lru == -1 || cache->records[i]->last_accessed < cache->records[lru]->last_accessed) {
            lru = i;
        }
    }

    // Evict the least recently used record from the cache
    cache->count--;
}
