int main(void) {
    // Declare variables for socket and connection
    int sock, conn;

    // Create a socket
    if ((sock = socket(AF_UNIX, SOCK_STREAM, 0)) == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to a specific address and port
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(5000);
    if (bind(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock, 3) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Accept an incoming connection
    struct sockaddr_in client_addr;
    memset(&client_addr, 0, sizeof(client_addr));
    int clen = sizeof(client_addr);
    if ((conn = accept(sock, (struct sockaddr*)&client_addr, (socklen_t*)&clen)) == -1) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays for offset values and keys
    int* offsets = malloc(sizeof(int) * 200);
    int* keys = malloc(sizeof(int) * 200);
    memset(offsets, 0, sizeof(int) * 200);
    memset(keys, 0, sizeof(int) * 200);

