function traverseDOM(node, selector) {
    var elements = [];

    // If the current node matches the selector, add it to the array of elements
    if (node.matches(selector)) {
        elements.push(node);
    }

    // Recursively traverse the child nodes of the current node
    for (var i = 0; i < node.childNodes.length; i++) {
        elements = elements.concat(traverseDOM(node.childNodes[i], selector));
    }

    return elements;
}
