// Define a record structure to store offset and key values
typedef struct Record {
    long offset;
    int key;
} Record;

// Establish a connection to the remote address using a Unix socket channel
int establish_connection(const char *remote_addr) {
    // Check if there are available file descriptors
    if (getdtablesize() < 2) {
        perror("Error: No available file descriptors");
        return -1;
    }

    // Create a socket and connect to the remote address
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Error: Socket creation failed");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, remote_addr, &server_addr.sin_addr) <= 0) {
        perror("Error: Invalid IP address");
        return -1;
    }

    // Connect to the remote address
    int ret = connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        perror("Error: Connection failed");
        close(sock);
        return -1;
    }

    // Initialize two arrays for offset and key values
    long *offset_values = malloc(sizeof(long) * 10);
    if (!offset_values) {
        perror("Error: Memory allocation failed");
        close(sock);
        return -1;
    }

    int *key_values = malloc(sizeof(int) * 10);
    if (!key_values) {
        perror("Error: Memory allocation failed");
        free(offset_values);
        close(sock);
        return -1;
    }

    // Initialize an array of record structures
    Record *records = malloc(sizeof(Record) * 10);
    if (!records) {
        perror("Error: Memory allocation failed");
        free(offset_values);
        free(key_values);
        close(sock);
        return -1;
    }

    // Set the value of each record's int field to a random value within a given range
    for (int i = 0; i < 10; i++) {
        records[i].offset = offset_values[i];
        records[i].key = key_values[i];
    }

    return sock;
}

// Close the connection to the remote address
void close_connection(int sock) {
    // Check if the socket is valid
    if (sock < 0) {
        perror("Error: Invalid socket");
        return;
    }

    // Close the socket
    close(sock);
}
