// Function to dynamically manage a list of UE contexts
void manage_ue_contexts(char **imsi_list, int num_uces) {
    // Initialize the list of UE contexts
    ue_context_t *ue_contexts = (ue_context_t *)malloc(num_uces * sizeof(ue_context_t));
    for (int i = 0; i < num_uces; i++) {
        // Allocate memory for the UE context structure
        ue_contexts[i].imsi = strdup(imsi_list[i]);
        ue_contexts[i].num_active_bearers = 0;
        ue_contexts[i].active_bearer_ids = (int *)malloc(1 * sizeof(int));
        ue_contexts[i].qos_parameters = (float *)malloc(1 * sizeof(float));
    }

    // Check for expired UE contexts and remove them from the list
    time_t current_time;
    time(&current_time);
    for (int i = 0; i < num_uces; i++) {
        if (ue_contexts[i].last_activity_timestamp + 30 * 60 < current_time) { // 30 minutes
            remove_ue_context(i);
            i--; // Decrement index since we removed an element from the list
        }
    }
}

// Function to add a new UE context to the list
void add_ue_context(char *imsi) {
    int num_uces = sizeof(ue_contexts) / sizeof(ue_context_t);
    if (num_uces == 0) { // No existing UE contexts, create a new one
        ue_context_t new_context;
        new_context.imsi = strdup(imsi);
        new_context.num_active_bearers = 0;
        new_context.active_bearer_ids = (int *)malloc(1 * sizeof(int));
        new_context.qos_parameters = (float *)malloc(1 * sizeof(float));
        ue_contexts[num_uces] = new_context;
    } else { // Check if the IMSI already exists in the list
        for (int i = 0; i < num_uces; i++) {
            if (strcmp(imsi, ue_contexts[i].imsi) == 0) { // UE context already exists
                return; // Do not add a new UE context
            }
        }
        // Add a new UE context to the list
        ue_context_t new_context;
        new_context.imsi = strdup(imsi);
        new_context.num_active_bearers = 0;
        new_context.active_bearer_ids = (int *)malloc(1 * sizeof(int));
        new_context.qos_parameters = (float *)malloc(1 * sizeof(float));
        ue_contexts[num_uces] = new_context;
    }
}

// Function to remove an existing UE context from the list
void remove_ue_context(int index) {
    free(ue_contexts[index].imsi);
    free(ue_contexts[index].active_bearer_ids);
    free(ue_contexts[index].qos_parameters);
    for (int i = index; i < num_uces - 1; i++) {
        ue_contexts[i] = ue_contexts[i + 1];
    }
    num_uces--;
}

