// JavaScript function that recursively traverses a DOM tree and returns a list of elements that match a given selector
function getElementsBySelector(root, selector) {
    // Initialize an empty array to store the matched elements
    let matched_elements = [];

    // Recursively traverse the DOM tree, starting from the root element
    function traverseDOM(element) {
        // Check if the current element matches the given selector
        if (matchesSelector(element, selector)) {
            // Add the matching element to the list of matched elements
            matched_elements.push(element);
        }

        // Recursively traverse the children of the current element
        for (let child of element.children) {
            traverseDOM(child);
        }
    }

    // Start the traversal from the root element
    traverseDOM(root);

    return matched_elements;
}

// Helper function to check if an element matches a given selector
function matchesSelector(element, selector) {
    // Check if the current element has the specified tag name
    if (selector.startsWith("#")) {
        return element.id === selector.substring(1);
    } else if (selector.startsWith(".")) {
        return element.classList.contains(selector.substring(1));
    } else {
        return element.tagName === selector;
    }
}']

