# Define the number of worker processes for parallel processing
WORKER_PROCESSES = cpu_count() - 1

class DistributedDataProcessingFramework:
    def __init__(self):
        # Initialize the messaging queue
        self.queue = []

        # Initialize the list of nodes in the cluster
        self.nodes = []

        # Initialize the list of tasks to be processed
        self.tasks = []

    def add_node(self, node):
        """Add a new node to the cluster."""
        self.nodes.append(node)

    def remove_node(self, node):
        """Remove a node from the cluster."""
        if node in self.nodes:
            self.nodes.remove(node)

    def add_task(self, task):
        """Add a new task to be processed."""
        self.tasks.append(task)

    def remove_task(self, task):
        """Remove a task from the list of tasks to be processed."""
        if task in self.tasks:
            self.tasks.remove(task)

    def distribute_tasks(self, num_nodes=0):
        """Distribute tasks across the nodes in the cluster."""
        # Get the number of nodes to use for distribution, defaulting to all available nodes
        if num_nodes == 0:
            num_nodes = len(self.nodes)

        # Distribute tasks across the nodes, ensuring each node has a task assigned
        tasks_per_node = int(len(self.tasks) / num_nodes)
        for i in range(num_nodes):
            self.queue.append(self.tasks[i * tasks_per_node: (i + 1) * tasks_per_node])

    def process_tasks(self, pool=None):
        """Process the distributed tasks."""
        # Get the number of worker processes for parallel processing
        if pool is None:
            pool = Pool(WORKER_PROCESSES)

        # Process the tasks in parallel using the worker processes
        results = []
        for node, tasks in self.queue:
            for task in tasks:
                try:
                    result = task()
                except Exception as e:
                    print(f"Error processing task {task}: {e}")
                else:
                    results.append((node, task, result))

        # Return the results of the processed tasks
        return results

    def aggregate_results(self):
        """Aggregate the results of the processed tasks."""
        # Initialize an empty dictionary to store the aggregated results
        aggregated_results = {}

        # Aggregate the results of each task across all nodes
        for node, task, result in self.process_tasks():
            if task not in aggregated_results:
                aggregated_results[task] = [result]
            else:
                aggregated_results[task].append(result)

        # Return the aggregated results
        return aggregated_results

    def handle_node_failure(self, node):
        """Handle a failed node by reassigning tasks to other nodes in the cluster."""
        # Get the list of tasks assigned to the failed node
        failed_tasks = []
        for task in self.queue:
            if task[0] == node:
                failed_tasks.append(task)

        # Remove the failed tasks from the queue
        for failed_task in failed_tasks:
            self.queue.remove(failed_task)

        # Reassign the failed tasks to other nodes in the cluster
        for task in failed_tasks:
            self.add_node(task[0])
            self.add_task(task[1])

    def handle_network_latency(self):
        """Handle network latency by retrying tasks that were not completed successfully."""
        # Get the list of tasks that were not completed successfully
        failed_tasks = []
        for task in self.queue:
