std::string selectedAttack;

void selectAttack() {
    // Load attack data from external JSON file
    std::ifstream ifs("/data/attacks.json");
    json attacksJson;
    if (!ifs) {
        // Handle error: file missing or corrupted
        std::cout << "Error loading attack data" << std::endl;
        return;
    } else {
        ifs >> attacksJson;
    }

    // Randomly select an attack from the available ones
    int numAttacks = attacksJson.size();
    int selectedIndex = rand() % numAttacks;
    selectedAttack = attacksJson[selectedIndex]["name"].get<std::string>();

    // Wait for cooldown period to elapse before allowing next attack
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [&] { return !attackReady; });

    // Mark attack as ready and print selected attack to console
    attackReady = true;
    attackNum++;
    std::cout << "Attack #" << attackNum << ": " << selectedAttack << std::endl;
}

void deallocateMemory() {
    // Release allocated memory for attack data
    if (attacksJson.is_object()) {
        attacksJson.clear();
    }

    // Log memory deallocation
    std::cout << "Deallocated attack data" << std::endl;
}

int main() {
    while (true) {
        selectAttack();

        // Wait for cooldown period to elapse before allowing next attack
