  function filterAndTransformNodes(root, filterCriteria, applyTransformation) {
    const transformedNodes = [];

    // Recursively traverse the DOM tree and apply transformations based on filter criteria
    function traverse(node) {
      if (matchCriteria(node, filterCriteria)) {
        transformedNodes.push(applyTransformation(node));
      }

      for (const child of node.children) {
        traverse(child);
      }
    }

    // Helper function to check if a node matches the specified filter criteria
    function matchCriteria(node, filterCriteria) {
      const selector = filterCriteria.split(' ')[0];
      const transform = filterCriteria.split(' ')[1];

      if (selector === '*') {
        return true;
      } else if (node.tagName === selector) {
        return true;
      }
    }

    // Helper function to apply a transformation on an element
    function applyTransformation(element) {
      const transformedElement = document.createElement(element.tagName);
      for (const attribute of element.attributes) {
        transformedElement.setAttribute(attribute.name, attribute.value);
      }

      if (transform === 'uppercase') {
        transformedElement.textContent = element.textContent.toUpperCase();
      }

      return transformedElement;
    }

    traverse(root);
    return transformedNodes;
  }
