    int value;
    Record* records;
    OffsetArray offsets;
    KeyArray keys;
} DataEntry;

// Define the function for creating and populating an array of 'record' structures
void populateRecords(size_t numRecords, size_t recordSize) {
    // Allocate memory for the records array
    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the records array with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; i++) {
        records[i].key = rand() % recordSize;
    }

    // Allocate memory for the offset array
    OffsetArray offsets = malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        free(records);
        return;
    }

    // Initialize the offset array with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; i++) {
        offsets[i] = rand() % recordSize;
    }

    // Allocate memory for the key array
    KeyArray keys = malloc(numRecords * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(records);
        free(offsets);
        return;
    }

    // Initialize the key array with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; i++) {
        keys[i] = rand() % recordSize;
    }

    // Allocate memory for the data entry array
    DataEntry* entries = malloc(numRecords * sizeof(DataEntry));
    if (!entries) {
        printf("Error: Failed to allocate memory for data entry array\n");
        free(records);
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the data entry array with the appropriate values
    for (size_t i = 0; i < numRecords; i++) {
        entries[i].value = records[i].key;
        entries[i].records = &records[i];
        entries[i].offsets = &offsets[i];
        entries[i].keys = &keys[i];
    }

    // Free the allocated memory
    free(records);
    free(offsets);
    free(keys);
}
