```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold UE context information
struct UEContext {
    char *imsi; // IMSI identifier of the UE
    struct RadioBearerList {
        int num_active_bearers; // number of active radio bearers
        struct RadioBearer {
            char *qos_params; // QoS parameters for this radio bearer
            int bearer_id; // ID of the radio bearer
        } *radio_bearers[50]; // array of active radio bearers
    } active_bearers; // list of active radio bearers for this UE
};

// Define a linked list data structure to hold the UE contexts
struct UELinkedList {
    struct UEContext *next; // pointer to the next UE context in the list
    struct UEContext ue_context; // the actual UE context information
};

// Define a function to add a new UE context to the list
int add_ue(char *imsi, int bearer_id, char *qos_params) {
    struct UELinkedList *new_entry = (struct UELinkedList *)malloc(sizeof(struct UELinkedList));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    new_entry->ue_context.imsi = imsi; // copy the IMSI identifier to the structure
    new_entry->ue_context.active_bearers.num_active_bearers = 1; // set the number of active radio bearers to 1
    new_entry->ue_context.active_bearers.radio_bearers[0].bearer_id = bearer_id; // copy the radio bearer ID to the structure
    new_entry->ue_context.active_bearers.radio_bearers[0].qos_params = qos_params; // copy the QoS parameters to the structure
    // add the new entry to the linked list
    if (list_head == NULL) {
        list_head = new_entry;
        return 0;
    } else {
        struct UELinkedList *last_entry = list_head;
        while (last_entry->next != NULL) {
            last_entry = last_entry->next;
        }
        last_entry->next = new_entry;
        return 0;
    }
}

// Define a function to remove a UE context from the list
int remove_ue(char *imsi) {
    struct UELinkedList *prev_entry = NULL, *current_entry = list_head;
    while (current_entry != NULL && strcmp(current_entry->ue_context.imsi, imsi) != 0) {
        prev_entry = current_entry;
        current_entry = current_entry->next;
    }
    if (current_entry == NULL) {
        return -1; // UE context not found in the list
    } else {
        if (prev_entry != NULL) {
            prev_entry->next = current_entry->next;
        } else {
            list_head = current_entry->next;
        }
        free(current_entry); // free the memory used by the UE context
        return 0;
    }
}

// Define a function to update the QoS parameters for a radio bearer in an UE context
int update_qos_params(char *imsi, int bearer_id, char *new_qos_params) {
    struct UELinkedList *current_entry = list_head;
    while (current_entry != NULL && strcmp(current_entry->ue_context.imsi, imsi) != 0) {
        current_entry = current_entry->next;
    }
    if (current_entry == NULL) {
        return -1; // UE context not found in the list
    } else {
        for (int i = 0; i < current_entry->ue_context.active_bearers.num_active_bearers; i++) {
            if (current_entry->ue_context.active_bearers.radio_bearers[i].bearer_id == bearer_id) {
                free(current_entry->ue_context.active_bearers.radio_bearers[i].qos_params); // free the old memory used by the QoS parameters
                current_entry->ue_context.active_bearers.radio_bearers[i].qos_params = new_qos_params; // copy the new QoS parameters to the structure
                return 0;
            }
        }
        return -2; // radio bearer ID not found in the list
    }
}

// Define a function to check for stale radio bearers and remove them from the list
int check_stale_radio_bearers(int check_interval) {
    struct UELinkedList *current_entry = list_head;
    while (current_entry != NULL) {
        int num_stale_bearers = 0; // number of stale radio bearers in the current UE context
        for (int i = 0; i < current_entry->ue_context.active_bearers.num_active_bearers; i++) {
            if (current_entry->ue_context.active_bearers.radio_bearers[i].last_used_time + check_interval < time(NULL)) { // check if the radio bearer has not been used for the specified interval
                num_stale_bearers++;
            } else {
                current_entry->ue_context.active_bearers.radio_bearers[i].last_used_time = time(NULL); // update the last used time of the radio bearer
            }
        }
        if (num_stale_bearers > 0) { // remove the stale radio bearers from the list
            struct UELinkedList *new_entry = current_entry;
            while (new_entry != NULL && new_entry->ue_context.active_bearers.num_active_bearers > num_stale_bearers) {
                new_entry = new_entry->next;
            }
            if (new_entry == NULL) { // no more stale radio bearers in the list
                return -1;
            } else {
                for (int i = 0; i < num_stale_bearers; i++) {
                    free(current_entry->ue_context.active_bearers.radio_bearers[i].qos_params); // free the memory used by the QoS parameters of the stale radio bearer
                    current_entry->ue_context.active_bearers.num_active_bearers--;
                }
            }
        }
        current_entry = current_entry->next;
    }
    return 0;
}

// Define a function to get the number of active radio bearers in an UE context
int get_num_active_radio_bearers(char *imsi) {
    struct UELinkedList *current_entry = list_head;
    while (current_entry != NULL && strcmp(current_entry->ue_context.imsi, imsi) != 0) {
        current_entry = current_entry->next;
    }
    if (current_entry == NULL) {
