    while (current_entry != NULL && strcmp(current_entry->ue_context.imsi, imsi) != 0) {
        current_entry = current_entry->next;
    }
    if (current_entry == NULL) {
        return -1; // UE context not found in the list
    } else {
        for (int i = 0; i < current_entry->ue_context.active_bearers.num_active_bearers; i++) {
            if (current_entry->ue_context.active_bearers.radio_bearers[i].bearer_id == bearer_id) {
                return current_entry->ue_context.active_bearers.radio_bearers[i].qos_params;
            }
        }
        return -2; // radio bearer ID not found in the list
    }
}

