// 링크드 리스트를 사용하여 UE contexts을 관리합니다.
typedef struct {
    char *imsi;
    int num_active_radio_bearers;
    radio_bearer_t active_radio_bearers[MAX_NUM_RADIO_BEARERS];
} ue_context_t;

typedef struct {
    ue_context_t *ue_contexts;
    int num_ue_contexts;
} ue_context_manager_t;

// 링크드 리스트를 사용하여 UE context를 관리합니다.
int add_ue_context(char *imsi, int num_active_radio_bearers, radio_bearer_t *active_radio_bearers) {
    // 1. imsi를 통해 이미 존재하는 UE context를 검사합니다.
    for (int i = 0; i < manager->num_ue_contexts; i++) {
        if (!strcmp(manager->ue_contexts[i].imsi, imsi)) {
            return -1; // UE context가 이미 존재합니다.
        }
    }

    // 2. 새로운 UE context를 추가합니다.
    manager->ue_contexts[manager->num_ue_contexts].imsi = imsi;
    manager->ue_contexts[manager->num_ue_contexts].num_active_radio_bearers = num_active_radio_bearers;
    for (int i = 0; i < num_active_radio_bearers; i++) {
        manager->ue_contexts[manager->num_ue_contexts].active_radio_bearers[i] = active_radio_bearers[i];
    }

    // 3. UE context의 수를 증가시킵니다.
    manager->num_ue_contexts++;

    return 0;
}

// 링크드 리스트를 사용하여 UE context를 관리합니다.
int remove_ue_context(char *imsi) {
    // 1. imsi를 통해 이미 존재하는 UE context를 검사합니다.
    for (int i = 0; i < manager->num_ue_contexts; i++) {
        if (!strcmp(manager->ue_contexts[i].imsi, imsi)) {
            break;
        }
    }
    // UE context가 존재하지 않는다면 -1을 반환합니다.
    if (i == manager->num_ue_contexts) return -1;

    // 2. 해당 UE context를 삭제합니다.
    for (int j = i + 1; j < manager->num_ue_contexts; j++) {
        manager->ue_contexts[j - 1] = manager->ue_contexts[j];
    }

    // 3. UE context의 수를 감소시킵니다.
    manager->num_ue_contexts--;

    return 0;
}

// 링크드 리스트를 사용하여 UE context를 관리합니다.
int get_ue_context(char *imsi, int *num_active_radio_bearers, radio_bearer_t *active_radio_bearers) {
    // 1. imsi를 통해 이미 존재하는 UE context를 검사합니다.
    for (int i = 0; i < manager->num_ue_contexts; i++) {
        if (!strcmp(manager->ue_contexts[i].imsi, imsi)) {
            break;
        }
    }
    // UE context가 존재하지 않는다면 -1을 반환합니다.
    if (i == manager->num_ue_contexts) return -1;

    // 2. 해당 UE context에 대한 정보를 복사합니다.
    *num_active_radio_bearers = manager->ue_contexts[i].num_active_radio_bearers;
    for (int j = 0; j < *num_active_radio_bearers; j++) {
        active_radio_bearers[j] = manager->ue_contexts[i].active_radio_bearers[j];
    }

    return 0;
}
