// Define a function to dynamically allocate memory for an array of records and initialize it with random values
Record *allocate_record_array(int size) {
    // Allocate memory for the array
    Record *arr = malloc(size * sizeof(Record));
    if (arr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Set the values of each element in the array to random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        arr[i].value = rand() % 100 + 1;
    }

    return arr;
}

// Define a function to track the total allocated memory and dynamically adjust the size of the arrays if necessary
void *track_memory(void **arr, int size) {
    // Check if the array is NULL or has reached its maximum size
    if (arr == NULL || size >= 1000000) {
        return NULL;
    }

    // Increment the size of the array by a factor of 2
    size *= 2;

    // Reallocate memory for the array
    void *tmp = realloc(arr, size);
    if (tmp == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    arr = tmp;

    return arr;
}

// Define a function to handle error conditions where memory allocation fails gracefully
void handle_error(void **arr, int size) {
    // Check if the array is NULL or has reached its maximum size
    if (arr == NULL || size >= 1000000) {
        return;
    }

    // Free any partially allocated data
    free(arr);

    // Set the array to NULL
    arr = NULL;
}

// Define a function to integrate this function into an existing system where it needs to be called multiple times with different parameters
