    if (long_arr == NULL || int_arr == NULL || record_arr == NULL) {
        handle_error(&long_arr, &int_arr, &record_arr);
        return;
    }

    // Track the total allocated memory and dynamically adjust the size of the arrays if necessary
    long_arr = track_memory(&long_arr, size);
    int_arr = track_memory(&int_arr, size);
    record_arr = track_memory(&record_arr, size);

    // Print the values of each element in the arrays
    printf("Long array: ");
    for (int i = 0; i < size; i++) {
        printf("%ld ", long_arr[i]);
    }
    printf("\n");

    printf("Int array: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", int_arr[i]);
    }
    printf("\n");

    printf("Record array: ");
    for (int i = 0; i < size; i++) {
        printf("{%d} ", record_arr[i].value);
    }
    printf("\n");

    // Free the allocated memory
    free(long_arr);
    free(int_arr);
    free(record_arr);
}

// Call the function to demonstrate its use
