    // Locking mechanism to ensure thread-safe access
    mutex attackSelectionMutex;
    bool locked = false;
    while (!locked) {
        locked = attackSelectionMutex.try_lock();
        if (locked) break;
        this_thread::sleep_for(chrono::milliseconds(10));
    }

    // Cooldown period and attack selection logic
    const int COOLDOWN_PERIOD = 9000;
    while (*cooldownTimer < COOLDOWN_PERIOD) {
        *cooldownTimer += 100;
        this_thread::sleep_for(chrono::milliseconds(10));
    }
    *cooldownTimer = 0;

    int attackNum = rand() % 2 + 1; // Randomly select an attack from 1 to 2

    // Logging mechanisms for memory allocation and deallocation
    cout << "Attack selection: " << attackNum << endl;

    // Cleanup mechanism for allocated memory
    free(cooldownTimer);

    attackSelectionMutex.unlock();
}
