    // Listen for incoming connections on the network server socket
    if (listen(ctx->socketFd, SOMAXCONN) < 0) {
        SSL_CTX_free(ctx->sslCtx);
        return -8;
    }

    // Start a new thread for the network server and initialize the SSL context
    pthread_t serverThread;
    ret = pthread_create(&serverThread, NULL, startServerThread, ctx);
    if (ret < 0) return ret;

    return 0;
}

