### Network client implementation

The network client is responsible for establishing a connection with the server, sending messages to the server, and receiving responses from the server. It uses a TCP socket to communicate with the server and an SSL context to handle the encryption of the communication. The client also maintains a list of the servers it has connected to in order to support multiple connections at once.

The following is an example implementation of the network client:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

// The maximum length of a message that can be sent to the server
#define MAX_MESSAGE_LENGTH 1024

// A structure to represent the context of a connection with a server
struct ServerContext {
    SSL_CTX* sslCtx; // The SSL context for this connection
    int socketFd; // The file descriptor for the socket used for this connection
};

// A list of all servers that the client has connected to
struct ServerList {
    struct ServerContext** servers; // An array of pointers to the server contexts
    size_t count; // The number of servers in the list
};

// Creates a new SSL context for a connection with a server
SSL_CTX* createSslContext(char* hostname, int port) {
    SSL_CTX* sslCtx = SSL_CTX_new(TLSv1_2_client_method());
    if (sslCtx == NULL) {
        printf("Failed to create SSL context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }
    // Load the server's certificate and private key into the SSL context
    if (!SSL_CTX_use_certificate_file(sslCtx, "server.crt", SSL_FILETYPE_PEM)) {
        printf("Failed to load server certificate: %s\n", ERR_error_string(ERR_get_error(), NULL));
        SSL_CTX_free(sslCtx);
        return NULL;
    }
    if (!SSL_CTX_use_PrivateKey_file(sslCtx, "server.key", SSL_FILETYPE_PEM)) {
        printf("Failed to load server private key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        SSL_CTX_free(sslCtx);
        return NULL;
    }
    return sslCtx;
}

// Connects to a server using the specified SSL context and returns the file descriptor for the connection
int connectToServer(SSL_CTX* sslCtx, char* hostname, int port) {
    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port);
    if (inet_pton(AF_INET, hostname, &serverAddr.sin_addr) <= 0) {
        printf("Failed to resolve server address: %s\n", strerror(errno));
        return -1;
    }
    int socketFd = socket(AF_INET, SOCK_STREAM, 0);
    if (socketFd < 0) {
        printf("Failed to create socket: %s\n", strerror(errno));
        return -1;
    }
    // Connect to the server using the SSL context
    int ret = SSL_connect(sslCtx, socketFd);
    if (ret < 0) {
        printf("Failed to connect: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(socketFd);
        return -1;
    }
    return socketFd;
}

// Reads a message from the server and returns it as a string
char* readMessageFromServer(int socketFd) {
    char buffer[MAX_MESSAGE_LENGTH];
    size_t bytesRead = SSL_read(socketFd, buffer, MAX_MESSAGE_LENGTH);
    if (bytesRead < 0) {
        printf("Failed to read message: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }
    // Create a new string with the message
    char* message = malloc((bytesRead + 1) * sizeof(char));
    if (message == NULL) {
        printf("Failed to allocate memory for message\n");
        return NULL;
    }
    memcpy(message, buffer, bytesRead);
    message[bytesRead] = '\0';
    return message;
}

// Sends a message to the server and returns the response as a string
char* sendMessageToServer(int socketFd, char* message) {
    int ret = SSL_write(socketFd, message, strlen(message));
    if (ret < 0) {
        printf("Failed to write message: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }
    return readMessageFromServer(socketFd);
}

// Creates a new server list with the specified number of servers
struct ServerList* createServerList(size_t count) {
    struct ServerList* list = malloc(sizeof(struct ServerList));
    if (list == NULL) {
        printf("Failed to allocate memory for server list\n");
        return NULL;
    }
    list->servers = malloc(count * sizeof(struct ServerContext*));
    if (list->servers == NULL) {
        printf("Failed to allocate memory for server list\n");
        free(list);
        return NULL;
    }
    list->count = count;
    return list;
}

// Adds a new server to the server list
void addServerToList(struct ServerList* list, SSL_CTX* sslCtx, int socketFd) {
    if (list == NULL || sslCtx == NULL || socketFd < 0) {
        printf("Invalid arguments\n");
        return;
    }
    // If the list is full, double its size
    if (list->count == 0) {
        list->servers = realloc(list->servers, (list->count * 2 + 1) * sizeof(struct ServerContext*));
        if (list->servers == NULL) {
            printf("Failed to allocate memory for server list\n");
            return;
        }
    }
    // Create a new server context and add it to the list
    struct ServerContext* server = malloc(sizeof(struct ServerContext));
    if (server == NULL) {
        printf("Failed to allocate memory for server context\n");
        return;
    }
    server->sslCtx = sslCtx;
    server->socketFd = socketFd;
    list->servers[list->count++] = server;
}

// Removes a server from the list by its index
void removeServerFromList(struct ServerList* list, size_t index) {
    if (list == NULL || index >= list->count) {
        printf("Invalid arguments\n");
        return;
    }
    // Remove the server and free its memory
    struct ServerContext* server = list->servers[index];
    SSL_free(server->sslCtx);
    close(server->socketFd);
    free(server);
    // Shift the remaining servers to fill the gap
    for (size_t i = index; i < list->count - 1; i++) {
        list->servers[i] = list->servers[i + 1];
    }
    list->count--;
}

// Disconnects from a server by its file descriptor
void disconnectFromServer(struct ServerList* list, int socketFd) {
    if (list == NULL || socketFd < 0) {
        printf("Invalid arguments\n");
        return;
    }
    // Find the index of the server with the specified file descriptor and remove it from the list
    size_t index = 0;
    for (; index < list->count; index++) {
        if (list->servers[index]->socketFd == socketFd) {
            break;
        }
    }
    if (index == list->count) {
        printf("Server not found\n");
        return;
    }
    removeServerFromList(list, index);
}

// Disconnects from all servers in the list
void disconnectFromAllServers(struct ServerList* list) {
    if (list == NULL) {
        printf("Invalid arguments\n");
        return;
    }
    for (size_t i = 0; i < list->count; i++) {
        SSL_free(list->servers[i]->sslCtx);
        close(list->servers[i]->socketFd);
        free(list->servers[i]);
    }
    free(list->servers);
    list->servers = NULL;
}

