    SSL_CTX* ctx2 = SSL_CTX_new(TLSv1_client_method());
    if (ctx2 == NULL) {
        printf("Failed to create SSL context\n");
        return 1;
    }
    int socketFd2 = connectToServer("example.com", 443);
    addServerToList(list, ctx2, socketFd2);
    // Disconnect from all servers in the list
    disconnectFromAllServers(list);
    // Free the server list and its memory
    free(list);
    return 0;
}
```

