int connectToRemoteAddress(char *ip, int port) {
    // Create a new socket file descriptor
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket == -1) {
        perror("socket");
        return -1;
    }

    // Set the socket to non-blocking mode
    int flags = fcntl(socket, F_GETFL, 0);
    if (flags == -1 || fcntl(socket, F_SETFL, flags | O_NONBLOCK) == -1) {
        perror("fcntl");
        close(socket);
        return -1;
    }

    // Connect to the remote address
    struct sockaddr_in serverAddr = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr = inet_addr(ip)
    };
    if (connect(socket, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) == -1) {
        perror("connect");
        close(socket);
        return -1;
    }

    // Wait for the connection to be established
    struct pollfd p = { .fd = socket, .events = POLLIN };
    int ret = poll(&p, 1, -1);
    if (ret == -1) {
        perror("poll");
        close(socket);
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Connection timed out\n");
        close(socket);
        return -1;
    }

    // Check if the connection was successful
    int error = 0;
    socklen_t len = sizeof(error);
    getsockopt(socket, SOL_SOCKET, SO_ERROR, &error, &len);
    if (error != 0) {
        perror("connect");
        close(socket);
        return -1;
    }

    // Add the connection to the list of open connections
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].socket == -1) {
            connections[i].socket = socket;
            strcpy(connections[i].ip, ip);
            break;
        }
    }

    return 0;
}

// A function to manage the data transfers efficiently by implementing chunked transfer encoding and managing buffer sizes to prevent overflow or underflow
void manageDataTransfers(char *data, int len) {
    // Check if the length of the data is greater than the maximum buffer size
    if (len > BUFFER_SIZE) {
        // Split the data into chunks and send each chunk separately
        for (int i = 0; i < len / BUFFER_SIZE; i++) {
            int ret = send(connections[i].socket, data + i * BUFFER_SIZE, BUFFER_SIZE, 0);
            if (ret == -1) {
                perror("send");
                close(connections[i].socket);
                connections[i].socket = -1;
