// JSON parser library
#include "json.hpp"
using json = nlohmann::json;

// Attack data structure
struct Attack {
    int cooldown; // Cooldown period in seconds
    std::string name; // Name of the attack
};

// Global variables for memory management
std::vector<Attack> attacks; // Vector to store all available attacks
std::mutex attacksMutex; // Mutex for accessing attacks vector concurrently
std::condition_variable attacksCondVar; // Condition variable for signals

// Function to randomly select an attack and print it to console
void randomSelectAttack() {
    std::unique_lock<std::mutex> locker(attacksMutex);

    // Load attack data from JSON file if not already loaded
    if (attacks.empty()) {
        json attacksData;
        try {
            std::ifstream attacksFile("/data/attacks.json");
            attacksData = json::parse(attacksFile);
        } catch (const std::exception& e) {
            // Handle exception for missing or corrupted JSON file
            std::cerr << "Error parsing attack data: " << e.what() << std::endl;
        }

        // Convert JSON to vector of attacks
        for (json attack : attacksData["attacks"]) {
            Attack newAttack;
            newAttack.cooldown = attack["cooldown"].get<int>();
            newAttack.name = attack["name"].get<std::string>();
            attacks.push_back(newAttack);
        }
    }

    // Select random attack from vector
    std::uniform_int_distribution<int> dist(0, attacks.size() - 1);
    int randAttack = dist(std::random_device());
    Attack selectedAttack = attacks[randAttack];

    // Print selected attack to console
    std::cout << "Selected attack: " << selectedAttack.name << " (cooldown in "
              << selectedAttack.cooldown << " seconds)" << std::endl;

    // Signal waiting threads that new data is available
    attacksCondVar.notify_all();
}
