void init_data(int num_categories, int num_data_points, int range_min, int range_max) {
    // Validate input parameters
    assert(num_categories >= 1 && num_data_points >= 0);
    assert(range_min <= range_max);

    // Initialize variables for memory allocation
    int size = sizeof(int) * (num_categories + 1);
    void* category_ids = NULL;
    void* data_values = NULL;
    int i, j;

    // Allocate memory for category IDs and initialize with random values
