    if (!category_ids) {
        fprintf(stderr, "Error: failed to allocate memory for category IDs.\n");
        exit(1);
    }
    srand((unsigned int) time(NULL)); // Seed random number generator
    for (i = 0; i < num_categories + 1; i++) {
        ((int*)category_ids)[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    // Allocate memory for data values and initialize with random values
    size = sizeof(data_point_t) * num_data_points;
    data_values = malloc(size);
    if (!data_values) {
        fprintf(stderr, "Error: failed to allocate memory for data values.\n");
        exit(1);
    }
    for (i = 0; i < num_data_points; i++) {
        ((data_point_t*)data_values)[i].value = ((int*)category_ids)[((data_point_t*)data_values)[i].category_id];
    }

    // Initialize data points with random values
    for (i = 0; i < num_categories + 1; i++) {
        int current_category_id = ((int*)category_ids)[i];
        for (j = 0; j < num_data_points; j++) {
            if (((data_point_t*)data_values)[j].category_id == current_category_id) {
                ((data_point_t*)data_values)[j].value += rand() % (range_max - range_min + 1) + range_min;
            }
        }
    }

    // Free memory for category IDs and data values
    free(category_ids);
    free(data_values);
}

// Define function to periodically log current memory usage during runtime
void log_memory_usage() {
    struct mallinfo mem = mallinfo();
    printf("Current memory usage: %lu\n", (unsigned long)mem.uordblks);
}

