}

void free_memory(long* offset, int* keys, record** records) {
    // Free the memory allocated for the arrays
    free(*offset);
    free(*keys);
    free(*records);

    // Log the deallocation of memory
    printf("Deallocated memory for arrays: offset=%p, keys=%p, records=%p\n", *offset, *keys, *records);
