```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_RETRIES 5
#define BACKOFF_FACTOR 2
#define SOCKET_BUFFER_SIZE 1024

// Structures for storing data
typedef struct {
    long offset;
    int key;
} record;

// Function to establish connection to remote address
int connectToRemote(const char *remoteAddress, const int port) {
    // Set up socket variables
    int sock = -1;
    struct sockaddr_in serverAddress;
    struct timeval timeout;

    // Initialize socket address structure
    memset(&serverAddress, 0, sizeof(struct sockaddr_in));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(port);

    // Resolve remote address and port to IPv4/IPv6 address
    struct addrinfo *remoteAddrInfo = NULL;
    if (getaddrinfo(remoteAddress, NULL, &remoteAddrInfo) != 0) {
        fprintf(stderr, "Failed to resolve remote address: %s\n", strerror(errno));
        return -1;
    }
    memcpy(&serverAddress.sin_addr, remoteAddrInfo->ai_addr, remoteAddrInfo->ai_addrlen);
    freeaddrinfo(remoteAddrInfo);

    // Create socket and set options
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        return -1;
    }
    timeout.tv_sec = 5;
    timeout.tv_usec = 0;
    if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(struct timeval)) < 0) {
        fprintf(stderr, "Failed to set receive timeout: %s\n", strerror(errno));
        return -1;
    }

    // Attempt to connect to remote address
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (connect(sock, (struct sockaddr *)&serverAddress, sizeof(serverAddress)) == 0) {
            break;
        }
        retries++;
        usleep(BACKOFF_FACTOR * retries);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to connect to remote address: %s\n", strerror(errno));
        return -1;
    }

    // Set up buffer for socket I/O
    char *buffer = malloc(SOCKET_BUFFER_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for socket buffer: %s\n", strerror(errno));
        return -1;
    }

    // Log connection attempt and successful connection
    printf("Attempting to connect to remote address...\n");
    if (retries > 0) {
        printf("Connection attempt failed, retrying %d time%s...\n", retries, (retries > 1 ? "s" : ""));
    } else {
        printf("Connection established successfully!\n");
    }

    // Clean up and return socket file descriptor
    free(buffer);
    return sock;
}

// Function to handle connection state changes
void handleConnectionStateChange(int sock, int oldState, int newState) {
    if (oldState == TCP_CONNECTING && newState == TCP_ESTABLISHED) {
        printf("Connection established successfully!\n");
    } else if (oldState == TCP_CLOSING && newState == TCP_CLOSED) {
        printf("Connection closed successfully!\n");
    } else {
        fprintf(stderr, "Unexpected connection state change: %d -> %d\n", oldState, newState);
    }
}

// Function to allocate memory for and initialize an array of 'record' structures
record *allocateRecords(int numRecords) {
    record *records = malloc(numRecords * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize 'offset' and 'key' fields of each record
    int i;
    for (i = 0; i < numRecords; i++) {
        records[i].offset = rand() % INT_MAX;
        records[i].key = i;
    }

    return records;
}

// Function to allocate memory for and initialize an array of 'int' values
int *allocateInts(int numInts) {
    int *ints = malloc(numInts * sizeof(int));
    if (ints == NULL) {
        fprintf(stderr, "Failed to allocate memory for integers: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize each integer with a random value
    int i;
    for (i = 0; i < numInts; i++) {
        ints[i] = rand() % INT_MAX;
    }

    return ints;
}

// Function to allocate memory for and initialize an array of 'char' values
char *allocateChars(int size) {
    char *chars = malloc(size * sizeof(char));
    if (chars == NULL) {
        fprintf(stderr, "Failed to allocate memory for characters: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize each character with a random ASCII value
    int i;
    for (i = 0; i < size; i++) {
        chars[i] = rand() % 128;
    }

    return chars;
}
```

Note that the above code is just an example and may not be suitable for your specific use case. You should modify it to fit your requirements and ensure that it is correct and safe.

